if (args.Length == 1 && string.Equals(args[0], "--dump-kernel2-details", StringComparison.Ordinal))
{
    var database = Kernel2TextDatabase.TryCreate(root)
        ?? throw new InvalidOperationException("Expected kernel2 text database.");
    Console.WriteLine($"Weapon: {database.ResolveWeaponDescription(0) ?? "<null>"}");
    Console.WriteLine($"Armor: {database.ResolveArmorDescription(0) ?? "<null>"}");
    Console.WriteLine($"Accessory: {database.ResolveAccessoryDescription(0) ?? "<null>"}");
    Console.WriteLine($"Materia: {database.ResolveMateriaDescription(0) ?? "<null>"}");
    return;
}

if (args.Length == 1 && string.Equals(args[0], "--audit-cutscene-cues", StringComparison.Ordinal))
{
    var catalog = new FieldScriptNavigationCatalog(root);
    var missingCount = 0;
    var groups = FieldCutsceneDescriptionCatalog.CreateEarlyGameDescriptions().GroupBy(cue => new
    {
        cue.FieldId,
        cue.EntityId,
        cue.ScriptId,
        cue.Opcode,
        cue.Text
    });
    foreach (var group in groups)
    {
        var first = group.First();
        var opcodes = catalog.ReadScriptOpcodes(first.FieldId, first.EntityId, first.ScriptId);
        if (group.Any(cue =>
                opcodes.Any(opcode => opcode.ByteIndex == cue.ByteIndex && opcode.Opcode == cue.Opcode)))
        {
            continue;
        }

        missingCount++;
        var nearby = opcodes
            .Where(opcode => opcode.Opcode == first.Opcode)
            .OrderBy(opcode => group.Min(cue => Math.Abs(opcode.ByteIndex - cue.ByteIndex)))
            .Take(5)
            .Select(opcode => opcode.ByteIndex);
        Console.WriteLine(
            $"missing field={first.FieldId} entity={first.EntityId} script={first.ScriptId} " +
            $"bytes={string.Join(',', group.Select(cue => cue.ByteIndex))} opcode=0x{first.Opcode:X2} " +
            $"nearby={string.Join(',', nearby)} text={first.Text}");
    }

    Console.WriteLine($"Cutscene cue audit: groups={groups.Count()}, missing={missingCount}");
    Environment.ExitCode = missingCount == 0 ? 0 : 1;
    return;
}

if (args.Length >= 2 && string.Equals(args[0], "--dump-field-waits", StringComparison.Ordinal))
{
    var catalog = new FieldScriptNavigationCatalog(root);
    foreach (var fieldId in args.Skip(1).Select(int.Parse))
    {
        var field = catalog.ReadField(fieldId);
        Console.WriteLine($"FIELD {fieldId}: {field.Diagnostic}");
        foreach (var wait in field.Waits.OrderBy(wait => wait.EntityId).ThenBy(wait => wait.ScriptId).ThenBy(wait => wait.ByteIndex))
        {
            Console.WriteLine(
                $"  entity={wait.EntityId} script={wait.ScriptId} byte={wait.ByteIndex} frames={wait.Frames}");
        }
    }

    return;
}

if (args.Length == 4 && string.Equals(args[0], "--dump-field-script", StringComparison.Ordinal))
{
    var catalog = new FieldScriptNavigationCatalog(root);
    var opcodes = catalog.ReadScriptOpcodes(int.Parse(args[1]), int.Parse(args[2]), int.Parse(args[3]));
    foreach (var opcode in opcodes)
    {
        Console.WriteLine(
            $"field={opcode.FieldId} entity={opcode.EntityId}:{opcode.EntityName} script={opcode.ScriptId} " +
            $"byte={opcode.ByteIndex} opcode=0x{opcode.Opcode:X2} bytes={Convert.ToHexString(opcode.Bytes.ToArray())}");
    }

    return;
}

if (args.Length is 3 or 4 && string.Equals(args[0], "--dump-field-opcode", StringComparison.Ordinal))
{
    var catalog = new FieldScriptNavigationCatalog(root);
    var fieldId = int.Parse(args[1]);
    var opcode = Convert.ToByte(args[2], 16);
    var maxEntityId = args.Length == 4 ? int.Parse(args[3]) : 31;
    for (var entityId = 0; entityId <= maxEntityId; entityId++)
    {
        for (var scriptId = 0; scriptId < 32; scriptId++)
        {
            foreach (var entry in catalog.ReadScriptOpcodes(fieldId, entityId, scriptId).Where(entry => entry.Opcode == opcode))
            {
                Console.WriteLine(
                    $"field={entry.FieldId} entity={entry.EntityId}:{entry.EntityName} script={entry.ScriptId} " +
                    $"byte={entry.ByteIndex} opcode=0x{entry.Opcode:X2} bytes={Convert.ToHexString(entry.Bytes.ToArray())}");
            }
        }
    }

    return;
}

if (args.Length >= 3 && string.Equals(args[0], "--dump-field-messages", StringComparison.Ordinal))
{
    var resolver = new FlevelFieldTextResolver(root);
    var fieldId = int.Parse(args[1]);
    foreach (var dialogId in args.Skip(2).Select(int.Parse))
    {
        Console.WriteLine($"field={fieldId} dialog={dialogId}: {resolver.ReadMessageById(fieldId, dialogId).Text}");
    }

    return;
}

if (args.Length == 3 && string.Equals(args[0], "--dump-field-message-bytes", StringComparison.Ordinal))
{
    var bytes = ReadInstalledFieldMessageBytes(int.Parse(args[1]), int.Parse(args[2]));
    Console.WriteLine(Convert.ToHexString(bytes));
    Console.WriteLine(Ff7EncodedTextDecoder.DecodeTerminated(bytes));
    return;
}

