static void AssertRuntimeEventQueueCoalescesFramesWithoutDroppingDiscreteEvents()
{
    var queue = new RuntimeEventQueue(maxDiscreteEvents: 8);
    var startedAt = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    queue.Publish(new MovieLifecycleEvent(startedAt, MovieLifecycleKind.Started, "opening"));
    queue.PublishFrame(CreateRuntimeFrame(
        startedAt,
        menu: new MenuFrameObservation(
            "title",
            true,
            1,
            [new MenuRowObservation(0, "New Game", true, true)])));
    queue.PublishFrame(CreateRuntimeFrame(
        startedAt.AddMilliseconds(16),
        field: new FieldFrameObservation(116, 0, 10, 20, 30, 4, true, 2, 1, 44)));
    queue.Publish(new MovieLifecycleEvent(startedAt.AddSeconds(1), MovieLifecycleKind.Stopped, "opening"));

    var batch = queue.Drain();

    AssertEqual(2, batch.Events.Count, "ordered discrete runtime event count");
    AssertEqual(MovieLifecycleKind.Started, ((MovieLifecycleEvent)batch.Events[0]).Kind, "first discrete runtime event");
    AssertEqual(MovieLifecycleKind.Stopped, ((MovieLifecycleEvent)batch.Events[1]).Kind, "second discrete runtime event");
    AssertEqual(RuntimeDomainUpdateKind.Present, batch.Frame!.Menu.Kind, "coalesced menu update kind");
    AssertEqual("New Game", batch.Frame.Menu.Value!.Rows.Single(row => row.Selected).Text, "coalesced menu observation");
    AssertEqual(RuntimeDomainUpdateKind.Present, batch.Frame.Field.Kind, "coalesced field update kind");
    AssertEqual(116, batch.Frame.Field.Value!.FieldId, "coalesced field observation");
    AssertEqual(startedAt.AddMilliseconds(16), batch.Frame.TimestampUtc, "latest frame timestamp");

    var empty = queue.Drain();
    AssertEqual(null, empty.Frame, "drained frame queue");
    AssertEqual(0, empty.Events.Count, "drained discrete event queue");
}

static void AssertRuntimeEventQueueClosesMenuAndDialogueDomainsExplicitly()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var queue = new RuntimeEventQueue();
    queue.PublishFrame(CreateRuntimeFrame(
        timestamp,
        menu: new MenuFrameObservation(
            "title",
            true,
            1,
            [new MenuRowObservation(0, "New Game", true, true)]),
        dialogue: new DialoguePageObservation(true, 0, 1, "Cloud", "Not interested.", [])));
    queue.PublishFrame(CreateRuntimeFrame(
        timestamp.AddMilliseconds(16),
        menuUpdate: RuntimeDomainUpdate<MenuFrameObservation>.Closed,
        dialogueUpdate: RuntimeDomainUpdate<DialoguePageObservation>.Closed));

    var frame = queue.Drain().Frame!;

    AssertEqual(RuntimeDomainUpdateKind.Closed, frame.Menu.Kind, "menu close update must replace prior menu");
    AssertEqual(null, frame.Menu.Value, "closed menu must not retain prior rows");
    AssertEqual(RuntimeDomainUpdateKind.Closed, frame.Dialogue.Kind, "dialogue close update must replace prior page");
    AssertEqual(null, frame.Dialogue.Value, "closed dialogue must not retain prior text");
}

static void AssertRuntimeEventQueueClearsUnchangedDomainsAcrossModuleTransitions()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var queue = new RuntimeEventQueue();
    queue.PublishFrame(CreateRuntimeFrame(
        timestamp,
        moduleId: 2,
        battle: new BattleFrameObservation(true, 1, 0, 0, -1, -1, 1, 1, [])));
    queue.PublishFrame(CreateRuntimeFrame(
        timestamp.AddMilliseconds(16),
        moduleId: 1,
        field: new FieldFrameObservation(116, 0, 10, 20, 30, 4, true, 2, 1, 44),
        battleUpdate: RuntimeDomainUpdate<BattleFrameObservation>.Unchanged));

    var frame = queue.Drain().Frame!;

    AssertEqual(1, frame.Lifecycle.ModuleId, "latest module after transition");
    AssertEqual(RuntimeDomainUpdateKind.Closed, frame.Battle.Kind, "module transition clears unchanged battle state");
    AssertEqual(null, frame.Battle.Value, "module transition cannot retain stale battle observation");
    AssertEqual(RuntimeDomainUpdateKind.Present, frame.Field.Kind, "new field observation remains present");
}

static void AssertRuntimeEventQueueReportsOverflowWithoutThrowingFromNativePublishers()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    RuntimeEvent[] orderedEvents =
    [
        new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening"),
        new MovieLifecycleEvent(timestamp.AddSeconds(1), MovieLifecycleKind.Stopped, "opening"),
        new MovieLifecycleEvent(timestamp.AddSeconds(2), MovieLifecycleKind.Skipped, "opening"),
        new GenericRuntimeEvent(timestamp.AddSeconds(3), "future-event")
    ];
    var queue = new RuntimeEventQueue(maxDiscreteEvents: orderedEvents.Length);
    foreach (var runtimeEvent in orderedEvents)
    {
        AssertEqual(
            RuntimeEventPublishStatus.Published,
            queue.Publish(runtimeEvent).Status,
            $"publish {runtimeEvent.GetType().Name}");
    }

    var rejected = queue.Publish(new GenericRuntimeEvent(timestamp.AddSeconds(4), "overflow"));
    AssertEqual(RuntimeEventPublishStatus.RejectedQueueFull, rejected.Status, "overflow publication result");
    AssertEqual(false, rejected.Succeeded, "overflow cannot silently claim success");

    var batch = queue.Drain();
    AssertEqual(orderedEvents.Length, batch.Events.Count, "already queued event count after overflow");
    for (var index = 0; index < orderedEvents.Length; index++)
    {
        AssertEqual(orderedEvents[index], batch.Events[index], $"queued event order {index}");
    }

    AssertEqual(RuntimeQueueDegradationKind.DiscreteEventOverflow, batch.Degradation!.Kind, "fatal queue degradation kind");
    AssertEqual(true, batch.Degradation.IsFatal, "queue overflow is fatal accessibility degradation");
    AssertEqual(1L, batch.Degradation.RejectedEventCount, "rejected event count");

    foreach (var kind in Enum.GetValues<MovieLifecycleKind>())
    {
        var pressureQueue = new RuntimeEventQueue(maxDiscreteEvents: 1);
        pressureQueue.Publish(new GenericRuntimeEvent(timestamp, "fill"));
        var result = pressureQueue.Publish(new MovieLifecycleEvent(timestamp, kind, "opening"));
        AssertEqual(RuntimeEventPublishStatus.RejectedQueueFull, result.Status, $"nonthrowing overflow for {kind}");
        AssertEqual(true, pressureQueue.Drain().Degradation?.IsFatal, $"fatal degradation for {kind}");
    }

    var sticky = queue.Drain();
    AssertEqual(true, sticky.Degradation?.IsFatal, "fatal degradation remains visible outside native hook timing");
}

static void AssertNormalizedRuntimeCollectionsAreProducerImmutable()
{
    var menuRows = new List<MenuRowObservation> { new(0, "New Game", true, true) };
    var dialogueChoices = new List<DialogueChoiceObservation> { new(0, "Yes", true, true) };
    var actors = new List<BattleActorObservation> { new(0, false, true, true, 100, 100, 20, 20, 0) };
    var player = new FieldFrameObservation(116, 0, 1, 2, 3, 4, true, 0, 0, 0);
    var targets = new List<NavigationTargetObservation>
    {
        new("exit:1", NavigationTargetKind.Exit, 1, 10, 20, 30, true, "exit-1")
    };
    var walkmesh = new List<WalkmeshTriangleObservation> { new(4, -1, -1, -1, 1, 2, 3, true) };
    var failures = new List<RuntimeCapabilityFailure>
    {
        new(RuntimeCapability.Dialogue, "dialogue-page", "not resolved")
    };
    var menu = new MenuFrameObservation("title", true, 1, menuRows);
    var dialogue = new DialoguePageObservation(true, 0, 1, "Cloud", "Ready?", dialogueChoices);
    var battle = new BattleFrameObservation(true, 1, 0, 0, -1, -1, 1, 1, actors);
    var navigation = new NavigationWorldObservation(116, 1, player, targets, walkmesh);
    var report = new RuntimeCapabilityReport(
        new RuntimeIdentity("test", "test.exe", new string('A', 64), true, "2.0.0.0"),
        RuntimeCapability.None,
        failures);
    var queue = new RuntimeEventQueue();
    queue.PublishFrame(CreateRuntimeFrame(DateTime.UtcNow, menu: menu));

    menuRows[0] = new MenuRowObservation(0, "Continue?", true, true);
    dialogueChoices.Clear();
    actors.Clear();
    targets.Clear();
    walkmesh.Clear();
    failures.Clear();

    AssertEqual("New Game", menu.Rows[0].Text, "menu rows defensive copy");
    AssertEqual(1, dialogue.Choices.Length, "dialogue choices defensive copy");
    AssertEqual(1, battle.Actors.Length, "battle actors defensive copy");
    AssertEqual(1, navigation.Targets.Length, "navigation targets defensive copy");
    AssertEqual(1, navigation.Walkmesh.Length, "navigation walkmesh defensive copy");
    AssertEqual(1, report.Failures.Length, "capability failures defensive copy");
    AssertEqual(
        "New Game",
        queue.Drain().Frame!.Menu.Value!.Rows[0].Text,
        "published observation unaffected by producer buffer reuse");
}

static void AssertNormalizedBattleActorEnforcesEnemyPrivacyInvariant()
{
    var unsensed = new BattleActorObservation(
        4,
        true,
        true,
        false,
        42,
        50,
        12,
        18,
        1u << 3);
    AssertEqual(0, unsensed.CurrentHp, "normalized unsensed enemy constructor redacts current HP");
    AssertEqual(0, unsensed.MaximumHp, "normalized unsensed enemy constructor redacts maximum HP");
    AssertEqual(0, unsensed.CurrentMp, "normalized unsensed enemy constructor redacts current MP");
    AssertEqual(0, unsensed.MaximumMp, "normalized unsensed enemy constructor redacts maximum MP");
    AssertEqual(0u, unsensed.StatusMask, "normalized unsensed enemy constructor redacts status");

    var initializerAttempt = new BattleActorObservation(
        4,
        false,
        true,
        false,
        42,
        50,
        12,
        18,
        1u << 3)
    {
        IsEnemy = true
    };
    AssertEqual(0, initializerAttempt.CurrentHp, "normalized enemy init setter redacts current HP");
    AssertEqual(0, initializerAttempt.MaximumHp, "normalized enemy init setter redacts maximum HP");
    AssertEqual(0, initializerAttempt.CurrentMp, "normalized enemy init setter redacts current MP");
    AssertEqual(0, initializerAttempt.MaximumMp, "normalized enemy init setter redacts maximum MP");
    AssertEqual(0u, initializerAttempt.StatusMask, "normalized enemy init setter redacts status");

    var mutationAttempt = unsensed with
    {
        CurrentHp = 41,
        MaximumHp = 50,
        CurrentMp = 11,
        MaximumMp = 18,
        StatusMask = 1u << 8
    };
    AssertEqual(0, mutationAttempt.CurrentHp, "normalized unsensed enemy with-expression cannot restore current HP");
    AssertEqual(0, mutationAttempt.MaximumHp, "normalized unsensed enemy with-expression cannot restore maximum HP");
    AssertEqual(0, mutationAttempt.CurrentMp, "normalized unsensed enemy with-expression cannot restore current MP");
    AssertEqual(0, mutationAttempt.MaximumMp, "normalized unsensed enemy with-expression cannot restore maximum MP");
    AssertEqual(0u, mutationAttempt.StatusMask, "normalized unsensed enemy with-expression cannot restore status");

    var sensed = new BattleActorObservation(
        4,
        true,
        true,
        true,
        42,
        50,
        12,
        18,
        1u << 3);
    var hiddenAgain = sensed with { IsSensed = false };
    AssertEqual(0, hiddenAgain.CurrentHp, "normalized enemy with-expression redacts current HP when Sense visibility is removed");
    AssertEqual(0, hiddenAgain.MaximumHp, "normalized enemy with-expression redacts maximum HP when Sense visibility is removed");
    AssertEqual(0, hiddenAgain.CurrentMp, "normalized enemy with-expression redacts current MP when Sense visibility is removed");
    AssertEqual(0, hiddenAgain.MaximumMp, "normalized enemy with-expression redacts maximum MP when Sense visibility is removed");
    AssertEqual(0u, hiddenAgain.StatusMask, "normalized enemy with-expression redacts status when Sense visibility is removed");
}

static void AssertAccessibilityRuntimeFailsClosedForIncompleteBackend()
{
    var identity = new RuntimeIdentity("incomplete", "test.exe", new string('1', 64), true, "2.0.0.0");
    var report = new RuntimeCapabilityReport(
        identity,
        RuntimeCapability.FullParity & ~RuntimeCapability.Dialogue,
        [new RuntimeCapabilityFailure(RuntimeCapability.Dialogue, "dialogue-page", "not resolved")]);
    var backend = new FakeRuntimeBackend(report, CreateRuntimeFrame(DateTime.UtcNow));
    var output = new RecordingAccessibilityOutput();
    var logs = new List<string>();

    using (var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add))
    {
        var actual = runtime.Start();
        runtime.Tick(DateTime.UtcNow);
        AssertEqual(false, actual.HasFullParity, "incomplete backend startup report");
        AssertEqual(false, backend.Started, "incomplete backend must not start");
        AssertEqual(0, backend.ReadCount, "incomplete backend must not be polled");
    }

    AssertEqual(0, output.Spoken.Count, "incomplete backend must remain silent");
    AssertEqual(true, logs.Any(line => line.Contains("Dialogue", StringComparison.Ordinal)), "missing capability diagnostic");
}

