static void AssertAccessibilityRuntimeAcceptsLifecycleOnlyBackend()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("lifecycle-only", "test.exe", new string('7', 64), true, string.Empty);
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Lifecycle, []),
        CreateRuntimeFrame(timestamp));
    var output = new RecordingAccessibilityOutput();

    using var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, _ => { });
    var report = runtime.Start();
    runtime.Tick(timestamp);

    AssertEqual(RuntimeCapability.Lifecycle, report.Available, "lifecycle-only backend capability");
    AssertEqual(0, report.Failures.Length, "lifecycle-only backend dispatcher gate");
    AssertEqual(true, backend.Started, "lifecycle-only backend starts");
    AssertEqual(1, backend.ReadCount, "lifecycle-only backend is polled");
    AssertEqual(0, output.Spoken.Count, "lifecycle observation manufactures no speech");
    AssertEqual(0, output.Played.Count, "lifecycle observation manufactures no cues");
}

static void AssertAccessibilityRuntimeRejectsUndispatchedAdvertisedCapabilities()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("lying-full-parity", "test.exe", new string('8', 64), true, "2.0.0.0");
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.FullParity, []),
        CreateRuntimeFrame(timestamp));
    var output = new RecordingAccessibilityOutput();
    var logs = new List<string>();

    using var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add);
    var effectiveReport = runtime.Start();
    runtime.Tick(timestamp);

    AssertEqual(false, effectiveReport.HasFullParity, "undispatched capabilities fail the effective parity report");
    AssertEqual(false, backend.Started, "backend advertising undispatched domains must not start");
    AssertEqual(0, backend.ReadCount, "backend advertising undispatched domains must not be polled");
    AssertEqual(0, output.Played.Count, "rejected backend must produce no output");
    AssertEqual(
        true,
        effectiveReport.Failures.Any(failure =>
            failure.Capability == RuntimeCapability.Battle
            && failure.Signal == "runtime-event-dispatcher"),
        "effective report names the missing battle dispatcher");
    AssertEqual(
        true,
        logs.Any(line =>
            line.Contains("Battle", StringComparison.Ordinal)
            && line.Contains("dispatcher", StringComparison.OrdinalIgnoreCase)),
        "undispatched battle capability failure is logged");
}

static void AssertAccessibilityRuntimeStartsAndDispatchesVerifiedMovieLifecycle()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("complete", "test.exe", new string('2', 64), true, "2.0.0.0");
    var report = new RuntimeCapabilityReport(identity, RuntimeCapability.Movies, []);
    var backend = new FakeRuntimeBackend(report, CreateRuntimeFrame(timestamp))
    {
        StartEvent = new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening")
    };
    var output = new RecordingAccessibilityOutput();
    var config = new AccessibilityConfig
    {
        EnableOpeningMovieAudioTrack = true,
        OpeningMovieAudioTrackPath = @"Assets\movies\opening_audio_description.ogg",
        OpeningMovieAudioTrackVolumePercent = 300
    };

    using (var runtime = new AccessibilityRuntime(backend, config, output, _ => { }))
    {
        AssertEqual(
            RuntimeCapability.Movies,
            runtime.Start().Available,
            "truthful movie-only backend startup report");
        runtime.Tick(timestamp);
        AssertEqual(true, backend.Started, "complete backend start");
        AssertEqual(1, backend.ReadCount, "complete backend frame read");
        AssertEqual(1, output.Played.Count, "verified movie start cue");
        AssertEqual(AccessibilityCueKind.MovieNarration, output.Played[0].Kind, "movie cue kind");
        AssertEqual(3.0f, output.Played[0].Volume, "movie cue configured gain");
    }

    AssertEqual(true, backend.Stopped, "runtime stops backend during disposal");
    AssertEqual(true, backend.Disposed, "runtime disposes backend");
}

static void AssertAccessibilityRuntimeFailsClosedWhenSpeechThrows()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 30, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("menu-output-failure", "test.exe", new string('9', 64), true, string.Empty);
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Menus, []),
        CreateRuntimeFrame(
            timestamp,
            menu: new MenuFrameObservation(
                "root",
                true,
                1,
                [new MenuRowObservation(0, "Item", true, true)])));
    var output = new RecordingAccessibilityOutput { SpeakFailuresRemaining = 1 };
    var logs = new List<string>();

    using var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add);
    AssertEqual(RuntimeCapability.Menus, runtime.Start().Available, "menu-only runtime start");
    runtime.Tick(timestamp);
    runtime.Tick(timestamp.AddMilliseconds(16));

    AssertEqual(true, backend.Stopped, "speech output failure stops backend");
    AssertEqual(1, backend.ReadCount, "speech output failure prevents subsequent polling");
    AssertEqual(1, output.SpeakAttempts, "speech output failure attempt count");
    AssertEqual(
        true,
        logs.Any(line => line.Contains("failed closed", StringComparison.OrdinalIgnoreCase)),
        "speech output failure is logged as fail-closed");
}

