static void AssertAccessibilityRuntimeFailsClosedWhenPlayCueThrows()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("play-output-failure", "test.exe", new string('9', 64), true, "2.0.0.0");
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Movies, []),
        CreateRuntimeFrame(timestamp))
    {
        StartEvent = new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening")
    };
    var output = new RecordingAccessibilityOutput { PlayCueFailuresRemaining = 1 };
    var logs = new List<string>();
    var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add);

    runtime.Start();
    runtime.Tick(timestamp);
    var latePublication = backend.PublishLate(
        new MovieLifecycleEvent(timestamp.AddSeconds(1), MovieLifecycleKind.Started, "opening"));
    runtime.Tick(timestamp.AddMilliseconds(16));

    AssertEqual(true, backend.Stopped, "PlayCue failure stops the backend");
    AssertEqual(1, backend.ReadCount, "PlayCue failure prevents subsequent polling");
    AssertEqual(1, output.PlayCueAttempts, "PlayCue failure is not retried as late output");
    AssertEqual(0, output.Played.Count, "failed PlayCue is not recorded as active output");
    AssertEqual(
        RuntimeEventPublishStatus.RejectedNotAccepting,
        latePublication.Status,
        "late event is rejected after PlayCue failure");
    AssertEqual(
        true,
        logs.Any(line =>
            line.Contains("failed closed", StringComparison.OrdinalIgnoreCase)
            && line.Contains("test PlayCue output failure", StringComparison.Ordinal)),
        "PlayCue failure remains observable at the runtime fail-closed boundary");

    runtime.Dispose();
    AssertEqual(true, backend.Disposed, "PlayCue-failed backend is disposed");
}

static void AssertAccessibilityRuntimeRetainsCueUntilStopSucceeds()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("stop-output-failure", "test.exe", new string('A', 64), true, "2.0.0.0");
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Movies, []),
        CreateRuntimeFrame(timestamp))
    {
        StartEvent = new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening")
    };
    var output = new RecordingAccessibilityOutput { StopCueFailuresRemaining = 2 };
    var logs = new List<string>();
    var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add);

    runtime.Start();
    runtime.Tick(timestamp);
    AssertEqual(1, output.Played.Count, "movie cue starts before StopCue failure");
    AssertEqual(
        RuntimeEventPublishStatus.Published,
        backend.PublishLate(new MovieLifecycleEvent(timestamp.AddSeconds(1), MovieLifecycleKind.Stopped, "opening")).Status,
        "movie stop event published before failure");

    runtime.Tick(timestamp.AddSeconds(1));
    var latePublication = backend.PublishLate(
        new MovieLifecycleEvent(timestamp.AddSeconds(2), MovieLifecycleKind.Started, "opening"));
    runtime.Tick(timestamp.AddSeconds(2));

    AssertEqual(true, backend.Stopped, "StopCue failure stops the backend");
    AssertEqual(2, backend.ReadCount, "StopCue failure prevents subsequent polling");
    AssertEqual(2, output.StopCueAttempts, "failed event stop is retried once during fail-closed cleanup");
    AssertEqual(0, output.Stopped.Count, "cue remains owned while StopCue keeps failing");
    AssertEqual(1, output.PlayCueAttempts, "no late cue starts after StopCue failure");
    AssertEqual(
        RuntimeEventPublishStatus.RejectedNotAccepting,
        latePublication.Status,
        "late event is rejected after StopCue failure");

    runtime.Dispose();

    AssertEqual(3, output.StopCueAttempts, "Dispose performs one bounded retry for the retained cue");
    AssertEqual(
        1,
        output.Stopped.Count(kind => kind == AccessibilityCueKind.MovieNarration),
        "retained cue is forgotten only after StopCue succeeds");
    AssertEqual(
        true,
        logs.Count(line => line.Contains("cue cleanup failed", StringComparison.OrdinalIgnoreCase)) >= 1,
        "failed cleanup attempts are logged");
}

static void AssertAccessibilityRuntimeStopsActiveCuesAndRejectsLateEventsOnDispose()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("complete", "test.exe", new string('4', 64), true, "2.0.0.0");
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Movies, []),
        CreateRuntimeFrame(timestamp))
    {
        StartEvent = new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening"),
        ThrowOnStop = true
    };
    var output = new RecordingAccessibilityOutput();
    var logs = new List<string>();
    var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add);

    runtime.Start();
    runtime.Tick(timestamp);
    AssertEqual(1, output.Played.Count, "movie narration is active before disposal");

    runtime.Dispose();

    AssertEqual(true, backend.Stopped, "backend stop attempted during disposal");
    AssertEqual(true, backend.Disposed, "backend disposed even when stop throws");
    AssertEqual(
        true,
        output.Stopped.Contains(AccessibilityCueKind.MovieNarration),
        "active narration stopped during disposal");
    AssertEqual(
        RuntimeEventPublishStatus.RejectedNotAccepting,
        backend.PublishLate(new MovieLifecycleEvent(timestamp.AddSeconds(1), MovieLifecycleKind.Stopped, "opening")).Status,
        "late native event rejected after disposal");
    AssertEqual(
        true,
        logs.Any(line => line.Contains("stop", StringComparison.OrdinalIgnoreCase)),
        "backend stop failure logged during safe cleanup");
}

static void AssertAccessibilityRuntimeFailsClosedBeforeDispatchingAnOverflowedBatch()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("complete", "test.exe", new string('5', 64), true, "2.0.0.0");
    RuntimeEvent[] startEvents =
    [
        new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening"),
        .. Enumerable.Range(0, 4095).Select(index =>
            (RuntimeEvent)new GenericRuntimeEvent(timestamp.AddTicks(index + 1), $"fill-{index}")),
        new GenericRuntimeEvent(timestamp.AddSeconds(1), "overflow")
    ];
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Movies, []),
        CreateRuntimeFrame(timestamp))
    {
        StartEvents = startEvents
    };
    var output = new RecordingAccessibilityOutput();
    var logs = new List<string>();
    using var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add);

    runtime.Start();
    runtime.Tick(timestamp);
    runtime.Tick(timestamp.AddMilliseconds(16));

    AssertEqual(0, output.Played.Count, "overflowed batch is never partially dispatched");
    AssertEqual(true, backend.Stopped, "fatal queue degradation stops backend outside callback");
    AssertEqual(1, backend.ReadCount, "failed-closed runtime is not polled again");
    AssertEqual(
        true,
        logs.Any(line => line.Contains("DiscreteEventOverflow", StringComparison.Ordinal)),
        "fatal queue degradation logged");
    AssertEqual(
        RuntimeEventPublishStatus.RejectedNotAccepting,
        backend.PublishLate(new GenericRuntimeEvent(timestamp.AddSeconds(2), "late")).Status,
        "events rejected after fatal degradation");
}

static void AssertAccessibilityRuntimeFailsClosedAfterPartialBackendStart()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("complete", "test.exe", new string('6', 64), true, "2.0.0.0");
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Movies, []),
        CreateRuntimeFrame(timestamp))
    {
        StartEvent = new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening"),
        ThrowOnStart = true
    };
    var output = new RecordingAccessibilityOutput();
    var logs = new List<string>();
    using var runtime = new AccessibilityRuntime(backend, new AccessibilityConfig(), output, logs.Add);

    InvalidOperationException? startFailure = null;
    try
    {
        runtime.Start();
    }
    catch (InvalidOperationException ex)
    {
        startFailure = ex;
    }

    AssertNotNull(startFailure, "partial backend start failure must remain visible to the caller");
    AssertContains(startFailure!.Message, "test backend start failure");
    AssertEqual(true, backend.Stopped, "partial backend start must still stop backend");
    AssertEqual(0, output.Played.Count, "event published before failed start is never dispatched");
    AssertEqual(
        RuntimeEventPublishStatus.RejectedNotAccepting,
        backend.PublishLate(new MovieLifecycleEvent(timestamp.AddSeconds(1), MovieLifecycleKind.Stopped, "opening")).Status,
        "late event rejected after partial backend start failure");
    AssertEqual(
        true,
        logs.Any(line =>
            line.Contains("failed closed", StringComparison.OrdinalIgnoreCase)
            && line.Contains("start", StringComparison.OrdinalIgnoreCase)
            && line.Contains("test backend start failure", StringComparison.Ordinal)),
        "partial backend start failure logged");

    InvalidOperationException? restartFailure = null;
    try
    {
        runtime.Start();
    }
    catch (InvalidOperationException ex)
    {
        restartFailure = ex;
    }

    AssertNotNull(restartFailure, "failed-closed runtime cannot restart after partial backend start");
    AssertContains(restartFailure!.Message, "cannot be restarted");
    runtime.Tick(timestamp.AddMilliseconds(16));
    AssertEqual(0, backend.ReadCount, "failed-closed partial start is never polled");
}

static void AssertAccessibilityRuntimeContainsReadFrameFailureAndCleansUp()
{
    var timestamp = new DateTime(2026, 7, 19, 20, 0, 0, DateTimeKind.Utc);
    var identity = new RuntimeIdentity("complete", "test.exe", new string('7', 64), true, "2.0.0.0");
    var backend = new FakeRuntimeBackend(
        new RuntimeCapabilityReport(identity, RuntimeCapability.Movies, []),
        CreateRuntimeFrame(timestamp))
    {
        StartEvent = new MovieLifecycleEvent(timestamp, MovieLifecycleKind.Started, "opening")
    };
    var output = new RecordingAccessibilityOutput();
    var config = new AccessibilityConfig
    {
        EnableOpeningMovieAudioTrack = true,
        OpeningMovieAudioTrackPath = @"Assets\movies\opening_audio_description.ogg"
    };
    var logs = new List<string>();
    var runtime = new AccessibilityRuntime(backend, config, output, logs.Add);

    runtime.Start();
    runtime.Tick(timestamp);
    AssertEqual(1, output.Played.Count, "movie narration is active before frame-read failure");

    backend.ThrowOnRead = true;
    runtime.Tick(timestamp.AddMilliseconds(16));
    runtime.Tick(timestamp.AddMilliseconds(32));

    AssertEqual(true, backend.Stopped, "frame-read failure stops backend");
    AssertEqual(2, backend.ReadCount, "frame-read failure prevents subsequent polling");
    AssertEqual(
        true,
        output.Stopped.Contains(AccessibilityCueKind.MovieNarration),
        "frame-read failure cleans up active narration");
    AssertEqual(
        RuntimeEventPublishStatus.RejectedNotAccepting,
        backend.PublishLate(new GenericRuntimeEvent(timestamp.AddSeconds(1), "late")).Status,
        "late event rejected after frame-read failure");
    AssertEqual(
        true,
        logs.Any(line =>
            line.Contains("failed closed", StringComparison.OrdinalIgnoreCase)
            && line.Contains("frame", StringComparison.OrdinalIgnoreCase)
            && line.Contains("test backend frame failure", StringComparison.Ordinal)),
        "frame-read failure logged");

    InvalidOperationException? restartFailure = null;
    try
    {
        runtime.Start();
    }
    catch (InvalidOperationException ex)
    {
        restartFailure = ex;
    }

    AssertNotNull(restartFailure, "failed-closed runtime cannot restart after frame-read failure");
    runtime.Dispose();

    ObjectDisposedException? disposedTickFailure = null;
    try
    {
        runtime.Tick(timestamp.AddMilliseconds(48));
    }
    catch (ObjectDisposedException ex)
    {
        disposedTickFailure = ex;
    }

    AssertNotNull(disposedTickFailure, "disposed runtime Tick keeps ObjectDisposedException contract");
}

