static void AssertLegacyX86CapabilitiesMapEveryRequiredSubsystem()
{
    var mappedCapabilities = LegacyX86CapabilityValidator.RequiredSignals.Keys
        .Aggregate(RuntimeCapability.None, (combined, capability) => combined | capability);
    var signals = LegacyX86CapabilityValidator.RequiredSignals.Values.SelectMany(value => value).ToArray();

    AssertEqual(RuntimeCapability.FullParity, mappedCapabilities, "legacy required capability mapping");
    AssertEqual(true, LegacyX86CapabilityValidator.RequiredSignals.Values.All(value => value.Count > 0), "legacy capability signal lists");
    AssertEqual(signals.Length, signals.Distinct(StringComparer.Ordinal).Count(), "legacy capability signal uniqueness");

    var identity = new RuntimeIdentity(
        "ff7-legacy-x86",
        "ff7_en.exe",
        LegacyX86Fingerprint.SupportedSha256,
        false,
        string.Empty);
    var report = LegacyX86CapabilityValidator.Validate(identity, signals);
    AssertEqual(true, report.HasFullParity, "complete legacy capability signal set");
}

static void AssertLegacyX86CapabilityValidationFailsClosedOnMissingSignal()
{
    const string missingSignal = "menu-widget-update";
    var signals = LegacyX86CapabilityValidator.RequiredSignals.Values
        .SelectMany(value => value)
        .Where(signal => !string.Equals(signal, missingSignal, StringComparison.Ordinal));
    var identity = new RuntimeIdentity(
        "ff7-legacy-x86",
        "ff7_en.exe",
        LegacyX86Fingerprint.SupportedSha256,
        false,
        string.Empty);

    var report = LegacyX86CapabilityValidator.Validate(identity, signals);

    AssertEqual(false, report.HasFullParity, "missing legacy signal parity gate");
    AssertEqual(
        true,
        report.Failures.Any(failure => failure.Capability == RuntimeCapability.Menus && failure.Signal == missingSignal),
        "missing legacy menu signal diagnostic");
}

static RuntimeFrameObservation CreateRuntimeFrame(
    DateTime timestamp,
    int moduleId = 0,
    MenuFrameObservation? menu = null,
    DialoguePageObservation? dialogue = null,
    FieldFrameObservation? field = null,
    BattleFrameObservation? battle = null,
    NavigationWorldObservation? navigation = null,
    RuntimeDomainUpdate<MenuFrameObservation>? menuUpdate = null,
    RuntimeDomainUpdate<DialoguePageObservation>? dialogueUpdate = null,
    RuntimeDomainUpdate<FieldFrameObservation>? fieldUpdate = null,
    RuntimeDomainUpdate<BattleFrameObservation>? battleUpdate = null,
    RuntimeDomainUpdate<NavigationWorldObservation>? navigationUpdate = null)
{
    return new RuntimeFrameObservation(
        timestamp,
        new GameLifecycleObservation(true, false, moduleId, 1),
        menuUpdate ?? (menu is null
            ? RuntimeDomainUpdate<MenuFrameObservation>.Unchanged
            : RuntimeDomainUpdate<MenuFrameObservation>.Present(menu)),
        dialogueUpdate ?? (dialogue is null
            ? RuntimeDomainUpdate<DialoguePageObservation>.Unchanged
            : RuntimeDomainUpdate<DialoguePageObservation>.Present(dialogue)),
        fieldUpdate ?? (field is null
            ? RuntimeDomainUpdate<FieldFrameObservation>.Unchanged
            : RuntimeDomainUpdate<FieldFrameObservation>.Present(field)),
        battleUpdate ?? (battle is null
            ? RuntimeDomainUpdate<BattleFrameObservation>.Unchanged
            : RuntimeDomainUpdate<BattleFrameObservation>.Present(battle)),
        navigationUpdate ?? (navigation is null
            ? RuntimeDomainUpdate<NavigationWorldObservation>.Unchanged
            : RuntimeDomainUpdate<NavigationWorldObservation>.Present(navigation)));
}

