static void AssertNormalizedRuntimeObservationsContainNoNativePointers()
{
    var contractTypes = typeof(RuntimeFrameObservation).Assembly
        .GetExportedTypes()
        .Where(type => type.Namespace == typeof(RuntimeFrameObservation).Namespace);
    var pointerProperties = contractTypes
        .SelectMany(type => type.GetProperties().Select(property => (Type: type, Property: property)))
        .Where(entry => ContainsNativePointer(entry.Property.PropertyType))
        .Select(entry => $"{entry.Type.Name}.{entry.Property.Name}")
        .ToArray();

    AssertEqual(string.Empty, string.Join(", ", pointerProperties), "normalized contracts must not expose native pointers");
}

static bool ContainsNativePointer(Type type)
{
    if (type.IsPointer || type == typeof(IntPtr) || type == typeof(UIntPtr))
    {
        return true;
    }

    return type.IsGenericType && type.GetGenericArguments().Any(ContainsNativePointer);
}

static void AssertPrismBackendOutputIsSerialized()
{
    var activeCalls = 0;
    var maximumConcurrentCalls = 0;
    using var start = new ManualResetEventSlim(false);
    using var speaker = new PrismNativeSpeaker(
        _ => { },
        context: (nint)1,
        backend: (nint)1,
        output: (_, _, _) =>
        {
            var current = Interlocked.Increment(ref activeCalls);
            var observed = Volatile.Read(ref maximumConcurrentCalls);
            while (current > observed)
            {
                var replaced = Interlocked.CompareExchange(ref maximumConcurrentCalls, current, observed);
                if (replaced == observed)
                {
                    break;
                }

                observed = replaced;
            }

            Thread.Sleep(20);
            Interlocked.Decrement(ref activeCalls);
            return PrismError.Ok;
        },
        shutdown: _ => { });

    var calls = Enumerable.Range(0, 12)
        .Select(index => Task.Run(() =>
        {
            start.Wait();
            speaker.Speak($"speech {index}");
        }))
        .ToArray();

    start.Set();
    Task.WaitAll(calls);

    AssertEqual(1, maximumConcurrentCalls, "Prism backend output must be serialized");

    using var unavailable = new PrismNativeSpeaker(
        _ => { },
        context: (nint)1,
        backend: 0,
        output: (_, _, _) => PrismError.Ok,
        shutdown: _ => { });
    AssertEqual(false, unavailable.Speak("not delivered"), "unavailable Prism backend reports failed delivery");

    using var rejected = new PrismNativeSpeaker(
        _ => { },
        context: (nint)1,
        backend: (nint)1,
        output: (_, _, _) => (PrismError)1,
        shutdown: _ => { });
    AssertEqual(false, rejected.Speak("not delivered"), "non-Ok Prism output reports failed delivery");
    AssertEqual(true, speaker.Speak("delivered"), "Prism Ok reports actual delivery");
}

