static void AssertOpeningMovieDescriptionSchedule()
{
    var cues = ReadOpeningMovieCues();
    AssertEqual(17, cues.Count, "opening movie cue count");
    AssertEqual(0, cues[0].Seconds, "first cue start");
    AssertEqual(OpeningMovieDescription.MovieEndSeconds, cues[^1].Seconds, "last movie cue start");
    AssertContains(cues[0].Text, "White pinpoint stars slowly appear");
    AssertContains(cues[4].Text, "wicker basket full of yellow and white flowers");
    AssertContains(cues[12].Text, "FINAL FANTASY VII");
    AssertContains(cues[^1].Text, "Gameplay begins.");
    AssertEqual(false, cues.Any(cue => cue.Seconds > OpeningMovieDescription.MovieEndSeconds), "in-engine scenes must not use movie timers");
}

static void AssertOpeningMovieDescriptionSpeaksTimedCues()
{
    var type = GetOpeningMovieDescriptionType();
    var spoken = new List<string>();
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var description = Activator.CreateInstance(type, (Action<string>)spoken.Add, (Func<DateTime>)(() => now))
        ?? throw new InvalidOperationException("Could not construct OpeningMovieDescription.");

    Invoke(description, "Start");
    AssertEqual(2, spoken.Count, "start speech count");
    AssertContains(spoken[0], "Opening movie audio description started.");
    AssertContains(spoken[1], "White pinpoint stars slowly appear");

    now = now.AddSeconds(7);
    Invoke(description, "Tick");
    AssertEqual(3, spoken.Count, "second cue speech count");
    AssertContains(spoken[^1], "faint green luminescence");

    now = now.AddSeconds(23);
    Invoke(description, "Tick");
    AssertEqual(4, spoken.Count, "third cue speech count");
    AssertContains(spoken[^1], "extreme close-up");
}

static void AssertOpeningMovieDescriptionQueuesTimedCues()
{
    var spoken = new List<(string Text, bool Interrupt)>();
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var description = new OpeningMovieDescription(
        (text, interrupt) => spoken.Add((text, interrupt)),
        () => now);

    description.Start();

    AssertEqual(2, spoken.Count, "queued opening start speech count");
    AssertContains(spoken[0].Text, "Opening movie audio description started.");
    AssertEqual(true, spoken[0].Interrupt, "opening start speech interrupt");
    AssertContains(spoken[1].Text, "White pinpoint stars slowly appear");
    AssertEqual(false, spoken[1].Interrupt, "opening cue speech interrupt");

    now = now.AddSeconds(7);
    description.Tick();

    AssertEqual(3, spoken.Count, "queued second cue speech count");
    AssertContains(spoken[^1].Text, "faint green luminescence");
    AssertEqual(false, spoken[^1].Interrupt, "later opening cue speech interrupt");
}

static void AssertOpeningMovieDescriptionStopsAfterSkip()
{
    var spoken = new List<string>();
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var description = new OpeningMovieDescription(spoken.Add, () => now);

    description.Start();
    AssertEqual(true, description.IsRunning, "opening description should run after start");

    now = now.AddSeconds(10);
    description.Stop();
    AssertEqual(false, description.IsRunning, "opening description should stop when movie is skipped");

    now = now.AddSeconds(130);
    description.Tick();
    AssertEqual(2, spoken.Count, "stopped opening description should not speak later timed cues");
}

