static void AssertOpeningMovieAudioTrackVolumeMatchesFfnxGain()
{
    AssertEqual(3.0f, OpeningMovieAudioTrackVolumePolicy.ToGain(300), "FFNx-equivalent movie voice gain");
    AssertEqual(0.0f, OpeningMovieAudioTrackVolumePolicy.ToGain(0), "muted movie voice gain");
    AssertEqual(0.0f, OpeningMovieAudioTrackVolumePolicy.ToGain(-20), "negative movie voice gain");
    AssertEqual(4.0f, OpeningMovieAudioTrackVolumePolicy.ToGain(900), "bounded movie voice gain");
}

static void AssertFfnxRuntimeDetectorRecognizesDriverModules()
{
    AssertEqual(true, FfnxRuntimeDetector.IsFfnxModule("AF3DN.P", "FFNx"), "Steam FFNx driver module");
    AssertEqual(true, FfnxRuntimeDetector.IsFfnxModule("7H_GameDriver.dll", "FFNx"), "7th Heaven FFNx driver module");
    AssertEqual(true, FfnxRuntimeDetector.IsFfnxModule("FFNx.dll", "FFNx"), "standalone FFNx driver module");
    AssertEqual(false, FfnxRuntimeDetector.IsFfnxModule("AF3DN.P", "Square Enix"), "original game driver");
    AssertEqual(false, FfnxRuntimeDetector.IsFfnxModule("unrelated.dll", "FFNx"), "unrelated FFNx-named product");
}

static void AssertOpeningMoviePathResolverUsesFfnxOverrideOnlyWhenLoaded()
{
    const string root = @"C:\FF7";
    var dataMovie = Path.Combine(root, "data", "movies", "opening.avi");
    var overrideMovie = Path.Combine(root, "override", "movies", "opening.avi");
    Func<string, bool> overrideExists = path => string.Equals(path, overrideMovie, StringComparison.OrdinalIgnoreCase);

    AssertEqual(
        overrideMovie,
        OpeningMoviePathResolver.Resolve(root, ffnxLoaded: true, overrideExists),
        "FFNx should monitor the redirected override movie");
    AssertEqual(
        dataMovie,
        OpeningMoviePathResolver.Resolve(root, ffnxLoaded: false, overrideExists),
        "original renderer should monitor the data movie");
    AssertEqual(
        dataMovie,
        OpeningMoviePathResolver.Resolve(root, ffnxLoaded: true, _ => false),
        "FFNx without an override should monitor the data movie");
}

static void AssertOpeningMovieActivityUsesNativeStateForVirtualFfnxMovies()
{
    AssertEqual(
        OpeningMovieActivitySignal.NativeFieldMovieState,
        OpeningMovieActivityPolicy.Resolve(
            fileHandleActive: false,
            nativeStateReadable: true,
            nativeModule: FieldPositionReader.FieldModule,
            nativeFieldId: DeferredZoneSpeechTracker.OpeningFieldId,
            nativeMovieActive: 1).Signal,
        "virtual FFNx opening movie uses the native field-movie signal");
    AssertEqual(
        OpeningMovieActivitySignal.FileHandle,
        OpeningMovieActivityPolicy.Resolve(
            fileHandleActive: true,
            nativeStateReadable: false,
            nativeModule: 0,
            nativeFieldId: 0,
            nativeMovieActive: 0).Signal,
        "physical opening movie retains file-handle priority");
    AssertEqual(
        OpeningMovieActivitySignal.None,
        OpeningMovieActivityPolicy.Resolve(
            fileHandleActive: false,
            nativeStateReadable: true,
            nativeModule: 5,
            nativeFieldId: DeferredZoneSpeechTracker.OpeningFieldId,
            nativeMovieActive: 1).Signal,
        "stale movie state outside the field module is rejected");
    AssertEqual(
        OpeningMovieActivitySignal.None,
        OpeningMovieActivityPolicy.Resolve(
            fileHandleActive: false,
            nativeStateReadable: true,
            nativeModule: FieldPositionReader.FieldModule,
            nativeFieldId: DeferredZoneSpeechTracker.OpeningFieldId + 1,
            nativeMovieActive: 1).Signal,
        "field movies outside the opening field cannot start opening narration");
    AssertEqual(
        OpeningMovieActivitySignal.None,
        OpeningMovieActivityPolicy.Resolve(
            fileHandleActive: false,
            nativeStateReadable: false,
            nativeModule: FieldPositionReader.FieldModule,
            nativeFieldId: DeferredZoneSpeechTracker.OpeningFieldId,
            nativeMovieActive: 1).Signal,
        "unreadable native movie state fails closed");
    AssertEqual(
        OpeningMovieActivitySignal.None,
        OpeningMovieActivityPolicy.Resolve(
            fileHandleActive: false,
            nativeStateReadable: true,
            nativeModule: FieldPositionReader.FieldModule,
            nativeFieldId: DeferredZoneSpeechTracker.OpeningFieldId,
            nativeMovieActive: 0).Signal,
        "inactive native movie state does not start narration");
}

static void AssertMenuTextRenderDiagnosticsFiltersAndDedupes()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var diagnostics = new MenuTextRenderDiagnostics(TimeSpan.FromSeconds(1), () => now);
    var color = unchecked((int)0xffffffff);

    if (!diagnostics.TryCreateEntry("  CONTINUE\0ignored", 12, 34, color, 0x12345678, out var first))
    {
        throw new InvalidOperationException("Expected first menu text render entry to be accepted.");
    }

    AssertEqual("CONTINUE", first.Text, "normalized menu text");
    AssertEqual(12u, first.X, "menu text x");
    AssertEqual(34u, first.Y, "menu text y");
    AssertEqual(color, first.Color, "menu text color");
    AssertContains(first.ToLogLine(), "text=CONTINUE");
    AssertContains(first.ToLogLine(), "color=0xFFFFFFFF");

    if (diagnostics.TryCreateEntry("CONTINUE", 12, 34, color, 0x12345678, out _))
    {
        throw new InvalidOperationException("Expected duplicate menu text render entry to be suppressed.");
    }

    if (!diagnostics.TryCreateEntry("CONTINUE", 12, 34, unchecked((int)0xff00ffff), 0x12345678, out _))
    {
        throw new InvalidOperationException("Expected changed color to be accepted.");
    }

    now = now.AddSeconds(2);
    if (!diagnostics.TryCreateEntry("CONTINUE", 12, 34, color, 0x12345678, out _))
    {
        throw new InvalidOperationException("Expected duplicate menu text render entry after dedup window to be accepted.");
    }

    if (diagnostics.TryCreateEntry("\0", 12, 34, color, 0x12345678, out _))
    {
        throw new InvalidOperationException("Expected blank menu text render entry to be ignored.");
    }
}

static void AssertRenderedMenuTextSpeechTrackerPrefersHighlightedText()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new RenderedMenuTextSpeechTracker(TimeSpan.FromMilliseconds(80));

    tracker.Observe(new MenuTextRenderEntry("Potion", 40, 70, unchecked((int)0xffffffff), 0x10), now);
    tracker.Observe(new MenuTextRenderEntry("Phoenix Down", 40, 86, unchecked((int)0xff00ffff), 0x10), now);
    AssertNull(tracker.Poll(now.AddMilliseconds(40)), "rendered menu speech should wait for batch to settle");
    AssertEqual("Phoenix Down", tracker.Poll(now.AddMilliseconds(100)), "rendered menu speech should prefer highlighted text");
    AssertNull(tracker.Poll(now.AddMilliseconds(200)), "rendered menu speech should not repeat without a new candidate");

    tracker.Observe(new MenuTextRenderEntry("Potion", 40, 70, unchecked((int)0xffffffff), 0x10), now.AddMilliseconds(300));
    AssertEqual("Potion", tracker.Poll(now.AddMilliseconds(400)), "rendered menu speech should speak later plain text when no highlighted candidate exists");

    tracker.Observe(new MenuTextRenderEntry("Potion", 40, 70, unchecked((int)0xffffffff), 0x10), now.AddMilliseconds(500));
    AssertNull(tracker.Poll(now.AddMilliseconds(600)), "rendered menu speech should suppress duplicate candidates");
}

