static void AssertFf7EncodedFieldTextDecodesForSpeech()
{
    var comeOn = new byte[] { 0x23, 0x4f, 0x4d, 0x45, 0x00, 0x4f, 0x4e, 0xff };
    AssertEqual("Come on", Ff7EncodedTextDecoder.Decode(comeOn), "decoded field text");

    var withControls = new byte[] { 0xea, 0x1a, 0x00, 0x23, 0x4f, 0x4d, 0x45, 0x00, 0x4f, 0x4e, 0x1, 0xe7, 0xfe, 0xd2, 0xff };
    AssertEqual("Cloud: Come on!", Ff7EncodedTextDecoder.Decode(withControls), "decoded field text with controls");

    var commaControl = new byte[] { 0x33, 0x2f, 0x2c, 0x24, 0x29, 0x25, 0x32, 0xe2, 0x48, 0x55, 0x48, 0x1f, 0xff };
    AssertEqual("SOLDIER, huh?", Ff7EncodedTextDecoder.Decode(commaControl), "decoded comma control text");

    var ellipsisControl = new byte[] { 0x4f, 0x56, 0x45, 0x52, 0xa9, 0x29, 0x07, 0x4d, 0xff };
    AssertEqual("over…I'm", Ff7EncodedTextDecoder.Decode(ellipsisControl), "decoded ellipsis control text");

    var controllerButtons = new byte[] { 0xf6, 0x00, 0xf7, 0x00, 0xf8, 0x00, 0xf9, 0xff };
    AssertEqual(
        "[OK] [MENU] [SWITCH] [CANCEL]",
        Ff7EncodedTextDecoder.Decode(controllerButtons),
        "decoded controller glyphs");
}

// A Spanish or French player hears every line of the game through this table, so a wrong entry
// is not a cosmetic fault: it is the difference between "Aeris está aquí" and a string of
// unrelated symbols read out letter by letter. The other decoder tests are all ASCII, which
// leaves the half of the table that only non-English installs reach completely uncovered.
static void AssertFf7EncodedFieldTextDecodesAccentedWesternLetters()
{
    var spanish = Ff7GameLanguages.Get(Ff7GameLanguage.Spanish);

    // "Ñoño: ¿Aeris está aquí? ¡Sí!" - inverted punctuation, tilde and acute accents in both cases.
    var spanishLine = new byte[]
    {
        0x64, 0x4f, 0x76, 0x4f, 0x1a, 0x00, 0xa0, 0x21, 0x45, 0x52, 0x49, 0x53, 0x00, 0x45,
        0x53, 0x54, 0x67, 0x00, 0x41, 0x51, 0x55, 0x72, 0x1f, 0x00, 0xa1, 0x33, 0x72, 0x01, 0xff
    };
    AssertEqual(
        "Ñoño: ¿Aeris está aquí? ¡Sí!",
        Ff7EncodedTextDecoder.DecodeField(spanishLine, spanish),
        "decoded Spanish field text");

    // The same table serves French and German, so a shifted entry would surface there too.
    var french = Ff7GameLanguages.Get(Ff7GameLanguage.French);
    var frenchLine = new byte[] { 0x34, 0x52, 0x6f, 0x53, 0x00, 0x6d, 0x41, 0x00, 0x56, 0x41, 0xff };
    AssertEqual("Très ça va", Ff7EncodedTextDecoder.DecodeField(frenchLine, french), "decoded French field text");

    var german = Ff7GameLanguages.Get(Ff7GameLanguage.German);
    var germanLine = new byte[] { 0x33, 0x54, 0x52, 0x41, 0x87, 0x45, 0xff };
    AssertEqual("Straße", Ff7EncodedTextDecoder.DecodeField(germanLine, german), "decoded German field text");
}

static void AssertFf7EncodedTextRequiresTerminatorForBufferReads()
{
    var platform = new byte[] { 0x30, 0x4c, 0x41, 0x54, 0x46, 0x4f, 0x52, 0x4d, 0xff, 0x00, 0x30, 0x4c };
    AssertEqual("Platform", Ff7EncodedTextDecoder.DecodeTerminated(platform), "terminated field buffer text");

    var staleBuffer = new byte[] { 0x00, 0x00, 0x30, 0x4c, 0x41, 0x54, 0x46, 0x4f, 0x52, 0x4d };
    AssertEqual(string.Empty, Ff7EncodedTextDecoder.DecodeTerminated(staleBuffer), "unterminated field buffer text");
}

static void AssertFf7EncodedAskTextPreservesNativeChoiceLines()
{
    var encoded = new byte[]
    {
        0xea, 0x1a, 0x00, 0x37, 0x48, 0x41, 0x54, 0x00, 0x48, 0x41, 0x50, 0x50, 0x45, 0x4e, 0x45, 0x44, 0x1f,
        0xe7,
        0xe0, 0x22, 0x55, 0x59, 0x00, 0x4f, 0x4e, 0x45,
        0xe7,
        0xe0, 0x26, 0x4f, 0x52, 0x47, 0x45, 0x54, 0x00, 0x49, 0x54,
        0xff
    };

    var lines = Ff7EncodedTextDecoder.DecodeLines(encoded);
    AssertEqual(3, lines.Count, "ASK text line count");
    AssertEqual("Cloud: What happened?", lines[0], "ASK prompt line");
    AssertEqual("Buy one", lines[1], "first ASK choice line");
    AssertEqual("Forget it", lines[2], "second ASK choice line");
