}

static void AssertFf7EncodedAskTextPreservesNativePages()
{
    byte[] encoded =
    [
        0x34, 0x48, 0x45, 0x52, 0x45, 0x07, 0x53, 0x00, 0x4a, 0x55, 0x53, 0x54, 0x00,
        0x4f, 0x4e, 0x45, 0x00, 0x43, 0x4f, 0x4e, 0x44, 0x49, 0x54, 0x49, 0x4f, 0x4e, 0x0e,
        0xe8,
        0x39, 0x4f, 0x55, 0x00, 0x47, 0x4f, 0x54, 0x54, 0x41, 0x00, 0x47, 0x49, 0x56, 0x45,
        0x00, 0x4d, 0x45, 0x00, 0x53, 0x4f, 0x4d, 0x45, 0x00, 0x43, 0x41, 0x53, 0x48, 0x0e,
        0xe7, 0xe0, 0x11, 0x00, 0x47, 0x49, 0x4c,
        0xe7, 0xe0, 0x11, 0x10, 0x00, 0x47, 0x49, 0x4c,
        0xe7, 0xe0, 0x4e, 0x4f, 0x54, 0x48, 0x49, 0x4e, 0x07,
        0xff
    ];

    var pages = Ff7EncodedTextDecoder.DecodePages(encoded);
    AssertEqual(2, pages.Count, "multi-page ASK page count");
    AssertEqual("There's just one condition.", pages[0].Lines[0].Text, "multi-page ASK leading page");
    AssertEqual(
        true,
        FieldAskTextFormatter.TryResolveChoicePage(pages, 1, 3, out var choicePage),
        "native choice range resolves exactly one indented page");
    AssertEqual(
        "You gotta give me some cash.",
        FieldAskTextFormatter.FormatPrompt(choicePage, 1, 3),
        "multi-page ASK prompt uses only the choice page");
    AssertEqual("1 gil", FieldAskTextFormatter.GetChoice(choicePage, 1, 3, 1), "first page-local ASK choice");
    AssertEqual("10 gil", FieldAskTextFormatter.GetChoice(choicePage, 1, 3, 2), "second page-local ASK choice");
    AssertEqual("nothin'", FieldAskTextFormatter.GetChoice(choicePage, 1, 3, 3), "third page-local ASK choice");
    AssertEqual(
        false,
        FieldAskTextFormatter.IsChoicePageVisible(choicePage, "There's just one condition."),
        "leading non-choice page cannot publish the later ASK prompt");
    AssertEqual(
        true,
        FieldAskTextFormatter.IsChoicePageVisible(
            choicePage,
            "You gotta give me some cash. 1 gil 10 gil nothin'"),
        "fully rendered choice page owns ASK prompt and cursor speech");
}

static void AssertInventoryItemReaderReadsNativeSlotWord()
{
    const int slot = 12;
    const int itemId = 7;
    const int quantity = 3;
    var raw = (ushort)((quantity << 9) | itemId);
    var expectedAddress = InventoryItemReader.AddressSavemap + InventoryItemReader.ItemsOffset + (slot * sizeof(ushort));
    var reader = new InventoryItemReader(
        address =>
        {
            AssertEqual(expectedAddress, address, "native inventory item slot address");
            return raw;
        },
        id => id == itemId ? "Phoenix Down" : null);

    if (!reader.TryRead(slot, out var item))
    {
        throw new InvalidOperationException("Expected native inventory item slot to be readable.");
    }

    AssertEqual(slot, item.Slot, "native inventory item slot");
    AssertEqual(itemId, item.ItemId, "native inventory item id");
    AssertEqual(quantity, item.Quantity, "native inventory item quantity");
    AssertEqual(raw, item.Raw, "native inventory raw slot word");
    AssertEqual("Phoenix Down", item.Name, "native inventory item name");
}

static void AssertInventoryItemReaderRejectsEmptyAndInvalidSlots()
{
    var reader = new InventoryItemReader(_ => 0xFFFF);

    if (reader.TryRead(-1, out _))
    {
        throw new InvalidOperationException("Negative inventory slot should be rejected.");
    }

    if (reader.TryRead(InventoryItemReader.SlotCount, out _))
    {
        throw new InvalidOperationException("Out-of-range inventory slot should be rejected.");
    }

    if (reader.TryRead(0, out _))
    {
        throw new InvalidOperationException("Empty native inventory slot should be rejected.");
    }

    var zeroQuantityReader = new InventoryItemReader(_ => 7);
    if (zeroQuantityReader.TryRead(0, out _))
    {
        throw new InvalidOperationException("Zero-quantity native inventory slot should be rejected.");
    }
}

static void AssertInventoryItemReaderDistinguishesStableEmptySlots()
{
    const int slot = 17;
    var slotAddress = InventoryItemReader.AddressSavemap +
        InventoryItemReader.ItemsOffset +
        (slot * sizeof(ushort));
    var memory = new Dictionary<int, byte>
    {
        [slotAddress] = 0xFF,
        [slotAddress + 1] = 0xFF
    };
    var reader = new InventoryItemReader(new DictionaryLegacyAddressSpace(memory));

    AssertEqual(
        true,
        reader.TryReadSlot(slot, out var empty),
        "a stable native 0xFFFF inventory record is a readable slot");
    AssertEqual(true, empty.IsEmpty, "native 0xFFFF inventory record is empty");
    AssertEqual(slot, empty.Slot, "empty inventory slot preserves its native index");
    AssertEqual(false, reader.TryRead(slot, out _), "legacy item-only API still rejects empty slots");

    AssertEqual(
        false,
        new InventoryItemReader(new DictionaryLegacyAddressSpace(new Dictionary<int, byte>()))
            .TryReadSlot(slot, out _),
        "unreadable inventory memory must not be called empty");
    AssertEqual(
        false,
        new InventoryItemReader(new TearingLegacyAddressSpace(memory, (uint)slotAddress))
            .TryReadSlot(slot, out _),
        "a torn 0xFFFF inventory record must remain silent");
}

