static void AssertBattleStateReaderReadsMaskedAllyAndEnemyTargets()
{
    var memory = CreateBattleMemoryWithCloud();
    EnableNativeBattleTargeting(memory);
    var allyBase = BattleStateReader.AddressBattleActors;
    WriteUInt32(memory, allyBase + BattleStateReader.ActorCurrentHpOffset, 300);
    WriteUInt32(memory, allyBase + BattleStateReader.ActorMaxHpOffset, 350);
    WriteUInt16(memory, allyBase + BattleStateReader.ActorCurrentMpOffset, 40);
    WriteUInt16(memory, allyBase + BattleStateReader.ActorMaxMpOffset, 54);
    memory[BattleStateReader.AddressTargetMode] = 5;
    WriteUInt16(memory, BattleStateReader.AddressTargetMask, 1);
    WriteUInt32(memory, BattleStateReader.AddressSelectedTarget, 0);

    var reader = CreateBattleStateReader(memory);
    var ally = reader.ReadTarget();
    AssertEqual(true, ally.IsValid, "masked ally target validity");
    AssertEqual("Cloud", ally.Actor.Name, "masked ally target name");
    AssertEqual(false, ally.Actor.IsEnemy, "masked ally target side");
    AssertEqual(300, ally.Actor.CurrentHp, "masked ally target current HP");

    const int enemyActorIndex = 4;
    const int sceneEnemyIndex = 1;
    WriteUInt16(memory, BattleStateReader.AddressTargetMask, 1 << enemyActorIndex);
    WriteUInt32(memory, BattleStateReader.AddressSelectedTarget, enemyActorIndex);
    WriteUInt16(memory, BattleStateReader.AddressEnemySceneIndexRecords, sceneEnemyIndex);
    WriteFf7Text(
        memory,
        BattleStateReader.AddressEnemyData + sceneEnemyIndex * BattleStateReader.EnemyDataSize,
        "Guard Hound",
        BattleStateReader.EnemyNameLength);
    var enemyBase = BattleStateReader.AddressBattleActors + enemyActorIndex * BattleStateReader.BattleActorSize;
    memory[enemyBase + BattleStateReader.ActorInstanceIdOffset] = sceneEnemyIndex;
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorCurrentHpOffset, 42);
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorMaxHpOffset, 42);

    var enemy = reader.ReadTarget();
    AssertEqual(true, enemy.IsValid, "masked enemy target validity");
    AssertEqual("Guard Hound", enemy.Actor.Name, "masked enemy target name");
    AssertEqual(true, enemy.Actor.IsEnemy, "masked enemy target side");

    WriteUInt16(memory, BattleStateReader.AddressTargetMask, 1 << 5);
    AssertEqual(false, reader.ReadTarget().IsValid, "selected target outside native mask must be silent");
}

static void AssertBattleStateReaderRequiresNativeTargetUiGates()
{
    var memory = CreateBattleMemoryWithCloud();
    var actorBase = BattleStateReader.AddressBattleActors;
    WriteUInt32(memory, actorBase + BattleStateReader.ActorCurrentHpOffset, 300);
    WriteUInt32(memory, actorBase + BattleStateReader.ActorMaxHpOffset, 350);
    memory[BattleStateReader.AddressTargetMode] = 0;
    WriteUInt16(memory, BattleStateReader.AddressTargetMask, 1);
    WriteUInt32(memory, BattleStateReader.AddressSelectedTarget, 0);
    EnableNativeBattleTargeting(memory);

    var reader = CreateBattleStateReader(memory);
    AssertEqual(true, reader.ReadTarget().IsValid, "native target UI baseline");

    memory[BattleStateReader.AddressConfigSettings] = 0;
    AssertEqual(true, reader.ReadTarget().IsValid, "config settings byte must not gate native targeting");

    WriteUInt32(memory, BattleStateReader.AddressBattleMenuTextState, 1);
    AssertEqual(false, reader.ReadTarget().IsValid, "non-target native battle text state must be silent");

    WriteUInt32(memory, BattleStateReader.AddressBattleMenuTextState, 0);
    WriteUInt32(memory, BattleStateReader.AddressTargetInvalid, 1);
    AssertEqual(true, reader.ReadTarget().IsValid, "masked native target should speak while confirmation is temporarily invalid");

    memory[BattleStateReader.AddressTargetInputBlocked] = 1;
    AssertEqual(true, reader.ReadTarget().IsValid, "masked native target should speak while target input is temporarily blocked");
}

