static void AssertBattleStateReaderReadsNativeAbilitySubmenuSelections()
{
    var cases = new[]
    {
        new
        {
            State = (short)6,
            ColumnAddress = BattleStateReader.AddressMagicCursorColumn,
            RowAddress = BattleStateReader.AddressMagicCursorRow,
            ScrollAddress = BattleStateReader.AddressMagicScrollRow,
            Columns = 3,
            RecordAddress = BattleStateReader.AddressMagicRecords,
            LocalEntryId = (byte)27,
            ResolvedEntryId = 27,
            Name = "Fire",
            Mp = (byte)4
        },
        new
        {
            State = (short)4,
            ColumnAddress = BattleStateReader.AddressEnemySkillCursorColumn,
            RowAddress = BattleStateReader.AddressEnemySkillCursorRow,
            ScrollAddress = BattleStateReader.AddressEnemySkillScrollRow,
            Columns = 2,
            RecordAddress = BattleStateReader.AddressEnemySkillRecords,
            LocalEntryId = (byte)10,
            ResolvedEntryId = 0x52,
            Name = "Matra Magic",
            Mp = (byte)8
        },
        new
        {
            State = (short)7,
            ColumnAddress = BattleStateReader.AddressSummonCursorColumn,
            RowAddress = BattleStateReader.AddressSummonCursorRow,
            ScrollAddress = BattleStateReader.AddressSummonScrollRow,
            Columns = 1,
            RecordAddress = BattleStateReader.AddressSummonRecords,
            LocalEntryId = (byte)0,
            ResolvedEntryId = 0x38,
            Name = "Choco/Mog",
            Mp = (byte)14
        }
    };

    foreach (var item in cases)
    {
        var memory = CreateBattleMemoryWithCloud();
        memory[BattleStateReader.AddressMenuWindowStates + item.State] = BattleStateReader.ActiveWindowState;
        var actorBase = BattleStateReader.AddressBattleActors;
        WriteUInt32(memory, actorBase + BattleStateReader.ActorCurrentHpOffset, 314);
        WriteUInt32(memory, actorBase + BattleStateReader.ActorMaxHpOffset, 350);
        WriteUInt16(memory, actorBase + BattleStateReader.ActorCurrentMpOffset, 42);
        WriteUInt16(memory, actorBase + BattleStateReader.ActorMaxMpOffset, 54);
        var selectedColumn = item.Columns == 1 ? 0 : 1;
        WriteUInt32(memory, item.ColumnAddress, (uint)selectedColumn);
        WriteUInt32(memory, item.RowAddress, 1);
        WriteUInt32(memory, item.ScrollAddress, 2);
        var selectedIndex = selectedColumn + 1 * item.Columns + 2 * item.Columns;
        var recordAddress = item.RecordAddress + selectedIndex * BattleStateReader.AbilityRecordSize;
        memory[recordAddress] = item.LocalEntryId;
        memory[recordAddress + BattleStateReader.AbilityMpCostOffset] = item.Mp;

        var reader = CreateBattleStateReader(
            memory,
            abilityId => abilityId == item.ResolvedEntryId ? item.Name : null,
            abilityId => abilityId == item.ResolvedEntryId ? $"{item.Name} description" : null);
        var selection = reader.ReadMenuState(item.State).Selection
            ?? throw new InvalidOperationException($"Expected native battle selection for state {item.State}.");

        AssertEqual(item.ResolvedEntryId, selection.EntryId, $"native battle state {item.State} ability id");
        AssertEqual(item.Name, selection.Name, $"native battle state {item.State} ability name");
        AssertEqual((int?)item.Mp, selection.MpCost, $"native battle state {item.State} MP cost");
    }
}

static void AssertBattleStateReaderReadsStableEmptyMenuSlots()
{
    const short enemySkillState = 4;
    const int enemySkillSlot = 21;
    var memory = CreateBattleMemoryWithCloud();
    memory[BattleStateReader.AddressMenuWindowStates + enemySkillState] =
        BattleStateReader.ActiveWindowState;
    var actorBase = BattleStateReader.AddressBattleActors;
    WriteUInt32(memory, actorBase + BattleStateReader.ActorCurrentHpOffset, 314);
    WriteUInt32(memory, actorBase + BattleStateReader.ActorMaxHpOffset, 350);
    WriteUInt16(memory, actorBase + BattleStateReader.ActorCurrentMpOffset, 42);
    WriteUInt16(memory, actorBase + BattleStateReader.ActorMaxMpOffset, 54);
    WriteUInt32(memory, BattleStateReader.AddressEnemySkillCursorColumn, 1);
    WriteUInt32(memory, BattleStateReader.AddressEnemySkillCursorRow, 10);
    WriteUInt32(memory, BattleStateReader.AddressEnemySkillScrollRow, 0);
    var enemySkillRecord = BattleStateReader.AddressEnemySkillRecords +
        (enemySkillSlot * BattleStateReader.AbilityRecordSize);
    memory[enemySkillRecord] = 0xFF;
    memory[enemySkillRecord + BattleStateReader.AbilityMpCostOffset] = 0;

    var enemySkill = CreateBattleStateReader(memory).ReadMenuState(enemySkillState).Selection
        ?? throw new InvalidOperationException("Expected the stable empty Enemy Skill cell.");
    AssertEqual("Empty slot", enemySkill.Name, "battle Enemy Skill empty cell speech");
    AssertEqual(-1, enemySkill.EntryId, "battle Enemy Skill empty cell has no action id");
    AssertEqual(enemySkillSlot, enemySkill.SlotIndex, "battle Enemy Skill preserves its grid index");

    const short itemState = 5;
    const int itemSlot = 9;
    memory[BattleStateReader.AddressMenuWindowStates + enemySkillState] = 0;
    memory[BattleStateReader.AddressMenuWindowStates + itemState] =
        BattleStateReader.ActiveWindowState;
    WriteUInt32(memory, BattleStateReader.AddressItemCursorRow, itemSlot);
    WriteUInt32(memory, BattleStateReader.AddressItemScrollRow, 0);
    var itemRecord = BattleStateReader.AddressBattleItems +
        (itemSlot * BattleStateReader.ItemRecordSize);
    WriteUInt16(memory, itemRecord, 0xFFFF);
    memory[itemRecord + BattleStateReader.ItemQuantityOffset] = 0;

    var item = CreateBattleStateReader(memory).ReadMenuState(itemState).Selection
        ?? throw new InvalidOperationException("Expected the stable empty battle Item cell.");
    AssertEqual("Empty slot", item.Name, "battle Item empty cell speech");
    AssertEqual(itemSlot, item.SlotIndex, "battle Item empty cell preserves its list index");

    var torn = CreateBattleStateReader(
        memory,
        byteTransform: (address, count, value) =>
            address == itemRecord && count > 1 ? (byte)(value - 1) : value)
        .ReadMenuState(itemState);
    AssertEqual(null, torn.Selection, "a torn battle Item record must remain silent");
}

static void AssertBattleMagicSelectionRejectsUnreadableAndTornState()
{
    const short rendererState = 6;
    var memory = CreateBattleMemoryWithCloud();
    memory[BattleStateReader.AddressMenuWindowStates + rendererState] = BattleStateReader.ActiveWindowState;
    var actorBase = BattleStateReader.AddressBattleActors;
    WriteUInt32(memory, actorBase + BattleStateReader.ActorCurrentHpOffset, 314);
    WriteUInt32(memory, actorBase + BattleStateReader.ActorMaxHpOffset, 350);
    WriteUInt16(memory, actorBase + BattleStateReader.ActorCurrentMpOffset, 42);
    WriteUInt16(memory, actorBase + BattleStateReader.ActorMaxMpOffset, 54);
    WriteUInt32(memory, BattleStateReader.AddressMagicCursorColumn, 1);
    WriteUInt32(memory, BattleStateReader.AddressMagicCursorRow, 1);
    WriteUInt32(memory, BattleStateReader.AddressMagicScrollRow, 2);
    const int selectedIndex = 10;
    var recordAddress = BattleStateReader.AddressMagicRecords +
        selectedIndex * BattleStateReader.AbilityRecordSize;
    memory[recordAddress] = 27;
    memory[recordAddress + BattleStateReader.AbilityMpCostOffset] = 4;

    BattleMenuStateSnapshot Read(Func<int, int, byte, byte>? transform = null) =>
        CreateBattleStateReader(
            memory,
            abilityId => abilityId is 27 or 28 ? "Native spell" : null,
            abilityId => abilityId is 27 or 28 ? "Native description" : null,
            byteTransform: transform)
        .ReadMenuState(rendererState);

    AssertEqual("Native spell", Read().Selection?.Name, "stable native battle Magic selection");

    memory.Remove(recordAddress + BattleStateReader.AbilityMpCostOffset);
    AssertEqual(null, Read().Selection, "unreadable battle Magic MP cost stays silent");
    memory[recordAddress + BattleStateReader.AbilityMpCostOffset] = 4;

    memory.Remove(actorBase + BattleStateReader.ActorCurrentMpOffset + 1);
    AssertEqual(null, Read().Selection, "unreadable battle current MP stays silent");
    WriteUInt16(memory, actorBase + BattleStateReader.ActorCurrentMpOffset, 42);

    memory[recordAddress] = 0xFE;
    AssertEqual(null, Read().Selection, "unresolved native battle Magic id stays silent");
    memory[recordAddress] = 27;

    WriteUInt32(memory, BattleStateReader.AddressMagicCursorColumn, 3);
    WriteUInt32(memory, BattleStateReader.AddressMagicCursorRow, 0);
    WriteUInt32(memory, BattleStateReader.AddressMagicScrollRow, 0);
    var aliasedRecordAddress = BattleStateReader.AddressMagicRecords +
        3 * BattleStateReader.AbilityRecordSize;
    memory[aliasedRecordAddress] = 27;
    memory[aliasedRecordAddress + BattleStateReader.AbilityMpCostOffset] = 4;
    AssertEqual(null, Read().Selection, "out-of-grid battle Magic column cannot alias another native row");
    WriteUInt32(memory, BattleStateReader.AddressMagicCursorColumn, 1);
    WriteUInt32(memory, BattleStateReader.AddressMagicCursorRow, 1);
    WriteUInt32(memory, BattleStateReader.AddressMagicScrollRow, 2);

    WriteUInt32(memory, BattleStateReader.AddressMagicScrollRow, (uint)int.MaxValue);
    AssertEqual(null, Read().Selection, "overflowing battle Magic cursor arithmetic stays silent");
    WriteUInt32(memory, BattleStateReader.AddressMagicScrollRow, 2);

    AssertEqual(
        null,
        Read((address, count, value) => address == recordAddress && count > 1 ? (byte)28 : value).Selection,
        "torn battle Magic spell id stays silent");
    AssertEqual(
        null,
        Read((address, count, value) =>
            address == recordAddress + BattleStateReader.AbilityMpCostOffset && count > 1
                ? (byte)5
                : value).Selection,
        "torn battle Magic MP cost stays silent");
    AssertEqual(
        null,
        Read((address, count, value) =>
            address == actorBase + BattleStateReader.ActorCurrentMpOffset && count > 1
                ? (byte)(value + 1)
                : value).Selection,
        "torn battle current MP stays silent");
    AssertEqual(
        null,
        Read((address, count, value) =>
            address == BattleStateReader.AddressMagicCursorColumn && count > 1
                ? (byte)(value + 1)
                : value).Selection,
        "torn battle Magic cursor stays silent");

    AssertEqual(
        false,
        Read((address, count, value) =>
            address == BattleStateReader.AddressMenuWindowStates + rendererState && count > 1
                ? (byte)0
                : value).IsValid,
        "torn battle Magic window ownership invalidates the frame");
    AssertEqual(
        false,
        Read((address, count, value) =>
            address == BattleStateReader.AddressCurrentActorSlot && count > 1
                ? (byte)1
                : value).IsValid,
        "torn battle Magic party ownership invalidates the frame");

    memory.Remove(BattleStateReader.AddressMenuWindowStates + rendererState);
    AssertEqual(false, Read().IsValid, "unreadable battle Magic window ownership invalidates the frame");
}

