static void AssertBattleStateReaderReadsEncounterActionAndStatusState()
{
    var memory = CreateBattleMemoryWithCloud();
    var partyBase = BattleStateReader.AddressBattleActors;
    WriteUInt32(memory, partyBase + BattleStateReader.ActorCurrentHpOffset, 314);
    WriteUInt32(memory, partyBase + BattleStateReader.ActorMaxHpOffset, 350);
    WriteUInt16(memory, partyBase + BattleStateReader.ActorCurrentMpOffset, 42);
    WriteUInt16(memory, partyBase + BattleStateReader.ActorMaxMpOffset, 54);
    const int enemyActorIndex = 4;
    WriteUInt16(memory, BattleStateReader.AddressEnemySceneIndexRecords, 0);
    WriteFf7Text(memory, BattleStateReader.AddressEnemyData, "Guard Scorpion", BattleStateReader.EnemyNameLength);
    var enemyBase = BattleStateReader.AddressBattleActors + enemyActorIndex * BattleStateReader.BattleActorSize;
    memory[enemyBase + BattleStateReader.ActorInstanceIdOffset] = 0;
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorCurrentHpOffset, 800);
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorMaxHpOffset, 800);
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorStatusMaskOffset, 1u << 3);
    WriteUInt16(memory, BattleStateReader.AddressBattleFormationId, 324);
    memory[BattleStateReader.AddressBattleLayoutType] = 2;

    const int eventIndex = 7;
    memory[BattleStateReader.AddressAnimationEventIndex] = eventIndex;
    var eventAddress = BattleStateReader.AddressAnimationEventQueue + eventIndex * BattleStateReader.AnimationEventSize;
    memory[eventAddress + BattleStateReader.AnimationEventAttackerOffset] = enemyActorIndex;
    memory[eventAddress + BattleStateReader.AnimationEventKindOffset] = BattleStateReader.ActionAnimationEventKind;
    memory[eventAddress + BattleStateReader.AnimationEventCommandOffset] = 0x20;
    WriteUInt16(memory, eventAddress + BattleStateReader.AnimationEventActionOffset, 2);
    WriteUInt16(memory, BattleStateReader.AddressBattleActionTargetMask, 1);
    WriteUInt16(memory, BattleStateReader.AddressSceneAttackIds + 2 * BattleStateReader.SceneAttackIdSize, 0x011A);
    WriteFf7Text(
        memory,
        BattleStateReader.AddressSceneAttackNames + 2 * BattleStateReader.SceneAttackNameLength,
        "Rifle",
        BattleStateReader.SceneAttackNameLength);

    var reader = CreateBattleStateReader(memory);
    var encounter = reader.ReadEncounter();
    AssertEqual(true, encounter.IsValid, "native battle encounter validity");
    AssertEqual(324, encounter.FormationId, "native battle formation id");
    AssertEqual(2, encounter.LayoutType, "native battle layout type");
    AssertEqual("Guard Scorpion", encounter.Enemies.Single().Name, "native encounter enemy name");
    AssertEqual(0u, encounter.Enemies.Single().StatusMask, "unsensed native enemy status is absent from public snapshot");

    var action = reader.ReadCurrentEnemyAction();
    AssertEqual(true, action.IsValid, "native enemy action validity");
    AssertEqual(eventIndex, action.EventIndex, "native animation event index");
    AssertEqual(enemyActorIndex, action.AttackerActorIndex, "native enemy action attacker");
    AssertEqual(0x20, action.CommandId, "native enemy action command");
    AssertEqual(2, action.SceneAttackIndex, "native enemy scene attack slot");
    AssertEqual(0x011A, action.ActionId, "native enemy action id");
    AssertEqual(1, action.TargetMask, "native enemy action target mask");
    AssertEqual("Rifle", action.ActionName, "native scene attack name");

    WriteUInt16(memory, eventAddress + BattleStateReader.AnimationEventActionOffset, BattleStateReader.SceneAttackCount);
    AssertEqual(
        false,
        CreateBattleStateReader(memory, abilityName: _ => "Cure3").ReadCurrentEnemyAction().IsValid,
        "out-of-range enemy scene slots must stay silent instead of falling through to kernel spells");
}

static void AssertBattleStateReaderUsesSceneSlotInsteadOfKernelSpellFallback()
{
    var memory = CreateBattleMemoryWithCloud();
    const int enemyActorIndex = 4;
    WriteUInt16(memory, BattleStateReader.AddressEnemySceneIndexRecords, 0);
    WriteFf7Text(memory, BattleStateReader.AddressEnemyData, "Sweeper", BattleStateReader.EnemyNameLength);
    var enemyBase = BattleStateReader.AddressBattleActors + enemyActorIndex * BattleStateReader.BattleActorSize;
    memory[enemyBase + BattleStateReader.ActorInstanceIdOffset] = 0;
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorCurrentHpOffset, 140);
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorMaxHpOffset, 140);
    memory[BattleStateReader.AddressAnimationEventIndex] = 0;
    memory[BattleStateReader.AddressAnimationEventQueue + BattleStateReader.AnimationEventAttackerOffset] = enemyActorIndex;
    memory[BattleStateReader.AddressAnimationEventQueue + BattleStateReader.AnimationEventKindOffset] =
        BattleStateReader.ActionAnimationEventKind;
    memory[BattleStateReader.AddressAnimationEventQueue + BattleStateReader.AnimationEventCommandOffset] = 0x20;
    WriteUInt16(memory, BattleStateReader.AddressAnimationEventQueue + BattleStateReader.AnimationEventActionOffset, 2);
    WriteUInt16(memory, BattleStateReader.AddressSceneAttackIds + 2 * BattleStateReader.SceneAttackIdSize, 0x012A);
    WriteFf7Text(
        memory,
        BattleStateReader.AddressSceneAttackNames + 2 * BattleStateReader.SceneAttackNameLength,
        "Machine Gun",
        BattleStateReader.SceneAttackNameLength);

