    AssertEqual(true, action.IsValid, "native enemy scene action validity");
    AssertEqual(2, action.SceneAttackIndex, "animation queue stores the local scene attack slot");
    AssertEqual(0x012A, action.ActionId, "scene slot should resolve its global attack id");
    AssertEqual("Machine Gun", action.ActionName, "scene slot name must beat the same-numbered kernel spell");
