static void AssertBattleStateReaderRejectsInactiveEnemyActions()
{
    var memory = CreateBattleMemoryWithCloud();
    const int enemyActorIndex = 4;
    WriteUInt16(memory, BattleStateReader.AddressEnemySceneIndexRecords, 0);
    WriteFf7Text(memory, BattleStateReader.AddressEnemyData, "Guard Hound", BattleStateReader.EnemyNameLength);
    var enemyBase = BattleStateReader.AddressBattleActors + enemyActorIndex * BattleStateReader.BattleActorSize;
    memory[enemyBase + BattleStateReader.ActorInstanceIdOffset] = 0;
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorCurrentHpOffset, 42);
    WriteUInt32(memory, enemyBase + BattleStateReader.ActorMaxHpOffset, 42);
    memory[BattleStateReader.AddressAnimationEventIndex] = 0;
    var eventAddress = BattleStateReader.AddressAnimationEventQueue;
    memory[eventAddress + BattleStateReader.AnimationEventAttackerOffset] = enemyActorIndex;
    memory[eventAddress + BattleStateReader.AnimationEventKindOffset] = 0;
    WriteUInt16(memory, eventAddress + BattleStateReader.AnimationEventActionOffset, 0x011A);

    var reader = CreateBattleStateReader(memory);
    AssertEqual(false, reader.ReadCurrentEnemyAction().IsValid, "inactive animation event must be silent");

    memory[eventAddress + BattleStateReader.AnimationEventKindOffset] = BattleStateReader.ActionAnimationEventKind;
    memory[eventAddress + BattleStateReader.AnimationEventAttackerOffset] = 0;
    AssertEqual(false, reader.ReadCurrentEnemyAction().IsValid, "party action must not be reported as an enemy move");

    memory[eventAddress + BattleStateReader.AnimationEventAttackerOffset] = enemyActorIndex;
    memory[eventAddress + BattleStateReader.AnimationEventCommandOffset] = 0x10;
    WriteUInt16(memory, eventAddress + BattleStateReader.AnimationEventActionOffset, 0);
    AssertEqual(false, reader.ReadCurrentEnemyAction().IsValid, "non-enemy-action commands must not be decoded through the scene attack table");

    memory[BattleStateReader.AddressAnimationEventIndex] = BattleStateReader.AnimationEventCount;
    AssertEqual(false, reader.ReadCurrentEnemyAction().IsValid, "out-of-range animation event must be silent");

    memory[BattleStateReader.AddressCurrentModule] = 1;
    AssertEqual(false, reader.ReadEncounter().IsValid, "encounter reader must reject non-battle modules");
}

static void AssertBattleStateReaderDescribesGuardScorpionTailActions()
{
    var memory = CreateBattleMemoryWithCloud();
    const int enemyActorIndex = 4;
