    memory[BattleStateReader.AddressAnimationEventQueue + BattleStateReader.AnimationEventCommandOffset] =
        BattleStateReader.EnemyActionCommandId;
    WriteUInt16(memory, BattleStateReader.AddressSceneAttackIds + tailUpSlot * 2, 0x011F);
    WriteUInt16(memory, BattleStateReader.AddressSceneAttackIds + tailDownSlot * 2, 0x0120);
    WriteFf7Text(
