}

static void AssertBattleStateReaderIgnoresStaleEnemySceneRecords()
{
    var memory = CreateBattleMemoryWithCloud();
    var cloudBase = BattleStateReader.AddressBattleActors;
    WriteUInt32(memory, cloudBase + BattleStateReader.ActorCurrentHpOffset, 314);
    WriteUInt32(memory, cloudBase + BattleStateReader.ActorMaxHpOffset, 350);
    WriteUInt16(memory, BattleStateReader.AddressBattleFormationId, 37);
    memory[BattleStateReader.AddressBattleLayoutType] = 0;

    const int firstEnemy = 4;
    WriteUInt16(memory, BattleStateReader.AddressEnemySceneIndexRecords, 0);
    WriteFf7Text(memory, BattleStateReader.AddressEnemyData, "Custom Sweeper", BattleStateReader.EnemyNameLength);
    var firstEnemyBase = BattleStateReader.AddressBattleActors + firstEnemy * BattleStateReader.BattleActorSize;
    WriteUInt32(memory, firstEnemyBase + BattleStateReader.ActorCurrentHpOffset, 140);
    WriteUInt32(memory, firstEnemyBase + BattleStateReader.ActorMaxHpOffset, 140);

    var reader = CreateBattleStateReader(memory);
    AssertEqual(
        false,
        reader.ReadEncounter().IsValid,
        "a stale scene-index record must not manufacture an active enemy");

    memory[firstEnemyBase + BattleStateReader.ActorInstanceIdOffset] = 0;
    var oneEnemy = reader.ReadEncounter();
    AssertEqual(true, oneEnemy.IsValid, "the game's active actor identity enables the real enemy slot");
    AssertEqual(1, oneEnemy.Enemies.Count, "one active actor identity means one announced enemy");

    const int staleSecondEnemy = 5;
    WriteUInt16(
        memory,
        BattleStateReader.AddressEnemySceneIndexRecords + BattleStateReader.EnemySceneIndexRecordSize,
        0);
    var secondEnemyBase = BattleStateReader.AddressBattleActors + staleSecondEnemy * BattleStateReader.BattleActorSize;
    WriteUInt32(memory, secondEnemyBase + BattleStateReader.ActorCurrentHpOffset, 140);
    WriteUInt32(memory, secondEnemyBase + BattleStateReader.ActorMaxHpOffset, 140);
    AssertEqual(
        1,
        reader.ReadEncounter().Enemies.Count,
        "a second stale scene record must not inflate the encounter count");
}

static void AssertBattleEncounterSpeaksFormationAndEnemiesOnce()
{
    var tracker = new BattleEncounterSpeechTracker();
    var enemies = new[]
    {
        new BattleActorSnapshot(4, "Guard Hound", true, 42, 42, 0, 0, false),
        new BattleActorSnapshot(5, "MP", true, 30, 30, 0, 0, false)
    };
    var encounter = new BattleEncounterSnapshot(true, 12, 2, enemies);

    tracker.Observe(encounter);
    AssertEqual("Back attack. Enemies: Guard Hound and MP.", tracker.Poll(), "native back-attack introduction");
    tracker.Observe(encounter);
    AssertNull(tracker.Poll(), "unchanged encounter must speak only once");

    tracker.Reset();
    tracker.Observe(new BattleEncounterSnapshot(true, 12, 0, enemies));
    AssertEqual("Battle. Enemies: Guard Hound and MP.", tracker.Poll(), "normal encounter introduction");
}

static void AssertBattleEnemyActionSpeaksOnlyVerifiedNativeMoveOnce()
{
    var tracker = new BattleEnemyActionSpeechTracker();
    var actors = new[]
    {
        new BattleActorSnapshot(0, "Cloud", false, 300, 350, 40, 54, true),
        new BattleActorSnapshot(4, "Guard Scorpion", true, 800, 800, 0, 0, false)
    };
    var action = new BattleEnemyActionSnapshot(true, 7, 4, 0x20, 2, 0x011A, 1, "Rifle", null);

    tracker.Observe(action, actors);
    AssertEqual("Guard Scorpion used Rifle.", tracker.Poll(), "enemy action speech must omit an unverified target mask");
    tracker.Observe(action, actors);
    AssertNull(tracker.Poll(), "same native animation event must not repeat");

    tracker.Observe(action with { EventIndex = 8 }, actors);
    AssertEqual("Guard Scorpion used Rifle.", tracker.Poll(), "new queue event may repeat an attack");

    tracker.Observe(
        action with
        {
            EventIndex = 9,
            ActionName = null,
            AccessibilityDescription = "Guard Scorpion raises its tail."
        },
        actors);
    AssertEqual("Guard Scorpion raises its tail.", tracker.Poll(), "semantic enemy action speech");
}

static void AssertBattleEnemyActionAllowsSameMoveAfterNativeEventEnds()
{
    var tracker = new BattleEnemyActionSpeechTracker();
    var actors = new[]
    {
        new BattleActorSnapshot(4, "Sweeper", true, 140, 140, 0, 0, false)
    };
    var action = new BattleEnemyActionSnapshot(true, 0, 4, 0x20, 2, 0x012A, 0, "Machine Gun", null);

    tracker.Observe(action, actors);
    AssertEqual("Sweeper used Machine Gun.", tracker.Poll(), "first native enemy action");
    tracker.Observe(BattleEnemyActionSnapshot.Invalid, actors);
    tracker.Observe(action, actors);
    AssertEqual("Sweeper used Machine Gun.", tracker.Poll(), "same queue slot may speak again after the native event ends");
}

static void AssertBattleStatusSpeaksGainsAndRemovals()
{
    var tracker = new BattleStatusSpeechTracker();
    var cloud = new BattleActorSnapshot(0, "Cloud", false, 300, 350, 40, 54, true);

    tracker.Observe([cloud with { StatusMask = 1u << 3 }]);
    AssertEqual("Cloud was poisoned.", tracker.Poll(), "initial native poison status");
    tracker.Observe([cloud with { StatusMask = 1u << 3 }]);
    AssertNull(tracker.Poll(), "unchanged status must not repeat");

    tracker.Observe([cloud with { StatusMask = (1u << 3) | (1u << 8) }]);
    AssertEqual("Cloud gained Haste.", tracker.Poll(), "native haste gain");

    tracker.Observe([cloud with { StatusMask = 1u << 8 }]);
    AssertEqual("Cloud's poison cleared.", tracker.Poll(), "native poison removal");

    tracker.Observe([cloud with { StatusMask = 0 }]);
    AssertEqual("Cloud's Haste wore off.", tracker.Poll(), "native haste removal");
}

static void AssertBattleStatusRequiresTrustedVisibleDefeatCorrelation()
{
    var tracker = new BattleStatusSpeechTracker();
    var ray = new BattleActorSnapshot(4, "1st Ray", true, 18, 18, 0, 0, false);

    tracker.Observe([ray]);
    AssertNull(tracker.Poll(), "initial living actor should be silent");

    var defeated = ray with { CurrentHp = 0, StatusMask = 1u };
    tracker.Observe([defeated]);
    AssertNull(tracker.Poll(), "unsensed public enemy status remains silent");

    var finalDamage = new BattleDamagePopupSnapshot(true, 12, 4, 18, 0);
    tracker.ConfirmDamage(finalDamage, defeated);
    AssertNull(tracker.Poll(), "public redacted snapshot cannot confirm an enemy defeat");

    tracker.ConfirmVisibleDamageOutcome(
        finalDamage,
        new BattleActorVisibleCorrelation(4, "1st Ray", true, false));
    AssertNull(tracker.Poll(), "nonlethal trusted correlation remains silent");

    var visibleDefeat = new BattleActorVisibleCorrelation(4, "1st Ray", true, true);
    tracker.ConfirmVisibleDamageOutcome(finalDamage, visibleDefeat);
    AssertEqual("1st Ray was defeated.", tracker.Poll(), "trusted lethal popup correlation confirms visible defeat");

    tracker.ConfirmVisibleDamageOutcome(finalDamage, visibleDefeat);
    AssertNull(tracker.Poll(), "the same defeated actor must not repeat");

    tracker.Observe([ray]);
    AssertNull(tracker.Poll(), "redacted enemy status cannot synthesize a revival");
}

static void AssertBattleResultsReaderReadsNativeRewards()
{
    var memory = new Dictionary<int, byte>();
    memory[BattleResultsReader.AddressCurrentModule] = BattleResultsReader.ResultsModule;
    WriteUInt32(memory, BattleResultsReader.AddressHasRewardItems, 1);
    WriteUInt32(memory, BattleResultsReader.AddressRewardSelection, 0);
    WriteUInt16(memory, BattleResultsReader.AddressRewardTransition, 0);
    memory[BattleResultsReader.AddressResultsPageReady] = 1;
    WriteUInt32(memory, BattleResultsReader.AddressResultsState, 0);
    WriteUInt32(memory, BattleResultsReader.AddressExperience, 125);
    WriteUInt32(memory, BattleResultsReader.AddressAp, 8);
    WriteUInt32(memory, BattleResultsReader.AddressGil, 96);
    WriteUInt32(memory, BattleResultsReader.AddressInputEdges, 0);
    WriteUInt32(memory, BattleResultsReader.AddressInputRepeat, 0);
    WriteUInt32(memory, BattleResultsReader.AddressHeldInput, 0);
    for (var index = 0; index < BattleResultsReader.RewardItemCount; index++)
    {
        var address = BattleResultsReader.AddressRewardItems + index * BattleResultsReader.RewardItemSize;
        WriteUInt16(memory, address, ushort.MaxValue);
        WriteUInt16(memory, address + 2, 0);
        WriteUInt16(memory, address + BattleResultsReader.RewardSelectedOffset, 0);
    }
    WriteUInt16(memory, BattleResultsReader.AddressRewardItems, 7);
    WriteUInt16(memory, BattleResultsReader.AddressRewardItems + 2, 2);
    WriteUInt16(memory, BattleResultsReader.AddressRewardItems + 4, 1);

    var snapshot = CreateBattleResultsReader(memory).Read();

    AssertEqual(true, snapshot.IsValid, "native battle results validity");
    AssertEqual(125, snapshot.Experience, "native battle result EXP");
    AssertEqual(8, snapshot.Ap, "native battle result AP");
    AssertEqual(96, snapshot.Gil, "native battle result gil");
    AssertEqual(1, snapshot.Items.Count, "native battle reward item count");
    AssertEqual("Phoenix Down", snapshot.Items[0].Name, "native battle reward item name");
    AssertEqual(2, snapshot.Items[0].Quantity, "native battle reward item quantity");
    AssertEqual(0, snapshot.Items[0].PhysicalSlot, "native physical reward slot");
    AssertEqual(true, snapshot.Items[0].IsSelectedToTake, "native selected-to-take flag");
}

static void AssertBattleResultsReaderRejectsInvalidStateAndRewardRecords()
{
    var memory = new Dictionary<int, byte>();
