static void AssertBattleResultsReaderReadsStablePageStateAndInventoryRewards()
{
    var memory = new Dictionary<int, byte>();
    memory[BattleResultsReader.AddressCurrentModule] = BattleResultsReader.ResultsModule;
    WriteUInt32(memory, BattleResultsReader.AddressHasRewardItems, 1);
    WriteUInt32(memory, BattleResultsReader.AddressRewardSelection, 0);
    WriteUInt16(memory, BattleResultsReader.AddressRewardTransition, 0);
    memory[BattleResultsReader.AddressResultsPageReady] = 0;
    WriteUInt32(memory, BattleResultsReader.AddressResultsState, 0);
    WriteUInt32(memory, BattleResultsReader.AddressExperience, 125);
    WriteUInt32(memory, BattleResultsReader.AddressAp, 8);
    WriteUInt32(memory, BattleResultsReader.AddressGil, 96);
    WriteUInt32(memory, BattleResultsReader.AddressInputEdges, 0);
    WriteUInt32(memory, BattleResultsReader.AddressInputRepeat, 0);
    WriteUInt32(memory, BattleResultsReader.AddressHeldInput, 0);

    var names = new Dictionary<int, string>
    {
        [0] = "Potion",
        [128] = "Buster Sword",
        [256] = "Bronze Bangle",
        [288] = "Power Wrist"
    };
    var ids = names.Keys.ToArray();
    for (var index = 0; index < ids.Length; index++)
    {
        var address = BattleResultsReader.AddressRewardItems + index * BattleResultsReader.RewardItemSize;
        WriteUInt16(memory, address, (ushort)ids[index]);
        WriteUInt16(memory, address + 2, 1);
        WriteUInt16(memory, address + BattleResultsReader.RewardSelectedOffset, 0);
    }

    var reader = CreateBattleResultsReader(
        memory,
        objectId => names.TryGetValue(objectId, out var name) ? name : null);
    AssertEqual(false, reader.Read().IsPageReady, "sliding native result page state");

    memory[BattleResultsReader.AddressResultsPageReady] = 1;
    var snapshot = reader.Read();

    AssertEqual(true, snapshot.IsPageReady, "native result page ready state");
    AssertEqual(
        "Potion,Buster Sword,Bronze Bangle,Power Wrist",
        string.Join(',', snapshot.Items.Select(item => item.Name)),
        "battle rewards must resolve consumables, weapons, armor, and accessories");
}

static void AssertBattleResultsReaderReadsRewardMenuOwnership()
{
    var memory = new Dictionary<int, byte>();
    memory[BattleResultsReader.AddressCurrentModule] = BattleResultsReader.ResultsModule;
    memory[BattleResultsReader.AddressResultsPageReady] = 1;
    WriteUInt32(memory, BattleResultsReader.AddressResultsState, 2);
    WriteUInt32(memory, BattleResultsReader.AddressExperience, 125);
    WriteUInt32(memory, BattleResultsReader.AddressAp, 8);
    WriteUInt32(memory, BattleResultsReader.AddressGil, 96);
    WriteUInt32(memory, BattleResultsReader.AddressHasRewardItems, 1);
    WriteUInt32(memory, BattleResultsReader.AddressRewardSelection, 1);
    WriteUInt16(memory, BattleResultsReader.AddressRewardTransition, 0);
    WriteUInt32(memory, BattleResultsReader.AddressInputEdges, 0x4000);
    WriteUInt32(memory, BattleResultsReader.AddressInputRepeat, 2);
    WriteUInt32(memory, BattleResultsReader.AddressHeldInput, 0x20);
    for (var index = 0; index < BattleResultsReader.RewardItemCount; index++)
    {
        var address = BattleResultsReader.AddressRewardItems + index * BattleResultsReader.RewardItemSize;
        WriteUInt16(memory, address, index == 0 ? (ushort)7 : ushort.MaxValue);
        WriteUInt16(memory, address + 2, index == 0 ? (ushort)2 : (ushort)0);
        WriteUInt16(memory, address + BattleResultsReader.RewardSelectedOffset, index == 0 ? (ushort)1 : (ushort)0);
    }

    var snapshot = CreateBattleResultsReader(memory).Read();
    AssertEqual(true, snapshot.IsValid, "stable reward menu ownership");
    AssertEqual(true, snapshot.HasRewardItems, "native has-items flag");
    AssertEqual(1, snapshot.RewardSelection, "native reward cursor");
    AssertEqual((short)0, snapshot.RewardTransition, "settled reward panel transition");
    AssertEqual(0x4000, snapshot.InputEdges, "native reward directional edge");
    AssertEqual(2, snapshot.InputRepeat, "native reward repeat mask");
    AssertEqual(0x20, snapshot.HeldInput, "native reward held confirm");
    AssertEqual(true, snapshot.Items.Single().IsSelectedToTake, "reward disposition from record offset four");
}

