static void AssertBattleStateReaderReadsRootCommandFromNativeGrid()
{
    var memory = CreateBattleMemoryWithCloud();
    WriteUInt32(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorCurrentHpOffset, 314);
    WriteUInt32(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorMaxHpOffset, 350);
    WriteUInt16(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorCurrentMpOffset, 42);
    WriteUInt16(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorMaxMpOffset, 54);
    WriteUInt32(memory, BattleStateReader.AddressRootCommandColumn, 0);
    WriteUInt32(memory, BattleStateReader.AddressRootCommandRow, 0);
    memory[BattleStateReader.AddressRootCommandColumnCount] = 1;
    memory[BattleStateReader.AddressRootCommandRecords] = 1;

    var snapshot = CreateBattleStateReader(
        memory,
        commandName: commandId => commandId == 1 ? "Attack" : null).ReadMenuState(1);

    AssertEqual(true, snapshot.IsValid, "native root command snapshot");
    AssertEqual("Attack", snapshot.Selection?.Name, "native root command name");
}

static void AssertBattleStateReaderReadsNativeSideCommands()
{
