    WriteUInt32(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorCurrentHpOffset, 314);
    WriteUInt32(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorMaxHpOffset, 350);
    WriteUInt16(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorCurrentMpOffset, 42);
    WriteUInt16(memory, BattleStateReader.AddressBattleActors + BattleStateReader.ActorMaxMpOffset, 54);
    memory[BattleStateReader.AddressMenuWindowStates + 2] = BattleStateReader.ActiveWindowState;
    memory[BattleStateReader.AddressMenuWindowStates + 3] = BattleStateReader.ActiveWindowState;

    string? ResolveCommand(int commandId) => commandId switch
    {
        18 => "Change",
        19 => "Defend",
        _ => null
    };

    var reader = CreateBattleStateReader(memory, commandName: ResolveCommand);
    var change = reader.ReadMenuState(2);
    var defend = reader.ReadMenuState(3);

    AssertEqual(18, change.Selection?.EntryId, "native Change command id");
    AssertEqual("Change", change.Selection?.Name, "native Change command name");
    AssertEqual(19, defend.Selection?.EntryId, "native Defend command id");
    AssertEqual("Defend", defend.Selection?.Name, "native Defend command name");

    var coordinator = new BattleMenuFrameSpeechCoordinator();
    coordinator.BeginFrame(2);
    coordinator.CompleteFrame(change);
    AssertEqual("Cloud. Change", coordinator.Poll(), "native Change side command speech");
    coordinator.BeginFrame(3);
    coordinator.CompleteFrame(defend);
    AssertEqual("Defend", coordinator.Poll(), "native Defend side command speech");
}

