static void AssertTifaSlotResultsSpeakWhenEachNativeReelSettles()
{
    var memory = new Dictionary<int, byte>
    {
        [TifaSlotResultReader.AddressCurrentModule] = BattleStateReader.BattleModule,
        [TifaSlotResultReader.AddressReelCount] = 3
    };

    var themes = new byte[] { 0, 1, 3 };
    for (var reel = 0; reel < 3; reel++)
    {
        memory[TifaSlotResultReader.AddressReelThemes + reel] = themes[reel];
        WriteUInt16(memory, TifaSlotResultReader.AddressReelPositions + (reel * 2), 4);
        memory[TifaSlotResultReader.AddressReelStopped + reel] = 0;
        memory[TifaSlotResultReader.AddressResultTable + (themes[reel] * 16) + 1] =
            reel switch
            {
                0 => 1,
                1 => 2,
                _ => 0
            };
    }

    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0xFF;
    ushort ReadUInt16Value(int address) =>
        (ushort)(ReadByte(address) | (ReadByte(address + 1) << 8));

    var reader = new TifaSlotResultReader(ReadByte, ReadUInt16Value);
    var tracker = new TifaSlotSpeechTracker();
    tracker.Observe(reader.Read());
    AssertNull(tracker.Poll(), "unstopped Tifa reels stay silent");

    memory[TifaSlotResultReader.AddressReelStopped] = 1;
    WriteUInt16(memory, TifaSlotResultReader.AddressReelPositions, 5);
    tracker.Observe(reader.Read());
    AssertNull(tracker.Poll(), "a stopped but unaligned reel stays silent");

    WriteUInt16(memory, TifaSlotResultReader.AddressReelPositions, 4);
    tracker.Observe(reader.Read());
    AssertNull(tracker.Poll(), "one aligned post-render frame is not enough");
    tracker.Observe(reader.Read());
    AssertEqual("Hit", tracker.Poll(), "first Tifa reel result");
    AssertNull(tracker.Poll(), "first Tifa reel result does not repeat");

    memory[TifaSlotResultReader.AddressReelStopped + 1] = 1;
    memory[TifaSlotResultReader.AddressReelStopped + 2] = 1;
    tracker.Observe(reader.Read());
    AssertNull(tracker.Poll(), "newly stopped reels wait for a confirmed rendered frame");
    tracker.Observe(reader.Read());
    AssertEqual("Yeah!", tracker.Poll(), "second Tifa reel result");
    AssertEqual("Miss", tracker.Poll(), "third Tifa reel result");
    AssertNull(tracker.Poll(), "settled Tifa reels do not repeat");

    tracker.Reset();
    memory[TifaSlotResultReader.AddressCurrentReel] = 3;
    memory[TifaSlotResultReader.AddressCommittedResults] = 1;
    memory[TifaSlotResultReader.AddressCommittedResults + 1] = 2;
    memory[TifaSlotResultReader.AddressCommittedResults + 2] = 0;
    memory[BattleStateReader.AddressMenuWindowStates + 0x1B] =
        BattleStateReader.ActiveWindowState;
    tracker.ObserveCommitted(reader.ReadCommitted());
    AssertNull(tracker.Poll(), "active slot window must reject stale committed results");

    memory[BattleStateReader.AddressMenuWindowStates + 0x1B] = 3;
    tracker.ObserveCommitted(reader.ReadCommitted());
    AssertEqual("Hit", tracker.Poll(), "committed first-reel fallback");
    AssertEqual("Yeah!", tracker.Poll(), "committed second-reel fallback");
    AssertEqual("Miss", tracker.Poll(), "committed final-reel fallback");
    AssertNull(tracker.Poll(), "committed Tifa fallback does not add extra results");
}

