static void AssertBattleRuntimeTextReadsResolvedStealItem()
{
    var memory = new Dictionary<int, byte>();
    const int slot = 3;
    const ushort offset = 0x20;
    WriteUInt16(
        memory,
        BattleRuntimeTextReader.AddressRuntimeTextOffsets + slot * sizeof(ushort),
        offset);

    var address = BattleRuntimeTextReader.AddressRuntimeTextBuffer + offset;
    var encoded = new byte[]
    {
        (byte)('S' - 0x20),
        (byte)('t' - 0x20),
        (byte)('o' - 0x20),
        (byte)('l' - 0x20),
        (byte)('e' - 0x20),
        0,
        BattleRuntimeTextReader.ItemNameControl,
        0,
        3,
        0,
        0xFF
    };
    for (var index = 0; index < encoded.Length; index++)
    {
        memory[address + index] = encoded[index];
    }

    var reader = new BattleRuntimeTextReader(
        new DictionaryLegacyAddressSpace(memory),
        id => id == 48 ? "Couldn't steal anything." : null,
        id => id == 3 ? "Ether" : null);

    AssertEqual("Stole Ether", reader.Resolve(0x100 + slot), "native dynamic Steal result");
    AssertEqual("Couldn't steal anything.", reader.Resolve(48), "static Steal failure result");
    AssertNull(reader.Resolve(0x140), "out-of-range dynamic battle text slot");
}

