static void AssertBattleResultsReadsBothRewardPanesAndLiveSelection()
{
    var tracker = new BattleResultsSpeechTracker();
    tracker.ObserveBattleProgress([new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    var unselected = new BattleRewardItemSnapshot(7, 2, "Phoenix Down", 0, false);
    var potion = new BattleRewardItemSnapshot(0, 1, "Potion", 2, true);

    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            0,
            125,
            8,
            96,
            [unselected, potion],
            true,
            true,
            0,
            0),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    _ = tracker.Poll();

    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            2,
            125,
            8,
            40,
            [unselected, potion],
            true,
            true,
            0,
            0),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    AssertEqual(
        "96 gil. Items available: Phoenix Down x2, Potion x1. Items selected: Potion x1. Take everything.",
        tracker.Poll(),
        "both native reward panes and take-everything focus at entry");

    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            2,
            125,
            8,
            40,
            [unselected, potion],
            true,
            true,
            1,
            0,
            InputEdges: 0x4000),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    var rowFocus = tracker.PollSpeech()
        ?? throw new InvalidOperationException("Expected live reward row focus speech.");
    AssertEqual("Phoenix Down x2. Not selected.", rowFocus.Text, "reward row focus state");
    AssertEqual(true, rowFocus.Interrupt, "live reward row replaces stale menu speech");

    var selected = unselected with { IsSelectedToTake = true };
    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            2,
            125,
            8,
            40,
            [selected, potion],
            true,
            true,
            1,
            0,
            HeldInput: 0x20),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    AssertEqual("Phoenix Down x2. Selected to take.", tracker.Poll(), "live selected-pane update");

    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            2,
            125,
            8,
            40,
            [selected, potion],
            true,
            true,
            5,
            0,
            InputEdges: 0x4000),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    AssertEqual("Exit.", tracker.Poll(), "native reward Exit row");

    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            2,
            125,
            8,
            40,
            [selected, potion],
            true,
            true,
            1,
            0,
            InputEdges: 0x4000),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            2,
            125,
            8,
            40,
            [selected, potion],
            true,
            true,
            0,
            0,
            InputEdges: 0x1000),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    AssertEqual("Take everything.", tracker.Poll(), "rapid reward movement keeps only the newest focus");
    AssertNull(tracker.Poll(), "superseded reward focus must not backlog");

    tracker.ObserveResults(
        new BattleResultsSnapshot(
            true,
            2,
            125,
            8,
            40,
            [selected, potion],
            true,
            true,
            0,
            1),
        [new BattlePartyProgressSnapshot(0, 0, "Cloud", 7)]);
    AssertNull(tracker.Poll(), "sliding reward panel remains silent");
}

