static void AssertBattleDamagePopupReaderReadsOnlyFirstFrameNativePopups()
{
    var memory = new Dictionary<int, byte>();
    memory[BattleDamagePopupReader.AddressCurrentModule] = BattleStateReader.BattleModule;
    WriteUInt16(memory, BattleDamagePopupReader.AddressCurrentEffectIndex, 5);
    var record = BattleDamagePopupReader.AddressEffectData + 5 * BattleDamagePopupReader.EffectRecordSize;
    memory[record + BattleDamagePopupReader.StateOffset] = 0;
    WriteUInt16(memory, record + BattleDamagePopupReader.ValueOffset, 12);
    WriteUInt32(memory, record + BattleDamagePopupReader.TargetActorOffset, 0);
    WriteUInt32(memory, record + BattleDamagePopupReader.FlagsOffset, 0);

    var reader = CreateBattleDamagePopupReader(memory);
    var popup = reader.Read();
    AssertEqual(true, popup.IsValid, "first-frame native damage popup");
    AssertEqual(0, popup.TargetActor, "native damage target actor");
    AssertEqual(12, popup.Value, "native displayed damage value");

    memory[record + BattleDamagePopupReader.StateOffset] = 1;
    AssertEqual(false, reader.Read().IsValid, "later popup frames must be silent");
    WriteUInt16(memory, BattleDamagePopupReader.AddressCurrentEffectIndex, BattleDamagePopupReader.EffectCount);
    AssertEqual(false, reader.Read().IsValid, "out-of-range native effect index");

    WriteUInt16(memory, BattleDamagePopupReader.AddressCurrentEffectIndex, 5);
    memory[record + BattleDamagePopupReader.StateOffset] = 0;
    WriteUInt16(memory, record + BattleDamagePopupReader.ValueOffset, unchecked((ushort)-1));
    AssertEqual(true, reader.Read().IsMiss, "native miss popup");
}

static void AssertBattleDamageSpeechReportsDamageAndRecovery()
{
    var tracker = new BattleDamageSpeechTracker();
    tracker.SeedActors([new BattleActorSnapshot(0, "Cloud", false, 300, 350, 40, 54, true)]);

    tracker.Observe(
        new BattleDamagePopupSnapshot(true, 0, 0, 12, 0),
        new BattleActorSnapshot(0, "Cloud", false, 288, 350, 40, 54, true));
    AssertEqual("Cloud took 12 damage.", tracker.Poll(), "party HP damage speech");

    tracker.Observe(
        new BattleDamagePopupSnapshot(true, 1, 0, 12, 4),
        new BattleActorSnapshot(0, "Cloud", false, 300, 350, 40, 54, true));
    AssertEqual("Cloud recovered 12 HP.", tracker.Poll(), "native HP restoration speech");

    tracker.Observe(
        new BattleDamagePopupSnapshot(true, 2, 0, 10, 4),
        new BattleActorSnapshot(0, "Cloud", false, 300, 350, 50, 54, true));
    AssertEqual("Cloud recovered 10 MP.", tracker.Poll(), "native MP restoration speech");

    tracker.Observe(
        new BattleDamagePopupSnapshot(true, 3, 0, 7, 0),
        new BattleActorSnapshot(0, "Cloud", false, 293, 350, 40, 54, true));
    AssertEqual("Cloud took 7 damage.", tracker.Poll(), "damage after healing uses refreshed HP baseline");

    var unsensedEnemy = new BattleActorSnapshot(4, "Guard Hound", true, 42, 42, 0, 0, false);
    AssertEqual(0, unsensedEnemy.CurrentHp, "unsensed enemy HP is redacted before damage correlation");
    tracker.SeedActors([unsensedEnemy]);
    tracker.Observe(
        new BattleDamagePopupSnapshot(true, 4, 4, 18, 0),
        new BattleActorSnapshot(4, "Guard Hound", true, 24, 42, 0, 0, false));
    AssertEqual("Guard Hound took 18 damage.", tracker.Poll(), "visible enemy popup value drives damage speech");

    tracker.Observe(
        new BattleDamagePopupSnapshot(true, 5, 4, -1, 0),
        new BattleActorSnapshot(4, "Guard Hound", true, 24, 42, 0, 0, false));
    AssertEqual("Attack missed Guard Hound.", tracker.Poll(), "native miss speech");
}

static void AssertSavemapPartyReaderReadsPartyMemberAndEquipment()
{
    var memory = new Dictionary<int, byte>();
    const int characterId = 0;
    var characterBase = SavemapPartyReader.AddressSavemap + SavemapPartyReader.CharactersOffset + (characterId * SavemapPartyReader.CharacterSize);
    var partyBase = SavemapPartyReader.AddressSavemap + SavemapPartyReader.PartyMembersOffset;
    memory[partyBase] = characterId;
    WriteFf7Text(memory, characterBase + SavemapPartyReader.CharacterNameOffset, "Cloud", 12);
    memory[characterBase + SavemapPartyReader.EquippedWeaponOffset] = 0;
    memory[characterBase + SavemapPartyReader.EquippedArmorOffset] = 1;
    memory[characterBase + SavemapPartyReader.EquippedAccessoryOffset] = 0;

    var reader = new SavemapPartyReader(
        address => memory.TryGetValue(address, out var value) ? value : (byte)0xFF,
        weaponId => weaponId == 0 ? "Buster Sword" : null,
        armorId => armorId == 1 ? "Iron Bangle" : null,
        accessoryId => accessoryId == 0 ? "Power Wrist" : null);

    if (!reader.TryReadPartySlot(0, out var member))
    {
        throw new InvalidOperationException("Expected party member slot to be readable.");
    }

    AssertEqual(characterId, member.CharacterId, "party member character id");
    AssertEqual("Cloud", member.Name, "party member name");

    if (!reader.TryReadEquipment(0, 0, out var weapon))
    {
        throw new InvalidOperationException("Expected weapon slot to be readable.");
    }

    if (!reader.TryReadEquipment(0, 1, out var armor))
    {
        throw new InvalidOperationException("Expected armor slot to be readable.");
    }

    if (!reader.TryReadEquipment(0, 2, out var accessory))
    {
        throw new InvalidOperationException("Expected accessory slot to be readable.");
    }

    AssertEqual("Weapon, Buster Sword", weapon.Text, "native weapon selection text");
    AssertEqual("Armor, Iron Bangle", armor.Text, "native armor selection text");
    AssertEqual("Accessory, Power Wrist", accessory.Text, "native accessory selection text");
}

static void AssertOrderMenuSelectionReadsNativeRowsAndPendingMember()
{
    var memory = new Dictionary<int, byte>();
    var partyBase = SavemapPartyReader.AddressSavemap + SavemapPartyReader.PartyMembersOffset;
    var cloudBase = SavemapPartyReader.AddressSavemap + SavemapPartyReader.CharactersOffset;
    var barretBase = cloudBase + SavemapPartyReader.CharacterSize;
    memory[partyBase] = 0;
    memory[partyBase + 1] = 1;
    WriteFf7Text(memory, cloudBase + SavemapPartyReader.CharacterNameOffset, "Cloud", 12);
    WriteFf7Text(memory, barretBase + SavemapPartyReader.CharacterNameOffset, "Barret", 12);
    memory[cloudBase + SavemapPartyReader.RowFlagsOffset] = 0xFF;
    memory[barretBase + SavemapPartyReader.RowFlagsOffset] = 0xFE;
    WriteUInt32(memory, OrderMenuSelectionReader.AddressSelectionLatch, 0);
    memory[OrderMenuSelectionReader.AddressSelectedPartySlot] = 0;

    var addressSpace = new DictionaryLegacyAddressSpace(memory);
    var reader = new OrderMenuSelectionReader(
        addressSpace,
        new SavemapPartyReader(addressSpace));

    AssertEqual(
        true,
        reader.TryRead(OrderMenuSelectionReader.OrderPartyWidget, 0, out var cloud),
        "Order should read the highlighted party member");
    AssertEqual("Cloud, front row", cloud.Text, "Order should expose Cloud's visible row");

    WriteUInt32(memory, OrderMenuSelectionReader.AddressSelectionLatch, 1);
    AssertEqual(
        true,
        reader.TryRead(OrderMenuSelectionReader.OrderPartyWidget, 0, out var selectedCloud),
        "Order should read the first selected party member");
    AssertEqual(
        "Cloud, front row. Selected. Select Cloud again to change rows, or choose another member to swap",
        selectedCloud.Text,
        "Order should explain how the selected member can change row or swap");

    AssertEqual(
        true,
        reader.TryRead(OrderMenuSelectionReader.OrderPartyWidget, 1, out var barret),
        "Order should retain pending-member context while moving the cursor");
    AssertEqual(
        "Barret, back row. Cloud selected. Select Barret to swap",
        barret.Text,
        "Order should announce both the highlighted row and pending swap");

    WriteUInt32(memory, OrderMenuSelectionReader.AddressSelectionLatch, 0);
    memory[cloudBase + SavemapPartyReader.RowFlagsOffset] = 0xFE;
    AssertEqual(
        true,
        reader.TryRead(OrderMenuSelectionReader.OrderPartyWidget, 0, out var movedCloud),
        "Order should reread the same character after a native row change");
    AssertEqual("Cloud, back row", movedCloud.Text, "Order should announce the completed row change");
}

