static void AssertSavemapPartyReaderReadsNativeStatusSummary()
{
    var memory = new Dictionary<int, byte>();
    const int partySlot = 0;
    const int characterId = 0;
    var characterBase = SavemapPartyReader.AddressSavemap + SavemapPartyReader.CharactersOffset;
    memory[SavemapPartyReader.AddressSavemap + SavemapPartyReader.PartyMembersOffset] = characterId;
    WriteFf7Text(memory, characterBase + SavemapPartyReader.CharacterNameOffset, "Cloud", 12);
    memory[characterBase + SavemapPartyReader.LevelOffset] = 7;
    memory[characterBase + SavemapPartyReader.LimitLevelOffset] = 1;
    memory[characterBase + SavemapPartyReader.EquippedWeaponOffset] = 0;
    memory[characterBase + SavemapPartyReader.EquippedArmorOffset] = 1;
    memory[characterBase + SavemapPartyReader.EquippedAccessoryOffset] = 0xFF;
    WriteUInt16(memory, characterBase + SavemapPartyReader.CurrentHpOffset, 314);
    WriteUInt16(memory, characterBase + SavemapPartyReader.CurrentMpOffset, 54);
    WriteUInt16(memory, characterBase + SavemapPartyReader.MaxHpOffset, 314);
    WriteUInt16(memory, characterBase + SavemapPartyReader.MaxMpOffset, 54);
    WriteUInt32(memory, characterBase + SavemapPartyReader.ExperienceOffset, 1250);
    WriteUInt32(memory, characterBase + SavemapPartyReader.ExperienceToNextLevelOffset, 550);

    var computedBase = SavemapPartyReader.AddressComputedPartyData +
        (partySlot * SavemapPartyReader.ComputedPartyBlockSize);
    memory[computedBase + SavemapPartyReader.ComputedStrengthOffset] = 17;
    memory[computedBase + SavemapPartyReader.ComputedDexterityOffset] = 8;
    memory[computedBase + SavemapPartyReader.ComputedVitalityOffset] = 14;
    memory[computedBase + SavemapPartyReader.ComputedMagicOffset] = 13;
    memory[computedBase + SavemapPartyReader.ComputedSpiritOffset] = 12;
    memory[computedBase + SavemapPartyReader.ComputedLuckOffset] = 10;
    WriteUInt16(memory, computedBase + SavemapPartyReader.ComputedAttackOffset, 22);
    WriteUInt16(memory, computedBase + SavemapPartyReader.ComputedDefenseOffset, 18);
    WriteUInt16(memory, computedBase + SavemapPartyReader.ComputedMagicAttackOffset, 13);
    WriteUInt16(memory, computedBase + SavemapPartyReader.ComputedMagicDefenseOffset, 12);
    memory[SavemapPartyReader.AddressWeaponAttackPercent] = 96;
    memory[SavemapPartyReader.AddressArmorDefensePercent + SavemapPartyReader.ArmorRecordSize] = 11;
    memory[SavemapPartyReader.AddressArmorMagicDefensePercent + SavemapPartyReader.ArmorRecordSize] = 4;

    var reader = new SavemapPartyReader(
        address => memory.TryGetValue(address, out var value) ? value : (byte)0xFF,
        weaponId => weaponId == 0 ? "Buster Sword" : null,
        armorId => armorId == 1 ? "Bronze Bangle" : null,
        _ => null);

    if (!reader.TryReadStatusSummary(partySlot, out var status))
    {
        throw new InvalidOperationException("Expected native Status summary to be readable.");
    }

    AssertEqual("Cloud", status.Name, "Status character name");
    AssertEqual(7, status.Level, "Status level");
    AssertEqual(314, status.CurrentHp, "Status current HP");
    AssertEqual(54, status.CurrentMp, "Status current MP");
    AssertEqual(17, status.Strength, "Status computed strength");
    AssertEqual(8, status.Dexterity, "Status computed dexterity");
    AssertEqual(22, status.Attack, "Status computed attack");
    AssertEqual(96, status.AttackPercent, "Status weapon attack percent");
    AssertEqual(13, status.DefensePercent, "Status armor and dexterity defense percent");
    AssertEqual(4, status.MagicDefensePercent, "Status armor magic defense percent");
    AssertEqual("Buster Sword", status.WeaponName, "Status weapon name");
    AssertEqual("Bronze Bangle", status.ArmorName, "Status armor name");
    AssertEqual("None", status.AccessoryName, "Status empty accessory");
}

static void AssertFieldMessageReaderUsesVisibleWindowPage()
{
    var messageData = 0x500000;
    var activeMessage = messageData + 0x40;
    var memory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = messageData,
        [FieldMessageReader.AddressFieldWindowMessagePointers] = activeMessage,
        [FieldMessageReader.AddressFieldWindowStates] = 0
    };

    var texts = new Dictionary<int, string>
    {
        [FieldMessageReader.AddressFieldMessageLineBuffer] = "Sector 1 Station",
        [activeMessage] = "Barret: First page. Second page.",
        [FieldMessageReader.AddressFieldWindowTextBuffers] = "Barret: First page."
    };

    var reader = CreateFieldMessageReader(memory, texts);
    var firstPage = reader.ReadCurrent();

    AssertEqual("window 0", firstPage.Source, "visible field window should be the speech source");
    AssertEqual("Barret: First page.", firstPage.Text, "field speech must not read beyond the visible page");

