}

static void AssertCurrentProcessMemoryTextReaderReadsValidText()
{
    var encoded = new byte[] { 0x23, 0x4f, 0x4d, 0x45, 0x00, 0x4f, 0x4e, 0xff };
    var address = System.Runtime.InteropServices.Marshal.AllocHGlobal(encoded.Length);
    try
    {
        System.Runtime.InteropServices.Marshal.Copy(encoded, 0, address, encoded.Length);
        AssertEqual(
            "Come on",
            CurrentProcessMemoryTextReader.ReadFf7EncodedText(address.ToInt32(), encoded.Length),
            "safe current-process text read");
    }
    finally
    {
        System.Runtime.InteropServices.Marshal.FreeHGlobal(address);
    }
}

