static void AssertFieldPollingRejectsDialogPointerFallback()
{
    var method = typeof(Mod).GetMethod(
        "SelectCurrentFieldMessageCandidate",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static)
        ?? throw new MissingMethodException(nameof(Mod), "SelectCurrentFieldMessageCandidate");

    var selected = (FieldMessageCandidate?)method.Invoke(
        null,
        [
            new FieldMessageCandidate(
                "dialog pointer",
                "0 @ P ` p 0 @ P ` p Cait Sith Cait Sith Cait Sith"),
            (byte)1
        ]) ?? throw new InvalidOperationException("Field message candidate selection returned null.");

    AssertEqual(string.Empty, selected.Source, "dialog pointer fallback must never become polling speech");
    AssertEqual(string.Empty, selected.Text, "dialog pointer control memory must remain silent");

    var visible = (FieldMessageCandidate?)method.Invoke(
        null,
        [new FieldMessageCandidate("window 2", "Cloud: Not now."), (byte)1])
        ?? throw new InvalidOperationException("Visible field message candidate selection returned null.");
    AssertEqual("window 2", visible.Source, "verified visible window polling source");
    AssertEqual("Cloud: Not now.", visible.Text, "verified visible window polling text");
}

