static void AssertFieldOpcodeAddressResolverUsesFfnxExecuteOpcodeTablePattern()
{
    var memory = new Dictionary<int, int>();
    var bytes = new Dictionary<int, byte>();
    var executeOpcode = 0x00618000;
    var opcodeTable = 0x00990000;
    var waitOpcode = 0x00622000;
    var soundOpcode = 0x0062F100;
    var messageOpcode = 0x00630CAA;
    var askOpcode = 0x00631000;
    var askUpdateLoop = 0x006310A1;

    WriteRelativeCall(bytes, memory, FieldOpcodeAddressResolver.AddressFieldInitEvent + FieldOpcodeAddressResolver.ExecuteOpcodeCallOffset, executeOpcode);
    memory[executeOpcode + FieldOpcodeAddressResolver.ExecuteOpcodeTableOffset] = opcodeTable;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeWaitIndex * sizeof(int)] = waitOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeSoundIndex * sizeof(int)] = soundOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeMessageIndex * sizeof(int)] = messageOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeAskIndex * sizeof(int)] = askOpcode;
    WriteRelativeCall(bytes, memory, askOpcode + FieldOpcodeAddressResolver.AskUpdateLoopCallOffset, askUpdateLoop);

    var resolver = new FieldOpcodeAddressResolver(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0);

    AssertEqual(true, resolver.TryResolve(out var result), "FFNx opcode table resolver should resolve");
    AssertEqual(executeOpcode, result.ExecuteOpcodeAddress, "execute opcode address");
    AssertEqual(opcodeTable, result.OpcodeTableAddress, "opcode table address");
    AssertEqual(waitOpcode, result.WaitOpcodeAddress, "wait opcode address");
    AssertEqual(soundOpcode, result.SoundOpcodeAddress, "sound opcode address");
    AssertEqual(messageOpcode, result.MessageOpcodeAddress, "message opcode address");
    AssertEqual(askOpcode, result.AskOpcodeAddress, "ask opcode address");
    AssertEqual(askUpdateLoop, result.AskUpdateLoopAddress, "ASK native cursor update-loop address");
}

