{
    AssertEqual(typeof(Mod).Assembly, typeof(FieldOpcodeAddressResolver).Assembly, "field opcode address resolver assembly");
    AssertEqual(typeof(Ff7.Accessibility.LegacyLayout.ILegacyAddressSpace).Assembly, typeof(FieldOpcodeParameterReader).Assembly, "field opcode parameter reader assembly");
}

static void AssertFieldOpcodeAddressResolverFollowsFfnxReplacementHandler()
{
    var memory = new Dictionary<int, int>();
    var bytes = new Dictionary<int, byte>();
    var executeOpcode = 0x00618000;
    var opcodeTable = 0x00990000;
    var originalWaitOpcode = 0x00622000;
    var ffnxWaitOpcode = 0x11234000;
    var originalSoundOpcode = 0x0062F100;
    var ffnxSoundOpcode = 0x1123F100;

    WriteRelativeCall(bytes, memory, FieldOpcodeAddressResolver.AddressFieldInitEvent + FieldOpcodeAddressResolver.ExecuteOpcodeCallOffset, executeOpcode);
    memory[executeOpcode + FieldOpcodeAddressResolver.ExecuteOpcodeTableOffset] = opcodeTable;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeWaitIndex * sizeof(int)] = originalWaitOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeSoundIndex * sizeof(int)] = originalSoundOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeMessageIndex * sizeof(int)] = 0x00630CAA;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeAskIndex * sizeof(int)] = 0x00631000;
    WriteRelativeCall(bytes, memory, 0x00631000 + FieldOpcodeAddressResolver.AskUpdateLoopCallOffset, 0x006310A1);

    var resolver = new FieldOpcodeAddressResolver(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0);

    AssertEqual(true, resolver.TryResolve(out var original), "original Steam WAIT handler should resolve");
    AssertEqual(originalWaitOpcode, original.WaitOpcodeAddress, "original Steam WAIT handler address");
    AssertEqual(originalSoundOpcode, original.SoundOpcodeAddress, "original Steam SOUND handler address");

    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeWaitIndex * sizeof(int)] = ffnxWaitOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeSoundIndex * sizeof(int)] = ffnxSoundOpcode;

    AssertEqual(true, resolver.TryResolve(out var replacement), "FFNx replacement opcode handlers should resolve");
    AssertEqual(ffnxWaitOpcode, replacement.WaitOpcodeAddress, "resolver must follow the live FFNx WAIT table entry");
    AssertEqual(ffnxSoundOpcode, replacement.SoundOpcodeAddress, "resolver must follow the live FFNx SOUND table entry");
}

static void AssertFieldOpcodeAddressResolverRefreshesCutsceneHandlersAfterAskHook()
{
    var memory = new Dictionary<int, int>();
    var bytes = new Dictionary<int, byte>();
    const int executeOpcode = 0x00618000;
    const int opcodeTable = 0x00990000;
    const int waitOpcode = 0x11234000;
    const int soundOpcode = 0x1123F100;
    const int askOpcode = 0x00631000;

    WriteRelativeCall(
        bytes,
        memory,
        FieldOpcodeAddressResolver.AddressFieldInitEvent + FieldOpcodeAddressResolver.ExecuteOpcodeCallOffset,
        executeOpcode);
    memory[executeOpcode + FieldOpcodeAddressResolver.ExecuteOpcodeTableOffset] = opcodeTable;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeWaitIndex * sizeof(int)] = waitOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeSoundIndex * sizeof(int)] = soundOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeMessageIndex * sizeof(int)] = 0x00630CAA;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeAskIndex * sizeof(int)] = askOpcode;
    bytes[askOpcode + FieldOpcodeAddressResolver.AskUpdateLoopCallOffset] = 0xCC;

    var resolver = new FieldOpcodeAddressResolver(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0);

    AssertEqual(false, resolver.TryResolve(out _), "full resolver should reject the already-hooked ASK prologue");
    AssertEqual(
        true,
        resolver.TryResolveCutsceneHandlers(out var refreshedWait, out var refreshedSound, out _),
        "cutscene refresh should depend only on the live opcode table");
    AssertEqual(waitOpcode, refreshedWait, "cutscene refresh WAIT handler");
    AssertEqual(soundOpcode, refreshedSound, "cutscene refresh SOUND handler");
}

static void AssertFieldOpcodeAddressResolverKeepsMessageHooksWhenFfnxAskLayoutMoves()
{
    var memory = new Dictionary<int, int>();
    var bytes = new Dictionary<int, byte>();
    const int executeOpcode = 0x00618000;
    const int opcodeTable = 0x00990000;
    const int messageOpcode = 0x11234040;
    const int askOpcode = 0x11234048;

    WriteRelativeCall(
        bytes,
        memory,
        FieldOpcodeAddressResolver.AddressFieldInitEvent + FieldOpcodeAddressResolver.ExecuteOpcodeCallOffset,
        executeOpcode);
    memory[executeOpcode + FieldOpcodeAddressResolver.ExecuteOpcodeTableOffset] = opcodeTable;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeMessageIndex * sizeof(int)] = messageOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeAskIndex * sizeof(int)] = askOpcode;

    // Current FFNx replaces ASK with a longer handler, so the legacy +0x8E
    // location lands in ordinary code rather than at a CALL instruction.
    bytes[askOpcode + FieldOpcodeAddressResolver.AskUpdateLoopCallOffset] = 0xCC;

    var resolver = new FieldOpcodeAddressResolver(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0);

    AssertEqual(
        true,
        resolver.TryResolveMessageHooks(out var resolution),
        "MESSAGE and ASK handlers remain independently usable when the ASK cursor helper moves");
    AssertEqual(messageOpcode, resolution.MessageOpcodeAddress, "FFNx MESSAGE handler address");
    AssertEqual(askOpcode, resolution.AskOpcodeAddress, "FFNx ASK handler address");
    AssertEqual(0, resolution.AskUpdateLoopAddress, "unknown FFNx ASK cursor helper must not be guessed");
    AssertEqual(
        false,
        resolution.HasAskUpdateLoop,
        "moved FFNx ASK cursor helper is optional for MESSAGE accessibility");
}

static void AssertFieldOpcodeAddressResolverFindsAskCursorThroughFfnxVoiceWrapper()
{
    var memory = new Dictionary<int, int>();
    var bytes = new Dictionary<int, byte>();
    const int executeOpcode = 0x00618000;
    const int opcodeTable = 0x00990000;
    const int messageOpcode = 0x11234040;
    const int ffnxAskWrapper = 0x11234048;
    const int ffnxAskWrapperTail = ffnxAskWrapper + 0x2E0;
    const int originalAskPointerSlot = 0x121152EC;
    const int originalAskOpcode = 0x00631000;
    const int ffnxAskOptionParser = 0x11235500;

    WriteRelativeCall(
        bytes,
        memory,
        FieldOpcodeAddressResolver.AddressFieldInitEvent + FieldOpcodeAddressResolver.ExecuteOpcodeCallOffset,
        executeOpcode);
    memory[executeOpcode + FieldOpcodeAddressResolver.ExecuteOpcodeTableOffset] = opcodeTable;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeMessageIndex * sizeof(int)] = messageOpcode;
    memory[opcodeTable + FieldOpcodeAddressResolver.OpcodeAskIndex * sizeof(int)] = ffnxAskWrapper;

    // FFNx 1.24.3's opcode_voice_ask tail pushes the original argument and
    // calls opcode_old_ask through a global function-pointer slot.
    bytes[ffnxAskWrapperTail] = 0xFF;
    bytes[ffnxAskWrapperTail + 1] = 0x75;
    bytes[ffnxAskWrapperTail + 2] = 0x08;
    bytes[ffnxAskWrapperTail + 3] = 0x88;
    bytes[ffnxAskWrapperTail + 4] = 0x58;
    bytes[ffnxAskWrapperTail + 5] = 0x08;
    bytes[ffnxAskWrapperTail + 6] = 0xA1;
    memory[ffnxAskWrapperTail + 7] = originalAskPointerSlot;
    bytes[ffnxAskWrapperTail + 11] = 0xFF;
    bytes[ffnxAskWrapperTail + 12] = 0xD0;
    bytes[ffnxAskWrapperTail + 13] = 0x83;
    bytes[ffnxAskWrapperTail + 14] = 0xC4;
    bytes[ffnxAskWrapperTail + 15] = 0x04;
    bytes[ffnxAskWrapperTail + 16] = 0x5F;
    bytes[ffnxAskWrapperTail + 17] = 0x5E;
    bytes[ffnxAskWrapperTail + 18] = 0x5B;
    bytes[ffnxAskWrapperTail + 19] = 0x8B;
    bytes[ffnxAskWrapperTail + 20] = 0xE5;
    bytes[ffnxAskWrapperTail + 21] = 0x5D;
    bytes[ffnxAskWrapperTail + 22] = 0xC3;
    memory[originalAskPointerSlot] = originalAskOpcode;
    WriteRelativeCall(
        bytes,
        memory,
        originalAskOpcode + FieldOpcodeAddressResolver.AskUpdateLoopCallOffset,
        ffnxAskOptionParser);

    var resolver = new FieldOpcodeAddressResolver(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0);

    AssertEqual(
        true,
        resolver.TryResolveMessageHooks(out var resolution),
        "FFNx-wrapped ASK handler should remain hookable");
    AssertEqual(messageOpcode, resolution.MessageOpcodeAddress, "FFNx MESSAGE handler address");
    AssertEqual(ffnxAskWrapper, resolution.AskOpcodeAddress, "FFNx ASK wrapper address");
    AssertEqual(
        ffnxAskOptionParser,
        resolution.AskUpdateLoopAddress,
        "FFNx option parser must supply the live highlighted choice");
    AssertEqual(
        originalAskOpcode,
        resolution.OriginalAskOpcodeAddress,
        "FFNx wrapper resolution must retain the original ASK handler for direct-call capture");
    AssertEqual(true, resolution.HasAskUpdateLoop, "FFNx ASK cursor helper should resolve through opcode_old_ask");
}

static void AssertFieldOpcodeAddressResolverResolvesArbitraryHandlers()
{
    var memory = new Dictionary<int, int>();
    var bytes = new Dictionary<int, byte>();
    const int executeOpcode = 0x00618000;
    const int opcodeTable = 0x00990000;
    const int anime1Opcode = 0x1123A300;
