}

static void AssertFieldOpcodeHookTargetTrackerInstallsEachNativeHandlerOnce()
{
    var tracker = new FieldOpcodeHookTargetTracker();
    const int steamWaitOpcode = 0x00610818;
    const int ffnxWaitOpcode = 0x11234000;

    AssertEqual(true, tracker.NeedsInstall(steamWaitOpcode), "Steam WAIT handler should need its first hook");
    tracker.MarkInstalled(steamWaitOpcode);
    AssertEqual(false, tracker.NeedsInstall(steamWaitOpcode), "Steam WAIT handler must not be hooked twice");
    AssertEqual(true, tracker.NeedsInstall(ffnxWaitOpcode), "changed FFNx WAIT handler should need a hook");
    tracker.MarkInstalled(ffnxWaitOpcode);
    AssertEqual(false, tracker.NeedsInstall(ffnxWaitOpcode), "FFNx WAIT handler must not be hooked twice");
}

