static void AssertFieldAskChoiceSpeechFollowsNativeHighlightedLine()
{
    var tracker = new FieldAskChoiceSpeechTracker();
    var lines = new[] { "Cloud: What happened?", "Buy one", "Forget it" };
    var first = new FieldAskChoiceObservation(true, 134, 2, 1, 1, 2, 1, lines);

    tracker.Observe(first);
    AssertEqual("Buy one", tracker.Poll(), "initial native ASK highlight");
    tracker.Observe(first);
    AssertNull(tracker.Poll(), "unchanged native ASK highlight must not repeat");

    tracker.Observe(first with { CurrentQuestionLine = 2 });
    AssertEqual("Forget it", tracker.Poll(), "changed native ASK highlight");

    tracker.Observe(first with { CurrentQuestionLine = 8 });
    AssertNull(tracker.Poll(), "out-of-range ASK cursor must stay silent");
    tracker.Reset();
    tracker.Observe(first);
    AssertEqual("Buy one", tracker.Poll(), "new ASK lifecycle should speak its initial highlight");
}

static void AssertFieldScriptContextReaderReadsActiveNativeScript()
{
    var script = 0x2B200000;
    var entityId = 6;
    var priority = 3;
    var scriptId = 4;
    var scriptBaseOffset = 0x0500;
    var byteIndex = 0x00A6;
    var absolutePosition = scriptBaseOffset + byteIndex;
    var scriptTableOffsetDwords = 0x20;
    var entityCount = 13;
    var scriptOffsetAddress = script + (scriptTableOffsetDwords << 2) + 0x20 + entityCount * 8 + entityId * 0x40 + scriptId * sizeof(ushort);
    var memory = new Dictionary<int, int>
    {
        [FieldScriptContextReader.AddressCurrentModule] = FieldPositionReader.FieldModule,
        [FieldScriptContextReader.AddressCurrentFieldId] = 116,
        [FieldScriptContextReader.AddressFieldScriptPtr] = script,
        [script + 2] = entityCount,
        [script + 6] = scriptTableOffsetDwords,
        [FieldScriptContextReader.AddressCurrentEntityId] = entityId,
        [FieldScriptContextReader.AddressCurrentEntityScriptPriority + entityId] = priority,
        [FieldScriptContextReader.AddressCurrentEntityScriptId + entityId * 8 + priority] = scriptId,
        [FieldScriptContextReader.AddressFieldCurrScriptPosition + entityId * sizeof(ushort)] = absolutePosition,
        [scriptOffsetAddress] = scriptBaseOffset,
        [script + absolutePosition] = FieldOpcodeAddressResolver.OpcodeWaitIndex
    };
    var reader = CreateFieldScriptContextReader(memory);

    AssertEqual(true, reader.TryRead(out var context), "live field script context should read");
    AssertEqual(116, context.FieldId, "live field script field id");
    AssertEqual(entityId, context.EntityId, "live field script entity id");
    AssertEqual(scriptId, context.ScriptId, "live field script id from the active priority slot");
    AssertEqual(byteIndex, context.ByteIndex, "live field script byte index normalized from the event buffer offset");
    AssertEqual(FieldOpcodeAddressResolver.OpcodeWaitIndex, context.Opcode, "live field script opcode");
}

static void AssertFieldScriptContextReaderRejectsInvalidNativeState()
{
    var memory = new Dictionary<int, int>
    {
        [FieldScriptContextReader.AddressCurrentModule] = 0,
        [FieldScriptContextReader.AddressFieldScriptPtr] = 0
    };
    var reader = CreateFieldScriptContextReader(memory);
    AssertEqual(false, reader.TryRead(out _), "non-field modules and null script pointers must be rejected");

    var script = 0x2B300000;
    memory[FieldScriptContextReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    memory[FieldScriptContextReader.AddressFieldScriptPtr] = script;
    memory[script + 2] = 2;
    memory[FieldScriptContextReader.AddressCurrentEntityId] = 2;
    AssertEqual(false, reader.TryRead(out _), "entity ids outside the native entity table must be rejected");

    memory[FieldScriptContextReader.AddressCurrentEntityId] = 1;
    memory[FieldScriptContextReader.AddressCurrentEntityScriptPriority + 1] = 8;
    AssertEqual(false, reader.TryRead(out _), "script priorities outside the eight native slots must be rejected");
}

