static void AssertFieldCutsceneDescriptionCatalogCoversReactor5AndAeris()
{
    var cues = FieldCutsceneDescriptionCatalog.CreateReactor5AndAerisDescriptions();
    AssertEqual(28, cues.Count, "Reactor 5 through Aeris's home cue count including branch-specific church barrel outcomes");
    AssertEqual(
        "127,132,181,182,183,184,188,190,276,322",
        string.Join(',', cues.Select(cue => cue.FieldId).Distinct().Order()),
        "Reactor 5 through Aeris's home fields covered");
    AssertEqual(
        true,
        cues.Any(cue => cue.Opcode == FieldOpcodeAddressResolver.OpcodeRequestIndex) &&
        cues.Any(cue => cue.Opcode == FieldOpcodeAddressResolver.OpcodeJumpIndex) == false &&
        cues.Any(cue => cue.Opcode == FieldOpcodeAddressResolver.OpcodeSplitIndex),
        "the sequence must use exact visual-action anchors without describing player-controlled jumps");
    AssertEqual(cues.Count, cues.Select(cue => cue.Key).Distinct().Count(), "Reactor 5 and Aeris cue keys must be unique");

    AssertContains(cues.Single(cue => cue.FieldId == 132 && cue.EntityId == 2 && cue.ScriptId == 7 && cue.ByteIndex == 83).Text, "memory");
    AssertContains(cues.Single(cue => cue.FieldId == 127 && cue.EntityId == 4 && cue.ScriptId == 8 && cue.ByteIndex == 44).Text, "Air Buster");
    AssertContains(cues.Single(cue => cue.FieldId == 127 && cue.EntityId == 2 && cue.ScriptId == 7 && cue.ByteIndex == 68).Text, "falls");
    AssertContains(cues.Single(cue => cue.FieldId == 183 && cue.EntityId == 6 && cue.ScriptId == 7 && cue.ByteIndex == 39).Text, "church");
    AssertContains(cues.Single(cue => cue.FieldId == 182 && cue.EntityId == 1 && cue.ScriptId == 1 && cue.ByteIndex == 20).Text, "Reno");
    AssertContains(cues.Single(cue => cue.FieldId == 188 && cue.EntityId == 0 && cue.ScriptId == 0 && cue.ByteIndex == 70).Text, "Elmyra");
    AssertContains(cues.Single(cue => cue.FieldId == 127 && cue.EntityId == 3 && cue.ScriptId == 3 && cue.ByteIndex == 35).Text, "high above");
    AssertContains(cues.Single(cue => cue.FieldId == 127 && cue.EntityId == 8 && cue.ScriptId == 3 && cue.ByteIndex == 0).Text, "hovers");
    AssertContains(cues.Single(cue => cue.FieldId == 127 && cue.EntityId == 8 && cue.ScriptId == 5 && cue.ByteIndex == 12).Text, "helicopter");
    AssertContains(cues.Single(cue => cue.FieldId == 127 && cue.EntityId == 4 && cue.ScriptId == 12 && cue.ByteIndex == 19).Text, "breaks apart");
    AssertContains(cues.Single(cue => cue.FieldId == 276 && cue.EntityId == 2 && cue.ScriptId == 1 && cue.ByteIndex == 52).Text, "childhood");
    AssertContains(cues.Single(cue => cue.FieldId == 190 && cue.EntityId == 0 && cue.ScriptId == 0 && cue.ByteIndex == 90).Text, "memory fades");

    var barrelHits = cues
        .Where(cue => cue.FieldId == 184 && cue.Text.Contains("strikes the soldier", StringComparison.Ordinal))
        .OrderBy(cue => cue.EntityId)
        .ThenBy(cue => cue.ByteIndex)
        .ToArray();
    AssertEqual(3, barrelHits.Length, "the three correct church barrels should describe their successful hit");
    AssertEqual("8:53,9:50,10:50", string.Join(',', barrelHits.Select(cue => $"{cue.EntityId}:{cue.ByteIndex}")), "native successful barrel branches");

    var barrelMisses = cues
        .Where(cue => cue.FieldId == 184 && cue.Text.Contains("misses the soldier", StringComparison.Ordinal))
        .OrderBy(cue => cue.EntityId)
        .ThenBy(cue => cue.ByteIndex)
        .ToArray();
    AssertEqual(4, barrelMisses.Length, "all four church barrel miss branches should describe the failed result");
    AssertEqual("8:166,9:208,10:127,11:80", string.Join(',', barrelMisses.Select(cue => $"{cue.EntityId}:{cue.ByteIndex}")), "native missed barrel branches");

    var nativeCatalog = new FieldScriptNavigationCatalog(FindGameRoot());
    var nibelheimVariants = cues
        .Where(cue => cue.FieldId == 322 && cue.EntityId == 0 && cue.ScriptId == 0 &&
            cue.Text.Contains("injured father", StringComparison.Ordinal))
        .ToArray();
    AssertEqual("444,446", string.Join(',', nibelheimVariants.Select(cue => cue.ByteIndex)), "verified PC Nibelheim cue anchors");
    foreach (var cue in cues.Except(nibelheimVariants))
    {
        var nativeOpcodes = nativeCatalog.ReadScriptOpcodes(cue.FieldId, cue.EntityId, cue.ScriptId);
        AssertEqual(
            true,
            nativeOpcodes.Any(opcode => opcode.ByteIndex == cue.ByteIndex && opcode.Opcode == cue.Opcode),
            $"Reactor 5/Aeris cue field={cue.FieldId} entity={cue.EntityId} script={cue.ScriptId} byte={cue.ByteIndex} must use its exact installed native opcode");
    }

    var nibelheimOpcodes = nativeCatalog.ReadScriptOpcodes(322, 0, 0);
    AssertEqual(
        true,
        nibelheimVariants.Any(cue =>
            nibelheimOpcodes.Any(opcode => opcode.ByteIndex == cue.ByteIndex && opcode.Opcode == cue.Opcode)),
        "one explicitly verified PC Nibelheim cue anchor must match the installed field data");
}

