static void AssertFieldCutsceneDescriptionTrackerSpeaksExactCueOnce()
{
    var tracker = new FieldCutsceneDescriptionTracker(FieldCutsceneDescriptionCatalog.CreateOpeningTrainArrival());
    var cueContext = new FieldScriptContext(116, 0, 0, 160, FieldOpcodeAddressResolver.OpcodeWaitIndex);

    var first = tracker.Observe(cueContext);
    AssertContains(first?.Text ?? string.Empty, "train pulls into the station");
    AssertNull(tracker.Observe(cueContext), "blocking WAIT repeats must not repeat cutscene speech");
    AssertNull(
        tracker.Observe(cueContext with { ByteIndex = 161 }),
        "nearby script positions must not trigger a cutscene description fallback");
    AssertNull(
        tracker.Observe(cueContext with { Opcode = 0x23 }),
        "matching byte positions must still require the native WAIT opcode");
}

static void AssertFieldCutsceneDescriptionTrackerRequiresCatalogedOpcode()
{
    var cue = FieldCutsceneDescriptionCatalog.CreateSector8EscapeDescriptions()
        .Single(candidate => candidate.FieldId == 134 && candidate.EntityId == 2 && candidate.ScriptId == 5 && candidate.ByteIndex == 0);
    var tracker = new FieldCutsceneDescriptionTracker([cue]);
    var context = new FieldScriptContext(cue.FieldId, cue.EntityId, cue.ScriptId, cue.ByteIndex, FieldOpcodeAddressResolver.OpcodeWaitIndex);

    AssertNull(tracker.Observe(context), "a SOUND cue must not fire from a WAIT at the same script position");
    AssertNotNull(
        tracker.Observe(context with { Opcode = FieldOpcodeAddressResolver.OpcodeSoundIndex }),
        "the exact native SOUND opcode should fire its description");
    AssertNull(
        tracker.Observe(context with { Opcode = FieldOpcodeAddressResolver.OpcodeSoundIndex }),
        "a repeating native SOUND handler must not repeat its description");
}

static void AssertFieldCutsceneDescriptionTrackerResetsOnFieldReentry()
{
    var tracker = new FieldCutsceneDescriptionTracker(FieldCutsceneDescriptionCatalog.CreateOpeningTrainArrival());
    var cueContext = new FieldScriptContext(116, 0, 0, 160, FieldOpcodeAddressResolver.OpcodeWaitIndex);

    AssertNotNull(tracker.Observe(cueContext), "first field entry should describe the train");
    AssertNull(tracker.Observe(cueContext), "same field entry should remain deduplicated");
    AssertNull(
        tracker.Observe(new FieldScriptContext(117, 0, 0, 160, FieldOpcodeAddressResolver.OpcodeWaitIndex)),
        "changing fields must not match md1stin cues");
    AssertNotNull(tracker.Observe(cueContext), "returning to md1stin should start a fresh cue session");

    tracker.Reset();
    AssertNotNull(tracker.Observe(cueContext), "leaving the field module should reset cutscene cue state");
}

static void AssertFieldCutsceneSpeechPriorityIgnoresResidualMessageCount()
{
    AssertEqual(
        false,
        FieldCutsceneSpeechPriority.ShouldWaitForDialogue(activeMessageCount: 1, hasReadableActiveMessage: false),
        "a stale native message count without a readable window must not delay a cutscene description");
    AssertEqual(
        true,
        FieldCutsceneSpeechPriority.ShouldWaitForDialogue(activeMessageCount: 1, hasReadableActiveMessage: true),
        "a genuinely readable field message should finish before a later description");
}

static void AssertFieldCutsceneSpeechPriorityQueuesDialogueBehindNarration()
{
    var priority = new FieldCutsceneSpeechPriority();
    var now = new DateTime(2026, 7, 17, 18, 0, 0, DateTimeKind.Utc);
    priority.BeginNarration(139, "Cloud drops through the train roof and lands inside the rattling car.", now);

    AssertEqual(
        true,
        priority.ShouldQueueDialogue(139, now.AddSeconds(1)),
        "field dialogue should queue while the current cutscene description is being spoken");
    AssertEqual(
        false,
        priority.ShouldQueueDialogue(140, now.AddSeconds(1)),
        "narration priority must not leak into a different field");
    AssertEqual(
        false,
        priority.ShouldQueueDialogue(139, now.AddSeconds(20)),
        "narration priority should expire after the description has had time to finish");
}

