static void AssertFieldOpcodeMessageSpeechGateSuppressesActiveRepeats()
{
    const string firstKey = "opcode Message field 117 window 1 dialog 31";
    const string secondKey = "opcode Message field 117 window 2 dialog 32";
    var gate = new FieldOpcodeMessageSpeechGate();

    AssertEqual(true, gate.ShouldQueue(firstKey, 1), "first active opcode message should speak");
    AssertEqual(false, gate.ShouldQueue(firstKey, 1), "repeated active opcode message should not speak");
    AssertEqual(true, gate.ShouldQueue(secondKey, 1), "different active opcode message should speak");
    AssertEqual(false, gate.ShouldQueue(firstKey, 0), "opcode completion should not speak");
    AssertEqual(true, gate.ShouldQueue(firstKey, 1), "same opcode message should speak again after completion");
}

static void AssertNativeFieldMessageOwnershipSuppressesTypewriterSuffixes()
{
    var now = new DateTime(2026, 7, 16, 18, 0, 0, DateTimeKind.Utc);
    var tracker = new NativeFieldMessageOwnershipTracker(TimeSpan.FromSeconds(5));
    var firstIdentity = new NativeFieldMessageIdentity(FieldOpcodeKind.Ask, 117, 0, 38);
    var otherWindowIdentity = new NativeFieldMessageIdentity(FieldOpcodeKind.Ask, 117, 1, 38);
    var nextIdentity = new NativeFieldMessageIdentity(FieldOpcodeKind.Ask, 117, 0, 39);
    const string fullText = "Jessie: Speak of the devil. That light means we are nearing the surface.";

    tracker.ObserveNative(firstIdentity, fullText, now);

    AssertEqual(
        true,
        tracker.ShouldSuppressPolling(windowId: 0, firstIdentity, activeMessageCount: 1, now.AddMilliseconds(50)),
        "native field speech should own its exact active window and lifecycle");
    AssertEqual(
        true,
        tracker.ShouldSuppressPolling(windowId: 0, firstIdentity, activeMessageCount: 1, now.AddSeconds(3)),
        "native ownership should cover typewriter suffixes within its exact window lifecycle");
    AssertEqual(
        false,
        tracker.ShouldSuppressPolling(windowId: 1, firstIdentity, activeMessageCount: 1, now.AddSeconds(3)),
        "identical or substring text in another window must remain available to polling");
    AssertEqual(
        false,
        tracker.ShouldSuppressPolling(windowId: 0, nextIdentity, activeMessageCount: 1, now.AddSeconds(3)),
        "a different native message identity in the same window is not owned");
    AssertEqual(
        false,
        tracker.ShouldSuppressPolling(windowId: 0, firstIdentity, activeMessageCount: 0, now.AddSeconds(4)),
        "closing the native message should release ownership");

    tracker.ObserveNative(otherWindowIdentity, "Barret: Move out!", now.AddSeconds(6));
    AssertEqual(
        true,
        tracker.ShouldSuppressPolling(windowId: 1, otherWindowIdentity, activeMessageCount: 1, now.AddSeconds(12)),
        "the exact active ASK must not expire while the user leaves it open");
    tracker.MarkSpeechDelivered(otherWindowIdentity, now.AddSeconds(12), visibleContentComplete: true);
    AssertEqual(
        true,
        tracker.WasSpeechDelivered(otherWindowIdentity, now.AddSeconds(20), preserveActiveIdentity: true),
        "successful exact delivery remains complete beyond stale cleanup lifetime while ASK is active");
    tracker.ObserveNative(otherWindowIdentity, "No", now.AddSeconds(21));
    AssertEqual(
        false,
        tracker.WasSpeechDelivered(otherWindowIdentity, now.AddSeconds(21), preserveActiveIdentity: true),
        "new cursor content returns exact ownership to pending until speech succeeds");
    tracker.MarkSpeechDelivered(otherWindowIdentity, now.AddSeconds(22), visibleContentComplete: false);
    AssertEqual(
        false,
        tracker.ShouldSuppressPolling(windowId: 1, otherWindowIdentity, activeMessageCount: 1, now.AddSeconds(22)),
        "partial native content leaves the full visible ASK eligible for checked polling recovery");
    tracker.Release(otherWindowIdentity);
    AssertEqual(
        false,
        tracker.ShouldSuppressPolling(windowId: 1, otherWindowIdentity, activeMessageCount: 1, now.AddSeconds(13)),
        "an exact lifecycle close releases ownership without waiting for age cleanup");
}

static void AssertFieldMessageReaderRejectsStaleOrInvalidWindowPointer()
{
    var messageData = 0x600000;
    var staleMessage = messageData + 0x80;
    var outsideMessage = messageData + 0x20000;
    var texts = new Dictionary<int, string>
    {
        [FieldMessageReader.AddressFieldMessageLineBuffer] = "Platform",
        [staleMessage] = "Stale field message",
        [outsideMessage] = "Out-of-range field message"
    };

    var freeSlotMemory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = messageData,
        [FieldMessageReader.AddressFieldWindowMessagePointers] = staleMessage,
        [FieldMessageReader.AddressFieldWindowStates] = 0xff
    };

    var freeSlotResult = CreateFieldMessageReader(freeSlotMemory, texts).ReadCurrent();
    AssertEqual("line", freeSlotResult.Source, "free field message window slot should not use stale pointer source");
    AssertEqual("Platform", freeSlotResult.Text, "free field message window slot should fall back to line buffer");

    var outsidePointerMemory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = messageData,
        [FieldMessageReader.AddressFieldWindowMessagePointers] = outsideMessage,
        [FieldMessageReader.AddressFieldWindowStates] = 0
    };

    var outsidePointerResult = CreateFieldMessageReader(outsidePointerMemory, texts).ReadCurrent();
    AssertEqual("line", outsidePointerResult.Source, "out-of-range field message pointer should be ignored");
    AssertEqual("Platform", outsidePointerResult.Text, "out-of-range field message pointer should fall back to line buffer");
}

static void AssertFieldMessageReaderIgnoresWindowGenerationByte()
{
    var memory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = 0x700000,
        [FieldMessageReader.AddressFieldWindowStates] = 0xff,
        [FieldMessageReader.AddressFieldWindowStates + 1] = 0xff,
        [FieldMessageReader.AddressFieldWindowStates + 2] = 0xff,
        [FieldMessageReader.AddressFieldWindowStates + 3] = 0xff,
        [FieldMessageReader.AddressFieldWindowStates + 4] = 0x20
    };
    var texts = new Dictionary<int, string>
    {
        [FieldMessageReader.AddressFieldMessageLineBuffer] = "Sector 7 Slums",
        [FieldMessageReader.AddressFieldWindowTextBuffers + 0x400] = "$ %%%%'$$ ' # + FY"
    };

    var reader = CreateFieldMessageReader(memory, texts);
    var current = reader.ReadCurrent();
    var diagnostics = reader.ReadDiagnostics();

    AssertEqual("line", current.Source, "window generation byte must not be treated as a fifth slot");
    AssertEqual("Sector 7 Slums", current.Text, "window generation byte must not expose adjacent memory");
    AssertEqual(4, diagnostics.Windows.Count, "FFVII has four field message window slots");
}

static void AssertFieldMessageReaderReportsWindowDiagnostics()
{
    var messageData = 0x700000;
    var activeMessage = messageData + 0x120;
    var memory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = messageData,
        [FieldMessageReader.AddressFieldWindowMessagePointers] = activeMessage,
        [FieldMessageReader.AddressFieldWindowStates] = 3,
        [FieldMessageReader.AddressFieldWindowStates + 1] = 0xff
    };

    var texts = new Dictionary<int, string>
    {
        [activeMessage] = "Cloud: What the?",
        [FieldMessageReader.AddressFieldWindowTextBuffers] = "Cloud: What the?",
        [FieldMessageReader.AddressFieldMessageLineBuffer] = "Platform"
    };

    var diagnostics = CreateFieldMessageReader(memory, texts).ReadDiagnostics();
    AssertEqual(unchecked((uint)messageData), diagnostics.MessageDataPointer, "field message diagnostics should include message data pointer");
    AssertEqual(4, diagnostics.Windows.Count, "field message diagnostics should report all four window slots");
    AssertEqual(true, diagnostics.Windows[0].IsActive, "field message diagnostics should mark non-free window state active");
    AssertEqual(true, diagnostics.Windows[0].PointerInsideMessageData, "field message diagnostics should mark pointer inside message data");
    AssertEqual("Cloud: What the?", diagnostics.Windows[0].PointerText, "field message diagnostics should decode active pointer text");
    AssertContains(diagnostics.ToCompactLogLine(), "slot0:state=0x03");
    AssertContains(diagnostics.ToCompactLogLine(), "ptrText=\"Cloud: What the?\"");
}

static void AssertFieldMessageDiagnosticsSkipsFreedPointerText()
{
    var messageData = 0x720000;
    var freedMessage = messageData + 0x80;
    var memory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = messageData,
        [FieldMessageReader.AddressFieldWindowMessagePointers] = freedMessage,
        [FieldMessageReader.AddressFieldWindowStates] = 0xff
    };
    var reader = new FieldMessageReader(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => (byte)(memory.TryGetValue(address, out var value) ? value : 0xff),
        (address, _) => address == freedMessage
            ? throw new InvalidOperationException("free field window pointer must never be decoded")
            : string.Empty);

    var diagnostics = reader.ReadDiagnostics();

    AssertEqual(false, diagnostics.Windows[0].IsActive, "freed field window should be inactive");
    AssertEqual(string.Empty, diagnostics.Windows[0].PointerText, "freed field window pointer text");
}

static void AssertFieldMessageDiagnosticsRejectsNullMessagePointers()
{
    var memory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = 0,
        [FieldMessageReader.AddressFieldWindowMessagePointers] = 0,
        [FieldMessageReader.AddressFieldWindowStates] = 0
    };

    var reader = new FieldMessageReader(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => (byte)(memory.TryGetValue(address, out var value) ? value : 0xff),
        (address, _) => address == 0
            ? throw new InvalidOperationException("diagnostics should not decode text at address zero")
            : string.Empty);

    var diagnostics = reader.ReadDiagnostics();

    AssertEqual(false, diagnostics.Windows[0].PointerInsideMessageData, "null field message pointer should not be in range");
    AssertEqual(string.Empty, diagnostics.Windows[0].PointerText, "null field message pointer text");
}

