static void AssertFieldMessageReaderReadsNativeAskLinesById()
{
    const int messageData = 0x711000;
    const int messageId = 2;
    const int messageOffset = 0x100;
    var bytes = new Dictionary<int, byte>();
    var encoded = new byte[]
    {
        0x28, 0x45, 0x59, 0x1f,
        0xe7,
        0xe0, 0x26, 0x49, 0x47, 0x48, 0x54, 0x00, 0x54, 0x48, 0x45, 0x4d, 0x01,
        0xe7,
        0xe0, 0x2c, 0x41, 0x54, 0x45, 0x52, 0x01,
        0xff
    };
    bytes[messageData + 2 + messageId * 2] = 0;
    bytes[messageData + 3 + messageId * 2] = 1;
    for (var index = 0; index < encoded.Length; index++)
    {
        bytes[messageData + messageOffset + index] = encoded[index];
    }

    var reader = new FieldMessageReader(
        address => address == FieldMessageReader.AddressFieldMessageDataPointer ? messageData : 0,
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0,
        (_, _) => string.Empty);
    var lines = reader.ReadMessageLinesById(messageId);

    AssertEqual(3, lines.Count, "live ASK message line count");
    AssertEqual("Hey?", lines[0], "live ASK prompt");
    AssertEqual("Fight them!", lines[1], "live ASK first choice");
    AssertEqual("Later!", lines[2], "live ASK second choice");
}

static void AssertFieldMessageReaderTreatsNullDecodedTextAsEmpty()
{
    var memory = new Dictionary<int, int>
    {
        [FieldMessageReader.AddressFieldMessageDataPointer] = 0
    };

    var reader = new FieldMessageReader(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => 0xff,
        (_, _) => null!);

    var result = reader.ReadCurrent();
    AssertEqual(string.Empty, result.Source, "null field text source");
    AssertEqual(string.Empty, result.Text, "null field text should normalize to empty");
}

static void AssertFieldMessageSpeechTrackerWaitsForStableText()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new FieldMessageSpeechTracker(TimeSpan.FromMilliseconds(300));

    AssertNull(tracker.Observe("Come", now), "partial message should not speak");
    AssertNull(tracker.Observe("Come on", now.AddMilliseconds(100)), "changed message should not speak");
    AssertNull(tracker.Observe("Come on", now.AddMilliseconds(250)), "unstable message should not speak");
    AssertEqual("Come on", tracker.Observe("Come on", now.AddMilliseconds(450)), "stable message should speak");
    AssertNull(tracker.Observe("Come on", now.AddMilliseconds(600)), "duplicate stable message should not repeat");
    AssertNull(tracker.Observe("", now.AddMilliseconds(700)), "empty message clears the tracker");
    AssertNull(tracker.Observe("Come on", now.AddMilliseconds(800)), "reappeared message should wait again");
    AssertEqual("Come on", tracker.Observe("Come on", now.AddMilliseconds(1200)), "reappeared stable message should speak");
}

static void AssertDeferredZoneSpeechWaitsUntilOpeningMovieEnds()
{
    var now = new DateTime(2026, 7, 14, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new DeferredZoneSpeechTracker(TimeSpan.FromMilliseconds(300));
    AssertNull(
        tracker.Observe(116, new FieldMessageCandidate("line", "Platform"), now, announcementBlocked: true),
        "zone text should not speak while opening movie is running");
    AssertNull(
        tracker.Observe(116, new FieldMessageCandidate("line", "Platform"), now.AddSeconds(1), announcementBlocked: true),
        "queued zone should stay silent during opening movie");
    AssertEqual(
        "Platform",
        tracker.Observe(116, new FieldMessageCandidate(string.Empty, string.Empty), now.AddSeconds(2), announcementBlocked: false),
        "queued zone should speak after opening movie ends");
    AssertEqual(true, tracker.Acknowledge(116, "Platform"), "accepted Platform announcement");
    AssertNull(
        tracker.Observe(116, new FieldMessageCandidate("line", "Platform"), now.AddSeconds(3), announcementBlocked: false),
        "queued zone should speak only once for the field entry");
}

static void AssertDeferredZoneSpeechSpeaksZoneWhenMovieNotRunning()
{
    var now = new DateTime(2026, 7, 14, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new DeferredZoneSpeechTracker(TimeSpan.FromMilliseconds(300));

    AssertNull(
        tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now, announcementBlocked: false),
        "zone text should wait for the native field id to settle");
    AssertEqual(
        "Sector 1 Station",
        tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now.AddMilliseconds(400), announcementBlocked: false),
        "zone text should speak after a stable non-movie field entry");
    AssertEqual(true, tracker.Acknowledge(117, "Sector 1 Station"), "accepted ordinary zone announcement");
    AssertNull(
        tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now.AddMilliseconds(800), announcementBlocked: false),
        "same zone text should not repeat immediately");
    AssertNull(
        tracker.Observe(117, new FieldMessageCandidate("active window 0", "Cloud: What the?"), now.AddSeconds(1), announcementBlocked: false),
        "NPC dialogue should not be treated as a zone announcement");
}

static void AssertDeferredZoneSpeechWaitsForStableFieldAndRepeatsOnReentry()
{
    var now = new DateTime(2026, 7, 14, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new DeferredZoneSpeechTracker(TimeSpan.FromMilliseconds(300));

    AssertNull(tracker.Observe(116, new FieldMessageCandidate("line", "Platform"), now, false), "first field sample primes the settle gate");
    AssertNull(tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now.AddMilliseconds(200), false), "field id change restarts the settle gate");
    AssertNull(tracker.Observe(116, new FieldMessageCandidate("line", "Platform"), now.AddMilliseconds(400), false), "transient old field id must not speak");
    AssertNull(tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now.AddMilliseconds(600), false), "final field id must settle again");
    AssertEqual("Sector 1 Station", tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now.AddMilliseconds(950), false), "stable final field should announce");
    AssertEqual(true, tracker.Acknowledge(117, "Sector 1 Station"), "accepted stable field announcement");

    tracker.LeaveField();
    AssertNull(tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now.AddSeconds(2), false), "reentry starts a new settle window");
    AssertEqual("Sector 1 Station", tracker.Observe(117, new FieldMessageCandidate("line", "Sector 1 Station"), now.AddMilliseconds(2400), false), "same zone may speak on a genuine reentry");
    AssertEqual(true, tracker.Acknowledge(117, "Sector 1 Station"), "accepted reentry announcement");
}

static void AssertOpeningFieldZoneGateCoversMovieDetectionRace()
{
    AssertEqual(true, DeferredZoneSpeechTracker.ShouldBlockForOpeningMovie(116, movieDetected: false, movieFileActive: false, descriptionRunning: false), "opening field must wait before the file handle is detected");
    AssertEqual(true, DeferredZoneSpeechTracker.ShouldBlockForOpeningMovie(116, movieDetected: true, movieFileActive: true, descriptionRunning: false), "opening field must remain blocked while the movie file is active");
    AssertEqual(true, DeferredZoneSpeechTracker.ShouldBlockForOpeningMovie(116, movieDetected: true, movieFileActive: false, descriptionRunning: true), "opening field must remain blocked while description cues run");
    AssertEqual(false, DeferredZoneSpeechTracker.ShouldBlockForOpeningMovie(116, movieDetected: true, movieFileActive: false, descriptionRunning: false), "opening field may announce only after movie and description end");
    AssertEqual(false, DeferredZoneSpeechTracker.ShouldBlockForOpeningMovie(117, movieDetected: false, movieFileActive: false, descriptionRunning: false), "ordinary field entries do not use the opening race gate");
}

static void AssertDeferredZoneSpeechWaitsForNativeControlUnlock()
{
    AssertEqual(
        true,
        DeferredZoneSpeechTracker.ShouldBlockForFieldEntry(116, false, 0, 1, false, false),
        "Platform should wait while a native entry cutscene owns control");
    AssertEqual(
        true,
        DeferredZoneSpeechTracker.ShouldBlockForFieldEntry(116, false, 1, 0, false, false),
        "Platform should wait for active dialogue");
    AssertEqual(
        false,
        DeferredZoneSpeechTracker.ShouldBlockForFieldEntry(116, false, 0, 0, false, false),
        "Platform may run after movies, dialogue, narration, and scripted control end");
    AssertEqual(
        true,
        DeferredZoneSpeechTracker.ShouldBlockForFieldEntry(116, false, 0, 0, true, false),
        "Platform should wait for queued cutscene narration");
    AssertEqual(
        true,
        DeferredZoneSpeechTracker.ShouldBlockForFieldEntry(116, false, 0, 0, false, true),
        "Platform should wait through the narration protection window");
    AssertEqual(
        true,
        DeferredZoneSpeechTracker.ShouldBlockForFieldEntry(117, true, 1, 1, true, true),
        "ordinary zones should also wait while dialogue, scripted control, or narration owns the entry");
    AssertEqual(
        false,
        DeferredZoneSpeechTracker.ShouldBlockForFieldEntry(156, false, 0, 0, false, false),
        "an ordinary settled field should announce normally when no higher-priority content is active");
}

static void AssertDeferredZoneSpeechQueuesBehindCutsceneNarration()
{
    var now = new DateTime(2026, 7, 24, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new DeferredZoneSpeechTracker(TimeSpan.FromMilliseconds(300));

    AssertNull(
        tracker.Observe(156, new FieldMessageCandidate("line", "Sector 7 Slums"), now, announcementBlocked: true),
        "Sector 7 should wait while its entry cutscene owns control");
    AssertNull(
        tracker.Observe(156, new FieldMessageCandidate(string.Empty, string.Empty), now.AddMilliseconds(400), announcementBlocked: true),
        "Sector 7 should remain queued behind active cutscene narration");
    AssertEqual(
        false,
        tracker.ShouldInterruptPendingAnnouncement,
        "a zone deferred by a cutscene must queue behind the description instead of interrupting it");
    AssertEqual(
        "Sector 7 Slums",
        tracker.Observe(156, new FieldMessageCandidate(string.Empty, string.Empty), now.AddMilliseconds(800), announcementBlocked: false),
        "Sector 7 should announce after the cutscene and narration gates clear");
    AssertEqual(
        false,
        tracker.ShouldInterruptPendingAnnouncement,
        "the released Sector 7 announcement should remain non-interrupting until accepted");
    AssertEqual(true, tracker.Acknowledge(156, "Sector 7 Slums"), "accepted deferred Sector 7 announcement");

    tracker.LeaveField();
    AssertNull(
        tracker.Observe(157, new FieldMessageCandidate("line", "Beginner's Hall"), now.AddSeconds(2), announcementBlocked: false),
        "ordinary field entry should still use the settle window");
    AssertEqual(
        "Beginner's Hall",
        tracker.Observe(157, new FieldMessageCandidate(string.Empty, string.Empty), now.AddMilliseconds(2400), announcementBlocked: false),
        "ordinary field entry should announce after settling");
    AssertEqual(
        true,
        tracker.ShouldInterruptPendingAnnouncement,
        "an ordinary unblocked zone announcement should retain normal interruption behavior");
}

static void AssertFieldZoneTransitionCueUsesConfirmedFieldChangesOnly()
{
    var now = new DateTime(2026, 7, 15, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new FieldZoneTransitionCueTracker(TimeSpan.FromMilliseconds(300));

    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 116, now), "initial field must not play a zone cue");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 116, now.AddMilliseconds(350)), "initial stable field establishes the baseline silently");

    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 117, now.AddMilliseconds(500)), "new field starts a settle window");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 117, now.AddMilliseconds(700)), "unsettled field must remain silent");
    AssertEqual(true, tracker.Observe(FieldPositionReader.FieldModule, 117, now.AddMilliseconds(850)), "confirmed field transition should play once");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 117, now.AddMilliseconds(900)), "same field must not repeat the cue");

    AssertEqual(false, tracker.Observe(BattleStateReader.BattleModule, 117, now.AddSeconds(1)), "battle entry must not play a field cue");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 117, now.AddMilliseconds(1100)), "return from battle starts no transition");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 117, now.AddMilliseconds(1450)), "returning to the same field stays silent after settling");

    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 118, now.AddMilliseconds(1600)), "transient next field starts settling");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 117, now.AddMilliseconds(1700)), "field-id flicker cancels the transient transition");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 118, now.AddMilliseconds(1800)), "final field must restart settling");
    AssertEqual(true, tracker.Observe(FieldPositionReader.FieldModule, 118, now.AddMilliseconds(2150)), "only the final stable field plays");

    AssertEqual(false, tracker.Observe(FieldZoneTransitionCueTracker.TitleModule, 0, now.AddSeconds(3)), "title screen resets the session silently");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 116, now.AddMilliseconds(3100)), "first field after title is a silent baseline");
    AssertEqual(false, tracker.Observe(FieldPositionReader.FieldModule, 116, now.AddMilliseconds(3450)), "new game initial field must not sound like an exit");
}

