    AssertEqual(false, config.EnableFieldZoneTransitionCue, "post-transition zone cue should default disabled");
    AssertEqual(300, config.FieldZoneTransitionCueSettleMs, "field zone transition cue settle default");
    AssertEqual(100, config.FieldZoneTransitionCueVolumePercent, "field zone transition cue volume default");
    AssertEqual(@"Assets\navigation\field_zone_transition.wav", config.FieldZoneTransitionCueSoundPath, "field zone transition cue path default");
}

static void AssertSwingingBarTimingCueUsesNativeSuccessWindow()
{
    var tracker = new SwingingBarTimingCueTracker();
    const byte fieldModule = FieldPositionReader.FieldModule;
    const int triggerX = -425;
    const int triggerY = 1640;
    const int triggerZ = 3257;

    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            222,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: true,
            isUserControlLocked: true,
            frameCounter: 58),
        "the swinging-bar counter must be ignored outside wcrimb_1");
    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            playerX: -250,
            playerY: 1400,
            playerZ: 3000,
            isAttemptWaiting: true,
            isUserControlLocked: true,
            frameCounter: 58),
        "the shared animation counter must be ignored away from the native swinging-bar line");
    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: false,
            isUserControlLocked: true,
            frameCounter: 58),
        "the cue must remain silent before the native script starts waiting for the jump key");
    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: true,
            isUserControlLocked: false,
            frameCounter: 58),
        "the cue must remain silent outside the scripted control lock");
    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: true,
            isUserControlLocked: true,
            frameCounter: 58),
        "a first-seen counter already inside the window is not enough evidence that it is advancing");
    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: true,
            isUserControlLocked: true,
            frameCounter: 58),
        "a stationary counter inside the window must remain silent");
    AssertEqual(
        true,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: true,
            isUserControlLocked: true,
            frameCounter: 59),
        "an advancing native counter inside 54 through 62 should emit the jump cue");
    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: true,
            isUserControlLocked: true,
            frameCounter: 60),
        "the cue must be one-shot while the same attempt remains in the success window");
    AssertEqual(
        false,
        tracker.Observe(
            fieldModule,
            SwingingBarTimingCueTracker.SwingingBarFieldId,
            triggerX,
            triggerY,
            triggerZ,
            isAttemptWaiting: true,
            isUserControlLocked: true,
            frameCounter: 63),
        "the native counter outside the success window must remain silent");
}

static void AssertSwingingBarTimingCueRearmsForTheNextAttempt()
{
    var tracker = new SwingingBarTimingCueTracker();
    var config = new AccessibilityConfig();
    const byte fieldModule = FieldPositionReader.FieldModule;
    const ushort fieldId = SwingingBarTimingCueTracker.SwingingBarFieldId;
    const int triggerX = -425;
    const int triggerY = 1640;
    const int triggerZ = 3257;

    AssertEqual(true, config.EnableFieldSwingingBarTimingCue, "swinging-bar timing accessibility should default enabled");
    AssertEqual(100, config.FieldSwingingBarTimingCueVolumePercent, "swinging-bar cue volume default");
    AssertEqual(
        @"Assets\navigation\swing_jump_058.wav",
        config.FieldSwingingBarTimingCueSoundPath,
        "swinging-bar cue should use the supplied sound");
    AssertEqual(
        false,
        tracker.Observe(fieldModule, fieldId, triggerX, triggerY, triggerZ, true, true, 0),
        "first attempt baseline");
    AssertEqual(
        false,
        tracker.Observe(fieldModule, fieldId, triggerX, triggerY, triggerZ, true, true, 53),
        "before first success window");
    AssertEqual(
        true,
        tracker.Observe(fieldModule, fieldId, triggerX, triggerY, triggerZ, true, true, 54),
        "first attempt cue");
    AssertEqual(
        false,
        tracker.Observe(fieldModule, fieldId, triggerX, triggerY, triggerZ, true, true, 80),
        "first attempt remains one-shot");
    AssertEqual(
        false,
        tracker.Observe(fieldModule, fieldId, triggerX, triggerY, triggerZ, false, true, 80),
        "ending the native key-wait rearms silently");
    AssertEqual(
        false,
        tracker.Observe(fieldModule, fieldId, triggerX, triggerY, triggerZ, true, true, 53),
        "second attempt baseline");
    AssertEqual(
        true,
        tracker.Observe(fieldModule, fieldId, triggerX, triggerY, triggerZ, true, true, 54),
        "second native attempt should receive its own cue");
    AssertEqual(
        false,
        tracker.Observe(
            FieldZoneTransitionCueTracker.TitleModule,
            fieldId,
            triggerX,
            triggerY,
            triggerZ,
            true,
            true,
            55),
        "leaving the field module resets without leaking a cue");
}

static void AssertFloor60StatueBeaconFollowsNativeHideSpotsAndGuardLines()
{
    var tracker = new Floor60SoldierTurnCueTracker(TimeSpan.FromMilliseconds(500));
    var now = new DateTime(2026, 7, 28, 0, 0, 0, DateTimeKind.Utc);
    var start = Floor60Position(-873, 63, 65);

    AssertEqual(
        true,
        Floor60SoldierTurnCueTracker.HideSpots
            .Select(spot => spot.TriangleId)
            .SequenceEqual(new ushort[] { 152, 303, 307, 140, 101, 99, 314 }),
        "floor 60 statue targets should use the native walkmesh triangles reached by the scripted party path");
    AssertEqual(
        true,
        Floor60SoldierTurnCueTracker.HideSpots
            .Select(spot => (spot.X, spot.Y))
            .SequenceEqual(
                new (int X, int Y)[]
                {
                    (-551, 248),
                    (-396, 259),
                    (-260, 251),
                    (7, 204),
                    (267, 256),
                    (407, 256),
                    (547, 252)
                }),
        "floor 60 statue targets should use the native MOVE destinations beside the golden statues");
    AssertEqual(
        true,
        Floor60SoldierTurnCueTracker.HideSpots
            .Select(spot => spot.GuardLineEntityId)
            .SequenceEqual(new[] { -1, 22, 23, 24, 25, 26, 27 }),
        "each destination after the first should use only the native guard line crossed to reach it");

    var inactive = ObserveFloor60(
        tracker,
        start,
        now,
        minigameActive: false);
    AssertEqual(Floor60GuardSpeechCue.None, inactive.SpeechCue, "inactive floor 60 speech");
    AssertEqual(false, inactive.PlayHideSpotBeacon, "inactive floor 60 beacon");
    AssertNull(inactive.HideSpotTarget, "inactive floor 60 target");
    AssertNull(
        tracker.CurrentNavigationTarget,
        "inactive floor 60 state must not replace the ordinary Story catalog");

    var initial = ObserveFloor60(
        tracker,
        start,
        now.AddMilliseconds(50),
        firstLeftEnabled: true,
        firstMiddleEnabled: true,
        firstRightEnabled: true);
    AssertEqual(
        Floor60GuardSpeechCue.FindFirstHidingSpot,
        initial.SpeechCue,
        "the sequence should introduce the first hiding destination");
    AssertEqual(true, initial.PlayHideSpotBeacon, "the first statue should emit a locator pulse");
    AssertEqual(-551, initial.HideSpotTarget?.X, "first statue beacon x");
    AssertEqual(248, initial.HideSpotTarget?.Y, "first statue beacon y");
    AssertEqual(
        new FieldNavigationTarget(
            Floor60SoldierTurnCueTracker.FloorId,
            FieldNavigationCategory.Story,
            "Starting cover statue",
            -551,
            248,
            0,
            "floor60:statue:0",
            CompletesOnArrival: true,
            InteractionRadius: Floor60SoldierTurnCueTracker.DefaultArrivalDistanceUnits),
        tracker.CurrentNavigationTarget,
        "Floor 60 Story navigation must begin at the first real statue");

    var firstReached = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(100),
        firstLeftEnabled: true,
        firstMiddleEnabled: false,
        firstRightEnabled: false);
    AssertEqual(
        Floor60GuardSpeechCue.HidingSpotReached,
        firstReached.SpeechCue,
        "reaching the first native statue location should confirm the hiding spot");
    AssertEqual(true, firstReached.StopHideSpotBeacon, "arrival should stop the current statue beacon");
    AssertNull(firstReached.HideSpotTarget, "arrival should not point past the statue before its guard turns");
    AssertEqual(
        "floor60:statue:0",
        tracker.CurrentNavigationTarget?.StableId,
        "while waiting for the guard, Story must retain the current hiding statue");

    var wrongGuardTurns = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(150),
        firstLeftEnabled: true,
        firstMiddleEnabled: false,
        firstRightEnabled: false);
    AssertEqual(
        Floor60GuardSpeechCue.None,
        wrongGuardTurns.SpeechCue,
        "turning unrelated guards must not release Cloud toward the next statue");
    AssertNull(wrongGuardTurns.HideSpotTarget, "unrelated guard turn target");

    var relevantGuardTurns = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(200),
        firstLeftEnabled: false,
        firstMiddleEnabled: true,
        firstRightEnabled: true);
    AssertEqual(
        Floor60GuardSpeechCue.MoveNow,
        relevantGuardTurns.SpeechCue,
        "OLINEA becoming safe should release Cloud across only the first guarded gap");
    AssertEqual(true, relevantGuardTurns.PlayHideSpotBeacon, "next hiding spot should sound as movement begins");
    AssertEqual(-396, relevantGuardTurns.HideSpotTarget?.X, "second statue beacon x");
    AssertEqual(
        "floor60:statue:1",
        tracker.CurrentNavigationTarget?.StableId,
        "Story may advance to the second statue only after its native guard gap becomes safe");

    var repeatedSafeFrame = ObserveFloor60(
        tracker,
        Floor60Position(-530, 248, 152),
        now.AddMilliseconds(250),
        firstLeftEnabled: false,
        firstMiddleEnabled: true,
        firstRightEnabled: true);
    AssertEqual(
        Floor60GuardSpeechCue.None,
        repeatedSafeFrame.SpeechCue,
        "one native guard turn should produce only one movement announcement");
    AssertEqual(false, repeatedSafeFrame.PlayHideSpotBeacon, "statue pulses should respect their interval");

    var secondReached = ObserveFloor60(
        tracker,
        Floor60Position(-396, 259, 303),
        now.AddMilliseconds(300),
        firstLeftEnabled: false,
        firstMiddleEnabled: true,
        firstRightEnabled: true);
    AssertEqual(
        Floor60GuardSpeechCue.HidingSpotReached,
        secondReached.SpeechCue,
        "the second native statue position should stop the moving beacon");

    var secondRelevantGuardTurns = ObserveFloor60(
        tracker,
        Floor60Position(-396, 259, 303),
        now.AddMilliseconds(350),
        firstLeftEnabled: true,
        firstMiddleEnabled: false,
        firstRightEnabled: true);
    AssertEqual(
        Floor60GuardSpeechCue.MoveNow,
        secondRelevantGuardTurns.SpeechCue,
        "OLINEB becoming safe should release the second guarded gap");
    AssertEqual(-260, secondRelevantGuardTurns.HideSpotTarget?.X, "third statue beacon x");
}

static void AssertFloor60CurrentStatueOverridesStaticStoryTarget()
{
    IReadOnlyList<FieldNavigationTarget> staticTargets =
    [
        new FieldNavigationTarget(
            Floor60SoldierTurnCueTracker.FloorId,
            FieldNavigationCategory.Story,
            "Reach the floor 60 signaling point; press OK when the soldiers turn away",
            5,
            66,
            0,
            "story:239:21:264:old-center-line",
            CompletesOnArrival: true)
    ];
    var currentStatue = new FieldNavigationTarget(
        Floor60SoldierTurnCueTracker.FloorId,
        FieldNavigationCategory.Story,
        "Starting cover statue",
        -551,
        248,
        0,
        "floor60:statue:0",
        CompletesOnArrival: true,
        InteractionRadius: Floor60SoldierTurnCueTracker.DefaultArrivalDistanceUnits);

    var merged = Floor60NavigationTargetMerger.Merge(staticTargets, currentStatue);
    AssertEqual(1, merged.Count, "an active Floor 60 crossing should expose one actionable Story destination");
    AssertEqual(
        "floor60:statue:0",
        merged[0].StableId,
        "the current native hiding statue must replace the obsolete center-line Story target");
    AssertEqual(
        staticTargets,
        Floor60NavigationTargetMerger.Merge(staticTargets, currentStatue: null),
        "outside a crossing stage the ordinary Story catalog must remain unchanged");
}

static void AssertFloor60SignalAndCompletionPromptsUseNativeStates()
{
    var tracker = new Floor60SoldierTurnCueTracker(TimeSpan.Zero);
    var now = new DateTime(2026, 7, 28, 1, 0, 0, DateTimeKind.Utc);
    var middle = Floor60Position(7, 204, 140);

    _ = ObserveFloor60(
        tracker,
        middle,
        now,
        firstCompletionLineEnabled: true,
        secondCompletionLineEnabled: true,
        firstLeftEnabled: true,
        firstMiddleEnabled: true,
        firstRightEnabled: true);
    var firstPassed = ObserveFloor60(
        tracker,
        middle,
        now.AddMilliseconds(50),
        userControlLocked: true,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: true,
        firstLeftEnabled: true,
        firstMiddleEnabled: false,
        firstRightEnabled: false,
        guardTiming: Floor60Timing(firstLeftTicks: 16));
    AssertEqual(
        Floor60GuardSpeechCue.FirstGuardSectionPassed,
        firstPassed.SpeechCue,
        "LINE1 disabling with valid progress should confirm the first Cloud crossing");
    AssertNull(firstPassed.HideSpotTarget, "party signaling should suspend statue guidance");

    var unrelatedSignalLine = ObserveFloor60(
        tracker,
        middle,
        now.AddMilliseconds(100),
        userControlLocked: true,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: true,
        firstLeftEnabled: true,
        firstMiddleEnabled: false,
        firstRightEnabled: false);
    AssertEqual(
        Floor60GuardSpeechCue.None,
        unrelatedSignalLine.SpeechCue,
        "Barret progress zero must wait for OLINEA rather than any disabled patrol line");

    var signalNow = ObserveFloor60(
        tracker,
        middle,
        now.AddMilliseconds(150),
        userControlLocked: true,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: true,
        firstLeftEnabled: true,
        firstMiddleEnabled: true,
        firstRightEnabled: true,
        guardTiming: Floor60Timing(firstLeftTicks: 15));
    AssertEqual(
        Floor60GuardSpeechCue.SignalNow,
        signalNow.SpeechCue,
        "the guard line for the companion's next scripted MOVE should announce Signal now");
    AssertEqual(
        true,
        signalNow.PlayActionCue,
        "the companion prompt should play the centered action cue");

    var repeatedSignal = ObserveFloor60(
        tracker,
        middle,
        now.AddMilliseconds(175),
        userControlLocked: true,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: true,
        firstLeftEnabled: true,
        firstMiddleEnabled: true,
        firstRightEnabled: true,
        guardTiming: Floor60Timing(firstLeftTicks: 14));
    AssertEqual(
        Floor60GuardSpeechCue.None,
        repeatedSignal.SpeechCue,
        "one companion safe window should emit only one Action prompt");
    AssertEqual(false, repeatedSignal.PlayActionCue, "repeated companion action cue");

    var secondCrossing = ObserveFloor60(
        tracker,
        middle,
        now.AddMilliseconds(200),
        barretSignalingProgress: 3,
        tifaSignalingProgress: 3,
        userControlLocked: false,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: true,
        secondLeftEnabled: false,
        secondMiddleEnabled: true,
        secondRightEnabled: true);
    AssertEqual(
        Floor60GuardSpeechCue.MoveNow,
        secondCrossing.SpeechCue,
        "after both companions reach the middle, OLINED should release Cloud into the second crossing");
    AssertEqual(267, secondCrossing.HideSpotTarget?.X, "first statue in the second crossing");

    var completed = ObserveFloor60(
        tracker,
        Floor60Position(547, 252, 314),
        now.AddMilliseconds(250),
        barretSignalingProgress: 6,
        tifaSignalingProgress: 6,
        userControlLocked: true,
        guardsCleared: true,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: false,
        secondLeftEnabled: false,
        secondMiddleEnabled: false,
        secondRightEnabled: false);
    AssertEqual(
        Floor60GuardSpeechCue.SecondGuardSectionPassed,
        completed.SpeechCue,
        "the native guards-cleared flag should confirm the second section exactly once");
    AssertEqual(true, completed.StopHideSpotBeacon, "completion should stop every statue pulse");

    var completedAgain = ObserveFloor60(
        tracker,
        Floor60Position(547, 252, 314),
        now.AddMilliseconds(300),
        barretSignalingProgress: 6,
        tifaSignalingProgress: 6,
        userControlLocked: true,
        guardsCleared: true,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: false);
    AssertEqual(
        Floor60GuardSpeechCue.None,
        completedAgain.SpeechCue,
        "the completed crossing must not repeat its success message");

    tracker.Reset();
    var caught = ObserveFloor60(
        tracker,
        Floor60Position(-396, 259, 303),
        now.AddSeconds(1),
        barretSignalingProgress: 7,
        tifaSignalingProgress: 7,
        userControlLocked: true,
        firstCompletionLineEnabled: false,
        secondCompletionLineEnabled: false,
        firstLeftEnabled: false,
        firstMiddleEnabled: false,
        firstRightEnabled: false);
    AssertEqual(Floor60GuardSpeechCue.None, caught.SpeechCue, "caught-state speech");
    AssertEqual(false, caught.PlayHideSpotBeacon, "caught-state beacon");
}

static void AssertFloor60GuardCueLeadsNativeTurnAndConfirmsSafePass()
{
    var tracker = new Floor60SoldierTurnCueTracker(
        TimeSpan.Zero,
        Floor60SoldierTurnCueTracker.DefaultArrivalDistanceUnits,
        guardReactionLeadTicks: 15);
    var now = new DateTime(2026, 7, 29, 0, 0, 0, DateTimeKind.Utc);

    _ = ObserveFloor60(
        tracker,
        Floor60Position(-873, 63, 65),
        now,
        firstLeftEnabled: true,
        guardTiming: Floor60Timing(firstLeftTicks: 30));
    _ = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(50),
        firstLeftEnabled: true,
        guardTiming: Floor60Timing(firstLeftTicks: 20));

    var tooEarly = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(100),
        firstLeftEnabled: true,
        guardTiming: Floor60Timing(firstLeftTicks: 16));
    AssertEqual(
        Floor60GuardSpeechCue.None,
        tooEarly.SpeechCue,
        "the reaction cue should not fire before the configured native lead");

    var reactionCue = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(133),
        firstLeftEnabled: true,
        guardTiming: Floor60Timing(firstLeftTicks: 15));
    AssertEqual(
        Floor60GuardSpeechCue.MoveNow,
        reactionCue.SpeechCue,
        "the movement cue should lead the native guard turn by fifteen field ticks");
    AssertEqual(
        true,
        reactionCue.PlayHideSpotBeacon,
        "the next statue locator should start with the early movement cue");
    AssertEqual(-396, reactionCue.HideSpotTarget?.X, "early cue target");

    var dangerousSide = ObserveFloor60(
        tracker,
        Floor60Position(-430, 250, 152),
        now.AddMilliseconds(166),
        firstLeftEnabled: true,
        guardTiming: Floor60Timing(firstLeftTicks: 14));
    AssertEqual(
        Floor60GuardSpeechCue.None,
        dangerousSide.SpeechCue,
        "the destination side must not count as passed while the guard line is dangerous");

    var safeEdge = ObserveFloor60(
        tracker,
        Floor60Position(-500, 250, 152),
        now.AddMilliseconds(633),
        firstLeftEnabled: false,
        guardTiming: Floor60Timing());
    AssertEqual(
        Floor60GuardSpeechCue.None,
        safeEdge.SpeechCue,
        "the native safe edge must not repeat an early movement cue");

    var passed = ObserveFloor60(
        tracker,
        Floor60Position(-430, 250, 152),
        now.AddMilliseconds(666),
        firstLeftEnabled: false,
        guardTiming: Floor60Timing());
    AssertEqual(
        Floor60GuardSpeechCue.GuardSetPassed,
        passed.SpeechCue,
        "crossing to the destination side of the first native guard line should confirm success");
    AssertEqual(
        false,
        passed.StopHideSpotBeacon,
        "passing guards must not stop the next-statue locator");
    AssertEqual(-396, passed.HideSpotTarget?.X, "success should retain the current statue target");

    var passedAgain = ObserveFloor60(
        tracker,
        Floor60Position(-420, 252, 152),
        now.AddMilliseconds(700),
        firstLeftEnabled: false,
        guardTiming: Floor60Timing());
    AssertEqual(
        Floor60GuardSpeechCue.None,
        passedAgain.SpeechCue,
        "one guarded gap should announce success only once");
    AssertEqual(-396, passedAgain.HideSpotTarget?.X, "locator remains active after pass confirmation");

    var reached = ObserveFloor60(
        tracker,
        Floor60Position(-396, 259, 303),
        now.AddMilliseconds(733),
        firstLeftEnabled: false,
        guardTiming: Floor60Timing());
    AssertEqual(
        Floor60GuardSpeechCue.HidingSpotReached,
        reached.SpeechCue,
        "the destination statue should still announce arrival after guard success");
    AssertEqual(true, reached.StopHideSpotBeacon, "statue arrival stops the locator");
}

static void AssertFloor60GuardCueFallsBackToNativeSafeEdge()
{
    var tracker = new Floor60SoldierTurnCueTracker(TimeSpan.Zero);
    var now = new DateTime(2026, 7, 29, 1, 0, 0, DateTimeKind.Utc);

    _ = ObserveFloor60(
        tracker,
        Floor60Position(-873, 63, 65),
        now,
        firstLeftEnabled: true);
    _ = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(50),
        firstLeftEnabled: true);

    var fallback = ObserveFloor60(
        tracker,
        Floor60Position(-551, 248, 152),
        now.AddMilliseconds(100),
        firstLeftEnabled: false);
    AssertEqual(
        Floor60GuardSpeechCue.MoveNow,
        fallback.SpeechCue,
        "an unreadable timing counter should retain the exact native safe-edge cue");
    AssertEqual(
        true,
        fallback.PlayHideSpotBeacon,
        "the fallback cue should start the destination statue locator");
}

static Floor60GuardCueDecision ObserveFloor60(
    Floor60SoldierTurnCueTracker tracker,
    FieldPositionSnapshot position,
    DateTime observedAt,
    byte barretSignalingProgress = 0,
    byte tifaSignalingProgress = 0,
    bool minigameActive = true,
    bool guardsCleared = false,
    bool userControlLocked = false,
    bool firstCompletionLineEnabled = true,
    bool secondCompletionLineEnabled = true,
    bool firstLeftEnabled = true,
    bool firstMiddleEnabled = true,
    bool firstRightEnabled = true,
    bool secondLeftEnabled = true,
    bool secondMiddleEnabled = true,
    bool secondRightEnabled = true,
    Floor60GuardTimingSnapshot guardTiming = default) =>
    tracker.Observe(
        position,
        barretSignalingProgress,
        tifaSignalingProgress,
        minigameActive,
        guardsCleared,
        userControlLocked,
        firstCompletionLineEnabled,
        secondCompletionLineEnabled,
        firstLeftEnabled,
        firstMiddleEnabled,
        firstRightEnabled,
        secondLeftEnabled,
        secondMiddleEnabled,
        secondRightEnabled,
        guardTiming,
        observedAt);

static Floor60GuardTimingSnapshot Floor60Timing(
    ushort firstLeftTicks = 0,
    ushort firstMiddleTicks = 0,
    ushort firstRightTicks = 0,
    ushort secondLeftTicks = 0,
    ushort secondMiddleTicks = 0,
    ushort secondRightTicks = 0) =>
    new(
        true,
        firstLeftTicks,
        firstMiddleTicks,
        firstRightTicks,
        secondLeftTicks,
        secondMiddleTicks,
        secondRightTicks,
        "test");

static FieldPositionSnapshot Floor60Position(int x, int y, ushort triangleId) =>
    new(
        FieldPositionReader.FieldModule,
        Floor60SoldierTurnCueTracker.FloorId,
        0,
        x,
        y,
        0,
        triangleId,
        0);

