static void AssertFloor60GuardTimingReaderMapsNativeWaitCounters()
{
    const int modelTable = 0x01200000;
    var memory = new Dictionary<int, byte>
    {
        [FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule,
        [FieldPositionReader.AddressFieldNumModels] = 9
    };
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, Floor60SoldierTurnCueTracker.FloorId);
    WriteUInt32(memory, FieldPositionReader.AddressFieldModelsPtr, modelTable);
    WriteFloor60GuardTimingFixture(memory, modelTable, 30, 5, -482, 15);
    WriteFloor60GuardTimingFixture(memory, modelTable, 31, 6, -346, 14);
    WriteFloor60GuardTimingFixture(memory, modelTable, 32, 7, -166, 13);
    WriteFloor60GuardTimingFixture(memory, modelTable, 33, 8, 173, 12);

    var reader = new Floor60GuardTimingStateReader(new DictionaryLegacyAddressSpace(memory));
    var firstHalf = reader.Read();
    AssertEqual(true, firstHalf.IsUsable, "floor 60 guard timing sample");
    AssertEqual((ushort)15, firstHalf.FirstLeftTicks, "line 22 native wait ticks");
    AssertEqual((ushort)14, firstHalf.FirstMiddleTicks, "line 23 native wait ticks");
    AssertEqual((ushort)13, firstHalf.FirstRightTicks, "line 24 native wait ticks");
    AssertEqual((ushort)12, firstHalf.SecondLeftTicks, "line 25 native wait ticks");
    AssertEqual((ushort)0, firstHalf.SecondMiddleTicks, "unoccupied line 26 station");
    AssertEqual((ushort)0, firstHalf.SecondRightTicks, "unoccupied line 27 station");

    WriteFloor60GuardTimingFixture(memory, modelTable, 30, 5, 361, 11);
    WriteFloor60GuardTimingFixture(memory, modelTable, 31, 6, 505, 10);
    WriteFloor60GuardTimingFixture(memory, modelTable, 32, 7, 900, 9);
    WriteFloor60GuardTimingFixture(memory, modelTable, 33, 8, 361, 7);
    var secondHalf = reader.Read();
    AssertEqual((ushort)11, secondHalf.SecondMiddleTicks, "line 26 retains the latest matching watcher");
    AssertEqual((ushort)10, secondHalf.SecondRightTicks, "line 27 native wait ticks");
    AssertEqual((ushort)0, secondHalf.FirstLeftTicks, "moving guard must not map to a gap");
}

static void AssertFloor60GuardTimingReaderRejectsInvalidAndTornState()
{
    const int modelTable = 0x01210000;
    var memory = new Dictionary<int, byte>
    {
        [FieldPositionReader.AddressCurrentModule] = 0,
        [FieldPositionReader.AddressFieldNumModels] = 9
    };
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, Floor60SoldierTurnCueTracker.FloorId);
    WriteUInt32(memory, FieldPositionReader.AddressFieldModelsPtr, modelTable);
    for (var entityId = 30; entityId <= 33; entityId++)
    {
        WriteFloor60GuardTimingFixture(
            memory,
            modelTable,
            entityId,
            entityId - 25,
            -482 + (entityId - 30) * 100,
            15);
    }

    var reader = new Floor60GuardTimingStateReader(new DictionaryLegacyAddressSpace(memory));
    AssertEqual(false, reader.Read().IsUsable, "non-field guard timing state");

    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    memory[FieldPositionReader.AddressFieldNumModels] = 8;
    AssertEqual(false, reader.Read().IsUsable, "guard timing requires models 5 through 8");

    memory[FieldPositionReader.AddressFieldNumModels] = 9;
    var tearing = new TearingLegacyAddressSpace(
        memory,
        (uint)(Floor60GuardTimingStateReader.AddressEntityWaitCounters + 30 * sizeof(ushort)));
    AssertEqual(
        false,
        new Floor60GuardTimingStateReader(tearing).Read().IsUsable,
        "changed native wait counter must reject the complete timing sample");
}

static void WriteFloor60GuardTimingFixture(
    Dictionary<int, byte> memory,
    int modelTable,
    int entityId,
    int modelIndex,
    int x,
    ushort waitTicks)
{
    WriteUInt16(
        memory,
        Floor60GuardTimingStateReader.AddressEntityWaitCounters + entityId * sizeof(ushort),
        waitTicks);
    WriteUInt32(
        memory,
        modelTable + modelIndex * FieldPositionReader.FieldModelStride + FieldPositionReader.ModelXOffset,
        unchecked((uint)x));
}

static void AssertFieldPositionReaderIgnoresNonFieldModules()
{
    var memory = new Dictionary<int, int>
