static void AssertFieldPositionReaderReadsLiveModelCoordinates()
{
    var memory = new Dictionary<int, int>();
    const int modelTable = 0x120000;
    const int modelIndex = 1;
    var modelBase = modelTable + modelIndex * FieldPositionReader.FieldModelStride;

    memory[FieldPositionReader.AddressCurrentModule] = 1;
    memory[FieldPositionReader.AddressFieldId] = 116;
    memory[FieldPositionReader.AddressFieldNumModels] = 3;
    memory[FieldPositionReader.AddressFieldCurrentModelId] = modelIndex;
    memory[FieldPositionReader.AddressFieldModelsPtr] = modelTable;
    memory[modelBase + FieldPositionReader.ModelXOffset] = 100;
    memory[modelBase + FieldPositionReader.ModelYOffset] = 200;
    memory[modelBase + FieldPositionReader.ModelZOffset] = -300;
    memory[modelBase + FieldPositionReader.ModelDirectionOffset] = 64;
    memory[FieldPositionReader.AddressFieldModelsObjs + modelIndex * FieldPositionReader.FieldObjectStride + FieldPositionReader.ObjectTriangleOffset] = 7;

    var reader = CreateFieldPositionReader(memory);
    var result = reader.Read();

    AssertEqual(true, result.IsUsable, "live field model position should be usable");
    AssertEqual((uint)modelBase, result.ModelBase, "live field model base should use the current model index");
    AssertEqual(
        new FieldPositionSnapshot(1, 116, modelIndex, 100, 200, -300, 7, 64),
        result.Position,
        "live field model reader should return the active model coordinates");
    AssertContains(result.Diagnostic, "model=1");
}

static void AssertFieldLadderStateReaderReadsNativeMountedState()
{
    var memory = new Dictionary<int, int>();
    const int eventTable = 0x02340000;
    const int modelIndex = 2;
    var eventBase = eventTable + modelIndex * FieldLadderStateReader.FieldEventDataStride;
    memory[FieldNavigationObjectReader.AddressFieldEventDataPtr] = eventTable;
    memory[FieldPositionReader.AddressFieldNumModels] = 4;
    memory[eventBase + FieldLadderStateReader.MovementModeOffset] = 4;
    memory[eventBase + FieldLadderStateReader.LadderReverseOffset] = 1;
    memory[eventBase + FieldLadderStateReader.LadderProgressOffset] = 1;
    memory[eventBase + FieldLadderStateReader.TargetTriangleOffset] = 42;
    memory[eventBase + FieldLadderStateReader.TargetXOffset] = 125 * FieldLadderStateReader.FixedPointScale;
    memory[eventBase + FieldLadderStateReader.TargetYOffset] = -75 * FieldLadderStateReader.FixedPointScale;
    memory[eventBase + FieldLadderStateReader.TargetZOffset] = 900 * FieldLadderStateReader.FixedPointScale;

    var reader = CreateFieldLadderStateReader(memory);
    var position = new FieldPositionSnapshot(1, 123, modelIndex, 0, 0, 0, 4, 0);
    var result = reader.Read(position);

    AssertEqual(true, result.IsUsable, "native ladder state should be readable");
    AssertEqual(true, result.State.IsMounted, "movement mode four should mean mounted on a ladder");
    AssertEqual(FieldLadderPhase.Climbing, result.State.Phase, "native ladder progress one");
    AssertEqual(FieldNavigationInput.Up, result.State.RequiredInput, "mode four reverse one should climb up");
    AssertEqual(new FieldNavigationRouteWaypoint(125, -75, 900), result.State.Target, "native ladder endpoint");
    AssertEqual(42, result.State.TargetTriangle, "native ladder target triangle");

    memory[eventBase + FieldLadderStateReader.MovementModeOffset] = 5;
    memory[eventBase + FieldLadderStateReader.LadderReverseOffset] = 0;
    result = reader.Read(position);
    AssertEqual(FieldNavigationInput.Right, result.State.RequiredInput, "mode five reverse zero should climb right");
}

static void AssertFieldLadderStateReaderCorrectsWallClimbPenultimateLadderToLeft()
{
    var memory = new Dictionary<int, int>();
    const int eventTable = 0x02340000;
    const int modelIndex = 0;
    var eventBase = eventTable + modelIndex * FieldLadderStateReader.FieldEventDataStride;
    memory[FieldNavigationObjectReader.AddressFieldEventDataPtr] = eventTable;
    memory[FieldPositionReader.AddressFieldNumModels] = 1;
    memory[eventBase + FieldLadderStateReader.MovementModeOffset] = 4;
    memory[eventBase + FieldLadderStateReader.LadderReverseOffset] = 1;
    memory[eventBase + FieldLadderStateReader.LadderProgressOffset] = 1;
    memory[eventBase + FieldLadderStateReader.TargetTriangleOffset] = 158;
    memory[eventBase + FieldLadderStateReader.TargetXOffset] = -40 * FieldLadderStateReader.FixedPointScale;
    memory[eventBase + FieldLadderStateReader.TargetYOffset] = 1039 * FieldLadderStateReader.FixedPointScale;
    memory[eventBase + FieldLadderStateReader.TargetZOffset] = 2273 * FieldLadderStateReader.FixedPointScale;

    var reader = CreateFieldLadderStateReader(memory);
    var position = new FieldPositionSnapshot(1, 223, modelIndex, -11, 1123, 1898, 33, 0);
    var result = reader.Read(position);

    AssertEqual(true, result.IsUsable, "the wall-climb penultimate ladder should be readable");
    AssertEqual(
        FieldNavigationInput.Left,
        result.State.RequiredInput,
        "field 223 entity 15 requires Left even though the generic native mode decodes as Up");

    memory[eventBase + FieldLadderStateReader.TargetTriangleOffset] = 25;
    memory[eventBase + FieldLadderStateReader.TargetXOffset] = -414 * FieldLadderStateReader.FixedPointScale;
    memory[eventBase + FieldLadderStateReader.TargetYOffset] = 1566 * FieldLadderStateReader.FixedPointScale;
    memory[eventBase + FieldLadderStateReader.TargetZOffset] = 3187 * FieldLadderStateReader.FixedPointScale;
