static void AssertFieldAudibleCueStateSuppressesMoviesCutscenesAndDialogue()
{
    var memory = new Dictionary<int, int>
    {
        [FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule,
        [FieldAudibleCueStateReader.AddressUserControl] = 0,
        [FieldAudibleCueStateReader.AddressActiveFieldMessageCount] = 0,
        [FieldAudibleCueStateReader.AddressFieldMovieActive] = 0
    };
    var reader = CreateFieldAudibleCueStateReader(memory);

    memory[FieldAudibleCueStateReader.AddressFieldMovieActive] = 1;
    AssertEqual("movie", reader.Read().Reason, "field movie playback should suppress cues");

    memory[FieldAudibleCueStateReader.AddressFieldMovieActive] = 0;
    memory[FieldAudibleCueStateReader.AddressUserControl] = 1;
    AssertEqual("scripted control lock", reader.Read().Reason, "UC-disabled cutscenes should suppress cues");

    memory[FieldAudibleCueStateReader.AddressUserControl] = 0;
    memory[FieldAudibleCueStateReader.AddressActiveFieldMessageCount] = 1;
    AssertEqual("dialogue", reader.Read().Reason, "active field dialogue should suppress cues");

    memory[FieldAudibleCueStateReader.AddressActiveFieldMessageCount] = 0;
    memory[FieldPositionReader.AddressCurrentModule] = 5;
    AssertEqual("not field gameplay", reader.Read().Reason, "non-field modules should suppress field cues");
}

static void AssertFieldAudibleCueStateFailsClosedForUnreadableActiveMessage()
{
    var memory = new Dictionary<int, int>
    {
        [FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule,
        [FieldAudibleCueStateReader.AddressUserControl] = 0,
        [FieldAudibleCueStateReader.AddressActiveFieldMessageCount] = 1,
        [FieldAudibleCueStateReader.AddressFieldMovieActive] = 0
    };
    var hasReadableMessage = false;
    var reader = new FieldAudibleCueStateReader(
        address => (byte)memory.GetValueOrDefault(address),
        address => (ushort)memory.GetValueOrDefault(address),
        () => hasReadableMessage);

    AssertEqual(
        "dialogue unavailable",
        reader.Read().Reason,
        "an active native message count with unreadable ownership must suppress navigation cues");

    hasReadableMessage = true;
    AssertEqual(
        "dialogue",
        reader.Read().Reason,
        "a native active message with readable window text must still suppress navigation cues");
}

