static void AssertFieldRunStateReaderReadsNativeRunButtonStatus()
{
    const int runResolver = 0x006499F7;
    const int runStatusPointer = 0x00D011C8;
    var callAddress = FieldRunStateReader.AddressFieldLoopSub + FieldRunStateReader.RunStatusResolverCallOffset;
    var memory = new Dictionary<int, int>
    {
        [callAddress] = 0xE8,
        [callAddress + 1] = runResolver - callAddress - 5,
        [runResolver + FieldRunStateReader.RunButtonStatusPointerOffset] = runStatusPointer,
        [runStatusPointer] = 0
    };

    var reader = CreateFieldRunStateReader(memory);
    AssertEqual(true, reader.TryRead(out var walking), "native run reader should resolve the FFNx run status pointer");
    AssertEqual(false, walking.IsRunning, "run button status 0 should use walk cadence");
    AssertEqual(runStatusPointer, walking.StatusAddress, "native run reader should expose the resolved run status pointer");
    AssertContains(walking.Diagnostic, "status=0");

    memory[runStatusPointer] = 1;
    AssertEqual(true, reader.TryRead(out var running), "native run reader should keep reading the resolved status pointer");
    AssertEqual(true, running.IsRunning, "nonzero run button status should use run cadence");
    AssertContains(running.Diagnostic, "running=True");
}

static void AssertFieldRunStateReaderRejectsUnexpectedCallInstruction()
{
    var callAddress = FieldRunStateReader.AddressFieldLoopSub + FieldRunStateReader.RunStatusResolverCallOffset;
    var memory = new Dictionary<int, int>
    {
        [callAddress] = 0x90
    };

    var reader = CreateFieldRunStateReader(memory);
    AssertEqual(false, reader.TryRead(out var result), "native run reader should reject an unexpected resolver instruction");
    AssertEqual(false, result.IsRunning, "failed native run read should not assume running");
    AssertContains(result.Diagnostic, "unexpected run resolver instruction");
}

static void AssertFieldFootstepTrackerPlaysOnlyAfterPositionChanges()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new FieldFootstepTracker(TimeSpan.FromMilliseconds(300));

    var start = new FieldPositionSnapshot(1, 116, 0, 100, 200, 300, 3, 16);
    AssertEqual(false, tracker.Observe(start, now), "first field position should prime the tracker without a step");
    AssertEqual(false, tracker.Observe(start, now.AddMilliseconds(400)), "unchanged field position should not play a step");

    var moved = start with { X = 104 };
    AssertEqual(true, tracker.Observe(moved, now.AddMilliseconds(450)), "changed field position should play a step");
    AssertEqual(false, tracker.Observe(moved, now.AddMilliseconds(900)), "settled unchanged position should stay silent");

    var menu = moved with { CurrentModule = 0 };
    AssertEqual(false, tracker.Observe(menu, now.AddMilliseconds(1200)), "non-field module should not play footsteps");
    AssertEqual(false, tracker.Observe(start with { X = 108 }, now.AddMilliseconds(1500)), "returning to field should re-prime before stepping");
}

static void AssertFieldFootstepTrackerThrottlesFastPositionChanges()
{
