static void AssertFieldFootstepTrackerUsesMeasuredPaceHysteresisWhenRunSignalFlickers()
{
    var now = new DateTime(2026, 7, 15, 0, 0, 0, DateTimeKind.Utc);
    var tracker = new FieldFootstepTracker(
        TimeSpan.FromMilliseconds(500),
        TimeSpan.FromMilliseconds(300),
        measuredRunSpeedUnitsPerSecond: 300);
    var start = new FieldPositionSnapshot(1, 116, 0, 0, 0, 0, 0, 0);

    tracker.Observe(start, now, isRunning: false);
    tracker.Observe(start with { X = 12 }, now.AddMilliseconds(100), isRunning: true);
    AssertEqual(FieldFootstepCadence.Walk, tracker.LastCadence, "a flickering native run bit must not turn measured walking into running");

    tracker.Observe(start with { X = 60 }, now.AddMilliseconds(200), isRunning: false);
    AssertEqual(FieldFootstepCadence.Run, tracker.LastCadence, "measured running should survive a false native run bit");

    tracker.Observe(start with { X = 88 }, now.AddMilliseconds(300), isRunning: false);
    AssertEqual(FieldFootstepCadence.Run, tracker.LastCadence, "pace inside the hysteresis band should retain running");

    tracker.Observe(start with { X = 100 }, now.AddMilliseconds(400), isRunning: true);
    AssertEqual(FieldFootstepCadence.Walk, tracker.LastCadence, "sustained measured walking should leave run cadence despite a true native bit");
}

