static void AssertFieldFootstepDistanceProbeRejectsInterruptedMovement()
{
    var now = new DateTime(2026, 7, 15, 0, 0, 0, DateTimeKind.Utc);
    var probe = new FieldFootstepDistanceProbe(reportEverySamples: 8);
    var start = new FieldPositionSnapshot(1, 116, 0, 0, 0, 300, 3, 16);

    probe.Observe(start, now, true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, false);
    probe.Observe(start with { X = 40 }, now.AddMilliseconds(80), true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, true);
    probe.Observe(start with { X = 80 }, now.AddMilliseconds(160), true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, false);
    probe.Observe(start with { X = 80 }, now.AddMilliseconds(240), true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, false);
    probe.Observe(start with { X = 120 }, now.AddMilliseconds(320), true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, true);
    AssertEqual(0, probe.Summary.Walk.SampleCount, "a stationary wall sample should discard the partial stride and its anchor");

    probe.Observe(start with { X = 160 }, now.AddMilliseconds(400), false, FieldNavigationInput.Right, FieldFootstepCadence.Walk, false);
    probe.Observe(start with { X = 200 }, now.AddMilliseconds(480), true, FieldNavigationInput.None, FieldFootstepCadence.Walk, false);
    probe.Observe(start with { X = 240 }, now.AddMilliseconds(560), true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, true);
    AssertEqual(0, probe.Summary.Walk.SampleCount, "background focus and released input should not bridge calibration strides");

    var nextField = start with { FieldId = 117, X = 0 };
    probe.Observe(nextField, now.AddMilliseconds(640), true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, true);
    probe.Observe(nextField with { X = 80 }, now.AddMilliseconds(720), true, FieldNavigationInput.Right, FieldFootstepCadence.Walk, true);
    AssertEqual(1, probe.Summary.Walk.SampleCount, "a field transition should establish a fresh anchor before recording");
    AssertEqual(80d, probe.Summary.Walk.AverageUnits, "only uninterrupted movement in the new field should be measured");
}

