static void AssertFieldNavigationObjectReaderUsesNativeModelAndCollectedState()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02000000;
    const int modelId = 8;
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 12;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 11] = modelId;
    memory[eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.VisibilityOffset] = 1;
    WriteUInt32(memory, eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.PositionXOffset, 385 * 4096);
    WriteUInt32(memory, eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.PositionYOffset, 3125 * 4096);
    WriteUInt32(memory, eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.PositionZOffset, unchecked((uint)(-272 * 4096)));
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x400 + 32] = 0;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    var reader = new FieldNavigationObjectReader(
        ReadInt32Value,
        ReadByte,
        id => id == 7 ? "Phoenix Down" : null,
        _ => null,
        FieldNavigationObjectCatalog.CreateOpeningReactor());
    var position = new FieldPositionSnapshot(1, 120, 0, 0, 0, 0, 0, 0);

    var targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "visible uncollected chest should be a navigation object");
    AssertEqual("Phoenix Down", targets[0].Label, "object label should come from kernel item text");
    AssertEqual(FieldObjectCueKind.Chest, targets[0].ObjectCueKind, "native treasure-box model should classify as a chest cue");
    AssertEqual(385, targets[0].X, "object x should come from live model state");
    AssertEqual(3125, targets[0].Y, "object y should come from live model state");
    AssertEqual(-272, targets[0].Z, "object z should come from live model state");
    AssertEqual(11, targets[0].TriggerEntityId, "model-backed object should retain its native entity for route collision exclusion");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x400 + 32] = 1 << 3;
    AssertEqual(0, reader.ReadTargets(position).Count, "native collected bit should remove chest from Objects");
}

static void AssertFieldNavigationObjectReaderUsesVariantCollectedState()
{
    var memory = new Dictionary<int, byte>();
    var collectedAddress = FieldNavigationObjectReader.AddressFieldBankBase + 0x400 + 32;
    var echoIdentity = new LoadedFieldScriptIdentity(
        116,
        0x02000000,
        "A5860AB734603DD6A62F9DD2CB262EB1E4F38A0A9B6ECFF09171F3CB6CB84D97");
    var firstGuard = new FieldNavigationObjectDefinition(
        116,
        9,
        FieldNavigationObjectKind.Item,
        NativeId: 0,
        CollectedBank: 15,
        CollectedAddress: 32,
        CollectedMask: 3,
        TargetKind: FieldNavigationObjectTargetKind.Location,
        StaticX: 10,
        StaticY: 20,
        StaticZ: 30);
    var secondGuard = firstGuard with
    {
        EntityId = 10,
        StaticX = 40
    };

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    var reader = new FieldNavigationObjectReader(
        _ => 0,
        ReadByte,
        id => id == 0 ? "Potion" : null,
        _ => null,
        [firstGuard, secondGuard],
        resolveCollectedMask: definition =>
            EchoSCompatibilityManifest.ResolveObjectCollectedMask(echoIdentity, definition));
    var position = new FieldPositionSnapshot(1, 116, 0, 0, 0, 0, 0, 0);

    AssertEqual(2, reader.ReadTargets(position).Count, "both Echo-S guard potions should begin available");

    memory[collectedAddress] = 1;
    var afterFirstGuard = reader.ReadTargets(position);
    AssertEqual(1, afterFirstGuard.Count, "taking the first Echo-S potion should leave only the second guard");
    AssertContains(afterFirstGuard[0].StableId, ":10:");

    memory[collectedAddress] = 3;
    AssertEqual(0, reader.ReadTargets(position).Count, "both Echo-S guard targets should clear after both potions");
}

