    WriteUInt32(memory, eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.PositionXOffset, 55 * 4096);
    WriteUInt32(memory, eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.PositionYOffset, 1583 * 4096);
    WriteUInt32(memory, eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.PositionZOffset, unchecked((uint)(-185 * 4096)));

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldNavigationObjectReader(
        ReadInt32Value,
        ReadByte,
