static void AssertFieldNavigationObjectReaderRejectsHiddenAndInvalidModels()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02100000;
    const int modelId = 3;
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 4;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 6] = modelId;
    memory[eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.VisibilityOffset] = 0;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldNavigationObjectReader(
        ReadInt32Value,
        ReadByte,
        _ => null,
        id => id == 53 ? "Restore" : null,
        FieldNavigationObjectCatalog.CreateOpeningReactor());
    var position = new FieldPositionSnapshot(1, 125, 0, 0, 0, 0, 0, 0);

    AssertEqual(0, reader.ReadTargets(position).Count, "VISI zero should remove hidden materia");

    memory[eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.VisibilityOffset] = 1;
    var targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "visible materia model should be available");
    AssertEqual("Restore Materia", targets[0].Label, "materia label should come from kernel text");

    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 6] = 0xFF;
    AssertEqual(0, reader.ReadTargets(position).Count, "entity without a live model mapping must be rejected");
}

static void AssertFieldNavigationObjectReaderReadsAllNativeByteBanks()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02200000;
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 2;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 4] = 1;
    memory[eventTable + FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.VisibilityOffset] = 1;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var definition = new FieldNavigationObjectDefinition(
        500,
        4,
        FieldNavigationObjectKind.Item,
        7,
        CollectedBank: 3,
        CollectedAddress: 10,
        CollectedMask: 0x04);
    var reader = new FieldNavigationObjectReader(
        ReadInt32Value,
        ReadByte,
        id => id == 7 ? "Phoenix Down" : null,
        _ => null,
        [definition]);
    var position = new FieldPositionSnapshot(1, 500, 0, 0, 0, 0, 0, 0);

    AssertEqual(1, reader.ReadTargets(position).Count, "clear Bank 3 collection bit should expose object");
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 10] = 0x04;
    AssertEqual(0, reader.ReadTargets(position).Count, "set Bank 3 collection bit should remove object");
}

static void AssertFieldNavigationObjectReaderUsesNativeLineTriggerState()
{
    var memory = new Dictionary<int, byte>();
    var lineEnabled = true;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var definition = new FieldNavigationObjectDefinition(
        500,
        35,
        FieldNavigationObjectKind.Item,
        241,
        CollectedBank: 3,
        CollectedAddress: 172,
        CollectedMask: 0x04,
        TargetKind: FieldNavigationObjectTargetKind.Line,
        StaticX: 122,
        StaticY: 830,
        StaticZ: 0,
        CueKindOverride: FieldObjectCueKind.Item,
        MinimumGameMoment: 1008);
    var reader = new FieldNavigationObjectReader(
        ReadInt32Value,
        ReadByte,
        id => id == 241 ? "HP Shout" : null,
        _ => null,
        [definition],
        entityId => lineEnabled && entityId == 35);
    var position = new FieldPositionSnapshot(1, 500, 0, 0, 0, 0, 0, 0);

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 1007);
    AssertEqual(0, reader.ReadTargets(position).Count, "line pickup should honor its native story threshold");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 1008);
    var target = reader.ReadTargets(position).Single();
    AssertEqual("HP Shout", target.Label, "line pickup should resolve its native inventory name");
    AssertEqual(122, target.X, "line pickup x should come from the native LINE midpoint");
    AssertEqual(830, target.Y, "line pickup y should come from the native LINE midpoint");
    AssertEqual(0, target.Z, "line pickup z should come from the native LINE midpoint");

    lineEnabled = false;
    AssertEqual(0, reader.ReadTargets(position).Count, "disabled native LINON state should hide a line pickup");

    lineEnabled = true;
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 172] = 0x04;
    AssertEqual(0, reader.ReadTargets(position).Count, "native collection state should remove a line pickup");
}

