static void AssertFieldNavigationObjectUsesNativeActionRangeForArrival()
{
    var definition = new FieldNavigationObjectDefinition(
        900,
        -1,
        FieldNavigationObjectKind.Named,
        Label: "Door control",
        TargetKind: FieldNavigationObjectTargetKind.Location,
        StaticX: 100,
        StaticY: 0,
        StaticZ: 0);
    var reader = new FieldNavigationObjectReader(
        _ => 0,
        _ => 0,
        _ => null,
        _ => null,
        [definition]);
    var position = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        900,
        0,
        25,
        0,
        0,
        0,
        0);
    var target = reader.ReadTargets(position).Single();
    AssertEqual(48, target.InteractionRadius, "field objects should use the native action-range arrival distance");

    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        new SingleTriangleRoutePlanner());
    var transform = new FieldNavigationControlTransform(-128);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    while (controller.CurrentCategory != FieldNavigationCategory.Objects)
    {
        controller.HandleAction(FieldNavigationAction.NextCategory, position, transform);
    }

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, position, transform);
    var tooFar = controller.UpdateLiveTracking(
        position,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80);
    AssertEqual(true, controller.BeaconEnabled, "an object 75 units away must remain under guidance");
    AssertEqual(
        false,
        (tooFar?.Speech ?? string.Empty).Contains("reached", StringComparison.OrdinalIgnoreCase),
        "configured generic arrival range must not stop an object before action range");

    var actionable = position with { X = 52 };
    var arrived = controller.UpdateLiveTracking(
        actionable,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80);
    AssertContains(arrived?.Speech ?? string.Empty, "Door control reached");
    AssertContains(arrived?.Speech ?? string.Empty, "Interact here");
    AssertContains(arrived?.Speech ?? string.Empty, "Navigation paused");
}

static void AssertFieldNavigationObjectCatalogCoversTheFullGame()
{
    var definitions = FieldNavigationObjectCatalog.CreateAllFields();

    AssertEqual(true, definitions.Count >= 339, "full-game object catalog should include model, contact, and background pickups plus save points");
    AssertEqual(true, definitions.Select(definition => definition.FieldId).Distinct().Count() >= 180, "object catalog field coverage");
    AssertEqual(true, definitions.Any(definition =>
        definition.FieldId == 120 &&
        definition.EntityId == 11 &&
        definition.Kind == FieldNavigationObjectKind.Item &&
        definition.NativeId == 7), "catalog should include opening Phoenix Down chest");
    var reactorElevatorSwitch = definitions.Single(definition =>
        definition.FieldId == 121 &&
        definition.EntityId == 5 &&
        definition.Label == "Reactor elevator switch; press OK");
    AssertEqual(FieldNavigationObjectKind.Named, reactorElevatorSwitch.Kind, "reactor elevator switch kind");
    AssertEqual(FieldNavigationObjectTargetKind.Location, reactorElevatorSwitch.TargetKind, "reactor elevator switch target kind");
    AssertEqual(86, reactorElevatorSwitch.StaticX, "reactor elevator switch x");
    AssertEqual(64, reactorElevatorSwitch.StaticY, "reactor elevator switch y");
    AssertEqual(5, reactorElevatorSwitch.StaticZ, "reactor elevator switch z");
    AssertEqual("ele", reactorElevatorSwitch.SourceEntityName, "reactor elevator switch native entity");
    AssertEqual(true, definitions.Any(definition =>
        definition.FieldId == 125 &&
        definition.Kind == FieldNavigationObjectKind.Materia &&
        definition.NativeId == 53), "catalog should include opening Restore Materia");
    AssertEqual(true, definitions.Any(definition =>
        definition.FieldId == 736 &&
        definition.Kind == FieldNavigationObjectKind.Materia &&
        definition.NativeId == 21), "catalog should include late-game W-Item Materia");
    AssertEqual(true, definitions.Any(definition =>
        definition.Kind == FieldNavigationObjectKind.SavePoint &&
        string.Equals(definition.Label, "Save Point", StringComparison.Ordinal)), "catalog should include save points");
    AssertEqual(true, definitions.Any(definition => definition.CollectedBank is 1 or 3 or 13), "catalog should preserve non-Bank-15 collection flags");

    var linePickups = definitions
        .Where(definition =>
            definition.TargetKind == FieldNavigationObjectTargetKind.Line &&
            definition.Kind is FieldNavigationObjectKind.Item or FieldNavigationObjectKind.Materia)
        .ToArray();
    AssertEqual(16, linePickups.Length, "curated native background-only pickup coverage");
    AssertEqual(true, linePickups.All(definition => definition.CollectedMask != 0), "background pickups should have native collection state");
    AssertEqual(true, linePickups.Any(definition =>
        definition.SourceFieldName == "blin64" &&
        definition.EntityId == 35 &&
        definition.NativeId == 241 &&
        definition.MinimumGameMoment == 1008), "catalog should include the late-game HP Shout locker without exposing it early");
    AssertEqual(true, linePickups.Any(definition =>
        definition.SourceFieldName == "elminn_2" &&
        definition.NativeId == 6), "catalog should include the Kalm cabinet Megalixir");
    AssertEqual(true, linePickups.Any(definition =>
        definition.SourceFieldName == "elmin2_2" &&
        definition.NativeId == 3), "catalog should include the Kalm upstairs cabinet Ether");
    AssertEqual(true, linePickups.Any(definition =>
        definition.SourceFieldName == "elmin3_2" &&
        definition.NativeId == 72), "catalog should include the Kalm upstairs cabinet Guard Source");
    AssertEqual(true, linePickups.Any(definition =>
        definition.SourceFieldName == "gnmk" &&
        definition.Kind == FieldNavigationObjectKind.Materia &&
        definition.NativeId == 78), "catalog should include the background-only Titan Materia spot");
    AssertEqual(true, definitions.Any(definition =>
        definition.SourceFieldName == "wcrimb_2" &&
        definition.EntityId == 11 &&
        definition.Kind == FieldNavigationObjectKind.Named &&
        definition.Label == "Optional battery socket" &&
        definition.CollectedBank == 1 &&
        definition.CollectedAddress == 165 &&
        definition.CollectedMask == 0x10), "catalog should include the optional wall-climb battery Ether");
    AssertEqual(true, linePickups.Any(definition =>
        definition.SourceFieldName == "hideway1" &&
        definition.NativeId == 225 &&
        definition.CueKindOverride == FieldObjectCueKind.Chest), "catalog should include the Wutai hidden-passage chest");
    AssertEqual(true, linePickups.Any(definition =>
        definition.SourceFieldName == "mkt_ia" &&
        definition.NativeId == 159 &&
        definition.MinimumGameMoment == 999), "catalog should include the late-game Premium Heart console");
    AssertEqual(true, definitions.Any(definition =>
        definition.SourceFieldName == "las3_3" &&
        definition.EntityId == 5 &&
        definition.Kind == FieldNavigationObjectKind.Materia &&
        definition.NativeId == 12), "catalog should include the contact-triggered Mega All Materia");
    AssertEqual(true, definitions.Any(definition =>
        definition.SourceFieldName == "mtcrl_5" &&
        definition.EntityId == 5 &&
        definition.NativeId == 298), "catalog should include the first Mt. Corel fall treasure");
    AssertEqual(true, definitions.Any(definition =>
        definition.SourceFieldName == "mtcrl_5" &&
        definition.EntityId == 6 &&
        definition.NativeId == 196), "catalog should include the second Mt. Corel fall treasure");
}

