    AssertEqual("Locked left display chest", earlyDisplayChests[0].Label, "left display chest label");
    AssertEqual("Locked right display chest", earlyDisplayChests[1].Label, "right display chest label");

    foreach (var lateChest in definitions.Where(definition =>
                 definition.FieldId == 236 &&
                 definition.EntityId is 17 or 18 &&
                 definition.Kind == FieldNavigationObjectKind.Item))
    {
        AssertEqual(1008, lateChest.MinimumGameMoment, $"late display chest {lateChest.EntityId} must not reveal its contents on the first visit");
    }

    var couponLabels = new Dictionary<int, string>
    {
