    {
        var definition = definitions.Single(candidate =>
            candidate.FieldId == 245 &&
            candidate.EntityId == coupon.Key &&
            candidate.Kind == FieldNavigationObjectKind.Named &&
            candidate.MaximumGameMoment == 1007);
