        AssertEqual(3, definition.CollectedBank, $"floor 63 coupon entity {coupon.Key} collection bank");
        AssertEqual(177, definition.CollectedAddress, $"floor 63 coupon entity {coupon.Key} collection address");
    }

    var libraryBooks = definitions.Where(definition =>
        definition.FieldId is 243 or 244 &&
        definition.EntityId is >= 19 and <= 30 &&
        definition.Kind == FieldNavigationObjectKind.Named).ToArray();
    AssertEqual(24, libraryBooks.Length, "all twenty-four readable floor 62 books should be targetable");
    AssertEqual(
        4,
        libraryBooks
            .Select(definition => definition.Label?.Split(',', 2)[0])
            .Distinct(StringComparer.Ordinal)
            .Count(),
        "the four floor 62 library sections should retain distinct labels");
    foreach (var library in libraryBooks.GroupBy(definition => definition.Label?.Split(',', 2)[0]))
    {
        AssertEqual(6, library.Count(), $"{library.Key} should expose exactly six readable book positions");
        AssertEqual(
            3,
            library.Select(definition =>
                    definition.Label?.Contains("top shelf", StringComparison.Ordinal) == true ? "top" :
                    definition.Label?.Contains("middle shelf", StringComparison.Ordinal) == true ? "middle" :
                    definition.Label?.Contains("bottom shelf", StringComparison.Ordinal) == true ? "bottom" :
                    "missing")
                .Distinct(StringComparer.Ordinal)
                .Count(),
            $"{library.Key} should identify top, middle, and bottom shelves");
    }

    var quickPasswordBook = libraryBooks.Single(definition =>
        definition.FieldId == 244 &&
        definition.EntityId == 27);
    AssertEqual(
        "Space Development Research Library, middle shelf, left book",
        quickPasswordBook.Label,
        "the guide's quick password clue should identify the left book on the middle shelf");
    AssertEqual(
        FieldNavigationObjectTargetKind.Location,
        quickPasswordBook.TargetKind,
        "the native triangle-gated quick password book should be a location target");
    AssertEqual(193, quickPasswordBook.StaticX, "quick password book native triangle x");
    AssertEqual(697, quickPasswordBook.StaticY, "quick password book native triangle y");

    var midgarParts = definitions.Where(definition =>
        definition.FieldId == 248 &&
        definition.EntityId is >= 15 and <= 19 &&
        definition.Label?.StartsWith("Midgar Parts chest ", StringComparison.Ordinal) == true).ToArray();
    AssertEqual(5, midgarParts.Length, "all five Midgar Parts chests should be distinct");
    AssertEqual(true, midgarParts.All(definition => definition.CollectedMask != 0), "Midgar Parts chests should disappear after collection");

    var keycardChest = definitions.Single(definition =>
        definition.FieldId == 248 &&
        definition.EntityId == 20 &&
        definition.Label == "Keycard 66 chest");
    AssertEqual(1, keycardChest.CollectedBank, "Keycard 66 chest collection bank");
    AssertEqual(57, keycardChest.CollectedAddress, "Keycard 66 chest collection address");
    AssertEqual((byte)0x08, keycardChest.CollectedMask, "Keycard 66 chest collection mask");

    var guidePickups = new[]
    {
        (FieldId: 230, EntityId: 16, Kind: FieldNavigationObjectKind.Item, NativeId: 5, Description: "emergency-stair Elixir"),
        (FieldId: 247, EntityId: 29, Kind: FieldNavigationObjectKind.Item, NativeId: 7, Description: "floor 64 Phoenix Down"),
        (FieldId: 247, EntityId: 32, Kind: FieldNavigationObjectKind.Item, NativeId: 3, Description: "floor 64 Ether"),
        (FieldId: 256, EntityId: 9, Kind: FieldNavigationObjectKind.Materia, NativeId: 60, Description: "floor 67 Poison materia"),
        (FieldId: 262, EntityId: 8, Kind: FieldNavigationObjectKind.Item, NativeId: 0, Description: "floor 68 Potion one"),
        (FieldId: 262, EntityId: 9, Kind: FieldNavigationObjectKind.Item, NativeId: 0, Description: "floor 68 Potion two"),
        (FieldId: 262, EntityId: 10, Kind: FieldNavigationObjectKind.Item, NativeId: 0, Description: "floor 68 Potion three"),
        (FieldId: 262, EntityId: 11, Kind: FieldNavigationObjectKind.Item, NativeId: 0, Description: "floor 68 Potion four"),
        (FieldId: 263, EntityId: 8, Kind: FieldNavigationObjectKind.Materia, NativeId: 44, Description: "floor 68 Enemy Skill materia")
    };
    foreach (var pickup in guidePickups)
    {
        AssertEqual(
            true,
            definitions.Any(definition =>
                definition.FieldId == pickup.FieldId &&
                definition.EntityId == pickup.EntityId &&
                definition.Kind == pickup.Kind &&
                definition.NativeId == pickup.NativeId),
            $"Shinra guide pickup should be cataloged: {pickup.Description}");
    }
}

