static void AssertFloor63DuctShaftsAreLabeledAndReachable()
{
    var expectedShafts = new[]
    {
        (Label: "Backtrack shaft to A Coupon room", X: -827, Y: 124, Z: 369),
        (Label: "Shaft to B Coupon room", X: 384, Y: 123, Z: 369),
        (Label: "Shaft to floor 63 computer room", X: 644, Y: -501, Z: 369)
    };
    var definitions = FieldNavigationObjectCatalog.CreateAllFields()
        .Where(definition =>
            definition.FieldId == 246 &&
            definition.Kind == FieldNavigationObjectKind.Named)
        .ToArray();

    AssertEqual(expectedShafts.Length, definitions.Length, "floor 63 duct shaft count");
    foreach (var expected in expectedShafts)
    {
        var definition = definitions.Single(candidate => candidate.Label == expected.Label);
        AssertEqual(FieldNavigationObjectTargetKind.Location, definition.TargetKind, $"{expected.Label} target kind");
        AssertEqual(expected.X, definition.StaticX, $"{expected.Label} x");
        AssertEqual(expected.Y, definition.StaticY, $"{expected.Label} y");
        AssertEqual(expected.Z, definition.StaticZ, $"{expected.Label} z");
    }

    var start = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        246,
        0,
        -827,
        124,
        369,
        36,
        0);
    var memory = new Dictionary<int, byte>
    {
        [FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 177] = 0x02
    };
    var objectReader = new FieldNavigationObjectReader(
        _ => 0,
        address => memory.GetValueOrDefault(address),
        _ => null,
        _ => null,
        definitions,
        _ => false);
    AssertEqual(
        2,
        objectReader.ReadTargets(start).Count,
        "after A Coupon, the duct should expose the B route and the explicit A-room backtrack only");

    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(246));
    foreach (var expected in expectedShafts)
    {
        var target = new FieldNavigationTarget(
            246,
            FieldNavigationCategory.Objects,
            expected.Label,
            expected.X,
            expected.Y,
            expected.Z);
        AssertEqual(
            true,
            planner.TryBuildRoute(start, target, out _),
            $"{expected.Label} should be reachable through the native duct walkmesh: {planner.LastDiagnostic}");
    }
}

static void AssertFloor63CouponRouteUsesNativeDoorAndCouponState()
{
    var definitions = FieldNavigationObjectCatalog.CreateAllFields()
        .Where(definition =>
            definition.FieldId is 245 or 246 &&
            definition.Kind == FieldNavigationObjectKind.Named)
        .ToArray();

    var firstDoor = definitions.Single(definition =>
        definition.Label == "Coupon route door 1 of 3, top corridor");
    AssertEqual(FieldNavigationObjectTargetKind.Location, firstDoor.TargetKind, "first coupon door target kind");
    AssertEqual(414, firstDoor.StaticX, "first coupon door approach x");
    AssertEqual(972, firstDoor.StaticY, "first coupon door approach y");
    AssertEqual(3, firstDoor.RequiredBank, "first coupon door activation bank");
    AssertEqual(177, firstDoor.RequiredAddress, "first coupon door activation address");
    AssertEqual((byte)0x10, firstDoor.RequiredMask, "first coupon door activation mask");
    AssertEqual((byte)0x10, firstDoor.RequiredValue, "first coupon door activation value");
    AssertEqual(3, firstDoor.CollectedBank, "first coupon door open bank");
    AssertEqual(174, firstDoor.CollectedAddress, "first coupon door open address");
    AssertEqual((byte)0x02, firstDoor.CollectedMask, "native D2 open bit");

    var secondDoor = definitions.Single(definition =>
        definition.Label == "Coupon route door 2 of 3, second door below the top corridor");
    AssertEqual(-549, secondDoor.StaticX, "second coupon door approach x");
    AssertEqual(752, secondDoor.StaticY, "second coupon door approach y");
    AssertEqual(174, secondDoor.RequiredAddress, "second coupon door requires D2");
    AssertEqual((byte)0x02, secondDoor.RequiredMask, "second coupon door D2 mask");
    AssertEqual((byte)0x02, secondDoor.RequiredValue, "second coupon door D2 value");
    AssertEqual(174, secondDoor.CollectedAddress, "second coupon door open address");
    AssertEqual((byte)0x08, secondDoor.CollectedMask, "native D4 open bit");
    AssertEqual("D4", secondDoor.SourceEntityName, "second coupon door native entity");

    var aCoupon = definitions.Single(definition => definition.Label == "A Coupon");
    AssertEqual(174, aCoupon.RequiredAddress, "A Coupon requires the second guide door");
    AssertEqual((byte)0x08, aCoupon.RequiredMask, "A Coupon native D4 mask");
    AssertEqual((byte)0x08, aCoupon.RequiredValue, "A Coupon native D4 value");

    var aDuct = definitions.Single(definition => definition.Label == "A Coupon room duct entrance");
    AssertEqual(177, aDuct.RequiredAddress, "A duct requires A Coupon");
    AssertEqual((byte)0x02, aDuct.RequiredMask, "A duct coupon mask");
    AssertEqual(177, aDuct.CollectedAddress, "A duct completion uses persistent coupon state");
    AssertEqual((byte)0x08, aDuct.CollectedMask, "A duct hides after B Coupon is collected");

    var bCoupon = definitions.Single(definition => definition.Label == "B Coupon");
    AssertEqual(177, bCoupon.RequiredAddress, "B Coupon requires the persistent A Coupon state");
    AssertEqual((byte)0x02, bCoupon.RequiredMask, "B Coupon A-coupon mask");
    AssertEqual((byte)0x02, bCoupon.RequiredValue, "B Coupon A-coupon value");

    var thirdDoor = definitions.Single(definition =>
        definition.Label == "Coupon route door 3 of 3, between B and C Coupon rooms");
    AssertEqual(-148, thirdDoor.StaticX, "third coupon door approach x");
    AssertEqual(-356, thirdDoor.StaticY, "third coupon door approach y");
    AssertEqual(177, thirdDoor.RequiredAddress, "third coupon door requires B Coupon");
    AssertEqual((byte)0x08, thirdDoor.RequiredMask, "third coupon door B Coupon mask");
    AssertEqual((byte)0x08, thirdDoor.RequiredValue, "third coupon door B Coupon value");
    AssertEqual(175, thirdDoor.CollectedAddress, "third coupon door open address");
    AssertEqual((byte)0x80, thirdDoor.CollectedMask, "native D16 open bit");
    AssertEqual("D16", thirdDoor.SourceEntityName, "third coupon door native entity");

    var cCoupon = definitions.Single(definition => definition.Label == "C Coupon");
    AssertEqual(175, cCoupon.RequiredAddress, "C Coupon requires D16 to be open");
    AssertEqual((byte)0x80, cCoupon.RequiredMask, "C Coupon D16 mask");
    AssertEqual((byte)0x80, cCoupon.RequiredValue, "C Coupon D16 value");

    var bDuct = definitions.Single(definition => definition.Label == "B Coupon room duct entrance");
    AssertEqual(177, bDuct.RequiredAddress, "return duct requires all coupons");
    AssertEqual((byte)0x0E, bDuct.RequiredMask, "return duct all-coupon mask");
    AssertEqual(181, bDuct.CollectedAddress, "return duct hides after coupon exchange");
    AssertEqual((byte)0x80, bDuct.CollectedMask, "coupon exchange completion bit");

    var ductTargets = definitions
        .Where(definition => definition.FieldId == 246)
        .ToDictionary(definition => definition.Label!, StringComparer.Ordinal);
    AssertEqual((byte)0x02, ductTargets["Shaft to B Coupon room"].RequiredMask, "B shaft requires A Coupon");
    AssertEqual(177, ductTargets["Shaft to B Coupon room"].CollectedAddress, "B shaft uses persistent coupon state");
    AssertEqual((byte)0x08, ductTargets["Shaft to B Coupon room"].CollectedMask, "B shaft hides after B Coupon");
    AssertEqual((byte)0x0E, ductTargets["Shaft to floor 63 computer room"].RequiredMask, "computer shaft requires all coupons");
    AssertEqual((byte)0x0E, ductTargets["Shaft to floor 63 computer room"].RequiredValue, "computer shaft all-coupon value");
    AssertEqual(181, ductTargets["Shaft to floor 63 computer room"].CollectedAddress, "computer shaft uses coupon exchange completion");

    var doorDefinitions = definitions
        .Where(definition => definition.Label?.StartsWith("Coupon route door", StringComparison.Ordinal) == true)
        .ToArray();
    var memory = new Dictionary<int, byte>
    {
        [FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 177] = 0x10
    };
    var objectReader = new FieldNavigationObjectReader(
        _ => 0,
        address => memory.GetValueOrDefault(address),
        _ => null,
        _ => null,
        doorDefinitions,
        _ => false);
    var position = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        245,
        0,
        920,
        -570,
        0,
        0,
        0);
    AssertEqual(
        "Coupon route door 1 of 3, top corridor",
        string.Join("|", objectReader.ReadTargets(position).Select(target => target.Label)),
        "activated puzzle should expose only D2");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 174] = 0x03;
    AssertEqual(
        "Coupon route door 2 of 3, second door below the top corridor",
        string.Join("|", objectReader.ReadTargets(position).Select(target => target.Label)),
        "opening D2 and the ignored D1 side door must not hide the still-closed D4 route door");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 174] = 0x0A;
    AssertEqual(
        string.Empty,
        string.Join("|", objectReader.ReadTargets(position).Select(target => target.Label)),
        "after D2 and D4, no additional door should be offered before B Coupon");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 177] = 0x18;
    AssertEqual(
        "Coupon route door 3 of 3, between B and C Coupon rooms",
        string.Join("|", objectReader.ReadTargets(position).Select(target => target.Label)),
        "B Coupon should expose D16 as the final route door");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 175] = 0x80;
    AssertEqual(
        string.Empty,
        string.Join("|", objectReader.ReadTargets(position).Select(target => target.Label)),
        "opening D16 should complete the three-door route");

    int[] allDoorBoundaryTriangles =
    [
        260, 261, 195, 196, 270, 402, 328, 329, 330, 244, 245, 246,
        183, 184, 185, 340, 341, 200, 223, 110, 111, 281, 282, 359,
        360, 232, 233, 205, 206, 295, 296, 306, 307, 310, 311, 212,
        213, 127, 128, 120, 122, 168, 169, 139, 140, 161, 162, 388,
        145, 146, 157, 158, 49, 50
    ];
    var walkmeshResult = CreateInstalledFieldWalkmeshReader(245).Read(position);
    AssertEqual(true, walkmeshResult.IsUsable, $"Floor 63 walkmesh should load: {walkmeshResult.Diagnostic}");
    var walkmesh = walkmeshResult.Walkmesh
        ?? throw new InvalidOperationException("Floor 63 walkmesh was unexpectedly empty.");
    var onlyD2Open = allDoorBoundaryTriangles
        .Where(triangle => triangle is not 195 and not 196)
        .ToHashSet();
    AssertEqual(
        true,
        FieldWalkmeshPathfinder.TryBuildRoute(
            walkmesh,
            194,
            429,
            997,
            0,
            -549,
            752,
            0,
            onlyD2Open.Contains,
            out _,
            out _,
            out _),
        "after D2 opens, D4's action side must be reachable without crossing another locked door");
    AssertEqual(
        false,
        FieldWalkmeshPathfinder.TryBuildRoute(
            walkmesh,
            194,
            429,
            997,
            0,
            -1221,
            759,
            0,
            onlyD2Open.Contains,
            out _,
            out _,
            out _),
        "the discarded D3 target is behind another closed door after D2 and must not be routed");

    var d2AndD4Open = allDoorBoundaryTriangles
        .Where(triangle => triangle is not 195 and not 196 and not 328 and not 329 and not 330)
        .ToHashSet();
    AssertEqual(
        true,
        FieldWalkmeshPathfinder.TryBuildRoute(
            walkmesh,
            327,
            -549,
            752,
            0,
            -993,
            83,
            0,
            d2AndD4Open.Contains,
            out _,
            out _,
            out _),
        "after D2 and D4 open, A Coupon must be reachable with every other door still locked");

    AssertEqual(
        true,
        FieldWalkmeshPathfinder.TryBuildRoute(
            walkmesh,
            164,
            302,
            -31,
            -10,
            -148,
            -356,
            0,
            d2AndD4Open.Contains,
            out _,
            out _,
            out _),
        "after B Coupon, native D16's B-room approach must be reachable while every unrelated door remains locked");
    AssertEqual(
        false,
        FieldWalkmeshPathfinder.TryBuildRoute(
            walkmesh,
            154,
            -148,
            -356,
            0,
            -274,
            83,
            0,
            d2AndD4Open.Contains,
            out _,
            out _,
            out _),
        "Coupon C must remain unreachable while native D16 triangles 310 and 311 are locked");

    var d2D4AndD16Open = d2AndD4Open
        .Where(triangle => triangle is not 310 and not 311)
        .ToHashSet();
    AssertEqual(
        true,
        FieldWalkmeshPathfinder.TryBuildRoute(
            walkmesh,
            154,
            -148,
            -356,
            0,
            -274,
            83,
            0,
            d2D4AndD16Open.Contains,
            out var cCouponRoute,
            out _,
            out _),
        "opening native D16 must make Coupon C reachable while every unrelated door remains locked");
    AssertEqual(
        true,
        cCouponRoute.Contains(310) && cCouponRoute.Contains(311),
        "the verified Coupon C route must cross D16's native boundary triangles");
}

