{
    var materia = new FieldNavigationObjectDefinition(1, 1, FieldNavigationObjectKind.Materia, SourceModelResource: "fieldbg_materia.char");
    var woodenChest = new FieldNavigationObjectDefinition(1, 2, FieldNavigationObjectKind.Item, SourceModelResource: "testfieldbg_trb_wood.char");
    var specialChest = new FieldNavigationObjectDefinition(1, 3, FieldNavigationObjectKind.Item, SourceModelResource: "testfieldbg_trbox_k.char");
    var looseItem = new FieldNavigationObjectDefinition(1, 4, FieldNavigationObjectKind.Item, SourceModelResource: "testfieldbg_potion.char");
    var named = new FieldNavigationObjectDefinition(1, 5, FieldNavigationObjectKind.Named, Label: "Save Point");
    var backgroundChest = new FieldNavigationObjectDefinition(
        1,
        6,
        FieldNavigationObjectKind.Item,
        CueKindOverride: FieldObjectCueKind.Chest);

    AssertEqual(FieldObjectCueKind.Materia, FieldNavigationObjectCueClassifier.Classify(materia), "materia cue classification");
    AssertEqual(FieldObjectCueKind.Chest, FieldNavigationObjectCueClassifier.Classify(woodenChest), "wooden chest cue classification");
    AssertEqual(FieldObjectCueKind.Chest, FieldNavigationObjectCueClassifier.Classify(specialChest), "special chest cue classification");
    AssertEqual(FieldObjectCueKind.Item, FieldNavigationObjectCueClassifier.Classify(looseItem), "loose inventory item cue classification");
    AssertEqual(FieldObjectCueKind.None, FieldNavigationObjectCueClassifier.Classify(named), "named navigation objects should not emit proximity cues");
    AssertEqual(FieldObjectCueKind.Chest, FieldNavigationObjectCueClassifier.Classify(backgroundChest), "background chest cue override");
}

static void AssertFieldObjectProximityCueTrackerClustersAndAttenuates()
{
    var now = new DateTime(2026, 7, 11, 0, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 120, 0, 0, 0, 0, 0, 0);
    var tracker = new FieldObjectProximityCueTracker(innerRange: 80, outerRange: 400, clusterRadius: 40, pulseInterval: TimeSpan.FromSeconds(1));
    var targets = new[]
    {
        new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Restore Materia", 80, 0, 0, "materia:1", FieldObjectCueKind.Materia),
        new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Chest", 240, 0, 0, "chest:1", FieldObjectCueKind.Chest),
        new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Potion", 400, 0, 0, "item:far", FieldObjectCueKind.Item)
    };

    var cues = tracker.Update(position, targets, now);
    AssertEqual(2, cues.Count, "objects at the outer cutoff should be silent");
    AssertApprox(1f, cues.Single(cue => cue.Kind == FieldObjectCueKind.Materia).Gain, 0.001f, "inner-range object gain");
    AssertApprox(0.5f, cues.Single(cue => cue.Kind == FieldObjectCueKind.Chest).Gain, 0.001f, "mid-range object gain");

    var clusteredTracker = new FieldObjectProximityCueTracker(80, 400, 40, TimeSpan.FromSeconds(1));
    var clusteredTargets = new[]
    {
        new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Potion", 100, 0, 0, "item:1", FieldObjectCueKind.Item),
        new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Potion", 120, 0, 0, "item:2", FieldObjectCueKind.Item),
        new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Ether", 170, 0, 0, "item:3", FieldObjectCueKind.Item),
        new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Materia", 110, 0, 0, "materia:2", FieldObjectCueKind.Materia)
    };

    var clustered = clusteredTracker.Update(position, clusteredTargets, now);
    AssertEqual(3, clustered.Count, "same-kind nearby pickups should cluster without merging distinct locations or types");
    AssertEqual(110, clustered.Single(cue => cue.ClusterKey.Contains("item:1", StringComparison.Ordinal)).Target.X, "cluster x should be the live member centroid");
    AssertEqual(0, clusteredTracker.Update(position, clusteredTargets, now.AddMilliseconds(500)).Count, "cluster should wait for its pulse interval");
    AssertEqual(3, clusteredTracker.Update(position, clusteredTargets, now.AddSeconds(1)).Count, "clusters should pulse again after the interval");
}

static void AssertFieldObjectProximityCueTrackerKeepsRemainingStackedItem()
{
    var now = new DateTime(2026, 7, 11, 0, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 120, 0, 0, 0, 0, 0, 0);
    var tracker = new FieldObjectProximityCueTracker(80, 400, 40, TimeSpan.FromSeconds(1));
    var first = new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Potion", 100, 0, 0, "item:1", FieldObjectCueKind.Item);
    var second = new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Potion", 120, 0, 0, "item:2", FieldObjectCueKind.Item);

    var initial = tracker.Update(position, [first, second], now);
    AssertEqual(1, initial.Count, "stacked pickups should initially emit one cue");
    AssertEqual(110, initial[0].Target.X, "stacked pickup cue should use the centroid");

    var afterFirstPickup = tracker.Update(position, [second], now.AddMilliseconds(500));
    AssertEqual(1, afterFirstPickup.Count, "remaining stacked pickup should continue cueing immediately");
    AssertEqual(120, afterFirstPickup[0].Target.X, "remaining pickup cue should move to its live position");

    AssertEqual(0, tracker.Update(position, [], now.AddMilliseconds(600)).Count, "cluster should stop after every member is collected");
}

static void AssertFieldObjectProximitySpatializerTracksMovementAroundObject()
{
    var transform = new FieldNavigationControlTransform(0);
    var target = new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Potion", 100, 0, 0, "item:1", FieldObjectCueKind.Item);
    var leftOfObject = new FieldPositionSnapshot(1, 120, 0, 0, 0, 0, 0, 0);
    var rightOfObject = leftOfObject with { X = 200 };

    var fromLeft = FieldObjectProximitySpatializer.CreateCue(leftOfObject, target, transform)
        ?? throw new InvalidOperationException("object cue should spatialize from the left side");
    var fromRight = FieldObjectProximitySpatializer.CreateCue(rightOfObject, target, transform)
        ?? throw new InvalidOperationException("object cue should spatialize from the right side");
    AssertEqual(true, fromLeft.SteamAudioX < -0.9f, "object should render to one side before passing it");
    AssertEqual(true, fromRight.SteamAudioX > 0.9f, "object direction should flip after walking around it");

    var atObject = FieldObjectProximitySpatializer.CreateCue(leftOfObject with { X = 100 }, target, transform)
        ?? throw new InvalidOperationException("object cue should remain audible at the exact pickup location");
    AssertEqual("here", atObject.Direction, "exact pickup location cue direction");
}

static void AssertFieldExitProximityCueTrackerAttenuatesAndTracksEachExit()
{
    var now = new DateTime(2026, 7, 16, 0, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 120, 0, 0, 0, 0, 0, 0);
    var tracker = new FieldExitProximityCueTracker(
        innerRange: 80,
        outerRange: 400,
        pulseInterval: TimeSpan.FromMilliseconds(3200));
    var exits = new[]
    {
        new FieldNavigationTarget(120, FieldNavigationCategory.Exits, "Exit 1", 80, 0, 0, "gateway:120:0:119"),
        new FieldNavigationTarget(120, FieldNavigationCategory.Exits, "Exit 2", 240, 0, 0, "gateway:120:1:121"),
        new FieldNavigationTarget(120, FieldNavigationCategory.Exits, "Exit 3", 400, 0, 0, "gateway:120:2:122")
    };

    var cues = tracker.Update(position, exits, now);
    AssertEqual(2, cues.Count, "each reachable exit inside the audible radius should emit its own cue");
    AssertApprox(1f, cues.Single(cue => cue.Target.Label == "Exit 1").Gain, 0.001f, "near exit gain");
    AssertApprox(0.5f, cues.Single(cue => cue.Target.Label == "Exit 2").Gain, 0.001f, "mid-range exit gain");
    AssertEqual(0, tracker.Update(position, exits, now.AddSeconds(3)).Count, "the three-second WAV should not overlap itself");
    AssertEqual(2, tracker.Update(position, exits, now.AddMilliseconds(3200)).Count, "exit cues should pulse after the full interval");

    AssertEqual(0, tracker.Update(position, [], now.AddMilliseconds(3300)).Count, "removed or newly locked exits should stop immediately");
    var restored = tracker.Update(position, [exits[0]], now.AddMilliseconds(3400));
    AssertEqual(1, restored.Count, "a newly reachable exit should cue immediately");
    AssertEqual("gateway:120:0:119", restored[0].TargetKey, "exit cue should retain its native gateway identity");
}

static void AssertFieldProximityCuesIgnoreDifferentElevation()
{
    var now = new DateTime(2026, 7, 29, 0, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 230, 0, 0, 0, 0, 0, 0);
    var sameLevelItem = new FieldNavigationTarget(
        230,
        FieldNavigationCategory.Objects,
        "Elixir",
        80,
        0,
        180,
        "item:same-level",
        FieldObjectCueKind.Item);
    var upperLevelItem = new FieldNavigationTarget(
        230,
        FieldNavigationCategory.Objects,
        "Elixir",
        80,
        0,
        225,
        "item:upper-level",
        FieldObjectCueKind.Item);
    var objectTracker = new FieldObjectProximityCueTracker(
        innerRange: 80,
        outerRange: 400,
        clusterRadius: 40,
        pulseInterval: TimeSpan.Zero);

    var objectCues = objectTracker.Update(
        position,
        [sameLevelItem, upperLevelItem],
        now);
    AssertEqual(
        1,
        objectCues.Count,
        "only pickups on Cloud's current elevation layer should emit a cue");
    AssertContains(objectCues[0].ClusterKey, sameLevelItem.StableId);
    AssertEqual(
        false,
        objectCues[0].ClusterKey.Contains(upperLevelItem.StableId, StringComparison.Ordinal),
        "a pickup on the next stair landing must not be clustered into the current-level cue");
    AssertEqual(
        180,
        objectCues[0].Target.Z,
        "the current-level pickup cue must retain its own native elevation");

    var sameLevelExit = new FieldNavigationTarget(
        230,
        FieldNavigationCategory.Exits,
        "Current landing exit",
        80,
        0,
        180,
        "exit:same-level");
    var upperLevelExit = new FieldNavigationTarget(
        230,
        FieldNavigationCategory.Exits,
        "Upper landing exit",
        80,
        0,
        225,
        "exit:upper-level");
    var exitTracker = new FieldExitProximityCueTracker(
        innerRange: 80,
        outerRange: 400,
        pulseInterval: TimeSpan.Zero);

    var exitCues = exitTracker.Update(
        position,
        [sameLevelExit, upperLevelExit],
        now);
    AssertEqual(
        1,
        exitCues.Count,
        "only exits on Cloud's current elevation layer should emit a cue");
    AssertEqual(
        sameLevelExit.StableId,
        exitCues[0].TargetKey,
        "the retained exit cue should be the current-level gateway");

    var transform = new FieldNavigationControlTransform(0);
    AssertEqual(
        true,
        FieldProximitySpatializer.CreateCue(position, sameLevelExit, transform) is not null,
        "a native target offset within the current elevation layer should remain spatializable");
    AssertEqual(
        true,
        FieldProximitySpatializer.CreateCue(position, upperLevelExit, transform) is null,
        "the shared spatializer must reject a target on another elevation layer");
}

static void AssertFieldExitProximityCueTrackerStopsPassedExitAfterClimbingAway()
{
    var now = new DateTime(2026, 7, 29, 1, 0, 0, DateTimeKind.Utc);
    var lowerExit = new FieldNavigationTarget(
        230,
        FieldNavigationCategory.Exits,
        "Lobby exit",
        80,
        0,
        0,
        "exit:lower-lobby");
    var tracker = new FieldExitProximityCueTracker(
        innerRange: 80,
        outerRange: 400,
        pulseInterval: TimeSpan.FromSeconds(3));
    var besideExit = new FieldPositionSnapshot(1, 230, 0, 0, 0, 0, 0, 0);

    AssertEqual(
        1,
        tracker.Update(besideExit, [lowerExit], now).Count,
        "the current-floor exit should begin its normal proximity cue");
    AssertEqual(
        true,
        tracker.HasAudibleTargets,
        "the player must know that an exit cue is still relevant between pulses");

    var climbingAboveExit = besideExit with
    {
        X = 80,
        Z = FieldProximityElevationPolicy.SeparateLevelMinimumVerticalDistance
    };
    AssertEqual(
        0,
        tracker.Update(climbingAboveExit, [lowerExit], now.AddSeconds(3)).Count,
        "an exit already passed below Cloud must not pulse again while he climbs over it");
    AssertEqual(
        false,
        tracker.HasAudibleTargets,
        "leaving the exit's elevation must retire its active audio immediately");
    AssertEqual(
        0,
        tracker.Update(climbingAboveExit, [lowerExit], now.AddSeconds(30)).Count,
        "the lower exit must stay silent on later passes over the same X and Y coordinates");
}

