static void AssertFieldLadderProximityCueTrackerUsesAllNativeLadders()
{
    var now = new DateTime(2026, 7, 18, 0, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 123, 0, 0, 0, 0, 0, 0);
    var tracker = new FieldLadderProximityCueTracker(
        innerRange: 80,
        outerRange: 400,
        pulseInterval: TimeSpan.FromMilliseconds(1600));
    var actionLadder = new FieldScriptNavigationTransition(
        123,
        FieldNavigationTransitionKind.Ladder,
        10,
        80,
        0,
        0,
        200,
        0,
        300,
        12,
        "ladder:123:10",
        FieldNavigationInput.Up,
        RequiresAction: true);
    var automaticLadder = actionLadder with
    {
        SourceEntityId = 11,
        SourceX = 160,
        StableId = "ladder:123:11",
        RequiresAction = false
    };
    var jump = actionLadder with
    {
        Kind = FieldNavigationTransitionKind.Jump,
        SourceEntityId = 12,
        SourceX = 240,
        StableId = "jump:123:12"
    };

    var cues = tracker.Update(position, [actionLadder, automaticLadder, jump], now);
    AssertEqual(2, cues.Count, "both action-gated and automatic native ladder entrances should emit a ladder cue");
    AssertEqual(
        true,
        cues.Any(cue => cue.Transition.StableId == "ladder:123:10"),
        "action-gated ladder cue native transition identity");
    AssertEqual(
        true,
        cues.Any(cue => cue.Transition.StableId == "ladder:123:11"),
        "automatic ladder cue native transition identity");
    AssertApprox(
        1f,
        cues.Single(cue => cue.Transition.StableId == "ladder:123:10").Gain,
        0.001f,
        "near action-gated ladder cue gain");
    AssertEqual(0, tracker.Update(position, [actionLadder], now.AddSeconds(1)).Count, "ladder cue pulse interval");
    AssertEqual(1, tracker.Update(position, [actionLadder], now.AddMilliseconds(1600)).Count, "ladder cue repeats after interval");
}

static void AssertFieldLadderProximityCueTrackerPrioritizesActiveRouteLadder()
{
    var now = new DateTime(2026, 8, 5, 0, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 123, 0, 0, 0, 0, 0, 0);
    var tracker = new FieldLadderProximityCueTracker(
        innerRange: 80,
        outerRange: 400,
        pulseInterval: TimeSpan.FromMilliseconds(700));
    var wrongLadder = new FieldScriptNavigationTransition(
        123,
        FieldNavigationTransitionKind.Ladder,
        8,
        30,
        0,
        0,
        30,
        0,
        null,
        7,
        "ladder:123:8:down",
        FieldNavigationInput.Down);
    var routeLadder = wrongLadder with
    {
        SourceEntityId = 10,
        SourceX = 60,
        StableId = "ladder:123:10:down"
    };

    var cues = tracker.Update(
        position,
        [wrongLadder, routeLadder],
        now,
        prioritizedTransitionId: routeLadder.StableId);
    AssertEqual(1, cues.Count, "an active route should pulse only its next ladder entrance");
    AssertEqual(routeLadder.StableId, cues[0].TargetKey, "route-priority ladder identity");
    AssertEqual(
        0,
        tracker.Update(
            position,
            [wrongLadder, routeLadder],
            now.AddMilliseconds(699),
            prioritizedTransitionId: routeLadder.StableId).Count,
        "route-priority ladder cue should honor its repeat interval");
    AssertEqual(
        1,
        tracker.Update(
            position,
            [wrongLadder, routeLadder],
            now.AddMilliseconds(700),
            prioritizedTransitionId: routeLadder.StableId).Count,
        "route-priority ladder cue should continue until the caller observes a mount");
}

static void AssertFieldLadderMountCueTrackerRequiresTheActiveEntrance()
{
    var now = new DateTime(2026, 8, 5, 18, 40, 0, DateTimeKind.Utc);
    var tracker = new FieldLadderMountCueTracker(
        entranceRange: 56,
        pulseInterval: TimeSpan.FromMilliseconds(700));
    var ladder = new FieldScriptNavigationTransition(
        123,
        FieldNavigationTransitionKind.Ladder,
        8,
        100,
        200,
        300,
        100,
        200,
        900,
        7,
        "ladder:123:8:mount",
        FieldNavigationInput.Down,
        RequiresAction: true);
    var wrongLadder = ladder with
    {
        SourceEntityId = 9,
        SourceX = 105,
        StableId = "ladder:123:9:mount"
    };
    var outsideEntrance = new FieldPositionSnapshot(1, 123, 0, 157, 200, 300, 0, 0);
    var atEntrance = outsideEntrance with { X = 100 };

    AssertEqual(
        0,
        tracker.Update(
            atEntrance,
            [ladder, wrongLadder],
            now,
            prioritizedTransitionId: null).Count,
        "the 214 mount cue must stay silent without an active route ladder");
    AssertEqual(
        0,
        tracker.Update(
            outsideEntrance,
            [ladder, wrongLadder],
            now,
            prioritizedTransitionId: ladder.StableId).Count,
        "the 214 mount cue must stay silent outside the exact entrance radius");
    var first = tracker.Update(
        atEntrance,
        [ladder, wrongLadder],
        now,
        prioritizedTransitionId: ladder.StableId);
    AssertEqual(1, first.Count, "the active route ladder should pulse 214 at its entrance");
    AssertEqual(ladder.StableId, first[0].TargetKey, "mount cue transition identity");
    AssertApprox(1f, first[0].Gain, 0.001f, "mount cue should play at full gain at the entrance");
    AssertEqual(
        0,
        tracker.Update(
            atEntrance,
            [ladder, wrongLadder],
            now.AddMilliseconds(699),
            prioritizedTransitionId: ladder.StableId).Count,
        "the mount cue should honor its repeat interval");
    AssertEqual(
        1,
        tracker.Update(
            atEntrance,
            [ladder, wrongLadder],
            now.AddMilliseconds(700),
            prioritizedTransitionId: ladder.StableId).Count,
        "the mount cue should repeat continuously while waiting to mount");
    AssertEqual(
        0,
        tracker.Update(
            outsideEntrance,
            [ladder, wrongLadder],
            now.AddMilliseconds(710),
            prioritizedTransitionId: ladder.StableId).Count,
        "moving away should stop and reset the mount cue");
    AssertEqual(
        1,
        tracker.Update(
            atEntrance,
            [ladder, wrongLadder],
            now.AddMilliseconds(720),
            prioritizedTransitionId: ladder.StableId).Count,
        "returning to the entrance should restart the mount cue immediately");
}

static void AssertFieldNavigationObjectReaderRequiresNativeBranchState()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02300000;
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 2;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 7] = 1;
    memory[eventTable + FieldNavigationObjectReader.FieldEventDataStride + FieldNavigationObjectReader.VisibilityOffset] = 1;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var definition = new FieldNavigationObjectDefinition(
        609,
        7,
        FieldNavigationObjectKind.Item,
        200,
        RequiredBank: 3,
        RequiredAddress: 230,
        RequiredMask: 0x08,
        RequiredValue: 0x08,
        CollectedBank: 15,
        CollectedAddress: 112,
        CollectedMask: 0x40);
    var reader = new FieldNavigationObjectReader(
        ReadInt32Value,
        ReadByte,
        id => id == 200 ? "Princess Guard" : null,
        _ => null,
        [definition]);
    var position = new FieldPositionSnapshot(1, 609, 0, 0, 0, 0, 0, 0);

    AssertEqual(0, reader.ReadTargets(position).Count, "inactive native branch must not expose reused chest model");
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 230] = 0x08;
    AssertEqual(1, reader.ReadTargets(position).Count, "active native branch should expose reused chest model");
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 0x400 + 112] = 0x40;
    AssertEqual(0, reader.ReadTargets(position).Count, "collected active branch should remove reused chest model");
}

static void AssertFieldNavigationObjectCatalogNamesResolve()
{
    var database = Kernel2TextDatabase.TryCreate(FindGameRoot())
        ?? throw new InvalidOperationException("Expected installed kernel2 text database.");
    var definitions = FieldNavigationObjectCatalog.CreateAllFields();
    var unresolved = definitions
        .Where(definition => definition.Kind is not FieldNavigationObjectKind.Named and not FieldNavigationObjectKind.SavePoint)
        .Where(definition => definition.Kind == FieldNavigationObjectKind.Item
            ? string.IsNullOrWhiteSpace(database.ResolveInventoryObjectName(definition.NativeId))
            : string.IsNullOrWhiteSpace(database.ResolveMateriaName(definition.NativeId)))
        .Select(definition => $"{definition.SourceFieldName}:{definition.EntityId}:{definition.Kind}:{definition.NativeId}")
        .ToArray();

    AssertEqual(0, unresolved.Length, $"all catalog names should resolve; unresolved={string.Join(",", unresolved)}");
}

static void AssertFieldStoryReaderFollowsNativeReactorDoorOrder()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02340000;
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 12;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 9] = 6;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 10] = 7;
    WriteLiveFieldModel(memory, eventTable, 6, -854, 2345, -277);
    WriteLiveFieldModel(memory, eventTable, 7, -575, 2631, -275);
    WriteUInt16(
        memory,
        eventTable + FieldNavigationNpcReader.CollisionRadiusOffset,
        48);
    WriteUInt16(
        memory,
        eventTable + 6 * FieldNavigationObjectReader.FieldEventDataStride +
        FieldNavigationNpcReader.TalkRadiusOffset,
        192);
    WriteUInt16(
        memory,
        eventTable + 7 * FieldNavigationObjectReader.FieldEventDataStride +
        FieldNavigationNpcReader.TalkRadiusOffset,
        160);
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 10);

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    short ReadInt16Value(int address) =>
        unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var definitions = new[]
    {
        new FieldStoryEventDefinition(
