            MaximumGameMoment: 26,
            Priority: 1,
            RequiredCondition: new FieldStoryStateCondition(1, 225, 0x08, 0x08),
            CompletedCondition: new FieldStoryStateCondition(1, 225, 0x10, 0x10)),
        new FieldStoryEventDefinition(
            120,
            FieldStoryTargetKind.Location,
            "Approach Barret and Avalanche",
            X: -704,
            Y: 2166,
            Z: -274,
            TargetGameMoment: 11,
            Priority: 100,
            RequiredCondition: new FieldStoryStateCondition(1, 225, 0x18, 0x18)),
        new FieldStoryEventDefinition(
            120,
            FieldStoryTargetKind.Location,
            "Press the walkway door button",
            X: -1699,
            Y: 4400,
            Z: -273,
            TargetGameMoment: 12,
            MinimumGameMoment: 11,
            MaximumGameMoment: 11,
            RequiredCondition: new FieldStoryStateCondition(1, 225, 0x18, 0x18),
            CompletedCondition: new FieldStoryStateCondition(5, 2, 0x01, 0x01)),
        new FieldStoryEventDefinition(
            120,
            FieldStoryTargetKind.Location,
            "Go through the opened walkway door",
            X: -1490,
            Y: 4517,
            Z: -282,
            TargetGameMoment: 12,
            MinimumGameMoment: 11,
            MaximumGameMoment: 11,
            RequiredCondition: new FieldStoryStateCondition(5, 2, 0x01, 0x01))
    };
    var reader = new FieldStoryTargetReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        definitions);
    var position = new FieldPositionSnapshot(1, 120, 0, -900, 2400, -277, 25, 0);

    var targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "the first closed reactor door should select Biggs only");
    AssertContains(targets[0].Label, "Biggs");
    AssertEqual(-854, targets[0].X, "Biggs target should use his live model position");
    AssertEqual(
        240,
        targets[0].InteractionRadius,
        "Biggs story arrival should use native player collision plus talk radius");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 225] = 0x08;
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after Biggs opens his door, Jessie should become the objective");
    AssertContains(targets[0].Label, "Jessie");
    AssertEqual(-575, targets[0].X, "Jessie target should use her live model position");
    AssertEqual(
        208,
        targets[0].InteractionRadius,
        "Jessie story arrival should use native player collision plus talk radius");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 225] = 0x18;
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after both doors open, the next native line trigger should become active");
    AssertContains(targets[0].Label, "Barret");
    AssertEqual(-704, targets[0].X, "line target should use the native trigger midpoint");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 11);
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after Barret joins, the native walkway button should become the objective");
    AssertEqual("Press the walkway door button", targets[0].Label, "walkway button label");
    AssertEqual(-1699, targets[0].X, "walkway button should use the native drE line midpoint");
    AssertEqual(4400, targets[0].Y, "walkway button native y coordinate");

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 2] = 0x01;
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "opening the button-operated door should advance to its passage");
    AssertEqual("Go through the opened walkway door", targets[0].Label, "opened walkway target label");
    AssertEqual(-1490, targets[0].X, "opened walkway should lead to the native exit approach");
}

static void AssertFieldStoryReaderUsesNextNativeMilestone()
{
    var memory = new Dictionary<int, byte>();
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 50);
    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte,
    [
        new FieldStoryEventDefinition(200, FieldStoryTargetKind.Location, "Earlier event", X: 10, TargetGameMoment: 48),
        new FieldStoryEventDefinition(200, FieldStoryTargetKind.Location, "Next event", X: 20, TargetGameMoment: 51),
        new FieldStoryEventDefinition(200, FieldStoryTargetKind.Location, "Later event", X: 30, TargetGameMoment: 63)
    ]);
    var position = new FieldPositionSnapshot(1, 200, 0, 0, 0, 0, 0, 0);

    var targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "only the next native story milestone in a field should be exposed");
    AssertEqual("Next event", targets[0].Label, "future story events must not appear before their turn");
    AssertEqual(true, targets[0].CompletesOnArrival, "fixed story locations complete when the player reaches them");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 51);
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "completing a milestone should advance to the next one");
    AssertEqual("Later event", targets[0].Label, "completed milestone must disappear immediately");
}

static void AssertFieldStoryReaderSupportsAnySetConditions()
{
    var memory = new Dictionary<int, byte>();
    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte,
    [
        new FieldStoryEventDefinition(
            201,
            FieldStoryTargetKind.Location,
            "Collect the finished dress",
            X: 140,
            RequiredCondition: new FieldStoryStateCondition(1, 161, 0xE0, 0, AnyBitSet: true),
            CompletedCondition: new FieldStoryStateCondition(1, 160, 0x80, 0, AnyBitSet: true))
    ]);
    var position = new FieldPositionSnapshot(1, 201, 0, 0, 0, 0, 0, 0);

    AssertEqual(0, reader.ReadTargets(position).Count, "an any-set requirement must reject a clear native bit group");
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 161] = 0x40;
    AssertEqual(1, reader.ReadTargets(position).Count, "any native dress-result bit should satisfy the requirement");
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 160] = 0x80;
    AssertEqual(0, reader.ReadTargets(position).Count, "an any-set completion must remove the completed objective");
}

static void AssertFieldStoryReaderRequiresEveryNativeCondition()
{
    var memory = new Dictionary<int, byte>();
    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte,
    [
        new FieldStoryEventDefinition(
            184,
            FieldStoryTargetKind.Location,
            "Push the left barrel to help Aerith",
            X: -368,
            Y: 1301,
            Z: 946,
            RequiredConditions:
            [
                new FieldStoryStateCondition(5, 10, 0xFF, 1),
                new FieldStoryStateCondition(5, 12, 0xFF, 1)
            ])
    ]);
    var position = new FieldPositionSnapshot(1, 184, 0, 0, 0, 0, 0, 0);

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 10] = 1;
    AssertEqual(
        0,
        reader.ReadTargets(position).Count,
        "a Story target must remain hidden when only one native requirement matches");
    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 12] = 1;
    AssertEqual(
        1,
        reader.ReadTargets(position).Count,
        "a Story target should appear after every native requirement matches");
    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 10] = 0;
    AssertEqual(
        0,
        reader.ReadTargets(position).Count,
        "clearing either native requirement should retire the Story target");
}

static void AssertFieldStoryCatalogExposesOnlyVisibleOpeningFollowersWithinNativeMoments()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields()
        .Where(definition =>
            definition is
            {
                Kind: FieldStoryTargetKind.Model,
                FieldId: 116,
                EntityId: 2,
                Label: "Follow Barret"
            } or
            {
                Kind: FieldStoryTargetKind.Model,
                FieldId: 117,
                EntityId: 4,
                Label: "Approach Avalanche"
            })
        .OrderBy(definition => definition.FieldId)
        .ToArray();

    AssertEqual(2, definitions.Length, "native opening follow objectives should be present in the story catalog");

    var barret = definitions[0];
    AssertEqual(6, barret.TargetGameMoment, "Barret follow target completion moment");
    AssertEqual(1, barret.MinimumGameMoment, "Barret follow target minimum moment");
    AssertEqual(5, barret.MaximumGameMoment, "Barret follow target maximum moment");
    AssertEqual(0, barret.Priority, "Barret follow target priority");

    var barretMemory = new Dictionary<int, byte>();
    const int barretEventTable = 0x02340000;
    const int barretModelId = 1;
    WriteUInt32(barretMemory, FieldNavigationObjectReader.AddressFieldEventDataPtr, barretEventTable);
    barretMemory[FieldPositionReader.AddressFieldNumModels] = 10;
    barretMemory[FieldNavigationObjectReader.AddressFieldModelIdArray + barret.EntityId] = barretModelId;
    WriteLiveFieldModel(barretMemory, barretEventTable, barretModelId, 3578, 29360, 323);
    WriteUInt16(barretMemory, FieldNavigationObjectReader.AddressFieldBankBase, 1);

    byte ReadBarretByte(int address) =>
        barretMemory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadBarretInt32(int address) =>
        ReadBarretByte(address) |
        (ReadBarretByte(address + 1) << 8) |
        (ReadBarretByte(address + 2) << 16) |
        (ReadBarretByte(address + 3) << 24);

    var barretReader = new FieldStoryTargetReader(ReadBarretInt32, ReadBarretByte, [barret]);
    var barretPosition = new FieldPositionSnapshot(1, 116, 0, 3600, 27700, 323, 30, 0);
    var targets = barretReader.ReadTargets(barretPosition);
    AssertEqual(1, targets.Count, "visible Barret should be the pending field 116 story objective at GameMoment 1");
    AssertEqual(3578, targets[0].X, "Barret story target should use his live model position");
    AssertEqual(29360, targets[0].Y, "Barret story target live y position");
    AssertEqual(false, targets[0].CompletesOnArrival, "model story interactions wait for native script completion");

    var barretAddress = barretEventTable +
        barretModelId * FieldNavigationObjectReader.FieldEventDataStride;
    barretMemory[barretAddress + FieldNavigationObjectReader.VisibilityOffset] = 0;
    AssertEqual(0, barretReader.ReadTargets(barretPosition).Count, "hidden Barret must not remain a story target");
    barretMemory[barretAddress + FieldNavigationObjectReader.VisibilityOffset] = 1;
    WriteUInt16(barretMemory, FieldNavigationObjectReader.AddressFieldBankBase, 6);
    AssertEqual(0, barretReader.ReadTargets(barretPosition).Count, "completed GameMoment 6 must remove the Barret objective");
    WriteUInt16(barretMemory, FieldNavigationObjectReader.AddressFieldBankBase, 0);
    AssertEqual(0, barretReader.ReadTargets(barretPosition).Count, "the Barret objective must not appear during the opening movie moment");

    var avalanche = definitions[1];
    AssertEqual(7, avalanche.TargetGameMoment, "Avalanche approach target completion moment");
    AssertEqual(6, avalanche.MinimumGameMoment, "Avalanche approach target minimum moment");
    AssertEqual(6, avalanche.MaximumGameMoment, "Avalanche approach target maximum moment");
    AssertEqual(0, avalanche.Priority, "Avalanche approach target priority");

    var avalancheMemory = new Dictionary<int, byte>();
    const int avalancheEventTable = 0x02350000;
    const int avalancheModelId = 3;
    WriteUInt32(avalancheMemory, FieldNavigationObjectReader.AddressFieldEventDataPtr, avalancheEventTable);
    avalancheMemory[FieldPositionReader.AddressFieldNumModels] = 7;
    avalancheMemory[FieldNavigationObjectReader.AddressFieldModelIdArray + avalanche.EntityId] = avalancheModelId;
    WriteLiveFieldModel(avalancheMemory, avalancheEventTable, avalancheModelId, 1157, 1619, 1298);
    WriteUInt16(
        avalancheMemory,
        avalancheEventTable + FieldNavigationNpcReader.CollisionRadiusOffset,
        48);
    WriteUInt16(
        avalancheMemory,
        avalancheEventTable + avalancheModelId * FieldNavigationObjectReader.FieldEventDataStride +
        FieldNavigationNpcReader.CollisionRadiusOffset,
        64);
    WriteUInt16(avalancheMemory, FieldNavigationObjectReader.AddressFieldBankBase, 6);

    byte ReadAvalancheByte(int address) =>
        avalancheMemory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadAvalancheInt32(int address) =>
        ReadAvalancheByte(address) |
        (ReadAvalancheByte(address + 1) << 8) |
        (ReadAvalancheByte(address + 2) << 16) |
        (ReadAvalancheByte(address + 3) << 24);
    short ReadAvalancheInt16(int address) => unchecked((short)(
        ReadAvalancheByte(address) |
        (ReadAvalancheByte(address + 1) << 8)));

    var avalancheReader = new FieldStoryTargetReader(
        ReadAvalancheInt32,
        ReadAvalancheByte,
        [avalanche]);
    var avalanchePosition = new FieldPositionSnapshot(1, 117, 0, 2200, 1200, 1298, 71, 0);
    targets = avalancheReader.ReadTargets(avalanchePosition);
    AssertEqual(1, targets.Count, "visible Avalanche should be the pending field 117 story objective at GameMoment 6");
    AssertEqual(1157, targets[0].X, "Avalanche story target should use the live model on native trigger triangle 62");
    AssertEqual(1619, targets[0].Y, "Avalanche story target live y position");
    AssertEqual(
        avalanche.EntityId,
        targets[0].TriggerEntityId,
        "model-backed story target should retain its native entity for route collision exclusion");
    var avalancheObstacles = new FieldNavigationDynamicObstacleReader(
        ReadAvalancheInt32,
        ReadAvalancheInt16,
        ReadAvalancheByte).Read(avalanchePosition, targets[0]);
    AssertEqual(
        0,
        avalancheObstacles.Count,
        "the selected Avalanche destination model must not block its own story route");

    var avalancheAddress = avalancheEventTable +
        avalancheModelId * FieldNavigationObjectReader.FieldEventDataStride;
    avalancheMemory[avalancheAddress + FieldNavigationObjectReader.VisibilityOffset] = 0;
    AssertEqual(0, avalancheReader.ReadTargets(avalanchePosition).Count, "hidden Avalanche must not remain a story target");
    avalancheMemory[avalancheAddress + FieldNavigationObjectReader.VisibilityOffset] = 1;
    WriteUInt16(avalancheMemory, FieldNavigationObjectReader.AddressFieldBankBase, 7);
    AssertEqual(0, avalancheReader.ReadTargets(avalanchePosition).Count, "completed GameMoment 7 must remove the Avalanche objective");
    WriteUInt16(avalancheMemory, FieldNavigationObjectReader.AddressFieldBankBase, 5);
    AssertEqual(0, avalancheReader.ReadTargets(avalanchePosition).Count, "the Avalanche objective must not appear before field 117's native moment");
}

static void AssertFieldStoryCatalogCoversFullGameAndReactorInteractions()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields();
    AssertEqual(true, definitions.Count >= 100, "story catalog should contain full-game native progression events");
    AssertEqual(true, definitions.Select(definition => definition.FieldId).Distinct().Count() >= 80, "story catalog field coverage");

    var labels = definitions.Select(definition => definition.Label).ToHashSet(StringComparer.Ordinal);
    foreach (var expected in new[]
    {
        "Talk to Biggs to unlock the first security door",
        "Talk to Jessie to unlock the second security door",
        "Press the walkway door button",
        "Go through the opened walkway door",
        "Press the elevator switch",
        "Talk to Jessie for ladder instructions",
        "Plant the bomb at the reactor core",
        "Help Jessie free her leg",
        "Talk to Jessie to reopen the inner security door",
        "Talk to Biggs to reopen the outer security door"
    })
    {
        AssertEqual(true, labels.Contains(expected), $"Reactor 1 story catalog should include: {expected}");
    }

    var bomb = definitions.Single(definition => definition.Label == "Plant the bomb at the reactor core");
    AssertEqual(14, bomb.MinimumGameMoment, "optional Restore Materia must not be required before planting the bomb");

    var walkwayButton = definitions.Single(definition => definition.Label == "Press the walkway door button");
    AssertEqual(120, walkwayButton.FieldId, "walkway button field");
    AssertEqual(-1699, walkwayButton.X, "walkway button native line midpoint x");
    AssertEqual(4400, walkwayButton.Y, "walkway button native line midpoint y");
    AssertEqual(new FieldStoryStateCondition(1, 225, 0x18, 0x18), walkwayButton.RequiredCondition, "walkway button code condition");
    AssertEqual(new FieldStoryStateCondition(5, 2, 0x01, 0x01), walkwayButton.CompletedCondition, "walkway button native completion condition");
}

