static void AssertFieldStoryCatalogCoversReactor5TrainEscape()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields();
    var expectedLabels = new[]
    {
        "Go to Tifa at the railway map monitor",
        "Escape Car 1 through the forward door",
        "Escape Car 2 through the forward door",
