    var railwayMap = definitions.Single(definition =>
        definition.Label == "Go to Tifa at the railway map monitor");
    var firstDoor = definitions.Single(definition =>
        definition.Label == "Escape Car 1 through the forward door");
    AssertEqual(139, railwayMap.FieldId, "second-train railway-map field");
