    AssertEqual(-215, railwayMap.Y, "second-train railway-map trigger midpoint y");
    AssertEqual(
        new FieldStoryStateCondition(5, 33, 0x01, 0x01),
        railwayMap.CompletedCondition,
        "security alert completion byte");
    AssertEqual(
        new FieldStoryStateCondition(5, 33, 0x01, 0x01),
        firstDoor.RequiredCondition,
        "first escape door waits for the security alert");
    AssertEqual(1, firstDoor.X, "first escape door trigger midpoint x");
    AssertEqual(-381, firstDoor.Y, "first escape door trigger midpoint y");

    var secondDoor = definitions.Single(definition =>
        definition.Label == "Escape Car 2 through the forward door");
    AssertEqual(140, secondDoor.FieldId, "second escape-car field");
    AssertEqual(-2, secondDoor.X, "second escape door trigger midpoint x");
    AssertEqual(-412, secondDoor.Y, "second escape door trigger midpoint y");

    var nextCar = definitions.Single(definition =>
        definition.Label == "Escape through the next train car");
    AssertEqual(142, nextCar.FieldId, "third escape-car field");
    AssertEqual(6, nextCar.X, "third escape door trigger midpoint x");
    AssertEqual(-444, nextCar.Y, "third escape door trigger midpoint y");

    var tifa = definitions.Single(definition =>
        definition.Label == "Talk to Tifa and jump from the train");
    AssertEqual(141, tifa.FieldId, "final train car field");
    AssertEqual(15, tifa.EntityId, "final train objective uses Tifa's native model entity");

    var tunnel = definitions.Single(definition =>
        definition.Label == "Continue north through the winding tunnel");
    AssertEqual(161, tunnel.FieldId, "winding tunnel field");
    AssertEqual(746, tunnel.X, "winding tunnel exit midpoint x");
    AssertEqual(2237, tunnel.Y, "winding tunnel exit midpoint y");

    var memory = new Dictionary<int, byte>();
    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 108);

    var reader = new FieldStoryTargetReader(
        ReadInt32Value,
        ReadByte,
        definitions.Where(definition => definition.FieldId == 139));
    var position = new FieldPositionSnapshot(1, 139, 0, 0, 0, 0, 0, 0);
    var targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "security alert should expose only its first native trigger");
    AssertEqual("Go to Tifa at the railway map monitor", targets[0].Label, "first second-train objective");

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 33] = 0x01;
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after the alert, Story should advance to the first-car exit");
    AssertEqual("Escape Car 1 through the forward door", targets[0].Label, "post-alert train objective");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 107);
    AssertEqual(0, reader.ReadTargets(position).Count, "second-train objectives must stay hidden before mission departure");
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 117);
    AssertEqual(0, reader.ReadTargets(position).Count, "second-train objectives must retire after reaching Reactor 5");
}

