        new FieldPositionSnapshot(1, 161, 0, 663, 1920, -10, 37, 128));

    AssertEqual(1, targets.Count, "native tunnel progression should expose one north Story target");
    AssertEqual(expectedLine, targets[0].TriggerLine, "Story target must preserve native line geometry");
