static void AssertFieldStoryCatalogAdvancesThroughTrainGraveyardTrainPositions()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields()
        .Where(candidate =>
            candidate.FieldId == 145 &&
            candidate.TargetGameMoment == 215 &&
            candidate.MinimumGameMoment == 212 &&
            candidate.MaximumGameMoment == 214 &&
            candidate.Priority == 0)
        .ToArray();
    var firstTrainLine = new FieldNavigationTriggerLine(1691, 3064, 0, 1790, 3124, 0);
    var upperTrainLine = new FieldNavigationTriggerLine(776, 3453, 0, 871, 3511, 0);
    var stationExitLine = new FieldNavigationTriggerLine(-2212, 3557, 101, -2095, 3223, 101);

    AssertEqual(
        4,
        definitions.Length,
        "Train Graveyard Story must expose recovery, both native train controls, and the station exit");

    var memory = new Dictionary<int, byte>();
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 212);
    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    var reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte, definitions);
    var position = new FieldPositionSnapshot(1, 145, 0, 0, 0, 0, 104, 0);

    var expectedByState = new[]
    {
        (State: (byte)0, Label: "Move the first Train Graveyard train", Line: firstTrainLine),
        (State: (byte)2, Label: "Move the first Train Graveyard train back into place", Line: firstTrainLine),
        (State: (byte)3, Label: "Move the upper Train Graveyard train", Line: upperTrainLine),
        (State: (byte)7, Label: "Leave the Train Graveyard for Sector 7 Station", Line: stationExitLine)
    };
    foreach (var expected in expectedByState)
    {
        memory[FieldNavigationObjectReader.AddressFieldBankBase + 164] = expected.State;
        var targets = reader.ReadTargets(position);
        AssertEqual(
            1,
            targets.Count,
            $"Train Graveyard Story must remain singular when native train state is {expected.State}");
        AssertEqual(
            expected.Label,
            targets[0].Label,
            $"Train Graveyard Story must advance at native train state {expected.State}");
        AssertEqual(
            expected.Line,
            targets[0].TriggerLine,
            $"Train Graveyard Story must route to the native trigger at state {expected.State}");
        AssertEqual(
            true,
            targets[0].CompletesOnArrival,
            $"Train Graveyard stage {expected.State} must stop at its actual trigger");
    }

    var upperTrainDefinition = definitions.Single(definition =>
        definition.Label == "Move the upper Train Graveyard train");
    AssertEqual(
        2,
        upperTrainDefinition.RouteDetours?.Length ?? 0,
        "upper-train Story must use both checkpoints around the first train's native reverse trigger");
    AssertEqual(
        new FieldNavigationRouteDetour(
            new FieldNavigationTriggerLine(798, 2547, 0, 896, 2610, 0),
            720,
            2480,
            0,
            30),
        upperTrainDefinition.RouteDetours?[0],
        "upper-train Story should first move left before the first train's reverse trigger");
    AssertEqual(
        new FieldNavigationRouteDetour(
            new FieldNavigationTriggerLine(798, 2547, 0, 896, 2610, 0),
            720,
            2680,
            0,
            30),
        upperTrainDefinition.RouteDetours?[1],
        "upper-train Story should then continue north beyond the first train's reverse trigger");
}

static void AssertFieldStoryCatalogGuidesEntireSupportPillarEscape()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields()
        .Where(candidate =>
            candidate.FieldId == 160 &&
            candidate.TargetGameMoment == 236 &&
            candidate.MinimumGameMoment == 221 &&
            candidate.MaximumGameMoment == 235 &&
            candidate.Priority == 0)
        .ToArray();

    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02400000;
    const int barretModelId = 4;
    const int tifaModelId = 5;
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 221);
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 9;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 4] = barretModelId;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 5] = tifaModelId;
    WriteLiveFieldModel(memory, eventTable, barretModelId, 443, -283, 6198);
    WriteLiveFieldModel(memory, eventTable, tifaModelId, 471, 62, 6198);

    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    short ReadInt16Value(int address) =>
        unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldStoryTargetReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        definitions);
    var position = new FieldPositionSnapshot(1, 160, 0, 0, 0, 6198, 0, 0);

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 15] = 1;
    var targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after Reno, Story should identify Tifa as the next visible objective");
    AssertEqual(
        "Talk to Tifa about stopping the plate release",
        targets[0].Label,
        "post-Reno support-pillar objective");
    AssertEqual(471, targets[0].X, "Tifa objective should use her live field position");
    AssertEqual(62, targets[0].Y, "Tifa objective live y coordinate");

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 18] = 1;
    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 16] = 1;
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after Tifa asks Cloud to try, Story should identify the native panel line");
    AssertEqual(
        "Examine the plate release control panel",
        targets[0].Label,
        "support-pillar control-panel objective");
    AssertEqual(295, targets[0].X, "control-panel target should use the native line midpoint");
    AssertEqual(-147, targets[0].Y, "control-panel native line midpoint y coordinate");
    AssertEqual(
        new FieldNavigationTriggerLine(213, -265, 6198, 377, -30, 6198),
        targets[0].TriggerLine,
        "control-panel objective should preserve its exact native activation line");

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 16] = 0;
    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 19] = 1;
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after the plate-release scene, Story should direct Cloud to Barret");
    AssertEqual(
        "Talk to Barret and find an escape route",
        targets[0].Label,
        "post-cutscene support-pillar objective");
    AssertEqual(443, targets[0].X, "Barret objective should follow his live search position");
    AssertEqual(-283, targets[0].Y, "Barret objective live y coordinate");

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 23] = 1;
    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 7] = 1;
    targets = reader.ReadTargets(position);
    AssertEqual(1, targets.Count, "after Barret identifies the wire, Story should lead to the native escape triangles");
    AssertEqual(
        "Reach the wire to escape the collapsing pillar",
        targets[0].Label,
        "support-pillar wire objective");
    AssertEqual(822, targets[0].X, "wire target should lie inside native escape triangle 19");
    AssertEqual(16, targets[0].Y, "wire target native triangle centroid y coordinate");
    AssertEqual(true, targets[0].CompletesOnArrival, "wire beacon should stop when Cloud reaches the escape trigger");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 236);
    AssertEqual(
        0,
        reader.ReadTargets(position).Count,
        "the support-pillar objectives must retire after the native escape advances GameMoment");
}

static void AssertFieldStoryCatalogCoversReactor5DescentAndBombPlacement()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields();
    var expected = new Dictionary<int, (string Label, int X, int Y, int Z, int TargetMoment, int MinimumMoment, int MaximumMoment, FieldNavigationTriggerLine? Line)>
    {
        [129] = (
            "Descend through Reactor 5 to the upper piping and ladder room",
            -650,
            -248,
            0,
            123,
            117,
            122,
            new FieldNavigationTriggerLine(-606, -284, 0, -694, -212, 0)),
        [130] = (
            "Cross the upper piping and descend toward the save point",
            296,
            1346,
            832,
            123,
            117,
            122,
            new FieldNavigationTriggerLine(258, 1356, 812, 333, 1336, 851)),
        [131] = (
            "Continue past the save point to Reactor 5's core",
            -113,
            -133,
            -180,
            123,
            117,
            122,
            new FieldNavigationTriggerLine(-56, -89, -180, -170, -177, -180)),
        [132] = (
            "Plant the bomb at Reactor 5's core",
            -67,
            -1632,
            -184,
            127,
            123,
            126,
            null)
    };

    var reactor5 = definitions
        .Where(definition => expected.ContainsKey(definition.FieldId) &&
            definition.Priority == 0 &&
            expected[definition.FieldId].Label == definition.Label)
        .OrderBy(definition => definition.FieldId)
        .ToArray();
    AssertEqual(4, reactor5.Length, "Reactor 5 descent and bomb-placement Story target count");

    foreach (var definition in reactor5)
    {
        var target = expected[definition.FieldId];
        AssertEqual(FieldStoryTargetKind.Location, definition.Kind, $"field {definition.FieldId} Story kind");
        AssertEqual(target.X, definition.X, $"field {definition.FieldId} native target x");
        AssertEqual(target.Y, definition.Y, $"field {definition.FieldId} native target y");
        AssertEqual(target.Z, definition.Z, $"field {definition.FieldId} native target z");
        AssertEqual(target.TargetMoment, definition.TargetGameMoment, $"field {definition.FieldId} target game moment");
        AssertEqual(target.MinimumMoment, definition.MinimumGameMoment, $"field {definition.FieldId} minimum game moment");
        AssertEqual(target.MaximumMoment, definition.MaximumGameMoment, $"field {definition.FieldId} maximum game moment");
        AssertEqual(target.Line, definition.TriggerLine, $"field {definition.FieldId} native trigger geometry");
    }

    var memory = new Dictionary<int, byte>();
    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 120);
    foreach (var definition in reactor5.Where(definition => definition.FieldId is >= 129 and <= 131))
    {
        var reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte, [definition]);
        var position = new FieldPositionSnapshot(
            1,
            definition.FieldId,
            0,
            definition.X,
            definition.Y,
            definition.Z,
            0,
            0);
        var targets = reader.ReadTargets(position);
        AssertEqual(1, targets.Count, $"field {definition.FieldId} exposes its descent target at moment 120");
        AssertEqual(definition.Label, targets[0].Label, $"field {definition.FieldId} descent target label");

        WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 123);
        AssertEqual(0, reader.ReadTargets(position).Count, $"field {definition.FieldId} retires at moment 123");
        WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 120);
    }

    var bomb = reactor5.Single(definition => definition.FieldId == 132);
    var bombReader = new FieldStoryTargetReader(ReadInt32Value, ReadByte, [bomb]);
    var bombPosition = new FieldPositionSnapshot(1, 132, 0, -86, -1088, -182, 0, 0);
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 122);
    AssertEqual(0, bombReader.ReadTargets(bombPosition).Count, "bomb target stays hidden before the reactor memory");
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 123);
    AssertEqual(1, bombReader.ReadTargets(bombPosition).Count, "bomb target appears after the reactor memory");
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 126);
    AssertEqual(1, bombReader.ReadTargets(bombPosition).Count, "bomb target remains active until placement");
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 127);
    AssertEqual(0, bombReader.ReadTargets(bombPosition).Count, "bomb target retires at the native post-placement moment");
}

static void AssertFieldStoryCatalogCoversReactor1PipingAndSaveRoom()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields();
    var expected = new Dictionary<string, (int FieldId, int X, int Y, int Z, int MinimumMoment, int MaximumMoment, FieldNavigationTriggerLine Line)>
    {
        ["Leave the elevator toward Reactor 1's main staircase"] = (
            121,
            -174,
            -6,
            5,
            12,
            13,
            new FieldNavigationTriggerLine(-174, -68, 5, -174, 56, 5)),
        ["Descend Reactor 1's main staircase toward Jessie and the upper piping"] = (
            122,
            -701,
            -249,
            0,
            12,
            13,
            new FieldNavigationTriggerLine(-730, -215, 0, -672, -284, 0)),
        ["Cross the Reactor 1 upper piping and descend toward the save point"] = (
            123,
            298,
            1265,
            855,
            14,
            26,
            new FieldNavigationTriggerLine(260, 1264, 852, 337, 1266, 858)),
        ["Continue past the save point to Reactor 1's core"] = (
            124,
            -111,
            -195,
            -180,
            14,
            26,
            new FieldNavigationTriggerLine(-52, -148, -180, -171, -242, -181)),
        ["Climb back toward the Reactor 1 exit"] = (
            124,
            250,
            1195,
            861,
            27,
            32,
            new FieldNavigationTriggerLine(206, 1195, 856, 294, 1195, 866)),
        ["Return to the Reactor 1 main staircase"] = (
            123,
            -371,
            1921,
            2053,
            27,
            32,
            new FieldNavigationTriggerLine(-371, 1959, 2053, -371, 1883, 2053)),
        ["Return up Reactor 1's main staircase to the elevator"] = (
            122,
            -774,
            309,
            1571,
            27,
            32,
            new FieldNavigationTriggerLine(-833, 346, 1571, -716, 273, 1571)),
        ["Leave the elevator toward Reactor 1's security rooms"] = (
            121,
            -174,
            -6,
            5,
            27,
            32,
            new FieldNavigationTriggerLine(-174, -68, 5, -174, 56, 5))
    };

    foreach (var item in expected)
    {
        var definition = definitions.Single(candidate => candidate.Label == item.Key);
        AssertEqual(item.Value.FieldId, definition.FieldId, $"{item.Key} field");
        AssertEqual(FieldStoryTargetKind.Location, definition.Kind, $"{item.Key} kind");
        AssertEqual(item.Value.X, definition.X, $"{item.Key} x");
        AssertEqual(item.Value.Y, definition.Y, $"{item.Key} y");
        AssertEqual(item.Value.Z, definition.Z, $"{item.Key} z");
        AssertEqual(item.Value.MinimumMoment, definition.MinimumGameMoment, $"{item.Key} minimum moment");
        AssertEqual(item.Value.MaximumMoment, definition.MaximumGameMoment, $"{item.Key} maximum moment");
        AssertEqual(item.Value.Line, definition.TriggerLine, $"{item.Key} native trigger geometry");
        AssertEqual(true, definition.CompletesOnArrival, $"{item.Key} should stop at its gateway");
    }

    var returnToStairs = definitions.Single(definition =>
        definition.Label == "Return to the Reactor 1 main staircase");
    AssertEqual(
        new FieldStoryStateCondition(1, 225, 0x20, 0x20),
        returnToStairs.RequiredCondition,
        "the escape route should not bypass helping Jessie");

    var memory = new Dictionary<int, byte>();
    byte ReadByte(int address) => memory.GetValueOrDefault(address);
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    var reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte, definitions);

    var elevator = new FieldPositionSnapshot(1, 121, 0, 86, 16, -6, 8, 0);
    var mainStaircase = elevator with { FieldId = 122, X = -682, Y = 308, Z = 1571, TriangleId = 92 };

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 12);
    var elevatorTargets = reader.ReadTargets(elevator);
    AssertEqual(1, elevatorTargets.Count, "Reactor 1 elevator should expose its post-ride exit");
    AssertEqual("Leave the elevator toward Reactor 1's main staircase", elevatorTargets[0].Label, "post-elevator objective");
    var staircaseTargets = reader.ReadTargets(mainStaircase);
    AssertEqual(1, staircaseTargets.Count, "Reactor 1 main staircase should expose the upper-piping route");
    AssertEqual("Descend Reactor 1's main staircase toward Jessie and the upper piping", staircaseTargets[0].Label, "main-staircase objective");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 14);
    var upperRoom = new FieldPositionSnapshot(1, 123, 0, -140, 1921, 2212, 40, 0);
    var upperTargets = reader.ReadTargets(upperRoom);
    AssertEqual(1, upperTargets.Count, "Reactor 1 upper piping should expose the descent after Jessie speaks");
    AssertEqual("Cross the Reactor 1 upper piping and descend toward the save point", upperTargets[0].Label, "upper piping objective");

    var saveRoom = upperRoom with { FieldId = 124, X = 250, Y = 1195, Z = 861, TriangleId = 0 };
    var saveTargets = reader.ReadTargets(saveRoom);
    AssertEqual(1, saveTargets.Count, "Reactor 1 save room should expose the route to the core");
    AssertEqual("Continue past the save point to Reactor 1's core", saveTargets[0].Label, "save-room objective");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 27);
    staircaseTargets = reader.ReadTargets(mainStaircase);
    AssertEqual(1, staircaseTargets.Count, "Reactor 1 main staircase should expose the escape return");
    AssertEqual("Return up Reactor 1's main staircase to the elevator", staircaseTargets[0].Label, "main-staircase escape objective");
    elevatorTargets = reader.ReadTargets(elevator);
    AssertEqual(1, elevatorTargets.Count, "Reactor 1 elevator should expose the security-room escape exit");
    AssertEqual("Leave the elevator toward Reactor 1's security rooms", elevatorTargets[0].Label, "elevator escape objective");

    saveTargets = reader.ReadTargets(saveRoom);
    AssertEqual(1, saveTargets.Count, "Reactor 1 save room should expose the escape climb");
    AssertEqual("Climb back toward the Reactor 1 exit", saveTargets[0].Label, "save-room escape objective");

    memory[FieldNavigationObjectReader.AddressFieldBankBase + 225] = 0x20;
    upperTargets = reader.ReadTargets(upperRoom);
    AssertEqual(1, upperTargets.Count, "helping Jessie should unlock the main-staircase escape target");
    AssertEqual("Return to the Reactor 1 main staircase", upperTargets[0].Label, "upper-room escape objective");
}

static void AssertFieldStoryCatalogCoversReactor5EscapeAndChurchProgression()
{
