        AssertEqual(expected.Value.Y, definition.Y, $"{expected.Key} y");
        AssertEqual(expected.Value.Z, definition.Z, $"{expected.Key} z");
        AssertEqual(expected.Value.Line, definition.TriggerLine, $"{expected.Key} native line");
        AssertEqual(0, definition.Priority, $"{expected.Key} priority");
    }

    foreach (var label in new[]
    {
        "Escape Reactor 5's core",
        "Climb back toward the Reactor 5 elevator",
        "Cross the upper piping back toward the elevator",
        "Return to the Reactor 5 elevator",
        "Reach the simultaneous security controls"
    })
    {
        var definition = definitions.Single(candidate => candidate.Label == label);
        AssertEqual(128, definition.TargetGameMoment, $"{label} completion moment");
        AssertEqual(127, definition.MinimumGameMoment, $"{label} minimum moment");
        AssertEqual(127, definition.MaximumGameMoment, $"{label} maximum moment");
    }

    var elevatorSwitch = definitions.Single(candidate =>
        candidate.Label == "Press the elevator switch to return upstairs");
    var elevatorExit = definitions.Single(candidate =>
        candidate.Label == "Leave the elevator for the security room");
    AssertEqual(121, elevatorSwitch.FieldId, "return elevator switch field");
    AssertEqual(86, elevatorSwitch.X, "return elevator switch x");
    AssertEqual(64, elevatorSwitch.Y, "return elevator switch y");
    AssertEqual(new FieldStoryStateCondition(1, 225, 0x01, 0x01), elevatorSwitch.RequiredCondition, "return elevator side requirement");
    AssertEqual(new FieldStoryStateCondition(1, 225, 0x01, 0x00), elevatorSwitch.CompletedCondition, "return elevator completion side");
    AssertEqual(121, elevatorExit.FieldId, "return elevator exit field");
    AssertEqual(-185, elevatorExit.X, "return elevator exit x");
    AssertEqual(-6, elevatorExit.Y, "return elevator exit y");
    AssertEqual(new FieldStoryStateCondition(1, 225, 0x01, 0x00), elevatorExit.RequiredCondition, "return elevator exit side");
    AssertEqual(
        new FieldNavigationTriggerLine(-185, -68, 5, -185, 56, 5),
        elevatorExit.TriggerLine,
        "return elevator exit native line");

    var bridgeApproach = definitions.Single(candidate =>
        candidate.Label == "Continue to the bridge approach");
    var bridgeDoor = definitions.Single(candidate =>
        candidate.Label == "Open the bridge door and continue");
    AssertEqual(140, bridgeApproach.TargetGameMoment, "bridge approach completion moment");
    AssertEqual(128, bridgeApproach.MinimumGameMoment, "bridge approach minimum moment");
    AssertEqual(139, bridgeApproach.MaximumGameMoment, "bridge approach maximum moment");
    AssertEqual(false, bridgeDoor.CompletesOnArrival, "bridge door Story must wait for native confirm interaction");

    var memory = new Dictionary<int, byte>();
    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    short ReadInt16Value(int address) =>
        unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 127);
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 225] = 0x01;
    var elevatorReader = new FieldStoryTargetReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        [elevatorSwitch, elevatorExit]);
    var elevatorPosition = new FieldPositionSnapshot(1, 121, 0, -116, -3, 5, 5, 64);
    var targets = elevatorReader.ReadTargets(elevatorPosition);
    AssertEqual(1, targets.Count, "the occupied elevator side should expose only its switch");
    AssertEqual(elevatorSwitch.Label, targets[0].Label, "return elevator first objective");
    memory[FieldNavigationObjectReader.AddressFieldBankBase + 225] = 0x00;
    targets = elevatorReader.ReadTargets(elevatorPosition);
    AssertEqual(1, targets.Count, "after the elevator moves, Story should expose its opposite passage");
    AssertEqual(elevatorExit.Label, targets[0].Label, "return elevator second objective");

    var field128Definitions = definitions.Where(candidate =>
        candidate.FieldId == 128 &&
        candidate.Label is "Reach the simultaneous security controls" or "Continue to the bridge approach");
    var field128Reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte, field128Definitions);
    var field128Position = new FieldPositionSnapshot(1, 128, 0, -1485, 4298, -277, 52, 0);
    targets = field128Reader.ReadTargets(field128Position);
    AssertEqual(1, targets.Count, "moment 127 should route to the simultaneous security controls");
    AssertEqual("Reach the simultaneous security controls", targets[0].Label, "pre-button security objective");
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 128);
    targets = field128Reader.ReadTargets(field128Position);
    AssertEqual(1, targets.Count, "moment 128 should route out toward the bridge");
    AssertEqual("Continue to the bridge approach", targets[0].Label, "post-button bridge objective");

    var aerisMeeting = definitions.Single(candidate =>
        candidate.FieldId == 183 &&
        candidate.Label == "Talk to Aeris by the flowers");
    AssertEqual(FieldStoryTargetKind.Model, aerisMeeting.Kind, "church meeting target kind");
    AssertEqual(6, aerisMeeting.EntityId, "church meeting uses Aeris's native model entity");
    AssertEqual(143, aerisMeeting.TargetGameMoment, "church meeting completion moment");
    AssertEqual(140, aerisMeeting.MinimumGameMoment, "church meeting minimum moment");
    AssertEqual(142, aerisMeeting.MaximumGameMoment, "church meeting maximum moment");
    AssertEqual(
        new FieldStoryStateCondition(3, 17, 0x01, 0x00),
        aerisMeeting.RequiredCondition,
        "church meeting remains active before Reno enters");
    AssertEqual(
        new FieldStoryStateCondition(3, 17, 0x01, 0x01),
        aerisMeeting.CompletedCondition,
        "church meeting retires when Reno enters");

    var aerisAfterReno = definitions.Single(candidate =>
        candidate.FieldId == 183 &&
        candidate.Label == "Talk to Aeris again after Reno arrives");
    AssertEqual(FieldStoryTargetKind.Model, aerisAfterReno.Kind, "post-Reno church target kind");
    AssertEqual(6, aerisAfterReno.EntityId, "post-Reno church target uses Aeris's model");
    AssertEqual(143, aerisAfterReno.TargetGameMoment, "post-Reno church completion moment");
    AssertEqual(140, aerisAfterReno.MinimumGameMoment, "post-Reno church minimum moment");
    AssertEqual(142, aerisAfterReno.MaximumGameMoment, "post-Reno church maximum moment");
    AssertEqual(
        new FieldStoryStateCondition(3, 17, 0x01, 0x01),
        aerisAfterReno.RequiredCondition,
        "post-Reno church target follows the native arrival bit");

    var churchMeetingMemory = new Dictionary<int, byte>();
    const int churchMeetingEventTable = 0x02361000;
    const int aerisModelId = 4;
    WriteUInt32(
        churchMeetingMemory,
        FieldNavigationObjectReader.AddressFieldEventDataPtr,
        churchMeetingEventTable);
    churchMeetingMemory[FieldPositionReader.AddressFieldNumModels] = 8;
    churchMeetingMemory[
        FieldNavigationObjectReader.AddressFieldModelIdArray + aerisMeeting.EntityId] =
        aerisModelId;
    WriteLiveFieldModel(
        churchMeetingMemory,
        churchMeetingEventTable,
        aerisModelId,
        -154,
        401,
        -2);
    byte ReadChurchMeetingByte(int address) =>
        churchMeetingMemory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadChurchMeetingInt32(int address) =>
        ReadChurchMeetingByte(address) |
        (ReadChurchMeetingByte(address + 1) << 8) |
        (ReadChurchMeetingByte(address + 2) << 16) |
        (ReadChurchMeetingByte(address + 3) << 24);
    var churchMeetingReader = new FieldStoryTargetReader(
        ReadChurchMeetingInt32,
        ReadChurchMeetingByte,
        [aerisMeeting, aerisAfterReno]);
    var churchMeetingPosition =
        new FieldPositionSnapshot(1, 183, 0, 0, 0, 0, 0, 0);
    WriteUInt16(
        churchMeetingMemory,
        FieldNavigationObjectReader.AddressFieldBankBase,
        140);
    targets = churchMeetingReader.ReadTargets(churchMeetingPosition);
    AssertEqual(1, targets.Count, "the controllable church meeting should expose Aeris");
    AssertEqual(aerisMeeting.Label, targets[0].Label, "the initial church meeting objective");
    AssertEqual(-154, targets[0].X, "church meeting uses Aeris's live x position");
    AssertEqual(401, targets[0].Y, "church meeting uses Aeris's live y position");
    churchMeetingMemory[
        FieldNavigationObjectReader.AddressFieldBankBase + 0x100 + 17] = 0x01;
    targets = churchMeetingReader.ReadTargets(churchMeetingPosition);
    AssertEqual(1, targets.Count, "Reno's native arrival bit should advance the church objective");
    AssertEqual(
        aerisAfterReno.Label,
        targets[0].Label,
        "the church objective should tell the player to speak to Aeris again");
    WriteUInt16(
        churchMeetingMemory,
        FieldNavigationObjectReader.AddressFieldBankBase,
        143);
    AssertEqual(
        0,
        churchMeetingReader.ReadTargets(churchMeetingPosition).Count,
        "the Aeris meeting target retires when the native church scene advances");

    var church = definitions
        .Where(candidate => candidate.FieldId == 184 && candidate.Priority == 0)
        .ToArray();
    AssertEqual(4, church.Length, "the playable church escape should expose its route and three rescue stages");
    var rafters = church.Single(candidate => candidate.Label == "Continue along the upper church rafters");
    var leftBarrel = church.Single(candidate => candidate.Label == "Push the left barrel to help Aerith");
    var middleBarrel = church.Single(candidate => candidate.Label == "Push the middle barrel to help Aerith");
    var rightBarrel = church.Single(candidate => candidate.Label == "Push the right barrel to help Aerith");

    AssertEqual(FieldStoryTargetKind.Location, rafters.Kind, "church rafter route kind");
    AssertEqual(-198, rafters.X, "church rafter trigger approach x");
    AssertEqual(1871, rafters.Y, "church rafter trigger approach y");
    AssertEqual(502, rafters.Z, "church rafter trigger approach z");
    AssertEqual(152, rafters.TargetGameMoment, "church rafter route completes at the native escape moment");

    var expectedBarrels = new[]
    {
        (Definition: leftBarrel, EntityId: 10, Stage: (byte)1),
        (Definition: middleBarrel, EntityId: 8, Stage: (byte)2),
        (Definition: rightBarrel, EntityId: 9, Stage: (byte)3)
    };
    foreach (var expected in expectedBarrels)
    {
        var requiredConditions = expected.Definition.RequiredConditions ?? [];
        AssertEqual(FieldStoryTargetKind.Model, expected.Definition.Kind, $"{expected.Definition.Label} kind");
        AssertEqual(expected.EntityId, expected.Definition.EntityId, $"{expected.Definition.Label} entity");
        AssertEqual(152, expected.Definition.MinimumGameMoment, $"{expected.Definition.Label} minimum moment");
        AssertEqual(152, expected.Definition.MaximumGameMoment, $"{expected.Definition.Label} maximum moment");
        AssertEqual(2, requiredConditions.Length, $"{expected.Definition.Label} native requirement count");
        AssertEqual(
            true,
            requiredConditions.Contains(
                new FieldStoryStateCondition(5, 10, 0xFF, 1)),
            $"{expected.Definition.Label} requires the active barrel window");
        AssertEqual(
            true,
            requiredConditions.Contains(
                new FieldStoryStateCondition(5, 12, 0xFF, expected.Stage)),
            $"{expected.Definition.Label} requires its native rescue stage");
    }

    const int eventTable = 0x02370000;
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 12;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 8] = 6;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 9] = 7;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + 10] = 8;
    WriteLiveFieldModel(memory, eventTable, 6, -383, 1916, 946);
    WriteLiveFieldModel(memory, eventTable, 7, 368, 1736, 946);
    WriteLiveFieldModel(memory, eventTable, 8, -368, 1301, 946);
    var churchReader = new FieldStoryTargetReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        church);
    var churchPosition = new FieldPositionSnapshot(1, 184, 0, 281, 1424, 0, 0, 64);

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 151);
    targets = churchReader.ReadTargets(churchPosition);
    AssertEqual(1, targets.Count, "the playable church escape should begin on the upper-rafter route");
    AssertEqual(rafters.Label, targets[0].Label, "church route objective before Reno's escape sequence");

    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 152);
    targets = churchReader.ReadTargets(churchPosition);
    AssertEqual(0, targets.Count, "barrel Story must wait until Cloud chooses to help Aerith");

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 10] = 1;
    for (byte stage = 1; stage <= 3; stage++)
    {
        memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 12] = stage;
        targets = churchReader.ReadTargets(churchPosition);
        AssertEqual(1, targets.Count, $"church rescue stage {stage} should expose exactly one barrel");
        AssertEqual(
            expectedBarrels.Single(expected => expected.Stage == stage).Definition.Label,
            targets[0].Label,
            $"church rescue stage {stage} barrel");
    }

    memory[FieldNavigationObjectReader.AddressTemporaryFieldBankBase + 10] = 0;
    targets = churchReader.ReadTargets(churchPosition);
    AssertEqual(0, targets.Count, "barrel Story should retire while the native rescue sequence resolves");

    var finalBeam = definitions.Single(candidate =>
        candidate.FieldId == 186 &&
        candidate.Label == "Cross the final roof beam to escape the church");
    AssertEqual(213, finalBeam.X, "final church beam native line midpoint x");
    AssertEqual(-12, finalBeam.Y, "final church beam native line midpoint y");
    AssertEqual(935, finalBeam.Z, "final church beam native line midpoint z");
    AssertEqual(
        new FieldNavigationTriggerLine(213, 2, 935, 213, -25, 935),
        finalBeam.TriggerLine,
        "final church beam native trigger");
    AssertEqual(155, finalBeam.TargetGameMoment, "final church beam completion moment");
    AssertEqual(152, finalBeam.MinimumGameMoment, "final church beam minimum moment");
    AssertEqual(154, finalBeam.MaximumGameMoment, "final church beam maximum moment");

    var routeToAerisHouse =
        new Dictionary<int, (string Label, int X, int Y, int Z, FieldNavigationTriggerLine? Line)>
        {
            [171] = (
                "Follow the rooftops toward the Sector 5 slums",
                -1068,
                -597,
                221,
                null),
            [173] = (
                "Continue through the outskirts toward Aeris's house",
                -1289,
                -180,
                0,
                new FieldNavigationTriggerLine(-1474, 79, 0, -1103, -438, 0)),
            [172] = (
                "Continue through Sector 5 toward Aeris's house",
                122,
                547,
                0,
                new FieldNavigationTriggerLine(221, 548, 0, 23, 546, 0)),
            [177] = (
                "Go to Aeris's garden",
                631,
                1314,
                0,
                new FieldNavigationTriggerLine(590, 1585, 0, 671, 1043, 0)),
            [187] = (
                "Enter Aeris's house",
                12,
                98,
                0,
                new FieldNavigationTriggerLine(-22, 98, 0, 46, 98, 0)),
            [181] = (
                "Return to the Sector 5 slum outskirts",
                -732,
                -149,
                -1,
                new FieldNavigationTriggerLine(-906, -33, -1, -558, -264, -1)),
            [182] = (
                "Leave the church and return toward Sector 5",
                -1,
                -467,
                0,
                new FieldNavigationTriggerLine(-80, -467, 0, 79, -467, 0))
        };

    foreach (var expected in routeToAerisHouse)
    {
        var definition = definitions.Single(candidate =>
            candidate.FieldId == expected.Key &&
            candidate.Label == expected.Value.Label &&
            candidate.TargetGameMoment == 164);
        AssertEqual(FieldStoryTargetKind.Location, definition.Kind, $"field {expected.Key} route kind");
        AssertEqual(expected.Value.X, definition.X, $"field {expected.Key} route x");
        AssertEqual(expected.Value.Y, definition.Y, $"field {expected.Key} route y");
        AssertEqual(expected.Value.Z, definition.Z, $"field {expected.Key} route z");
        AssertEqual(expected.Value.Line, definition.TriggerLine, $"field {expected.Key} native route line");
        AssertEqual(164, definition.TargetGameMoment, $"field {expected.Key} route completion moment");
        AssertEqual(158, definition.MinimumGameMoment, $"field {expected.Key} route minimum moment");
        AssertEqual(163, definition.MaximumGameMoment, $"field {expected.Key} route maximum moment");

        var routeMemory = new Dictionary<int, byte>();
        byte ReadRouteByte(int address) =>
            routeMemory.TryGetValue(address, out var value) ? value : (byte)0;
        int ReadRouteInt32(int address) =>
            ReadRouteByte(address) |
            (ReadRouteByte(address + 1) << 8) |
            (ReadRouteByte(address + 2) << 16) |
            (ReadRouteByte(address + 3) << 24);
        var routeReader = new FieldStoryTargetReader(
            ReadRouteInt32,
            ReadRouteByte,
            [definition]);
        var routePosition =
            new FieldPositionSnapshot(1, expected.Key, 0, 0, 0, 0, 0, 0);

        WriteUInt16(
            routeMemory,
            FieldNavigationObjectReader.AddressFieldBankBase,
            157);
        AssertEqual(
            0,
            routeReader.ReadTargets(routePosition).Count,
            $"field {expected.Key} route stays hidden before leaving the church");
        WriteUInt16(
            routeMemory,
            FieldNavigationObjectReader.AddressFieldBankBase,
            158);
        var routeTargets = routeReader.ReadTargets(routePosition);
        AssertEqual(1, routeTargets.Count, $"field {expected.Key} exposes its route at moment 158");
        AssertEqual(expected.Value.Label, routeTargets[0].Label, $"field {expected.Key} route label");
        WriteUInt16(
            routeMemory,
            FieldNavigationObjectReader.AddressFieldBankBase,
            164);
        AssertEqual(
            0,
            routeReader.ReadTargets(routePosition).Count,
            $"field {expected.Key} route retires after entering Aeris's house");
    }
}

