static void AssertInstalledAerisHouseSneakRouteAvoidsAllCatchLines()
{
    var memory = new Dictionary<int, byte>();
    WriteUInt16(
        memory,
        FieldNavigationObjectReader.AddressFieldBankBase,
        170);
    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    var start = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        190,
        0,
        -164,
        245,
        288,
        31,
        0);
    var targetReader = new FieldStoryTargetReader(
        ReadInt32Value,
        ReadByte,
        FieldStoryEventCatalog.CreateAllFields());
    var target = targetReader.ReadTargets(start).Single();
    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(190));
    var tracker = new FieldNavigationRouteTracker(planner);

    var routeStarted = tracker.TryStart(start, target, out _);
    AssertEqual(
        true,
        routeStarted,
        $"the installed Aeris-house sneak route should be reachable: {planner.LastDiagnostic}");
    var steps = tracker.CurrentProbeSnapshot?.StableWaypoints ??
        Array.Empty<FieldNavigationRouteStep>();
    AssertEqual(
        true,
        steps.Any(step =>
            Math.Abs(step.Waypoint.X - 20) <= 8 &&
            Math.Abs(step.Waypoint.Y - 340) <= 8),
        "the sneak route must retain the safe wall-side corner");

    var creakyStart = new FieldNavigationRouteWaypoint(-1, 288, 288);
    var creakyEnd = new FieldNavigationRouteWaypoint(21, 259, 288);
    var bedroomDoorStart = new FieldNavigationRouteWaypoint(58, 125, 288);
    var bedroomDoorEnd = new FieldNavigationRouteWaypoint(159, 131, 288);
    var previous = new FieldNavigationRouteWaypoint(start.X, start.Y, start.Z);
    foreach (var step in steps)
    {
        AssertEqual(
            false,
            SegmentsIntersect2D(previous, step.Waypoint, creakyStart, creakyEnd),
            $"sneak route segment {previous} to {step.Waypoint} must not cross the native creaky-floor line");
        AssertEqual(
            true,
            SegmentDistance2D(previous, step.Waypoint, bedroomDoorStart, bedroomDoorEnd) >= 40d,
            $"sneak route segment {previous} to {step.Waypoint} must clear Aeris's bedroom-door catch capsule");
        previous = step.Waypoint;
    }

    var failedTracePosition = start with
    {
        X = -16,
        Y = 273,
        TriangleId = 25
    };
    var failedTraceTracker = new FieldNavigationRouteTracker(
        new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(190)));
    AssertEqual(
        true,
        failedTraceTracker.TryStart(failedTracePosition, target, out _),
        "the exact pre-catch trace position should retain a safe route");
    AssertEqual(
        true,
        failedTraceTracker.CurrentProbeSnapshot?.StableWaypoints.Any(step =>
            step.MustReach &&
            Math.Abs(step.Waypoint.X - 20) <= 8 &&
            Math.Abs(step.Waypoint.Y - 340) <= 8) == true,
        "the exact pre-catch trace must turn back toward the mandatory safe corner");

    var clearedPosition = start with
    {
        X = 50,
        Y = 270,
        TriangleId = 24
    };
    var clearedTracker = new FieldNavigationRouteTracker(
        new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(190)));
    AssertEqual(
        true,
        clearedTracker.TryStart(clearedPosition, target, out _),
        "the route should remain available after clearing the creaky floor");
    AssertEqual(
        false,
        clearedTracker.CurrentProbeSnapshot?.StableWaypoints.Any(step => step.MustReach) == true,
        "the wall-side corner must not send Cloud backward after the hazard is cleared: " +
        string.Join(
            ";",
            clearedTracker.CurrentProbeSnapshot?.StableWaypoints.Select(
                step =>
                    $"{step.Waypoint.X},{step.Waypoint.Y},{step.Waypoint.Z}" +
                    $"/portal={step.RequiredPortalIndex}/mustReach={step.MustReach}") ??
            []));

    var beforeBedroomDoor = start with
    {
        X = 80,
        Y = 209,
        TriangleId = 24
    };
    var bedroomDoorPlanner =
        new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(190));
    var bedroomDoorTracker = new FieldNavigationRouteTracker(bedroomDoorPlanner);
    AssertEqual(
        true,
        bedroomDoorTracker.TryStart(beforeBedroomDoor, target, out _),
        "the exact live position before Aeris's bedroom doorway should retain a safe route");
    var bedroomDoorSteps =
        bedroomDoorTracker.CurrentProbeSnapshot?.StableWaypoints ??
        Array.Empty<FieldNavigationRouteStep>();
    previous = new FieldNavigationRouteWaypoint(
        beforeBedroomDoor.X,
        beforeBedroomDoor.Y,
        beforeBedroomDoor.Z);
    foreach (var step in bedroomDoorSteps)
    {
        AssertEqual(
            true,
            SegmentDistance2D(previous, step.Waypoint, bedroomDoorStart, bedroomDoorEnd) >= 40d,
            "the live replan before Aeris's bedroom doorway must stay on the stair side: " +
            $"{bedroomDoorPlanner.LastDiagnostic}; segment={previous} to {step.Waypoint}");
        previous = step.Waypoint;
    }

    static bool SegmentsIntersect2D(
        FieldNavigationRouteWaypoint firstStart,
        FieldNavigationRouteWaypoint firstEnd,
        FieldNavigationRouteWaypoint secondStart,
        FieldNavigationRouteWaypoint secondEnd)
    {
        const double epsilon = 0.000001d;
        var firstX = firstEnd.X - firstStart.X;
        var firstY = firstEnd.Y - firstStart.Y;
        var secondX = secondEnd.X - secondStart.X;
        var secondY = secondEnd.Y - secondStart.Y;
        var offsetX = secondStart.X - firstStart.X;
        var offsetY = secondStart.Y - firstStart.Y;
        var denominator = firstX * (double)secondY - firstY * (double)secondX;
        if (Math.Abs(denominator) <= epsilon)
        {
            return false;
        }

        var firstAmount =
            (offsetX * (double)secondY - offsetY * (double)secondX) /
            denominator;
        var secondAmount =
            (offsetX * (double)firstY - offsetY * (double)firstX) /
            denominator;
        return firstAmount >= -epsilon &&
               firstAmount <= 1d + epsilon &&
               secondAmount >= -epsilon &&
               secondAmount <= 1d + epsilon;
    }

    static double SegmentDistance2D(
        FieldNavigationRouteWaypoint firstStart,
        FieldNavigationRouteWaypoint firstEnd,
        FieldNavigationRouteWaypoint secondStart,
        FieldNavigationRouteWaypoint secondEnd)
    {
        if (SegmentsIntersect2D(firstStart, firstEnd, secondStart, secondEnd))
        {
            return 0d;
        }

        return Math.Min(
            Math.Min(
                PointSegmentDistance2D(firstStart, secondStart, secondEnd),
                PointSegmentDistance2D(firstEnd, secondStart, secondEnd)),
            Math.Min(
                PointSegmentDistance2D(secondStart, firstStart, firstEnd),
                PointSegmentDistance2D(secondEnd, firstStart, firstEnd)));
    }

    static double PointSegmentDistance2D(
        FieldNavigationRouteWaypoint point,
        FieldNavigationRouteWaypoint segmentStart,
        FieldNavigationRouteWaypoint segmentEnd)
    {
        var deltaX = segmentEnd.X - segmentStart.X;
        var deltaY = segmentEnd.Y - segmentStart.Y;
        var lengthSquared = deltaX * (double)deltaX + deltaY * (double)deltaY;
        if (lengthSquared <= 0d)
        {
            return Math.Sqrt(
                Math.Pow(point.X - segmentStart.X, 2d) +
                Math.Pow(point.Y - segmentStart.Y, 2d));
        }

        var amount = Math.Clamp(
            ((point.X - segmentStart.X) * deltaX +
             (point.Y - segmentStart.Y) * deltaY) /
            lengthSquared,
            0d,
            1d);
        var closestX = segmentStart.X + amount * deltaX;
        var closestY = segmentStart.Y + amount * deltaY;
        return Math.Sqrt(
            Math.Pow(point.X - closestX, 2d) +
            Math.Pow(point.Y - closestY, 2d));
    }
}

static void AssertFieldStoryCatalogCoversSector4PlateRoute()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields()
        .Where(definition =>
            definition.FieldId is >= 164 and <= 169 &&
            definition.Priority == 0 &&
            definition.MinimumGameMoment == 117 &&
            definition.MaximumGameMoment == 122)
        .ToArray();
    AssertEqual(6, definitions.Length, "Sector 4 plate Story should cover fields 164 through 169");

    var expected = new Dictionary<int, (string Label, int EntityId, FieldNavigationTriggerLine? Line)>
    {
        [164] = (
            "Follow the large duct to the far ladder",
            2,
            new FieldNavigationTriggerLine(-69, 65, 0, 68, 60, 0)),
        [165] = (
            "Continue across the upper ladder",
            -1,
            null),
        [166] = (
            "Cross Jessie's platform and use the next ladder",
            2,
            new FieldNavigationTriggerLine(-60, 52, 0, 72, 52, 0)),
        [167] = (
            "Go right across the small duct and use the ladder",
            5,
            new FieldNavigationTriggerLine(185, -35, 0, 170, 37, 0)),
        [168] = (
            "Use the ladder near Wedge",
            4,
            new FieldNavigationTriggerLine(-2323, 778, 0, -2239, 778, 0)),
        [169] = (
            "Use the ladder near Biggs to reach Reactor 5",
            3,
            new FieldNavigationTriggerLine(-357, -176, 14, -357, -112, 14))
    };

    foreach (var definition in definitions)
    {
        var plate = expected[definition.FieldId];
        AssertEqual(plate.Label, definition.Label, $"field {definition.FieldId} plate objective label");
        AssertEqual(plate.EntityId, definition.EntityId, $"field {definition.FieldId} native entity identity");
        AssertEqual(plate.Line, definition.TriggerLine, $"field {definition.FieldId} native trigger geometry");
        AssertEqual(123, definition.TargetGameMoment, $"field {definition.FieldId} plate story milestone");
    }

    var upperLadder = definitions.Single(definition => definition.FieldId == 165);
    AssertEqual(0, upperLadder.X, "upper-ladder scripted endpoint x");
    AssertEqual(277, upperLadder.Y, "upper-ladder scripted endpoint y");
    AssertEqual(0, upperLadder.Z, "upper-ladder scripted endpoint z");

    var memory = new Dictionary<int, byte>();
    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    foreach (var definition in definitions)
    {
        var reader = new FieldStoryTargetReader(ReadInt32Value, ReadByte, [definition]);
        var position =
            new FieldPositionSnapshot(1, definition.FieldId, 0, definition.X, definition.Y, definition.Z, 0, 0);

        WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 116);
        AssertEqual(
            0,
            reader.ReadTargets(position).Count,
            $"field {definition.FieldId} should remain hidden before the player chooses Go down");

        WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 117);
        var target = reader.ReadTargets(position);
        AssertEqual(
            1,
            target.Count,
            $"field {definition.FieldId} should expose its plate objective after Go down sets moment 117");
        AssertEqual(definition.Label, target[0].Label, $"field {definition.FieldId} reader objective");
        AssertEqual(definition.TriggerLine, target[0].TriggerLine, $"field {definition.FieldId} reader trigger geometry");

        WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 122);
        AssertEqual(
            1,
            reader.ReadTargets(position).Count,
            $"field {definition.FieldId} should remain navigable through the plate sequence");

        WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 123);
        AssertEqual(
            0,
            reader.ReadTargets(position).Count,
            $"field {definition.FieldId} should complete at the Reactor 5 milestone");
    }
}

static void AssertFieldStoryCatalogCoversSector7AndWallMarketMandatoryActions()
{
    var definitions = FieldStoryEventCatalog.CreateAllFields();
    var labels = definitions.Select(definition => definition.Label).ToHashSet(StringComparer.Ordinal);
    foreach (var expected in new[]
    {
        "Approach the front door; Barret and Avalanche are entering",
        "Use the pinball machine to descend to the Avalanche basement",
        "Approach Barret and the Avalanche meeting",
        "Head back toward the pinball elevator; Tifa wants to speak",
        "Use the pinball machine to return upstairs",
        "Use the pinball machine to return to the bar after waking",
        "Walk toward the front door; Tifa will stop Cloud about the promise",
        "Ask about Tifa; choose the Tifa question",
        "Ask to enter Corneo Hall; learn men are refused",
        "Ask the clothes-shop clerk for a dress; learn the owner is at the bar",
        "Ask the clothes-shop owner to make Cloud's dress",
        "Collect the finished dress and learn about the gym",
        "Talk to Big Bro and complete the squat contest for a wig",
        "Enter the fitting room and choose to change clothes",
        "Talk to the doorman while disguised and enter",
        "Talk to Tifa until the escort and selection sequence begins",
        "Confront Scotch and Corneo's lackeys",
        "Cross the bedroom rug and trigger the trap",
        "Wake and check Aeris",
        "Wake and check Tifa",
        "Choose to climb out after defeating Aps",
        "Use the final sewer ladder"
    })
    {
        AssertEqual(true, labels.Contains(expected), $"native Story catalog should include: {expected}");
    }

    var dress = definitions.Single(definition => definition.Label == "Collect the finished dress and learn about the gym");
    AssertEqual(new FieldStoryStateCondition(1, 161, 0xE0, 0, AnyBitSet: true), dress.RequiredCondition, "dress completion uses any native quality bit");
    AssertEqual(new FieldStoryStateCondition(1, 161, 0x08, 0x08), dress.CompletedCondition, "dress collection completion bit");

    var aeris = definitions.Single(definition => definition.Label == "Wake and check Aeris");
    var tifa = definitions.Single(definition => definition.Label == "Wake and check Tifa");
    AssertEqual(212, aeris.FieldId, "Aeris sewer wake target field");
    AssertEqual(212, tifa.FieldId, "Tifa sewer wake target field");
    AssertEqual(aeris.Priority, tifa.Priority, "both fallen party members must remain simultaneously available");
}

