static void AssertFieldStoryReaderExposesBothShinraEntryRoutesAndInitialElevator()
{
    var memory = new Dictionary<int, byte>
    {
        // The wall-climb gateway reaches the Shinra exterior at game moment 259.
        [FieldNavigationObjectReader.AddressFieldBankBase] = 0x03,
        [FieldNavigationObjectReader.AddressFieldBankBase + 1] = 0x01
    };
    var reader = new FieldStoryTargetReader(
        _ => 0,
        address => memory.GetValueOrDefault(address),
        FieldStoryEventCatalog.CreateAllFields());

    static string[] ReadLabels(
        FieldStoryTargetReader targetReader,
        int fieldId) =>
        targetReader
            .ReadTargets(new FieldPositionSnapshot(1, fieldId, 259, 0, 0, 0, 0, 0))
            .Select(target => target.Label)
            .OrderBy(label => label, StringComparer.Ordinal)
            .ToArray();

    var exteriorLabels = ReadLabels(reader, 227);
    AssertEqual(2, exteriorLabels.Length, "the Shinra exterior visible route-choice count");
    AssertEqual(
        true,
        exteriorLabels.Contains("Take the emergency stairs into Shinra Headquarters", StringComparer.Ordinal),
        "the Shinra exterior should expose the emergency stairs");
    AssertEqual(
        true,
        exteriorLabels.Contains("Take the front entrance into Shinra Headquarters", StringComparer.Ordinal),
        "the Shinra exterior should expose the front entrance");

    foreach (var stairField in new[] { 228, 229, 230, 231 })
    {
        AssertEqual(
            true,
            ReadLabels(reader, stairField).Any(label => label.Contains("stair", StringComparison.OrdinalIgnoreCase)),
            $"emergency-stair field {stairField} should remain guided before floor 59");
    }

    foreach (var lobbyField in new[] { 234, 235, 237 })
    {
        AssertEqual(
            2,
            ReadLabels(reader, lobbyField).Count(label => label.Contains("lobby elevator", StringComparison.Ordinal)),
            $"lobby field {lobbyField} should expose both native initial-elevator doors");
    }

    var elevatorStart = new FieldPositionSnapshot(1, 232, 259, -13, 218, 0, 13, 0);
    var elevator = reader.ReadTargets(elevatorStart);
    AssertEqual(1, elevator.Count, "the initial Shinra elevator should expose its native switch");
    AssertEqual(
        "Press the elevator switch to continue toward floor 59",
        elevator[0].Label,
        "initial Shinra elevator switch label");
    AssertEqual(
        false,
        elevator[0].CompletesOnArrival,
        "the switch target should remain active through the elevator's random stops");

    var elevatorPlanner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(232));
    AssertEqual(
        true,
        elevatorPlanner.TryBuildRoute(elevatorStart, elevator[0], out _),
        $"the initial elevator switch approach should be reachable: {elevatorPlanner.LastDiagnostic}");
}

