    AssertEqual(
        new FieldNavigationTriggerLine(282, 769, 4, 282, 937, 4),
        presidentOffice.TriggerLine,
        "President office native x-threshold line");

    var earlyRoofRecovery = definitions.Single(definition =>
        definition.FieldId == 268 &&
        definition.Label == "Return inside and enter President Shinra's office");
    AssertEqual(302, earlyRoofRecovery.MinimumGameMoment, "early roof recovery minimum game moment");
    AssertEqual(304, earlyRoofRecovery.MaximumGameMoment, "early roof recovery maximum game moment");
    AssertEqual(
        new FieldNavigationTriggerLine(-1312, 378, 182, -1128, 521, 182),
        earlyRoofRecovery.TriggerLine,
        "early roof recovery exact gateway");

    var roof = definitions.Single(definition =>
        definition.FieldId == 266 &&
        definition.Label == "Continue to the roof to confront Rufus");
    AssertEqual(
        new FieldNavigationTriggerLine(210, 1184, 4, 270, 1172, 4),
        roof.TriggerLine,
