    AssertEqual(320, returnInside.MinimumGameMoment, "post-Rufus roof return minimum game moment");
    AssertEqual(322, returnInside.MaximumGameMoment, "post-Rufus roof return maximum game moment");
    AssertEqual(
        new FieldNavigationTriggerLine(-1312, 378, 182, -1128, 521, 182),
        returnInside.TriggerLine,
        "post-Rufus roof return exact gateway");

    var descend = definitions.Single(definition =>
        definition.FieldId == 266 &&
