    AssertEqual(1, targets.Count, "floor 70 moment 302 should expose one next Story target");
    AssertEqual("Enter President Shinra's office and investigate", targets[0].Label, "floor 70 moment 302 Story target");

    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(266));
    AssertEqual(
        true,
        planner.TryBuildRoute(floor70Entry, targets[0], out _),
        $"captured floor 70 entry should route to President Shinra's office: {planner.LastDiagnostic}");
}

