static void AssertFieldStoryReaderSequencesFloor65MidgarModelFromNativeFlags()
{
    const int eventTable = 0x02500000;
    var memory = new Dictionary<int, byte>();
    WriteUInt16(memory, FieldNavigationObjectReader.AddressFieldBankBase, 263);
    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 9;

    var nativeModels = new[]
    {
        (EntityId: 15, ModelId: 3, X: -982, Y: -681, Z: 0),
        (EntityId: 16, ModelId: 4, X: -872, Y: -524, Z: 0),
        (EntityId: 17, ModelId: 5, X: -915, Y: 141, Z: 0),
        (EntityId: 18, ModelId: 6, X: -996, Y: -92, Z: 0),
        (EntityId: 19, ModelId: 7, X: 1008, Y: 858, Z: 0),
        (EntityId: 20, ModelId: 8, X: 772, Y: -4, Z: 0)
    };
    foreach (var model in nativeModels)
    {
        memory[FieldNavigationObjectReader.AddressFieldModelIdArray + model.EntityId] =
            (byte)model.ModelId;
        WriteLiveFieldModel(memory, eventTable, model.ModelId, model.X, model.Y, model.Z);
    }

    byte ReadByte(int address) => memory.GetValueOrDefault(address);
    short ReadInt16(int address) =>
        unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));
    int ReadInt32(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldStoryTargetReader(
        ReadInt32,
        ReadInt16,
        ReadByte,
        FieldStoryEventCatalog.CreateAllFields());
    var outerPosition = new FieldPositionSnapshot(1, 248, 0, 120, -921, 0, 84, 0);
    var modelPosition = new FieldPositionSnapshot(1, 249, 0, 0, -448, 0, 0, 0);

    void AssertOnlyTarget(
        FieldPositionSnapshot position,
        string expectedLabel,
        string phase)
    {
        var targets = reader.ReadTargets(position);
        AssertEqual(1, targets.Count, $"{phase} target count");
        AssertEqual(expectedLabel, targets[0].Label, $"{phase} target");
    }

    AssertOnlyTarget(
        outerPosition,
        "Open the lower chest in the upper-left room for the first Midgar part",
        "floor 65 before collecting any parts");

    var persistentBank = FieldNavigationObjectReader.AddressFieldBankBase;
    var modelBank = persistentBank + 0x100;

    // PARTD is the only chest initially unlocked. It writes the carried-part
    // bit 0x40 and the persistent collected bit 0x02.
    memory[persistentBank + 57] = 0x02;
    memory[persistentBank + 68] = 0x40;
    AssertOnlyTarget(
        outerPosition,
        "Carry the Midgar part into the model room",
        "floor 65 carrying first part");
    AssertOnlyTarget(
        modelPosition,
        "Place the first Midgar part in the bottom-right model slot",
        "floor 65 first model placement");

    memory[persistentBank + 68] = 0;
    memory[modelBank + 180] = 0x40;
    AssertOnlyTarget(
        modelPosition,
        "Return to the outer floor for the next unlocked chest",
        "floor 65 after first placement while still in model room");
    AssertOnlyTarget(
        outerPosition,
        "Open the lower chest in the lower-left room for the second Midgar part",
        "floor 65 after first model placement");

    memory[persistentBank + 56] = 0x80;
    memory[persistentBank + 68] = 0x10;
    AssertOnlyTarget(
        modelPosition,
        "Place the second Midgar part in the next counterclockwise model slot",
        "floor 65 second model placement");

    memory[persistentBank + 68] = 0;
    memory[modelBank + 180] = 0x60;
    AssertOnlyTarget(
        modelPosition,
        "Return to the outer floor for the next unlocked chest",
        "floor 65 after second placement while still in model room");
    AssertOnlyTarget(
        outerPosition,
        "Open the remaining chest in the upper-left room for the third Midgar part",
        "floor 65 after second model placement");

    memory[persistentBank + 57] = 0x03;
    memory[persistentBank + 68] = 0x20;
    AssertOnlyTarget(
        modelPosition,
        "Place the third Midgar part in the next counterclockwise model slot",
        "floor 65 third model placement");

    memory[persistentBank + 68] = 0;
    memory[modelBank + 180] = 0x68;
    AssertOnlyTarget(
        modelPosition,
        "Return to the outer floor for the next unlocked chest",
        "floor 65 after third placement while still in model room");
    AssertOnlyTarget(
        outerPosition,
        "Open the remaining chest in the lower-left room for the fourth Midgar part",
        "floor 65 after third model placement");

    memory[persistentBank + 56] = 0xC0;
    memory[persistentBank + 68] = 0x08;
    AssertOnlyTarget(
        modelPosition,
        "Place the fourth Midgar part in the next counterclockwise model slot",
        "floor 65 fourth model placement");

    memory[persistentBank + 68] = 0;
    memory[modelBank + 180] = 0x78;
    AssertOnlyTarget(
        modelPosition,
        "Return to the outer floor for the next unlocked chest",
        "floor 65 after fourth placement while still in model room");
    AssertOnlyTarget(
        outerPosition,
        "Open the chest in the upper-right room for the final Midgar part",
        "floor 65 after fourth model placement");

    memory[persistentBank + 57] = 0x07;
    // The live Floor 65 trace showed the carried-part byte clear during the
    // transition into blin65_2.  The final target must survive that transient
    // read by using the persistent final-chest and prior-slot state.
    memory[persistentBank + 68] = 0;
    AssertOnlyTarget(
        modelPosition,
        "Place the final Midgar part in the last model slot",
        "floor 65 final model placement after the carried flag clears");

    memory[persistentBank + 68] = 0;
    memory[modelBank + 180] = 0xF8;
    AssertOnlyTarget(
        modelPosition,
        "Return to the outer floor and collect Keycard 66",
        "floor 65 after final placement while still in model room");
    AssertOnlyTarget(
        outerPosition,
        "Collect Keycard 66 from the completed Midgar model",
        "floor 65 completed model");

    memory[persistentBank + 224] = 66;
    AssertOnlyTarget(
        outerPosition,
        "Continue to floor 66 with Keycard 66",
        "floor 65 after collecting Keycard 66");
}

