static void AssertFieldStoryReaderSequencesEveryWallClimbStepFromNativeFlags()
{
    const int wallClimbStateAddress =
        FieldNavigationObjectReader.AddressFieldBankBase + 165;
    var memory = new Dictionary<int, byte>
    {
        [FieldNavigationObjectReader.AddressFieldBankBase] = 0x01,
        [FieldNavigationObjectReader.AddressFieldBankBase + 1] = 0x01,
        [wallClimbStateAddress] = 0xE0
    };
    var definitions = FieldStoryEventCatalog.CreateAllFields();
    var reader = new FieldStoryTargetReader(
        _ => 0,
        address => memory.GetValueOrDefault(address),
        definitions);

    static void AssertSingleTarget(
        FieldStoryTargetReader targetReader,
        FieldPositionSnapshot position,
        string expectedLabel,
        string phase)
    {
        var targets = targetReader.ReadTargets(position);
        AssertEqual(1, targets.Count, $"{phase} target count");
        AssertEqual(expectedLabel, targets[0].Label, $"{phase} target");
    }

    var firstSocketPosition =
        new FieldPositionSnapshot(1, 223, 0, 304, 724, 1547, 32, 0);
    AssertSingleTarget(
        reader,
        firstSocketPosition,
        "Place a battery in the first wall-climb socket",
        "wall climb before first battery");
    AssertEqual(
        false,
        reader.ReadTargets(firstSocketPosition)[0].CompletesOnArrival,
        "first battery target should remain active until the native install flag changes");

    // The propeller animation's native Script 3 writes bit 0x02. Bit 0x01
    // only records inspecting the socket without installing a battery.
    memory[wallClimbStateAddress] = 0xE2;
    var secondSocketPosition =
        new FieldPositionSnapshot(1, 223, 0, -72, 1034, 2280, 158, 0);
    AssertSingleTarget(
        reader,
        secondSocketPosition,
        "Place a battery in the second wall-climb socket",
        "wall climb after first battery");
    AssertEqual(
        false,
        reader.ReadTargets(secondSocketPosition)[0].CompletesOnArrival,
        "second battery target should remain active until the native install flag changes");

    // The second socket's native Cloud script writes bit 0x04. The optional
    // third socket is an Object and must not block the mandatory swing.
    memory[wallClimbStateAddress] = 0xE6;
    var swingPosition =
        new FieldPositionSnapshot(1, 223, 0, -369, 1677, 3290, 13, 0);
    AssertSingleTarget(
        reader,
        swingPosition,
        "Reach the swinging bar and press OK at the prompt",
        "wall climb after second battery");
    AssertEqual(
        false,
        reader.ReadTargets(swingPosition)[0].CompletesOnArrival,
        "swing target should remain active until Cloud lands across the gap");

    var landedPosition =
        new FieldPositionSnapshot(1, 223, 0, 183, 1922, 3075, 39, 0);
    AssertSingleTarget(
        reader,
        landedPosition,
        "Climb the final ladder after landing from the swinging bar",
        "wall climb after successful swing");

    var optionalBatteryDetour =
        new FieldPositionSnapshot(1, 224, 0, -251, 969, 2576, 81, 0);
    AssertSingleTarget(
        reader,
        optionalBatteryDetour,
        "Descend the left ladder to return to the swinging bar",
        "wall climb optional battery detour");
    AssertEqual(
        true,
        reader.ReadTargets(optionalBatteryDetour)[0].CompletesOnArrival,
        "the optional detour beacon should stop once Cloud reaches the automatic return ladder");

    foreach (var expected in new[]
             {
                 (FieldId: 224, Label: "Finish the wall climb and enter the Shinra exterior"),
                 (FieldId: 225, Label: "Enter the Shinra Building")
             })
    {
        AssertSingleTarget(
            reader,
            new FieldPositionSnapshot(1, expected.FieldId, 0, 0, 0, 0, 0, 0),
            expected.Label,
            $"wall climb field {expected.FieldId}");
    }

    foreach (var label in new[]
             {
                 "Reach the swinging bar and press OK at the prompt",
                 "Climb the final ladder after landing from the swinging bar",
                 "Descend the left ladder to return to the swinging bar",
                 "Finish the wall climb and enter the Shinra exterior",
                 "Enter the Shinra Building"
             })
    {
        var definition = definitions.Single(candidate => candidate.Label == label);
        AssertEqual(
            new FieldStoryStateCondition(1, 165, 0x06, 0x06),
            definition.RequiredCondition,
            $"{label} native mandatory-battery state");
    }
}

static void AssertFieldStoryReaderSwitchesToFinalWallClimbLineAfterSuccessfulSwing()
{
    int[] successfulLandingComponent =
