static void AssertFieldStoryCatalogLabelsAreSpeakable()
{
    var malformed = FieldStoryEventCatalog.CreateAllFields()
        .Where(definition =>
            string.IsNullOrWhiteSpace(definition.Label) ||
            definition.Label.Length > 100 ||
            definition.Label.Contains('{') ||
            definition.Label.Contains('}') ||
            definition.Label.Contains('â'))
        .Select(definition => $"{definition.SourceFieldName}:{definition.Label}")
        .ToArray();

    AssertEqual(0, malformed.Length, $"story labels should be concise decoded speech; malformed={string.Join(" | ", malformed.Take(10))}");
}

