static void AssertFieldGatewayTargetReaderReadsEveryNativeGateway()
{
    var memory = new Dictionary<int, byte>();
    const int triggerHeader = 0x02380000;
    WriteFieldGatewayOwnership(memory, 117, triggerHeader);
    InitializeGatewayTable(memory, triggerHeader);

    WriteFieldGateway(memory, triggerHeader, 0, 996, 285, 1296, 929, 493, 1296, 116);
    WriteFieldGateway(memory, triggerHeader, 1, 1019, 1728, 1298, 1298, 1705, 1298, 118);

    var reader = new FieldGatewayTargetReader(new DictionaryLegacyAddressSpace(memory));
    var position = new FieldPositionSnapshot(1, 117, 0, 0, 0, 0, 0, 0);
    var exits = reader.ReadTargets(position);

    AssertEqual(2, exits.Count, "all valid native gateway records should be exposed as exits");
    AssertEqual("Exit", exits[0].Label, "raw native gateway labels must not expose an internal field id");
    AssertEqual(963, exits[0].X, "first gateway exit-line midpoint x");
    AssertEqual(389, exits[0].Y, "first gateway exit-line midpoint y");
    AssertEqual(1296, exits[0].Z, "first gateway exit-line midpoint z");
    AssertEqual("gateway:117:0:116", exits[0].StableId, "first gateway stable identity");
    AssertEqual(true, exits[0].CompletesOnArrival, "a native gateway route should finish on its exit line");
    AssertEqual(116, exits[0].DestinationFieldIds!.Single(), "first gateway destination metadata");
    AssertEqual("Exit", exits[1].Label, "raw native gateway labels must stay generic until a native name is resolved");
    AssertEqual(1159, exits[1].X, "second gateway exit-line midpoint x");
    AssertEqual(1717, exits[1].Y, "second gateway exit-line midpoint y");
    AssertEqual(1298, exits[1].Z, "second gateway exit-line midpoint z");
    AssertEqual("gateway:117:1:118", exits[1].StableId, "second gateway stable identity");
    AssertEqual(true, exits[1].CompletesOnArrival, "every native gateway route should finish before the next field");
    AssertEqual(118, exits[1].DestinationFieldIds!.Single(), "second gateway destination metadata");
    AssertContains(reader.LastDiagnostic, "count=2");
    AssertContains(reader.LastDiagnostic, "destinations=116,118");
}

