static void AssertFieldScriptNavigationCatalogReadsNativeMapNames()
{
    var root = FindGameRoot();
    var catalog = new FieldScriptNavigationCatalog(root);
    var textResolver = new FlevelFieldTextResolver(root);
    var names = new FieldMapNameCatalog(catalog, textResolver);
    var readAddress = 0;
    var readLength = 0;
    var liveNameReader = new FieldMapNameReader((address, length) =>
    {
        readAddress = address;
        readLength = length;
        return "Sector 1 Station";
    });

    AssertEqual("Sector 1 Station", liveNameReader.Read(), "live map-name buffer text");
    AssertEqual(0x00DC0C44, readAddress, "Ghidra-confirmed MPNAM destination buffer");
    AssertEqual(24, readLength, "MPNAM copies at most 23 bytes plus a terminator");

    AssertEqual(
        "1",
        string.Join(',', catalog.ReadField(117).MapNameDialogIds),
        "md1_1 should expose its native MPNAM dialog id");
    AssertEqual(
        "Sector 1 Station",
        names.Read(117).Names.Single(),
        "the installed destination name must come from the MPNAM-selected field string");
    AssertEqual(
        "No.1 Reactor|No.5 Reactor",
        string.Join('|', names.Read(121).Names),
        "a reused field must retain every native MPNAM location name");
    AssertEqual(true, names.Read(136).IsKnownField, "an installed field with no MPNAM should remain known");
    AssertEqual(0, names.Read(136).Names.Count, "a field with no MPNAM must retain the current native location name");
}

static void AssertFieldExitLabelResolverUsesNativeDestinationNames()
{
    var names = new Dictionary<int, FieldMapNameResolution>
    {
        [117] = FieldMapNameResolution.Known(["Sector 1 Station"]),
        [121] = FieldMapNameResolution.Known(["No.1 Reactor", "No.5 Reactor"]),
        [123] = FieldMapNameResolution.Known(["No.1 Reactor"]),
        [125] = FieldMapNameResolution.Known(["No.1 Reactor"]),
        [136] = FieldMapNameResolution.Known([])
    };
    var currentName = "No.1 Reactor";
    var resolver = new FieldExitLabelResolver(
        fieldId => names.TryGetValue(fieldId, out var result) ? result : FieldMapNameResolution.Unknown,
        () => currentName);

    var targets = resolver.Resolve(
    [
        new FieldNavigationTarget(
            120,
            FieldNavigationCategory.Exits,
            "Exit 1",
            0,
            0,
            0,
            "gateway:120:0:121",
            DestinationFieldIds: [121]),
        new FieldNavigationTarget(
            135,
            FieldNavigationCategory.Exits,
            "Exit 2",
            0,
            0,
            0,
            "gateway:135:0:136",
            DestinationFieldIds: [136]),
        new FieldNavigationTarget(
            116,
            FieldNavigationCategory.Exits,
            "Exit 3",
            0,
            0,
            0,
            "gateway:116:0:117",
            DestinationFieldIds: [117]),
        new FieldNavigationTarget(
            116,
            FieldNavigationCategory.Exits,
            "Exit 4",
            0,
            0,
            0,
            "gateway:116:1:999",
            DestinationFieldIds: [999]),
        new FieldNavigationTarget(
            122,
            FieldNavigationCategory.Exits,
            "Exit 5",
            0,
            0,
            0,
            "gateway:122:0:123",
            DestinationFieldIds: [123]),
        new FieldNavigationTarget(
            124,
            FieldNavigationCategory.Exits,
            "Exit 6",
            0,
            0,
            0,
            "gateway:124:0:125",
            DestinationFieldIds: [125])
    ]);

    AssertEqual("Exit to No.1 Reactor, elevator room", targets[0].Label, "reused reactor maps should include their room descriptor");
    currentName = "Sector 8";
    targets = resolver.Resolve(targets);
    AssertEqual("Exit", targets[1].Label, "a destination without a verified native name must stay generic");
    AssertEqual("Exit to Sector 1 Station, station forecourt", targets[2].Label, "single native destination and room descriptor");
    AssertEqual("Exit", targets[3].Label, "unknown destinations must never expose internal field ids");
    AssertEqual(false, targets.Any(target => System.Text.RegularExpressions.Regex.IsMatch(target.Label, @"\bfield\s+\d+\b", System.Text.RegularExpressions.RegexOptions.IgnoreCase)), "exit speech must not leak numeric field identifiers");
    AssertEqual("Exit to No.1 Reactor, upper piping and ladder room", targets[4].Label, "reactor ladder room descriptor");
    AssertEqual("Exit to No.1 Reactor, core and bomb room", targets[5].Label, "reactor bomb room descriptor");

    var weaponShopResolver = new FieldExitLabelResolver(
        fieldId => fieldId == 151
            ? FieldMapNameResolution.Known(["Sector 7 Slums"])
