static void AssertFieldGatewayTargetReaderRejectsInvalidState()
{
    var memory = new Dictionary<int, byte>();
    const int triggerHeader = 0x02390000;
    WriteFieldGatewayOwnership(memory, 117, 0);

    var reader = new FieldGatewayTargetReader(new DictionaryLegacyAddressSpace(memory));
    var fieldPosition = new FieldPositionSnapshot(1, 117, 0, 0, 0, 0, 0, 0);
    AssertEqual(0, reader.ReadTargets(fieldPosition).Count, "null trigger pointer should expose no exits");

    WriteFieldGatewayOwnership(memory, 117, triggerHeader);
    InitializeGatewayTable(memory, triggerHeader);

    AssertEqual(0, reader.ReadTargets(fieldPosition).Count, "unused native gateway sentinels should expose no exits");
    AssertEqual(0, reader.ReadTargets(fieldPosition with { CurrentModule = 5 }).Count, "non-field modules should expose no exits");

    var unreadableReader = new FieldGatewayTargetReader(
        new DictionaryLegacyAddressSpace(memory, (_, _) => false));
    AssertEqual(0, unreadableReader.ReadTargets(fieldPosition).Count, "unreadable trigger memory should expose no exits");
}

static void AssertFieldScriptNavigationCatalogReadsNativeTransitions()
{
    var catalog = new FieldScriptNavigationCatalog(FindGameRoot());

    var ladderField = catalog.ReadField(122);
    AssertEqual(true, ladderField.IsUsable, "the installed nmkin_2 field script should decode");
    AssertEqual(
        2,
        ladderField.Transitions.Count(transition => transition.Kind == FieldNavigationTransitionKind.Ladder),
        "nmkin_2 should expose both directions of its native ladder");
    AssertEqual(
        true,
        ladderField.Transitions.Any(transition => transition.Kind == FieldNavigationTransitionKind.Jump),
        "nmkin_2 should expose its line-triggered scripted jump as an off-mesh route");

    var multiLevelField = catalog.ReadField(123);
    AssertEqual(
        6,
        multiLevelField.Transitions.Count,
        "nmkin_3 should expose four composite ladders and two standalone jumps");
    AssertEqual(
        4,
        multiLevelField.Transitions.Count(transition => transition.Kind == FieldNavigationTransitionKind.Ladder),
        "nmkin_3 setup and cleanup jumps must not become alternatives to its ladders");
    AssertEqual(
        2,
        multiLevelField.Transitions.Count(transition => transition.Kind == FieldNavigationTransitionKind.Jump),
        "nmkin_3 should retain only its two standalone platform jumps");
    AssertEqual(
        FieldNavigationInput.Down,
        multiLevelField.Transitions.Single(transition => transition.SourceEntityId == 10).RequiredInput,
        "nmkin_3 lower ladder line should retain the native down input");
    AssertEqual(
        FieldNavigationInput.Up,
        multiLevelField.Transitions.Single(transition => transition.SourceEntityId == 11).RequiredInput,
        "nmkin_3 upper ladder line should retain the native up input");
    AssertEqual(
        true,
        multiLevelField.Transitions.Single(transition => transition.SourceEntityId == 10).RequiresAction,
        "nmkin_3 lower ladder must retain its native IFKEYON action gate");
    AssertEqual(
        true,
        multiLevelField.Transitions.Single(transition => transition.SourceEntityId == 11).RequiresAction,
        "nmkin_3 upper ladder must retain its native IFKEYON action gate");

    var returnField = catalog.ReadField(124);
    AssertEqual(
        2,
        returnField.Transitions.Count(transition => transition.Kind == FieldNavigationTransitionKind.Ladder),
        "nmkin_4 should expose both directions of its native ladder after the boss");
    AssertEqual(
        0,
        returnField.Transitions.Count(transition => transition.Kind == FieldNavigationTransitionKind.Jump),
        "nmkin_4 ladder setup and cleanup jumps must not become route shortcuts");

    var elevatorField = catalog.ReadField(121);
    AssertEqual(true, elevatorField.IsUsable, "the installed elevtr1 field script should decode");
    AssertEqual(1, elevatorField.Exits.Count, "the line-triggered elevator map jump should be an exit");
    AssertEqual(-185, elevatorField.Exits[0].X, "elevator exit line midpoint x");
    AssertEqual(-6, elevatorField.Exits[0].Y, "elevator exit line midpoint y");
    AssertEqual(10, elevatorField.Exits[0].TriggerEntityId, "elevator exit should retain its native script entity for LINON gating");
    AssertContains(elevatorField.Exits[0].StableId, "script-exit:121:10");
}

static void AssertWallClimbNavigationUsesNativeBranchAndCompositeLandings()
{
    var catalog = new FieldScriptNavigationCatalog(FindGameRoot());
    var firstClimb = catalog.ReadField(223);

    var lowerVertical = firstClimb.Transitions.Where(transition => transition.SourceEntityId == 11).ToArray();
    AssertEqual(1, lowerVertical.Length, "wcrimb_1 line10 should expose only its Bank[5][37]=0 branch");
    AssertEqual(FieldNavigationTransitionKind.Ladder, lowerVertical[0].Kind, "wcrimb_1 line10 route kind");
    AssertEqual(FieldNavigationInput.Up, lowerVertical[0].RequiredInput, "wcrimb_1 line10 native direction");
    AssertEqual(71, lowerVertical[0].TargetTriangle, "wcrimb_1 line10 native landing");

    var upperVertical = firstClimb.Transitions.Where(transition => transition.SourceEntityId == 12).ToArray();
    AssertEqual(1, upperVertical.Length, "wcrimb_1 line11 should expose only its Bank[5][37]=1 branch");
    AssertEqual(FieldNavigationInput.Down, upperVertical[0].RequiredInput, "wcrimb_1 line11 native direction");
    AssertEqual(147, upperVertical[0].TargetTriangle, "wcrimb_1 line11 native landing");

    var penultimateLadder = firstClimb.Transitions.Single(transition =>
        transition.SourceEntityId == 15 &&
        transition.TargetTriangle == 158);
    AssertEqual(
        FieldNavigationInput.Left,
        penultimateLadder.RequiredInput,
        "wcrimb_1 entity 15 is the verified leftward climb before the final ladder");

    var finalLadder = firstClimb.Transitions.Single(transition =>
        transition.SourceEntityId == 17 &&
        transition.TargetTriangle == 25);
    AssertEqual(
        FieldNavigationInput.Up,
        finalLadder.RequiredInput,
        "wcrimb_1 entity 17 remains the Up climb that reaches the swinging bar");

    var propellerNear = firstClimb.Transitions.Where(transition => transition.SourceEntityId == 29).ToArray();
    AssertEqual(1, propellerNear.Length, "wcrimb_1 lineb0 should expose one scripted propeller crossing");
    AssertEqual(FieldNavigationTransitionKind.Jump, propellerNear[0].Kind, "wcrimb_1 lineb0 crossing kind");
    AssertEqual(151, propellerNear[0].TargetTriangle, "wcrimb_1 lineb0 native landing");

    var propellerFar = firstClimb.Transitions.Where(transition => transition.SourceEntityId == 30).ToArray();
    AssertEqual(1, propellerFar.Length, "wcrimb_1 lineb1 should expose one scripted propeller crossing");
    AssertEqual(FieldNavigationTransitionKind.Jump, propellerFar[0].Kind, "wcrimb_1 lineb1 crossing kind");
    AssertEqual(146, propellerFar[0].TargetTriangle, "wcrimb_1 lineb1 native landing");

    var secondClimb = catalog.ReadField(224);
    var compositeDescent = secondClimb.Transitions
        .Where(transition => transition.SourceEntityId == 12)
        .ToArray();
    AssertEqual(1, compositeDescent.Length, "wcrimb_2 line30 should be one composite climb");
    AssertEqual(FieldNavigationTransitionKind.Ladder, compositeDescent[0].Kind, "wcrimb_2 line30 route kind");
    AssertEqual(FieldNavigationInput.Down, compositeDescent[0].RequiredInput, "wcrimb_2 line30 native direction");
    AssertEqual(81, compositeDescent[0].TargetTriangle, "wcrimb_2 line30 must land after its two cleanup jumps");

    AssertEqual(
        true,
        secondClimb.Transitions.Any(transition =>
            transition.Kind == FieldNavigationTransitionKind.Ladder &&
            transition.RequiredInput == FieldNavigationInput.Up &&
            Math.Abs(transition.SourceX - 166) <= 8 &&
            Math.Abs(transition.SourceY - 1022) <= 8 &&
            transition.TargetTriangle == 74),
        "wcrimb_2 should synthesize the native auto-up counterpart from lower triangle 85");
}

