static void AssertWallClimbFinalLadderUsesUpAndRetainsRetry()
{
    const short missing = -1;
    var mesh = new FieldWalkmesh(
    [
        new FieldWalkmeshTriangle(
            0,
            new FieldWalkmeshVertex(-360, 1280, 2670),
            new FieldWalkmeshVertex(-220, 1280, 2670),
            new FieldWalkmeshVertex(-290, 1420, 2670),
            missing,
            missing,
            missing),
        new FieldWalkmeshTriangle(
            1,
            new FieldWalkmeshVertex(-480, 1500, 3187),
            new FieldWalkmeshVertex(-340, 1500, 3187),
            new FieldWalkmeshVertex(-410, 1740, 3290),
            missing,
            missing,
            missing)
    ]);
    var transition = new FieldScriptNavigationTransition(
        223,
        FieldNavigationTransitionKind.Ladder,
        17,
        -292,
        1341,
        2670,
        -414,
        1566,
        3187,
        1,
        "ladder:223:17",
        FieldNavigationInput.Up);
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(mesh.Triangles.ToArray()),
        transitionProvider: fieldId => fieldId == 223 ? [transition] : []);
    var target = new FieldNavigationTarget(
        223,
        FieldNavigationCategory.Story,
        "Reach the swinging bar and press OK at the prompt",
        -369,
        1677,
        3290,
        "story:wall-climb-swing",
        CompletesOnArrival: false);
    var controller = new FieldNavigationController(new FieldNavigationTargetSource([target]), planner);
    var transform = new FieldNavigationControlTransform(-128);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    var entrance = new FieldPositionSnapshot(1, 223, 0, -292, 1341, 2670, 0, 0);

    controller.HandleAction(FieldNavigationAction.NextCategory, entrance, transform);
    controller.HandleAction(FieldNavigationAction.ToggleBeacon, entrance, transform);
    AssertEqual(
        "Climb up.",
        controller.UpdateLiveTracking(
            entrance,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5)?.Speech,
        "the final plate ladder should retain its actual Up input");

    var mounted = new FieldLadderStateSnapshot(
        true,
        true,
        FieldLadderPhase.Climbing,
        FieldNavigationInput.Up,
        new FieldNavigationRouteWaypoint(-414, 1566, 3187),
        1,
        4,
        1);
    AssertEqual(
        "Ladder mounted. Climb up.",
        controller.UpdateLiveTracking(
            entrance,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            ladderState: mounted)?.Speech,
        "mounted guidance should keep the final ladder's Up input");
    AssertEqual(
        "climb up",
        controller.CreateSpokenGuidance(entrance, transform, arrivalDistanceUnits: 5)?.Speech,
        "repeat guidance should preserve the final ladder's Up instruction");

    var landing = entrance with { X = -414, Y = 1566, Z = 3187, TriangleId = 1 };
    AssertEqual(
        "Ladder complete.",
        controller.UpdateLiveTracking(
            landing,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            ladderState: FieldLadderStateSnapshot.NotMounted)?.Speech,
        "the native landing should complete the climb step");
    AssertEqual(
        true,
        controller.BeaconEnabled,
        "missing the timed swinging bar must leave the story route available for another climb attempt");
}

static void AssertFieldNavigationCanActivateWhileAlreadyMountedOnNativeLadder()
{
    var catalog = new FieldScriptNavigationCatalog(FindGameRoot());
    var planner = new FieldWalkmeshRoutePlanner(
        CreateInstalledFieldWalkmeshReader(224),
        transitionProvider: fieldId =>
            fieldId == 224
                ? catalog.ReadField(fieldId).Transitions
                : Array.Empty<FieldScriptNavigationTransition>());
    var destination = new FieldNavigationTarget(
        224,
        FieldNavigationCategory.Story,
        "Finish the wall climb and enter the Shinra exterior",
        -2,
        1542,
        3981,
        "story:wall-climb-finish");
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([destination]),
        planner);
    var midClimb = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        224,
        0,
        162,
        1089,
        2277,
        85,
        128);
    var mounted = new FieldLadderStateSnapshot(
        true,
        true,
        FieldLadderPhase.Climbing,
        FieldNavigationInput.Up,
        new FieldNavigationRouteWaypoint(158, 1171, 2598),
        74,
        4,
        1);
    var transform = new FieldNavigationControlTransform(0);

    var selection = controller.HandleAction(
        FieldNavigationAction.NextCategory,
        midClimb,
        transform,
        ladderState: mounted);
    AssertContains(
        selection?.Speech ?? string.Empty,
        "climb up");

    var activation = controller.HandleAction(
        FieldNavigationAction.ToggleBeacon,
        midClimb,
        transform,
        ladderState: mounted);
    AssertEqual(true, controller.BeaconEnabled, "navigation should activate while Cloud is already on a ladder");
    AssertEqual(
        false,
        activation?.Speech.Contains("Route unavailable", StringComparison.Ordinal) ?? true,
        "mid-ladder activation must plan from the native LADER destination rather than the interpolated model position");

    var mountedSpeech = controller.UpdateLiveTracking(
        midClimb,
        new FieldNavigationInputSnapshot(0, FieldNavigationInput.None),
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        ladderState: mounted);
    AssertEqual(
        null,
        mountedSpeech,
        "activation speech should not be repeated on every mounted-ladder observation");
    AssertEqual(
        "climb up",
        controller.CreateSpokenGuidance(midClimb, transform, arrivalDistanceUnits: 5)?.Speech,
        "the active native ladder should retain its own destination and input");

    var landing = midClimb with
    {
        X = 158,
        Y = 1173,
        Z = 2593,
        TriangleId = 74
    };
    controller.UpdateLiveTracking(
        landing,
        new FieldNavigationInputSnapshot(0, FieldNavigationInput.None),
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        ladderState: FieldLadderStateSnapshot.NotMounted);
    AssertEqual(true, controller.BeaconEnabled, "navigation should remain active after the native ladder completes");
    AssertEqual(
        true,
        controller.CurrentRouteGuidance is not null,
        "navigation should resume the connected route from the native ladder landing");
}

static void AssertFieldNavigationCorrectsRouteAgainstMountedLadder()
{
    var catalog = new FieldScriptNavigationCatalog(FindGameRoot());
    var saveField = catalog.ReadField(124);
    var planner = new FieldWalkmeshRoutePlanner(
        CreateInstalledFieldWalkmeshReader(124),
        transitionProvider: fieldId =>
            fieldId == 124
                ? saveField.Transitions
                : Array.Empty<FieldScriptNavigationTransition>());
    var upperPipingExit = new FieldNavigationTarget(
        124,
        FieldNavigationCategory.Story,
        "Climb back toward the Reactor 1 exit",
        250,
        1195,
        861,
        "story:reactor-return",
        TriggerLine: new FieldNavigationTriggerLine(206, 1195, 856, 294, 1195, 866));
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([upperPipingExit]),
        planner);
    var midDescent = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        124,
        0,
        -220,
        2008,
        533,
        21,
        128);
    var mountedDown = new FieldLadderStateSnapshot(
        true,
        true,
        FieldLadderPhase.Climbing,
        FieldNavigationInput.Down,
        new FieldNavigationRouteWaypoint(-233, 1956, -185),
        27,
        4,
        0);
    var transform = new FieldNavigationControlTransform(0);

    controller.HandleAction(
        FieldNavigationAction.NextCategory,
        midDescent,
        transform,
        ladderState: mountedDown);
    var activation = controller.HandleAction(
        FieldNavigationAction.ToggleBeacon,
        midDescent,
        transform,
        ladderState: mountedDown);

    AssertEqual(true, controller.BeaconEnabled, "the Reactor return route should activate mid-ladder");
    AssertContains(activation?.Speech ?? string.Empty, "climb up");
    AssertEqual(
        false,
        (activation?.Speech ?? string.Empty).Contains("climb down", StringComparison.Ordinal),
        "the route must reverse the active ladder immediately instead of completing the wrong descent");
    AssertEqual(
        "climb up",
        controller.CreateSpokenGuidance(midDescent, transform, arrivalDistanceUnits: 5)?.Speech,
        "repeat guidance should retain the route-owned Up input while native motion still points Down");

    controller.UpdateLiveTracking(
        midDescent,
        new FieldNavigationInputSnapshot(0, FieldNavigationInput.None),
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        ladderState: mountedDown);
    AssertEqual(
        "climb up",
        controller.CreateSpokenGuidance(midDescent, transform, arrivalDistanceUnits: 5)?.Speech,
        "a repeated mounted sample must not switch the active route back to Down");

    var routeAction = controller.CurrentRouteGuidance?.NextAction ??
        throw new InvalidOperationException("the installed Reactor return route should expose its native ladder action");
    AssertEqual(FieldNavigationInput.Up, routeAction.RequiredInput, "the installed return ladder input");
    var upperLanding = midDescent with
    {
        X = routeAction.Destination.X,
        Y = routeAction.Destination.Y,
        Z = routeAction.Destination.Z,
        TriangleId = checked((ushort)routeAction.DestinationTriangle)
    };
    controller.UpdateLiveTracking(
        upperLanding,
        new FieldNavigationInputSnapshot(0, FieldNavigationInput.None),
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        ladderState: FieldLadderStateSnapshot.NotMounted);
    AssertEqual(true, controller.BeaconEnabled, "the route should continue from the upper ladder landing");
    AssertEqual(
        false,
        string.Equals(
            "climb down",
            controller.CreateSpokenGuidance(upperLanding, transform, arrivalDistanceUnits: 5)?.Speech,
            StringComparison.Ordinal),
        "reaching the intended landing must not send Cloud back down the same ladder");
}

