static void AssertInstalledHoneyBeeLobbyRoomsAreReachable()
{
    var catalog = new FieldScriptNavigationCatalog(FindGameRoot());
    var roomTargets = catalog
        .ReadField(218)
        .Exits
        .Select(FieldExitNavigationProfileCatalog.Apply)
        .OrderBy(target => target.StableId, StringComparer.Ordinal)
        .ToArray();
    AssertEqual(4, roomTargets.Length, "Honey Bee Inn lobby native room transition count");

    var memory = new Dictionary<int, byte>();
    const int fieldGlobalObject = 0x02450000;
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, 218);
    WriteUInt32(memory, FieldBoundaryStateReader.AddressFieldGlobalObjectPtr, fieldGlobalObject);
    foreach (var triangle in new[] { 4, 19, 28, 30 })
    {
        var address =
            fieldGlobalObject +
            FieldBoundaryStateReader.BoundaryBitsOffset +
            triangle / 8;
        memory[address] = (byte)(
            memory.GetValueOrDefault(address) |
            (1 << (triangle % 8)));
    }

    byte ReadByte(int address) =>
        memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    var planner = new FieldWalkmeshRoutePlanner(
        CreateInstalledFieldWalkmeshReader(218),
        new FieldBoundaryStateReader(ReadInt32Value, ReadByte, (_, _) => true));
    var lobbyCenter = new FieldPositionSnapshot(1, 218, 0, 1, 279, 16, 25, 0);
    foreach (var room in roomTargets)
    {
        AssertEqual(
            true,
            planner.TryBuildRoute(lobbyCenter, room, out var plan),
            $"{room.StableId} should route to its native activation edge ({planner.LastDiagnostic})");
        AssertEqual(
            true,
            plan.FinalApproachToTargetDistance > 0,
            $"{room.StableId} should use collision-range approach rather than an unreachable line midpoint");
        AssertEqual(
            true,
            plan.FinalApproachToTargetDistance < room.InteractionRadius,
            $"{room.StableId} approach should remain inside the native activation radius");
    }
}

