static void AssertFieldNavigationNpcReaderUsesNativeTalkState()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02400000;
    const int entityId = 3;
    const byte npcModelId = 2;
    var npcEvent = eventTable + npcModelId * FieldNavigationObjectReader.FieldEventDataStride;
    var definitions = new[]
    {
        new FieldScriptNpcDefinition(135, entityId, "BIGGS", [7])
    };

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    short ReadInt16Value(int address) =>
        unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));

    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 4;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + entityId] = npcModelId;
    memory[npcEvent + FieldNavigationObjectReader.VisibilityOffset] = 1;
    memory[npcEvent + FieldNavigationNpcReader.TalkDisabledOffset] = 0;
    WriteUInt32(memory, npcEvent + FieldNavigationObjectReader.PositionXOffset, 4096 * 125);
    WriteUInt32(memory, npcEvent + FieldNavigationObjectReader.PositionYOffset, unchecked((uint)(4096 * -50)));
    WriteUInt32(memory, npcEvent + FieldNavigationObjectReader.PositionZOffset, 4096 * 8);

    var reader = new FieldNavigationNpcReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        (_, _) => ["Biggs", "We made it!"],
        _ => definitions);
    var position = new FieldPositionSnapshot(1, 135, 0, 0, 0, 0, 0, 0);
    var targets = reader.ReadTargets(position);

    AssertEqual(1, targets.Count, "visible Talk-enabled native NPC should be exposed");
    AssertEqual("Biggs", targets[0].Label, "NPC label should come from native field dialogue");
    AssertEqual(125, targets[0].X, "NPC x should come from the live event model");
    AssertEqual(-50, targets[0].Y, "NPC y should come from the live event model");
    AssertEqual("npc:135:3", targets[0].StableId, "NPC stable identity should use its native entity");

    memory[npcEvent + FieldNavigationNpcReader.TalkDisabledOffset] = 1;
    AssertEqual(0, reader.ReadTargets(position).Count, "TLKON-disabled NPC must not be exposed");

    memory[npcEvent + FieldNavigationNpcReader.TalkDisabledOffset] = 0;
    AssertEqual(
        0,
        reader.ReadTargets(position with { ModelIndex = npcModelId }).Count,
        "the active player model must not be exposed as an NPC");
}

static void AssertFieldNavigationNpcReaderUsesNativeInteractionLineProxy()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02404000;
    const int entityId = 4;
    const int lineEntityId = 5;
    const byte npcModelId = 3;
    var npcEvent = eventTable + npcModelId * FieldNavigationObjectReader.FieldEventDataStride;
    var line = new FieldNavigationTriggerLine(60, -152, -153, 45, 54, -153);
    var definitions = new[]
    {
        new FieldScriptNpcDefinition(
            179,
            entityId,
            "oyaji",
            [1, 2],
            InteractionLineEntityId: lineEntityId,
            InteractionLine: line)
    };
    var lineEnabled = true;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    short ReadInt16Value(int address) =>
        unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));

    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 4;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + entityId] = npcModelId;
    memory[npcEvent + FieldNavigationObjectReader.VisibilityOffset] = 1;
    memory[npcEvent + FieldNavigationNpcReader.TalkDisabledOffset] = 1;

    var reader = new FieldNavigationNpcReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        (_, _) => ["Item shopkeeper", "What would you like?"],
        _ => definitions,
        isLineEnabled: id => id == lineEntityId && lineEnabled);
    var position = new FieldPositionSnapshot(1, 179, 0, 0, 0, 0, 0, 0);
    var target = reader.ReadTargets(position).Single();

    AssertEqual("Item shopkeeper", target.Label, "line-proxy NPC should keep its verified visible label");
    AssertEqual(53, target.X, "line-proxy NPC should route to the native counter midpoint x");
    AssertEqual(-49, target.Y, "line-proxy NPC should route to the native counter midpoint y");
    AssertEqual(line, target.TriggerLine, "line-proxy NPC should route to the exact counter segment");
    AssertEqual(lineEntityId, target.TriggerEntityId, "line-proxy NPC should retain the native interactive entity");

    lineEnabled = false;
    AssertEqual(
        0,
        reader.ReadTargets(position).Count,
        "a disabled native counter line must hide its proxy NPC target");
}

