        (ReadByte(address + 3) << 24);
    short ReadInt16Value(int address) =>
        unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));
    IReadOnlyList<string> ReadDialogLines(int _, int dialogId) =>
        dialogId switch
        {
            1 => ["He, HEY! Waitaminit you!!", "You can't just walk outta here."],
            21 => ["Use whatever bed you want.", "Sleep tight, old guy."],
            3 => ["Cloud", "So what."],
            _ => []
        };

    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 4;
    for (var index = 0; index < definitions.Length; index++)
    {
        var modelId = (byte)(index + 1);
        var eventAddress =
            eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride;
        memory[
            FieldNavigationObjectReader.AddressFieldModelIdArray +
            definitions[index].EntityId] = modelId;
        memory[eventAddress + FieldNavigationObjectReader.VisibilityOffset] = 1;
        memory[eventAddress + FieldNavigationNpcReader.TalkDisabledOffset] = 0;
        WriteUInt32(
            memory,
            eventAddress + FieldNavigationObjectReader.PositionXOffset,
            unchecked((uint)(4096 * (100 + index * 50))));
    }

    var reader = new FieldNavigationNpcReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        ReadDialogLines,
        _ => definitions);
    var targets = reader.ReadTargets(
        new FieldPositionSnapshot(1, 148, 0, 0, 0, 0, 0, 0));

    AssertEqual(3, targets.Count, "all three native Sector 7 shop NPCs should be targetable");
    AssertEqual(
        true,
        targets.All(target => target.Category == FieldNavigationCategory.Npcs),
        "shop people belong to the NPC category");
    AssertEqual(
        "Weapon shopkeeper, Boy, Man",
        string.Join(", ", targets.Select(target => target.Label)),
        "Sector 7 shop NPC labels");
    AssertEqual(
        false,
        targets.Any(target => target.Label == "Cloud"),
        "an NPC's Cloud response must not become the NPC label");
}

