    var npcEvent = eventTable + npcModelId * FieldNavigationObjectReader.FieldEventDataStride;
    var definitions = new[] { new FieldScriptNpcDefinition(135, entityId, "PANPI1", [4]) };

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    short ReadInt16Value(int address) => unchecked((short)(ReadByte(address) | (ReadByte(address + 1) << 8)));
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 4;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + entityId] = npcModelId;
    memory[npcEvent + FieldNavigationObjectReader.VisibilityOffset] = 1;
    memory[npcEvent + FieldNavigationNpcReader.TalkDisabledOffset] = 0;
    WriteUInt16(memory, playerEvent + FieldNavigationNpcReader.CollisionRadiusOffset, 48);
    WriteUInt16(memory, npcEvent + FieldNavigationNpcReader.TalkRadiusOffset, 192);
    WriteUInt32(memory, npcEvent + FieldNavigationObjectReader.PositionXOffset, 4096 * 300);

    var reader = new FieldNavigationNpcReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte,
        (_, _) => ["Station Guard", "Hey!"],
        _ => definitions);
    var position = new FieldPositionSnapshot(1, 135, playerModelId, 0, 0, 0, 0, 0);
    var target = reader.ReadTargets(position).Single();

    AssertEqual(240, target.InteractionRadius, "NPC reach should match native talk radius plus player collision radius");
}

static void AssertFieldNavigationCollisionReaderUsesNativeModelClearance()
{
    var memory = new Dictionary<int, byte>();
    const int eventTable = 0x02418000;
    const int targetEntityId = 7;
    const byte playerModelId = 0;
    const byte blockingModelId = 1;
    const byte disabledModelId = 2;
    var playerEvent = eventTable;
    var blockingEvent = eventTable + FieldNavigationObjectReader.FieldEventDataStride;
    var disabledEvent = eventTable + disabledModelId * FieldNavigationObjectReader.FieldEventDataStride;

    byte ReadByte(int address) => memory.GetValueOrDefault(address);
    short ReadInt16Value(int address) => unchecked((short)(
        ReadByte(address) |
        (ReadByte(address + 1) << 8)));
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    WriteUInt32(memory, FieldNavigationObjectReader.AddressFieldEventDataPtr, eventTable);
    memory[FieldPositionReader.AddressFieldNumModels] = 3;
    memory[FieldNavigationObjectReader.AddressFieldModelIdArray + targetEntityId] = blockingModelId;
    WriteUInt16(memory, playerEvent + FieldNavigationNpcReader.CollisionRadiusOffset, 48);
    WriteUInt16(memory, blockingEvent + FieldNavigationNpcReader.CollisionRadiusOffset, 64);
    WriteUInt32(memory, blockingEvent + FieldNavigationObjectReader.PositionXOffset, 200 * 4096);
    WriteUInt16(memory, disabledEvent + FieldNavigationNpcReader.CollisionRadiusOffset, 96);
    WriteUInt32(memory, disabledEvent + FieldNavigationObjectReader.PositionXOffset, 400 * 4096);
    memory[disabledEvent + FieldNavigationDynamicObstacleReader.CollisionDisabledOffset] = 1;

    var reader = new FieldNavigationDynamicObstacleReader(
        ReadInt32Value,
        ReadInt16Value,
        ReadByte);
    var position = new FieldPositionSnapshot(1, 264, playerModelId, 0, 0, 0, 0, 0);
    var obstacles = reader.Read(position, target: null);

    AssertEqual(1, obstacles.Count, "only native collision-enabled non-player models should block navigation");
    AssertEqual(blockingModelId, obstacles[0].ModelIndex, "native blocking model index");
    AssertEqual(56d, obstacles[0].ClearanceRadius, "native collision clearance is half the two model widths");

    var selectedTarget = new FieldNavigationTarget(
        264,
        FieldNavigationCategory.Story,
        "Talk to Tifa",
        200,
        0,
        0,
        "story:tifa",
        TriggerEntityId: targetEntityId);
    AssertEqual(
        0,
        reader.Read(position, selectedTarget).Count,
        "the selected interaction model must not be treated as an obstacle to its own approach");
}

static void AssertFieldScriptNavigationCatalogDecodesInstalledFieldSet()
{
    var gameRoot = FindGameRoot();
    var dataSource = new FlevelDataSource(gameRoot);
    var fieldNames = dataSource.FieldNames;
    var catalog = new FieldScriptNavigationCatalog(gameRoot);
    var mapNames = new FieldMapNameCatalog(catalog, new FlevelFieldTextResolver(gameRoot));
    var failures = new List<string>();
    var installedFieldCount = 0;
    var transitionFieldCount = 0;
    var scriptExitFieldCount = 0;
    var namedFieldCount = 0;

    foreach (var field in fieldNames)
    {
        if (!dataSource.HasField(field.Key))
        {
            continue;
        }

        installedFieldCount++;
        var result = catalog.ReadField(field.Key);
        if (!result.IsUsable)
        {
            failures.Add(result.Diagnostic);
            continue;
        }

        transitionFieldCount += result.Transitions.Count == 0 ? 0 : 1;
        scriptExitFieldCount += result.Exits.Count == 0 ? 0 : 1;
        var mapName = mapNames.Read(field.Key);
        if (!mapName.IsKnownField)
        {
            failures.Add($"field={field.Key} {field.Value}, map-name catalog rejected installed field");
        }

        namedFieldCount += mapName.Names.Count == 0 ? 0 : 1;
    }

    AssertEqual(true, installedFieldCount > 600, "the installed PC field set should contain the full game");
    AssertEqual(0, failures.Count, $"every installed maplist field should decode; failures: {string.Join("; ", failures.Take(5))}");
    AssertEqual(true, transitionFieldCount > 0, "the installed field set should contain native off-mesh transitions");
    AssertEqual(true, scriptExitFieldCount > 0, "the installed field set should contain line-triggered map exits");
    AssertEqual(true, namedFieldCount > 100, "native MPNAM strings should name the full game's logical areas");
}

static void AssertFieldScriptLineStateReaderUsesNativeLinonState()
{
    var memory = new Dictionary<int, byte>();
    const int entityId = 10;
    const byte lineIndex = 3;
    memory[FieldScriptLineStateReader.AddressFieldLineIndexByEntity + entityId] = lineIndex;
    memory[FieldScriptLineStateReader.AddressFieldLineStates + lineIndex * FieldScriptLineStateReader.LineStateStride] = 1;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    var reader = new FieldScriptLineStateReader(ReadByte, (address, length) =>
        address >= FieldScriptLineStateReader.AddressFieldLineIndexByEntity &&
        length > 0);

    AssertEqual(true, reader.IsEnabled(entityId), "a nonzero native LINON state should expose the line transition");
    memory[FieldScriptLineStateReader.AddressFieldLineStates + lineIndex * FieldScriptLineStateReader.LineStateStride] = 0;
    AssertEqual(false, reader.IsEnabled(entityId), "a zero native LINON state should hide the line transition");
    AssertEqual(false, reader.IsEnabled(-1), "an invalid script entity must not expose a line transition");
}

static void AssertFieldScriptNavigationTransitionTrackerBridgesNativeLineFlicker()
{
    var now = new DateTime(2026, 7, 15, 18, 0, 0, DateTimeKind.Utc);
    var enabled = false;
    var tracker = new FieldScriptNavigationTransitionTracker(
        TimeSpan.FromSeconds(3),
        () => now);
    var transition = new FieldScriptNavigationTransition(
        123,
        FieldNavigationTransitionKind.Ladder,
        9,
        100,
        200,
        300,
        400,
        500,
        600,
        28,
        "ladder:123:9:28");

    AssertEqual(
        0,
        tracker.Resolve(123, [transition], _ => enabled).Count,
        "a native transition that has never been live-enabled must remain unavailable");

    enabled = true;
    AssertEqual(1, tracker.Resolve(123, [transition], _ => enabled).Count, "a live native ladder should be available");

    enabled = false;
    now = now.AddSeconds(2);
    AssertEqual(
        1,
        tracker.Resolve(123, [transition], _ => enabled).Count,
        "a recently enabled ladder should survive its own short LINON flicker");

    now = now.AddSeconds(2);
    AssertEqual(
        0,
        tracker.Resolve(123, [transition], _ => enabled).Count,
        "a disabled ladder must expire instead of becoming a static fallback");

    enabled = true;
    tracker.Resolve(123, [transition], _ => enabled);
    enabled = false;
    AssertEqual(
        0,
        tracker.Resolve(124, [transition with { FieldId = 124 }], _ => enabled).Count,
        "transition grace state must reset when the field changes");
}

static void AssertFieldBoundaryStateReaderReadsNativeIdlckBits()
{
    var memory = new Dictionary<int, byte>();
    const int fieldGlobalObject = 0x02400000;
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, 119);
    WriteUInt32(memory, FieldBoundaryStateReader.AddressFieldGlobalObjectPtr, fieldGlobalObject);
    memory[fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset + 1] = 0x10;
    memory[fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset + 3] = 0x80;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldBoundaryStateReader(ReadInt32Value, ReadByte, (_, _) => true);
    var position = new FieldPositionSnapshot(1, 119, 0, 0, 0, 0, 0, 0);
    var result = reader.Read(position, triangleCount: 32);

    AssertEqual(true, result.IsUsable, "native IDLCK boundary state should be readable in a field");
    AssertEqual(true, result.State.IsBoundaryEnabled(12), "IDLCK bit 12 should enable triangle 12's boundary edges");
    AssertEqual(false, result.State.IsBoundaryEnabled(11), "a clear IDLCK bit should leave triangle 11's boundary edges open");
    AssertEqual(true, result.State.IsBoundaryEnabled(31), "the final requested IDLCK boundary bit should be read");
    AssertContains(result.Diagnostic, "activeBoundaries=12,31");

    var invalid = reader.Read(position with { CurrentModule = 0 }, triangleCount: 32);
    AssertEqual(false, invalid.IsUsable, "non-field modules must not expose stale boundary state");
}

static void AssertNativeFieldExitTargetProviderWaitsForStableSnapshotAndKeepsEveryExit()
{
    var memory = new Dictionary<int, byte>();
    const int triggerHeader = 0x02410000;
    WriteFieldGatewayOwnership(memory, 119, triggerHeader);
    InitializeGatewayTable(memory, triggerHeader);

    WriteFieldGateway(memory, triggerHeader, 0, 0, 0, 0, 10, 0, 0, 118);
    WriteFieldGateway(memory, triggerHeader, 1, 100, 0, 0, 110, 0, 0, 136);
    WriteFieldGateway(memory, triggerHeader, 2, 200, 0, 0, 210, 0, 0, 120);

    var now = new DateTime(2026, 7, 15, 0, 0, 0, DateTimeKind.Utc);
    var gatewayReader = new FieldGatewayTargetReader(new DictionaryLegacyAddressSpace(memory));
    var provider = new NativeFieldExitTargetProvider(
        gatewayReader,
        _ =>
        [
            new FieldNavigationTarget(
                119,
                FieldNavigationCategory.Exits,
                "Scripted exit",
                300,
                0,
                0,
                "script-exit:119:10:121",
                DestinationFieldIds: [121])
        ],
        TimeSpan.FromMilliseconds(300),
        TimeSpan.FromMilliseconds(100),
        () => now,
        new FieldExitLabelResolver(
            fieldId => fieldId switch
            {
                118 => FieldMapNameResolution.Known(["Sector 1"]),
                120 => FieldMapNameResolution.Known(["No.1 Reactor"]),
                121 => FieldMapNameResolution.Known(["No.1 Reactor", "No.5 Reactor"]),
                122 => FieldMapNameResolution.Known(["No.1 Reactor", "No.5 Reactor"]),
                136 => FieldMapNameResolution.Known(["Sector 8"]),
                _ => FieldMapNameResolution.Unknown
            },
            () => "No.1 Reactor"));
    var position = new FieldPositionSnapshot(1, 119, 0, 0, 0, 0, 0, 0);
    AssertEqual(0, provider.ReadTargets(position).Count, "new field must wait for native pointers to settle");
    now = now.AddMilliseconds(200);
    AssertEqual(0, provider.ReadTargets(position).Count, "field settle window must reject transitional gateway state");
    now = now.AddMilliseconds(150);
    var exits = provider.ReadTargets(position);

    AssertEqual(4, exits.Count, "every valid native gateway plus enabled script exit should remain visible");
    AssertEqual("Exit to Sector 1, industrial yard and reactor approach", exits[0].Label, "first native gateway should use its destination map name and room descriptor");
    AssertEqual("gateway:119:0:118", exits[0].StableId, "the first reachable gateway should keep its native identity");
    AssertEqual("Exit to Sector 8", exits[1].Label, "second native gateway should use its destination map name");
    AssertEqual("gateway:119:1:136", exits[1].StableId, "second gateway should keep its native identity");
    AssertEqual("Exit to No.1 Reactor, entrance and security rooms", exits[2].Label, "third native gateway should use its destination map name and room descriptor");
    AssertEqual("gateway:119:2:120", exits[2].StableId, "third gateway identity");
    AssertEqual("Exit to No.1 Reactor, elevator room", exits[3].Label, "a line-triggered MAPJUMP should use native destination metadata and room descriptor");
    AssertEqual("script-exit:119:10:121", exits[3].StableId, "script exit identity should remain native and stable");
    AssertContains(provider.LastDiagnostic, "scriptExits=1");
    AssertContains(provider.LastDiagnostic, "visible=4");

    const int nextTriggerHeader = 0x02420000;
    WriteUInt32(memory, FieldNavigationControlReader.AddressFieldTriggersPtr, nextTriggerHeader);
    InitializeGatewayTable(memory, nextTriggerHeader);
    WriteFieldGateway(memory, nextTriggerHeader, 0, 400, 0, 0, 410, 0, 0, 122);
    now = now.AddMilliseconds(50);
    AssertEqual(0, provider.ReadTargets(position).Count, "changed native pointer snapshot must settle before publication");
    now = now.AddMilliseconds(150);
    exits = provider.ReadTargets(position);
    AssertEqual(2, exits.Count, "stable replacement snapshot should publish its gateway and script exit");
    AssertEqual("gateway:119:0:122", exits[0].StableId, "replacement native gateway identity");
}

static void AssertReachableFieldExitTargetProviderHidesBlockedGateways()
{
    var memory = new Dictionary<int, byte>();
    const int fieldGlobalObject = 0x02430000;
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, 900);
    WriteUInt32(memory, FieldBoundaryStateReader.AddressFieldGlobalObjectPtr, fieldGlobalObject);
    memory[fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset] = 0x02;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(CreateThreeTriangleWalkmesh(connected: true).Triangles.ToArray()),
        new FieldBoundaryStateReader(ReadInt32Value, ReadByte, (_, _) => true));
    var nativeTargets = new[]
    {
        new FieldNavigationTarget(900, FieldNavigationCategory.Exits, "Exit 1", 25, 25, 0, "gateway:900:0:899"),
        new FieldNavigationTarget(900, FieldNavigationCategory.Exits, "Exit 2", 150, 25, 0, "gateway:900:1:901")
    };
    var provider = new ReachableFieldExitTargetProvider(_ => nativeTargets, planner);
    var position = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);

    var reachable = provider.ReadTargets(position);
    AssertEqual(1, reachable.Count, "a live boundary should hide only the unreachable exit");
    AssertEqual("gateway:900:0:899", reachable[0].StableId, "the reachable native exit should keep its identity");
    AssertContains(provider.LastDiagnostic, "blocked=Exit 2");

    memory[fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset] = 0;
    reachable = provider.ReadTargets(position);
    AssertEqual(2, reachable.Count, "opening the boundary should expose both native exits");

    AssertEqual(
        0,
        provider.ReadTargets(position with { CurrentModule = 0 }).Count,
        "non-field modules must not expose stale reachable exits");
}

static void AssertFieldNavigationSourceUsesNativeExitProviderWithoutFallbacks()
{
    var source = FieldNavigationTargetSource.CreateOpeningReactorRoute(
        exitTargetProvider: position => position.FieldId == 117
            ?
            [
                new FieldNavigationTarget(117, FieldNavigationCategory.Exits, "Exit 1", 963, 389, 1296),
                new FieldNavigationTarget(117, FieldNavigationCategory.Exits, "Exit 2", 1159, 1717, 1298)
            ]
            : []);
    var position = new FieldPositionSnapshot(1, 117, 0, 0, 0, 0, 0, 0);

    var exits = source.GetTargets(position, FieldNavigationCategory.Exits);
    AssertEqual(2, exits.Count, "native exit provider should expose every current-field gateway");
    AssertEqual("Exit 1", exits[0].Label, "native return gateway should replace the old single static exit");
    AssertEqual("Exit 2", exits[1].Label, "native forward gateway should remain independently selectable");

    exits = source.GetTargets(position with { FieldId = 116 }, FieldNavigationCategory.Exits);
    AssertEqual(0, exits.Count, "an empty native exit result must stay silent instead of falling back to the old hard-coded exit");
}

static void WriteFieldGateway(
    Dictionary<int, byte> memory,
    int triggerHeader,
    int gatewayIndex,
    short x1,
    short y1,
    short z1,
    short x2,
    short y2,
    short z2,
    short destinationFieldId)
{
    var address = triggerHeader + FieldGatewayTargetReader.GatewaysOffset +
        gatewayIndex * FieldGatewayTargetReader.GatewayStride;
    WriteUInt16(memory, address, unchecked((ushort)x1));
    WriteUInt16(memory, address + 2, unchecked((ushort)y1));
    WriteUInt16(memory, address + 4, unchecked((ushort)z1));
    WriteUInt16(memory, address + 6, unchecked((ushort)x2));
    WriteUInt16(memory, address + 8, unchecked((ushort)y2));
    WriteUInt16(memory, address + 10, unchecked((ushort)z2));
    WriteUInt16(memory, address + FieldGatewayTargetReader.DestinationFieldOffset, unchecked((ushort)destinationFieldId));
}

static void WriteFieldGatewayOwnership(
    Dictionary<int, byte> memory,
    ushort fieldId,
    int triggerHeader)
{
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, fieldId);
    WriteUInt32(
        memory,
        FieldNavigationControlReader.AddressFieldTriggersPtr,
        unchecked((uint)triggerHeader));
}

static void InitializeGatewayTable(Dictionary<int, byte> memory, int triggerHeader)
{
    var tableAddress = checked(triggerHeader + FieldGatewayTargetReader.GatewaysOffset);
    var byteCount = checked(FieldGatewayTargetReader.GatewayCount * FieldGatewayTargetReader.GatewayStride);
    for (var offset = 0; offset < byteCount; offset++)
    {
        memory[checked(tableAddress + offset)] = 0;
    }

    for (var gatewayIndex = 0; gatewayIndex < FieldGatewayTargetReader.GatewayCount; gatewayIndex++)
    {
        var gatewayAddress = checked(
            tableAddress + gatewayIndex * FieldGatewayTargetReader.GatewayStride);
        WriteUInt16(
            memory,
            checked(gatewayAddress + FieldGatewayTargetReader.DestinationFieldOffset),
            (ushort)short.MaxValue);
    }
}

static void WriteLiveFieldModel(
    Dictionary<int, byte> memory,
    int eventTable,
    int modelId,
    int x,
    int y,
    int z)
{
    var address = eventTable + modelId * FieldNavigationObjectReader.FieldEventDataStride;
    memory[address + FieldNavigationObjectReader.VisibilityOffset] = 1;
    WriteUInt32(memory, address + FieldNavigationObjectReader.PositionXOffset, unchecked((uint)(x * FieldNavigationObjectReader.ModelPositionFixedPointScale)));
    WriteUInt32(memory, address + FieldNavigationObjectReader.PositionYOffset, unchecked((uint)(y * FieldNavigationObjectReader.ModelPositionFixedPointScale)));
    WriteUInt32(memory, address + FieldNavigationObjectReader.PositionZOffset, unchecked((uint)(z * FieldNavigationObjectReader.ModelPositionFixedPointScale)));
}

static void AssertFieldNavigationTargetsCoverOpeningCategories()
{
    var source = FieldNavigationTargetSource.CreateOpeningReactorRoute(position =>
        position.FieldId == 120
            ? [new FieldNavigationTarget(120, FieldNavigationCategory.Objects, "Phoenix Down", 385, 3125, -272)]
            : []);
    var trainPlatform = new FieldPositionSnapshot(1, 116, 0, 3655, 27432, 300, 25, 128);

    var exits = source.GetTargets(trainPlatform, FieldNavigationCategory.Exits);
    AssertEqual(true, exits.Count > 0, "opening station should have an exit target");
    AssertEqual("Station stairs", exits[0].Label, "opening station exit label");

    var story = source.GetTargets(trainPlatform, FieldNavigationCategory.Story);
    AssertEqual(true, story.Count > 0, "opening station should have a story target");
    AssertContains(story[0].Label, "Avalanche");

    var npcs = source.GetTargets(trainPlatform, FieldNavigationCategory.Npcs);
    AssertEqual(true, npcs.Count > 0, "opening station should have an NPC target");

    var objects = source.GetTargets(trainPlatform, FieldNavigationCategory.Objects);
    AssertEqual(0, objects.Count, "opening station should not invent object targets");

    var reactorWalkway = trainPlatform with { FieldId = 120 };
    objects = source.GetTargets(reactorWalkway, FieldNavigationCategory.Objects);
    AssertEqual(1, objects.Count, "opening reactor object provider should feed the Objects category");
    AssertEqual("Phoenix Down", objects[0].Label, "opening reactor native object label");
}

static void AssertFieldWalkmeshReaderReadsNativePcSection()
{
    var expected = new FieldWalkmeshTriangle(
        0,
        new FieldWalkmeshVertex(-120, 35, 400),
        new FieldWalkmeshVertex(500, -75, 410),
        new FieldWalkmeshVertex(20, 600, 420),
        -1,
        7,
        3);
    var reader = CreateFieldWalkmeshReader(expected);
    var position = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);

    var result = reader.Read(position);

    AssertEqual(true, result.IsUsable, "native PC walkmesh section should parse");
    AssertEqual(1, result.Walkmesh?.Triangles.Count ?? 0, "native PC walkmesh triangle count");
    var actual = result.Walkmesh!.Triangles[0];
    AssertEqual(expected.Vertex0, actual.Vertex0, "walkmesh vertex 0");
    AssertEqual(expected.Vertex1, actual.Vertex1, "walkmesh vertex 1");
