    AssertEqual(expected.Adjacent1, actual.Adjacent1, "walkmesh edge 1 adjacency");
    AssertEqual(expected.Adjacent2, actual.Adjacent2, "walkmesh edge 2 adjacency");
}

static void AssertFieldWalkmeshReaderRetriesTransientInvalidSnapshot()
{
    const int fieldDataBase = 0x02000000;
    const int walkmeshSectionOffset = 0x100;
    var memory = new Dictionary<int, int>
    {
        [FieldWalkmeshReader.AddressFieldDataPtr] = fieldDataBase
    };
    var sectionEntry = fieldDataBase +
        FieldWalkmeshReader.SectionOffsetsHeaderOffset +
        FieldWalkmeshReader.WalkmeshSectionIndex * sizeof(int);
    memory[sectionEntry] = walkmeshSectionOffset;
    memory[sectionEntry + sizeof(int)] =
        walkmeshSectionOffset +
        sizeof(int) +
        sizeof(int) +
        FieldWalkmeshReader.TriangleSize +
        FieldWalkmeshReader.AccessSize;
    var payload = fieldDataBase + walkmeshSectionOffset + sizeof(int);
    memory[payload] = 0;

    var reader = new FieldWalkmeshReader(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => (short)(memory.TryGetValue(address, out var value) ? value : 0));
    var position = new FieldPositionSnapshot(1, 120, 0, -1463, 4275, -282, 60, 0);

    var loading = reader.Read(position);
    AssertEqual(false, loading.IsUsable, "an incomplete field load should fail closed");
    AssertContains(loading.Diagnostic, "triangle count 0");

    memory[payload] = 1;
    var triangleBase = payload + sizeof(int);
    WriteWalkmeshVertex(
        memory,
        triangleBase,
        new FieldWalkmeshVertex(-1600, 4200, -282));
    WriteWalkmeshVertex(
        memory,
        triangleBase + FieldWalkmeshReader.VertexSize,
        new FieldWalkmeshVertex(-1300, 4200, -282));
    WriteWalkmeshVertex(
        memory,
        triangleBase + FieldWalkmeshReader.VertexSize * 2,
        new FieldWalkmeshVertex(-1450, 4500, -282));
    var accessBase = triangleBase + FieldWalkmeshReader.TriangleSize;
    memory[accessBase] = -1;
    memory[accessBase + sizeof(short)] = -1;
    memory[accessBase + sizeof(short) * 2] = -1;

    var settled = reader.Read(position);

    AssertEqual(
        true,
        settled.IsUsable,
        "the same field/data pointer should recover after its walkmesh finishes loading");
    AssertEqual(1, settled.Walkmesh?.Triangles.Count ?? 0, "settled walkmesh triangle count");
}

