static void AssertFieldCorridorLookaheadCreatesObstacleRecoverySideStep()
{
    var mesh = CreateWideVerticalCorridorWalkmesh();
    var position = new FieldPositionSnapshot(1, 900, 0, 600, 20, 0, 0, 0);
    var plan = new FieldNavigationRoutePlan(
        900,
        "900:exit:north",
        [0, 1],
        Array.Empty<FieldNavigationRoutePortal>(),
        new FieldNavigationRouteWaypoint(600, 580, 0),
        1);
    FieldNavigationRouteStep[] steps =
    [
        new(new FieldNavigationRouteWaypoint(600, 580, 0), 0)
    ];
    var blockedHeading = new FieldNavigationRouteHeading(
        true,
        0,
        1,
        "sustained blocked movement",
        IsBlocked: true,
        BlockedSamples: 6,
        RecoveryAttempt: 0);

    var found = FieldNavigationCorridorLookahead.TryResolve(
        mesh,
        resolvedTriangle: 0,
        position,
        plan,
        steps,
        waypointIndex: 0,
        nextAction: null,
        blockedHeading,
        isTriangleBlocked: null,
        out var observation);

    AssertEqual(true, found, "sustained blockage should retain a walkable recovery observation");
    AssertEqual(
        FieldNavigationLookaheadMode.ObstacleRecovery,
        observation.Mode,
        "sustained blockage should replace the long held heading with a side-step");
    AssertEqual(false, observation.ConfirmsRoute, "a local side-step must not advance route progress");
    AssertEqual(
        true,
        Math.Abs(observation.Waypoint.X - position.X) >= 48,
        "the recovery point should move materially to one side of the obstacle");
    AssertEqual(
        true,
        observation.Waypoint.Y > position.Y,
        "the recovery side-step should retain some forward progress");

    var activeRecovery = blockedHeading with
    {
        IsBlocked = false,
        BlockedSamples = 0,
        RecoveryWaypoint = observation.Waypoint
    };
    AssertEqual(
        true,
        FieldNavigationCorridorLookahead.TryResolve(
            mesh,
            resolvedTriangle: 0,
            position,
            plan,
            steps,
            waypointIndex: 0,
            nextAction: null,
            activeRecovery,
            isTriangleBlocked: null,
            out var retained),
        "an active recovery side-step should stay available while the player moves");
    AssertEqual(
        observation.Waypoint,
        retained.Waypoint,
        "the recovery waypoint must not disappear after the first successful movement sample");
    AssertEqual(
        FieldNavigationLookaheadMode.ObstacleRecovery,
        retained.Mode,
        "active recovery mode");
}

static void AssertFieldCorridorLookaheadAvoidsLiveModelCollision()
{
    var mesh = CreateWideVerticalCorridorWalkmesh();
    var position = new FieldPositionSnapshot(1, 900, 0, 600, 150, 0, 0, 0);
    var destination = new FieldNavigationRouteWaypoint(600, 580, 0);
    var plan = new FieldNavigationRoutePlan(
        900,
        "900:object:north",
        [0, 1],
        Array.Empty<FieldNavigationRoutePortal>(),
        destination,
        1);
    FieldNavigationRouteStep[] steps = [new(destination, 0)];
    FieldNavigationDynamicObstacle[] obstacles =
    [
        new(
            ModelIndex: 1,
            X: 600,
            Y: 280,
            Z: 0,
            ClearanceRadius: 80d)
    ];
    AssertEqual(
        true,
        FieldNavigationDynamicObstacleGeometry.IntersectsAny(
            new FieldNavigationRouteWaypoint(position.X, position.Y, position.Z),
            destination,
            obstacles),
        "the test model must obstruct the direct route");
    AssertEqual(
        true,
        FieldNavigationDynamicObstacleGeometry.IntersectsAny(
            new FieldNavigationRouteWaypoint(position.X, position.Y, position.Z),
            new FieldNavigationRouteWaypoint(position.X, position.Y + 96, position.Z),
            obstacles),
        "the model must also block the minimum heading probe");

    var found = FieldNavigationCorridorLookahead.TryResolve(
        mesh,
        resolvedTriangle: 0,
        position,
        plan,
        steps,
        waypointIndex: 0,
        nextAction: null,
        new FieldNavigationRouteHeading(true, 0, 1, "toward live model"),
        isTriangleBlocked: null,
        dynamicObstacles: obstacles,
        out var observation);

    AssertEqual(true, found, "a route obstructed by a live field model should remain navigable");
    AssertEqual(
        FieldNavigationLookaheadMode.ObstacleRecovery,
        observation.Mode,
        "a live model on the direct line should produce a native-clearance side-step before Cloud stalls");
    AssertContains(observation.Diagnostic, "dynamic-model-collision");
    AssertEqual(
        false,
        FieldNavigationDynamicObstacleGeometry.IntersectsAny(
            new FieldNavigationRouteWaypoint(position.X, position.Y, position.Z),
            observation.Waypoint,
            obstacles),
        "the announced recovery segment must clear the live model collision cylinder");
    AssertEqual(
        false,
        FieldNavigationDynamicObstacleGeometry.IntersectsAny(
            observation.Waypoint,
            destination,
            obstacles),
        "the recovery point must reconnect to the route without cutting through the model");
}

