static void AssertInstalledShinraStairwellAdvancesPastMissedSwitchbackCorner()
{
    const int fieldId = 229;
    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(fieldId));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        fieldId,
        FieldNavigationCategory.Exits,
        "Exit to Shinra Bldg. Stairs",
        175,
        398,
        2169,
        "regression:shinra-stairs-top");
    var start = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        fieldId,
        0,
        -26,
        96,
        -10,
        161,
        64);
    FieldPositionSnapshot[] capturedAscent =
    [
        start with { X = 16, Z = 10, TriangleId = 164 },
        start with { X = 56, Z = 37, TriangleId = 164 },
        start with { X = 96, Z = 64, TriangleId = 164 },
        start with { X = 129, Z = 86, TriangleId = 164 },
        start with { X = 169, Z = 113, TriangleId = 164 },
        start with { X = 209, Z = 139, TriangleId = 163 },
        start with { X = 249, Z = 166, TriangleId = 163 },
        start with { X = 282, Z = 188, TriangleId = 163 },
        start with { X = 329, Z = 220, TriangleId = 163 },
        start with { X = 366, Z = 225, TriangleId = 110 },
        start with { X = 414, Z = 225, TriangleId = 182 },
        start with { X = 422, Z = 225, TriangleId = 182 },
        start with { X = 438, Z = 225, TriangleId = 182 },
        start with { X = 454, Z = 225, TriangleId = 183 },
        start with { X = 454, Y = 128, Z = 225, TriangleId = 183, Direction = 128 },
        start with { X = 454, Y = 184, Z = 225, TriangleId = 183, Direction = 128 },
        start with { X = 454, Y = 224, Z = 225, TriangleId = 62, Direction = 128 },
        start with { X = 454, Y = 272, Z = 225, TriangleId = 62, Direction = 128 },
        start with { X = 454, Y = 320, Z = 225, TriangleId = 168, Direction = 128 },
        start with { X = 454, Y = 368, Z = 225, TriangleId = 168, Direction = 128 },
        start with { X = 445, Y = 405, Z = 225, TriangleId = 169, Direction = 136 },
        start with { X = 440, Y = 445, Z = 225, TriangleId = 167, Direction = 128 },
        start with { X = 432, Y = 445, Z = 225, TriangleId = 169, Direction = 192 },
        start with { X = 392, Y = 445, Z = 225, TriangleId = 170, Direction = 192 },
        start with { X = 344, Y = 445, Z = 225, TriangleId = 171, Direction = 192 },
        start with { X = 302, Y = 445, Z = 245, TriangleId = 172, Direction = 192 }
    ];

    AssertEqual(
        true,
        tracker.TryStart(start, target, out _),
        $"the captured intermediate Shinra stair route should start ({planner.LastDiagnostic})");
    var initialProbe = tracker.CurrentProbeSnapshot ??
        throw new InvalidOperationException("Expected a Shinra stair route probe.");
    var missedCorner = initialProbe.StableWaypoints.Single(step =>
        step.MustReach &&
        step.Waypoint == new FieldNavigationRouteWaypoint(342, 342, 235));

    var previous = start;
    FieldNavigationRouteGuidance guidance = default;
    foreach (var current in capturedAscent)
    {
        var deltaX = current.X - previous.X;
        var deltaY = current.Y - previous.Y;
        var movement = new FieldNavigationMovementObservation(
            true,
            deltaX != 0 || deltaY != 0,
            FieldNavigationInput.Up,
            deltaX,
            deltaY,
            Math.Sqrt(deltaX * (double)deltaX + deltaY * (double)deltaY),
            "captured Shinra switchback ascent");
        AssertEqual(
            true,
            tracker.TryUpdate(current, target, movement, out guidance),
            $"the captured Shinra stair route should update at {current.X},{current.Y},{current.Z}");
        AssertEqual(
            false,
            guidance.Replanned,
            $"the native switchback ascent should not replan at {current.X},{current.Y},{current.Z}");
        previous = current;
    }

    var probe = tracker.CurrentProbeSnapshot ??
        throw new InvalidOperationException("Expected an updated Shinra stair route probe.");
    AssertEqual(
        true,
        probe.PortalIndex > missedCorner.RequiredPortalIndex,
        "the native triangle path must show that Cloud has crossed beyond the mandatory lower corner");
    AssertEqual(
        false,
        probe.StableWaypoints[probe.WaypointIndex].Waypoint == missedCorner.Waypoint,
        $"native portal progress past a missed switchback corner must advance guidance instead of pointing back down the stairs " +
        $"(portal={probe.PortalIndex}, required={missedCorner.RequiredPortalIndex}, guidance={guidance.Waypoint})");
}

static void AssertInstalledShinraStairwellTreatsCapturedAscentAsForwardProgress()
{
    const int fieldId = 230;
    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(fieldId));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        fieldId,
        FieldNavigationCategory.Exits,
        "Exit to Shinra Bldg. 59f",
        175,
        403,
        3069,
        "regression:shinra-emergency-stairs-top");
    var start = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        fieldId,
        0,
        -102,
        187,
        2722,
        79,
        0);
    FieldPositionSnapshot[] capturedAscent =
    [
        start with { Y = 139, TriangleId = 80 },
        start with { Y = 99, TriangleId = 80 },
        start with { Y = 67, TriangleId = 80 },
        start with { X = -72, Y = 60, Z = 2721, TriangleId = 81 },
        start with { X = -24, Y = 60, Z = 2721, TriangleId = 82 },
        start with { X = 19, Y = 60, Z = 2741, TriangleId = 47 },
        start with { X = 53, Y = 60, Z = 2762, TriangleId = 47 },
        start with { X = 94, Y = 60, Z = 2787, TriangleId = 47 },
        start with { X = 135, Y = 60, Z = 2812, TriangleId = 47 },
        start with { X = 176, Y = 60, Z = 2836, TriangleId = 47 },
        start with { X = 211, Y = 60, Z = 2858, TriangleId = 47 },
        start with { X = 252, Y = 60, Z = 2883, TriangleId = 47 },
        start with { X = 292, Y = 60, Z = 2908, TriangleId = 46 },
        start with { X = 333, Y = 60, Z = 2934, TriangleId = 46 }
    ];

    var progressSink = new RecordingFieldNavigationProgressSink();
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        planner,
        routeProgressSink: progressSink);
    var transform = new FieldNavigationControlTransform(-128);
    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, transform);
    AssertEqual(true, controller.BeaconEnabled, "the captured upper Shinra stair route should activate");
    AssertEqual(0, progressSink.Percent, "the captured upper Shinra stair route should start at zero percent");
    var previousPercent = controller.CurrentRouteProgressPercent;
    foreach (var current in capturedAscent)
    {
        controller.UpdateLiveTracking(
            current,
            new FieldNavigationInputSnapshot(
                FieldNavigationInputReader.UpMask,
                FieldNavigationInput.Up),
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5);
        var guidance = controller.CurrentRouteGuidance ??
            throw new InvalidOperationException(
                $"Expected upper Shinra stair guidance at {current.X},{current.Y},{current.Z}.");
        AssertEqual(
            false,
            guidance.Replanned,
            $"the native upper-stair ascent should not replan at {current.X},{current.Y},{current.Z}");
        var currentPercent = controller.CurrentRouteProgressPercent;
        AssertEqual(
            true,
            currentPercent >= previousPercent,
            $"forward native stair traversal must not lower route progress at " +
            $"{current.X},{current.Y},{current.Z}; previous={previousPercent}, current={currentPercent}, " +
            $"remaining={guidance.ProgressRemainingDistance:0}, waypoint={guidance.Waypoint}");
        AssertEqual(
            currentPercent,
            progressSink.Percent,
            "the native progress sink should receive the corridor-projected stair value");
        previousPercent = currentPercent;
    }
    AssertEqual(
        true,
        controller.CurrentRouteProgressPercent >= 40,
        $"the captured forward ramp should make material route progress, got " +
        $"{controller.CurrentRouteProgressPercent} percent");
    var forwardPercent = controller.CurrentRouteProgressPercent;
    var oneStepBack = capturedAscent[^2];
    controller.UpdateLiveTracking(
        oneStepBack,
        new FieldNavigationInputSnapshot(
            FieldNavigationInputReader.LeftMask,
            FieldNavigationInput.Left),
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5);
    AssertEqual(
        true,
        controller.CurrentRouteProgressPercent < forwardPercent,
        $"a real backward step on the same ramp should lower route progress; " +
        $"forward={forwardPercent}, backward={controller.CurrentRouteProgressPercent}");
    AssertEqual(
        controller.CurrentRouteProgressPercent,
        progressSink.Percent,
        "the native progress sink should receive the projected backtracking value");

    var rampPosition = capturedAscent.Single(position => position.X == 94);
    AssertEqual(
        true,
        tracker.TryStart(start, target, out _),
        "the guidance-direction replay should start from the captured upper stair");
    var previousPosition = start;
    FieldNavigationRouteGuidance rampGuidance = default;
    foreach (var current in capturedAscent.TakeWhile(position => position.X <= rampPosition.X))
    {
        var deltaX = current.X - previousPosition.X;
        var deltaY = current.Y - previousPosition.Y;
        AssertEqual(
            true,
            tracker.TryUpdate(
                current,
                target,
                new FieldNavigationMovementObservation(
                    true,
                    deltaX != 0 || deltaY != 0,
                    FieldNavigationInput.Right,
                    deltaX,
                    deltaY,
                    Math.Sqrt(deltaX * (double)deltaX + deltaY * (double)deltaY),
                    "captured upper Shinra stair guidance"),
                out rampGuidance),
            $"the upper-stair guidance replay should update at {current.X},{current.Y},{current.Z}");
        previousPosition = current;
    }

    AssertEqual(
        true,
        rampGuidance.Waypoint.X > rampPosition.X,
        $"forward stair guidance must not point back to a missed funnel endpoint; " +
        $"position={rampPosition.X},{rampPosition.Y},{rampPosition.Z}, waypoint={rampGuidance.Waypoint}");
}

static void AssertInstalledShinraLobbyDiagonalGuidanceKeepsForwardProgress()
{
    const int fieldId = 234;
    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(fieldId));
    var target = new FieldNavigationTarget(
        fieldId,
        FieldNavigationCategory.Exits,
        "Exit to Shinra Bldg. 2f. Lobby",
        983,
        775,
        247,
        "gateway:234:2:235",
        CompletesOnArrival: true);
    var start = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        fieldId,
        0,
        1427,
        -70,
        -10,
        19,
        128);
    var progressSink = new RecordingFieldNavigationProgressSink();
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        planner,
        spokenDistanceUnitsPerCount: 60,
        routeProgressSink: progressSink);
    var transform = new FieldNavigationControlTransform(-64);
    var diagonalInput = new FieldNavigationInputSnapshot(
        FieldNavigationInputReader.UpMask |
        FieldNavigationInputReader.RightMask |
        FieldNavigationInputReader.RunMask,
        FieldNavigationInput.UpRight);

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, transform);
    AssertEqual(true, controller.BeaconEnabled, "captured Shinra lobby route should activate");
    AssertEqual(
        "up-right 16",
        controller.CreateSpokenGuidance(start, transform, arrivalDistanceUnits: 5)?.Speech,
        "captured Shinra lobby route should keep Cloud inside the native diagonal corridor");

    FieldPositionSnapshot[] safeCorridor =
    [
        start with { X = 1394, Y = 54, Z = 0, TriangleId = 33 },
        start with { X = 1345, Y = 177, Z = 0, TriangleId = 31 },
        start with { X = 1257, Y = 150, Z = 0, TriangleId = 30 },
        start with { X = 1179, Y = 270, Z = 0, TriangleId = 29 },
        start with { X = 1136, Y = 389, Z = 23, TriangleId = 142 },
        start with { X = 1225, Y = 425, Z = 47, TriangleId = 143 },
        start with { X = 1127, Y = 474, Z = 72, TriangleId = 144 },
        start with { X = 1184, Y = 564, Z = 73, TriangleId = 145 },
        start with { X = 1046, Y = 630, Z = 133, TriangleId = 146 },
        start with { X = 1064, Y = 755, Z = 190, TriangleId = 147 },
        start with { X = 930, Y = 760, Z = 248, TriangleId = 148 }
    ];

    var previousPercent = controller.CurrentRouteProgressPercent;
    foreach (var current in safeCorridor)
    {
        controller.UpdateLiveTracking(
            current,
            diagonalInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5);
        var guidance = controller.CurrentRouteGuidance ??
            throw new InvalidOperationException(
                $"Expected Shinra lobby guidance at {current.X},{current.Y},{current.Z}.");
        AssertEqual(
            false,
            guidance.Replanned,
            $"following the native field 234 corridor must not rebuild at triangle {current.TriangleId}");
        var currentPercent = controller.CurrentRouteProgressPercent;
        AssertEqual(
            true,
            currentPercent >= previousPercent,
            $"forward field 234 corridor progress must not fall at triangle {current.TriangleId}; " +
            $"previous={previousPercent}, current={currentPercent}, " +
            $"remaining={guidance.ProgressRemainingDistance:0}");
        AssertEqual(
            currentPercent,
            progressSink.Percent,
            "native progress sink should match the captured corridor projection");
        previousPercent = currentPercent;
    }

    AssertEqual(
        true,
        controller.CurrentRouteProgressPercent >= 90,
        $"captured Shinra lobby corridor should reach material completion, got " +
        $"{controller.CurrentRouteProgressPercent} percent");
}

