static void AssertFieldWalkmeshRoutePlannerBuildsOrderedPlan()
{
    var mesh = CreateThreeTriangleWalkmesh(connected: true);
    var planner = new FieldWalkmeshRoutePlanner(CreateFieldWalkmeshReader(mesh.Triangles.ToArray()));
    var position = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Far exit",
        150,
        25,
        0,
        "exit:far");

    var found = planner.TryBuildRoute(position, target, out var plan);

    AssertEqual(true, found, "native route plan should be available");
    AssertEqual(3, plan.TrianglePath.Count, "route should preserve ordered triangles");
    AssertEqual(2, plan.Portals.Count, "route should expose one portal per triangle transition");
    AssertEqual(0, plan.TrianglePath[0], "route should start on the live player triangle");
    AssertEqual(2, plan.TrianglePath[^1], "route should end on the target triangle");
    AssertEqual(1, plan.Portals[0].ToTriangle, "first portal should lead to the second triangle");
    AssertEqual(2, plan.Portals[1].ToTriangle, "second portal should lead to the target triangle");
    AssertEqual("900:exit:far", plan.TargetId, "route should retain the stable target identity");

    var disconnectedPlanner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(CreateThreeTriangleWalkmesh(connected: false).Triangles.ToArray()));
    AssertEqual(
        false,
        disconnectedPlanner.TryBuildRoute(position, target, out _),
        "disconnected targets must not produce a route plan");
}

static void AssertFieldWalkmeshRoutePlannerUsesInteractionRangeForDisconnectedNpcCenter()
{
    var mesh = CreateThreeTriangleWalkmesh(connected: false);
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(mesh.Triangles.ToArray()));
    var position = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    var exactTarget = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Npcs,
        "Shopkeeper",
        150,
        25,
        0,
        "npc:shopkeeper");

    AssertEqual(
        false,
        planner.TryBuildRoute(position, exactTarget, out _),
        "a disconnected NPC center remains unroutable without native interaction range");

    var interactiveTarget = exactTarget with { InteractionRadius = 80 };
    AssertEqual(
        true,
        planner.TryBuildRoute(position, interactiveTarget, out var plan),
        "a reachable point inside native talk range should route around a disconnected model center");
    AssertEqual(0, plan.TargetTriangle, "interaction route should remain on the reachable player component");
    AssertEqual(
        true,
        plan.FinalApproachToTargetDistance < interactiveTarget.InteractionRadius,
        "interaction approach must be strictly inside native talk range");
    AssertEqual(
        false,
        plan.FinalApproach == new FieldNavigationRouteWaypoint(
            interactiveTarget.X,
            interactiveTarget.Y,
            interactiveTarget.Z),
        "interaction fallback must not retain the disconnected model center");
}

static void AssertFieldWalkmeshRoutePlannerUsesInteractionRangeForBlockedNpcCenter()
{
    var memory = new Dictionary<int, byte>();
    const int fieldGlobalObject = 0x02421000;
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, 900);
    WriteUInt32(memory, FieldBoundaryStateReader.AddressFieldGlobalObjectPtr, fieldGlobalObject);
    memory[fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset] = 0x04;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var mesh = CreateThreeTriangleWalkmesh(connected: true);
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(mesh.Triangles.ToArray()),
        new FieldBoundaryStateReader(ReadInt32Value, ReadByte, (_, _) => true));
    var position = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Npcs,
        "Tutorial man",
        150,
        25,
        0,
        "npc:tutorial",
        InteractionRadius: 80);

    AssertEqual(
        true,
        planner.TryBuildRoute(position, target, out var plan),
        "an unblocked talk point should remain reachable when the NPC center triangle is blocked");
    AssertEqual(
        false,
        plan.TargetTriangle == 2,
        "blocked center fallback should end on an unblocked reachable triangle");
    AssertEqual(
        true,
        plan.FinalApproachToTargetDistance < target.InteractionRadius,
        "blocked-center approach must remain strictly inside native talk range");
    AssertContains(planner.LastDiagnostic, "interaction approach");
}

