static void AssertFieldWalkmeshRoutePlannerRejectsLiveBoundaryCrossings()
{
    var memory = new Dictionary<int, byte>();
    const int fieldGlobalObject = 0x02420000;
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, 900);
    WriteUInt32(memory, FieldBoundaryStateReader.AddressFieldGlobalObjectPtr, fieldGlobalObject);
    memory[fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset] = 0x02;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var mesh = CreateThreeTriangleWalkmesh(connected: true);
    var boundaryReader = new FieldBoundaryStateReader(ReadInt32Value, ReadByte, (_, _) => true);
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(mesh.Triangles.ToArray()),
        boundaryReader);
    var position = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    var target = new FieldNavigationTarget(900, FieldNavigationCategory.Exits, "Locked exit", 150, 25, 0);

    AssertEqual(
        false,
        planner.TryBuildRoute(position, target, out _),
        "an active IDLCK triangle must block routes across its native boundary edges");
    AssertContains(planner.LastDiagnostic, "active boundary triangles=1");

    memory[fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset] = 0;
    AssertEqual(true, planner.TryBuildRoute(position, target, out _), "clearing IDLCK should restore the interior route");
}

static void AssertInstalledReactorEscapeRouteRejectsLockedSecurityDoors()
{
    var memory = new Dictionary<int, byte>();
    const int fieldGlobalObject = 0x02420000;
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, 120);
    WriteUInt32(memory, FieldBoundaryStateReader.AddressFieldGlobalObjectPtr, fieldGlobalObject);
    var activeBoundaries = new[] { 2, 8, 10, 37, 51, 52, 53, 61 };
    foreach (var triangle in activeBoundaries)
    {
        var address = fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset + (triangle >> 3);
        memory[address] = (byte)(memory.GetValueOrDefault(address) | (1 << (triangle & 7)));
    }

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var planner = new FieldWalkmeshRoutePlanner(
        CreateInstalledFieldWalkmeshReader(120),
        new FieldBoundaryStateReader(ReadInt32Value, ReadByte, (_, _) => true));
    var position = new FieldPositionSnapshot(1, 120, 0, -1250, 3200, -283, 68, 0);
    var escapeExit = new FieldNavigationTarget(
        120,
        FieldNavigationCategory.Exits,
        "Exit 2",
        -1494,
        4516,
        -272,
        "gateway:120:1:119");

    AssertEqual(
        false,
        planner.TryBuildRoute(position, escapeExit, out _),
        "the exact failed nmkin_1 escape state must not route through its locked security doors");

    foreach (var triangle in activeBoundaries)
    {
        var address = fieldGlobalObject + FieldBoundaryStateReader.BoundaryBitsOffset + (triangle >> 3);
        memory[address] = (byte)(memory.GetValueOrDefault(address) & ~(1 << (triangle & 7)));
    }

    AssertEqual(
        true,
        planner.TryBuildRoute(position, escapeExit, out var openPlan),
        "the same native exit should become reachable after the security boundaries open");
    AssertEqual(true, openPlan.TrianglePath.Count > 1, "the open reactor escape should produce a real walkmesh route");
}

