    AssertEqual(25, plan.Portals[0].Midpoint.X, "the first GPS waypoint should be the native ladder trigger line");
    AssertEqual(25, plan.Portals[0].Midpoint.Y, "the ladder waypoint should retain its native line midpoint");
    AssertEqual(new FieldNavigationRouteWaypoint(525, 25, 500), plan.Portals[0].TransitionExit, "the route portal should retain the native ladder landing");
    AssertEqual(true, plan.Portals[0].RequiresAction, "the route portal should retain the native action gate");
}

