static void AssertInstalledReactor1PipingAndSaveRoomRoutesUseNativeLadders()
{
    var root = FindGameRoot();
    var catalog = new FieldScriptNavigationCatalog(root);

    var upperField = catalog.ReadField(123);
    var upperPlanner = new FieldWalkmeshRoutePlanner(
        CreateInstalledFieldWalkmeshReader(123),
        transitionProvider: fieldId => fieldId == 123
            ? upperField.Transitions
            : Array.Empty<FieldScriptNavigationTransition>());
    var upperStart = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        123,
        0,
        -140,
        1921,
        2212,
        40,
        0);
    var lowerRoomExit = new FieldNavigationTarget(
        123,
        FieldNavigationCategory.Exits,
        "No. 1 Reactor lower piping and save room",
        298,
        1265,
        855,
        "gateway:123:1:124",
        TriggerLine: new FieldNavigationTriggerLine(260, 1264, 852, 337, 1266, 858));
    AssertEqual(
        true,
        upperPlanner.TryBuildRoute(upperStart, lowerRoomExit, out var upperPlan),
        $"field 123 should route through both downward native ladders: {upperPlanner.LastDiagnostic}");
    var upperLadders = upperPlan.Portals
        .Where(portal => portal.TransitionKind == FieldNavigationTransitionKind.Ladder)
        .ToArray();
    AssertEqual(2, upperLadders.Length, "field 123 route should traverse both ladders");
    AssertEqual(
        true,
        upperLadders.All(portal => portal.RequiredInput == FieldNavigationInput.Down),
        "field 123 descent should consistently direct the player down");

    var saveField = catalog.ReadField(124);
    var savePlanner = new FieldWalkmeshRoutePlanner(
        CreateInstalledFieldWalkmeshReader(124),
        transitionProvider: fieldId => fieldId == 124
            ? saveField.Transitions
            : Array.Empty<FieldScriptNavigationTransition>());
    var saveRoomStart = new FieldPositionSnapshot(
        FieldPositionReader.FieldModule,
        124,
        0,
        250,
        1195,
        861,
        0,
        0);
    var reactorCoreExit = new FieldNavigationTarget(
        124,
        FieldNavigationCategory.Exits,
        "No. 1 Reactor core",
        -111,
        -195,
        -180,
        "gateway:124:1:125",
        TriggerLine: new FieldNavigationTriggerLine(-52, -148, -180, -171, -242, -181));
    AssertEqual(
        true,
        savePlanner.TryBuildRoute(saveRoomStart, reactorCoreExit, out var savePlan),
        $"field 124 should route from the save point to the core exit: {savePlanner.LastDiagnostic}");
    var saveLadders = savePlan.Portals
        .Where(portal => portal.TransitionKind == FieldNavigationTransitionKind.Ladder)
        .ToArray();
    AssertEqual(1, saveLadders.Length, "field 124 route should traverse its native ladder");
    AssertEqual(FieldNavigationInput.Down, saveLadders[0].RequiredInput, "field 124 core route should direct the player down");

    var returnTarget = new FieldNavigationTarget(
        124,
        FieldNavigationCategory.Exits,
        "No. 1 Reactor upper piping and ladder room",
        250,
        1195,
        861,
        "gateway:124:0:123",
        TriggerLine: new FieldNavigationTriggerLine(206, 1195, 856, 294, 1195, 866));
    var coreSide = saveRoomStart with { X = -246, Y = 1945, Z = -185, TriangleId = 28 };
    AssertEqual(
        true,
        savePlanner.TryBuildRoute(coreSide, returnTarget, out var returnPlan),
        $"field 124 should retain the upward escape route: {savePlanner.LastDiagnostic}");
    AssertEqual(
        true,
        returnPlan.Portals.Any(portal =>
            portal.TransitionKind == FieldNavigationTransitionKind.Ladder &&
            portal.RequiredInput == FieldNavigationInput.Up),
        "field 124 return route should tell the player to climb up");
}

static void AssertFieldNavigationControllerAnnouncesNativeLadderAtEntry()
{
    const short missing = -1;
    var mesh = new FieldWalkmesh(
    [
        new FieldWalkmeshTriangle(
            0,
            new FieldWalkmeshVertex(0, 0, 0),
            new FieldWalkmeshVertex(100, 0, 0),
            new FieldWalkmeshVertex(0, 100, 0),
            missing,
            missing,
            missing),
        new FieldWalkmeshTriangle(
            1,
            new FieldWalkmeshVertex(500, 0, 500),
            new FieldWalkmeshVertex(600, 0, 500),
            new FieldWalkmeshVertex(500, 100, 500),
            missing,
            missing,
            missing)
    ]);
    var transition = new FieldScriptNavigationTransition(
        900,
        FieldNavigationTransitionKind.Ladder,
        7,
        25,
        25,
        0,
        525,
        25,
        500,
        1,
        "ladder:900:7:3",
        FieldNavigationInput.Down,
        RequiresAction: true);
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(mesh.Triangles.ToArray()),
        transitionProvider: fieldId => fieldId == 900 ? [transition] : []);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Upper exit",
        525,
        25,
        500,
        "exit:upper");
    var controller = new FieldNavigationController(new FieldNavigationTargetSource([target]), planner);
    var start = new FieldPositionSnapshot(1, 900, 0, 90, 5, 0, 0, 0);
    var ladderEntry = start with { X = 25, Y = 25 };
    var transform = new FieldNavigationControlTransform(-128);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, transform);
    AssertNull(
        controller.UpdateLiveTracking(start, noInput, transform, isSuppressed: false, arrivalDistanceUnits: 5),
        "ladder action speech must wait until the player reaches the native trigger");
    AssertEqual(
        "Ladder. Press action to mount, then climb down.",
        controller.UpdateLiveTracking(
            ladderEntry,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5)?.Speech,
        "an action-gated native LADER transition should stop at its entry");

    var mounted = new FieldLadderStateSnapshot(
        true,
        true,
        FieldLadderPhase.Climbing,
        FieldNavigationInput.Down,
        new FieldNavigationRouteWaypoint(525, 25, 500),
        1,
        4,
        1);
    AssertEqual(
        "Ladder mounted. Climb down.",
        controller.UpdateLiveTracking(
            ladderEntry,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            ladderState: mounted)?.Speech,
        "the native ladder movement mode should announce the correct climb input");
    AssertNull(
        controller.CreateBeaconCue(ladderEntry, transform, arrivalDistanceUnits: 5),
        "GPS beacon must pause while the player is mounted on a ladder");
    AssertEqual(
        "climb down",
        controller.CreateSpokenGuidance(ladderEntry, transform, arrivalDistanceUnits: 5)?.Speech,
        "repeat guidance should use the native mounted ladder direction");
    AssertNull(
        controller.UpdateLiveTracking(
            ladderEntry,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            ladderState: mounted),
        "mounted ladder speech should be announced only once");

    var landing = ladderEntry with { X = 525, Y = 25, Z = 500, TriangleId = 1 };
    AssertEqual(
        "Ladder complete.",
        controller.UpdateLiveTracking(
            landing,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            ladderState: FieldLadderStateSnapshot.NotMounted)?.Speech,
        "navigation should resume from the native ladder landing");
}

static void AssertFieldNavigationControllerRepeatsLadderMountPromptAndGuidesBackAfterDrift()
{
    var fixture = CreateRouteAwareLadderControllerFixture();
    var now = new DateTime(2026, 8, 5, 18, 0, 0, DateTimeKind.Utc);

    fixture.Controller.HandleAction(
        FieldNavigationAction.ToggleBeacon,
        fixture.Start,
        fixture.Transform);
    AssertEqual(
        "Ladder. Press action to mount, then climb right.",
        fixture.Controller.UpdateLiveTracking(
            fixture.Entrance,
            fixture.NoInput,
            fixture.Transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            observedAt: now)?.Speech,
        "the route should announce the mount instruction on first reaching the ladder entrance");
    AssertNull(
        fixture.Controller.UpdateLiveTracking(
            fixture.Entrance,
            fixture.NoInput,
            fixture.Transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            observedAt: now.AddMilliseconds(699)),
        "the ladder mount prompt should honor its repeat interval");
    AssertEqual(
        "Ladder. Press action to mount, then climb right.",
        fixture.Controller.UpdateLiveTracking(
            fixture.Entrance,
            fixture.NoInput,
            fixture.Transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            observedAt: now.AddMilliseconds(700))?.Speech,
        "the ladder mount prompt should repeat continuously while the player remains at the entrance");

    var drifted = fixture.Start with { X = -7 };
    AssertNull(
        fixture.Controller.UpdateLiveTracking(
            drifted,
            fixture.NoInput,
            fixture.Transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            observedAt: now.AddMilliseconds(1000)),
        "leaving the entrance should stop the mount prompt");
    AssertEqual(
        "right 1",
        fixture.Controller.CreateSpokenGuidance(
            drifted,
            fixture.Transform,
            arrivalDistanceUnits: 5)?.Speech,
        "ordinary live route guidance should take the player back to the ladder entrance");
    AssertEqual(
        "Ladder. Press action to mount, then climb right.",
        fixture.Controller.UpdateLiveTracking(
            fixture.Entrance,
            fixture.NoInput,
            fixture.Transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            observedAt: now.AddMilliseconds(1300))?.Speech,
        "returning to the ladder entrance should restart the mount prompt immediately");
}

static void AssertFieldNavigationControllerRejectsMountedBounceAfterLanding()
{
    var fixture = CreateRouteAwareLadderControllerFixture();
    var now = new DateTime(2026, 8, 5, 18, 10, 0, DateTimeKind.Utc);

    fixture.Controller.HandleAction(
        FieldNavigationAction.ToggleBeacon,
        fixture.Start,
        fixture.Transform);
    fixture.Controller.UpdateLiveTracking(
        fixture.Entrance,
        fixture.NoInput,
        fixture.Transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now);
    fixture.Controller.UpdateLiveTracking(
        fixture.Entrance,
        fixture.NoInput,
        fixture.Transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        ladderState: fixture.Mounted,
        observedAt: now.AddSeconds(1));
    AssertEqual(
        "Ladder complete.",
        fixture.Controller.UpdateLiveTracking(
            fixture.Landing,
            fixture.NoInput,
            fixture.Transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            ladderState: FieldLadderStateSnapshot.NotMounted,
            observedAt: now.AddSeconds(2))?.Speech,
        "the first coherent dismount at the expected landing should complete the route action");

    var staleReverseBounce = fixture.Mounted with
    {
        RequiredInput = FieldNavigationInput.Left,
        Target = new FieldNavigationRouteWaypoint(50, 50, 0),
        TargetTriangle = 0
    };
    AssertNull(
        fixture.Controller.UpdateLiveTracking(
            fixture.Landing,
            fixture.NoInput,
            fixture.Transform,
            isSuppressed: false,
            arrivalDistanceUnits: 5,
            ladderState: staleReverseBounce,
            observedAt: now.AddMilliseconds(2100)),
        "a stale native mounted bounce at the completed landing must not remount the route ladder");
    AssertNull(
        fixture.Controller.CurrentRouteGuidance?.NextAction,
        "a stale mounted bounce must not restore the completed ladder action");
    AssertEqual(
        "right 1",
        fixture.Controller.CreateSpokenGuidance(
            fixture.Landing,
            fixture.Transform,
            arrivalDistanceUnits: 5)?.Speech,
        "post-landing guidance should continue toward the destination instead of repeating the climb direction");
}

