static void AssertFieldNavigationRouteTrackerCompletesNativeAction()
{
    var planner = new ConfigurableCorridorRoutePlanner(includeAction: true);
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Upper exit",
        150,
        50,
        0,
        "exit:action-completion");
    var start = new FieldPositionSnapshot(1, 900, 0, 10, 50, 0, 0, 0);

    AssertEqual(true, tracker.TryStart(start, target, out var started), "action route should start");
    var action = started.NextAction
        ?? throw new InvalidOperationException("Expected a native route action.");
    var landing = start with
    {
        X = action.Destination.X,
        Y = action.Destination.Y,
        Z = action.Destination.Z,
        TriangleId = checked((ushort)action.DestinationTriangle)
    };

    AssertEqual(
        true,
        tracker.TryCompleteAction(action, landing, out var completed),
        "a confirmed forward landing should advance the route action explicitly");
    AssertEqual(action.PortalIndex + 1, completed.PortalIndex, "completed action portal progress");
    AssertNull(completed.NextAction, "the completed action must not remain the next route action");
    AssertEqual(
        new FieldNavigationRouteWaypoint(target.X, target.Y, target.Z),
        completed.Waypoint,
        "guidance should continue from the ladder landing toward the destination");
}

