static void AssertFieldNavigationRouteTrackerKeepsMonotonicPortalProgress()
{
    var mesh = CreateThreeTriangleWalkmesh(connected: true);
    var planner = new FieldWalkmeshRoutePlanner(CreateFieldWalkmeshReader(mesh.Triangles.ToArray()));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Far exit",
        150,
        25,
        0,
        "exit:far");
    var triangle0 = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    var triangle1 = triangle0 with { X = 75, Y = 75, TriangleId = 1 };
    var triangle2 = triangle0 with { X = 125, Y = 25, TriangleId = 2 };
    var edgeJitterBackToTriangle0 = triangle0 with { X = 49, Y = 49, TriangleId = 0 };

    AssertEqual(true, tracker.TryStart(triangle0, target, out var first), "route tracker should start");
    AssertEqual(0, first.PortalIndex, "first portal should be active");

    AssertEqual(true, tracker.TryUpdate(triangle1, target, out var second), "route tracker should advance");
    AssertEqual(1, second.PortalIndex, "entering the second triangle should advance portal progress");

    AssertEqual(true, tracker.TryUpdate(edgeJitterBackToTriangle0, target, out var jitter), "edge jitter should retain guidance");
    AssertEqual(1, jitter.PortalIndex, "edge jitter must not move portal progress backward");
    AssertEqual(second.Waypoint, jitter.Waypoint, "edge jitter must not reselect the crossed portal");

    AssertEqual(true, tracker.TryUpdate(triangle2, target, out var final), "target triangle should retain guidance");
    AssertEqual(2, final.PortalIndex, "entering the target triangle should complete all portals");
    AssertEqual(150, final.Waypoint.X, "final guidance should use target x");
    AssertEqual(25, final.Waypoint.Y, "final guidance should use target y");
    AssertEqual(true, final.RemainingDistance < jitter.RemainingDistance, "remaining route distance should decrease toward the target");
}

