static void AssertFieldNavigationRouteTrackerRetainsClearParallelLane()
{
    var planner = new ParallelLaneRoutePlanner();
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Far platform exit",
        150,
        150,
        0,
        "exit:parallel");
    var lowerLane = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    var upperLane = lowerLane with { X = 30, Y = 70, TriangleId = 2 };
    var movement = new FieldNavigationMovementObservation(
        true,
        true,
        FieldNavigationInput.Up,
        upperLane.X - lowerLane.X,
        upperLane.Y - lowerLane.Y,
        Math.Sqrt(
            Math.Pow(upperLane.X - lowerLane.X, 2) +
            Math.Pow(upperLane.Y - lowerLane.Y, 2)),
        "moving through clear parallel lane");

    AssertEqual(true, tracker.TryStart(lowerLane, target, out var started), "parallel-lane route should start");
    AssertEqual(
        new FieldNavigationRouteWaypoint(50, 0, 0),
        started.Waypoint,
        "the initial corridor should use its lower-lane approach");

    AssertEqual(
        true,
        tracker.TryUpdate(upperLane, target, movement, out var retained),
        "the valid upper lane should remain routable");
    AssertEqual(false, retained.Replanned, "a clear neighboring lane must retain the committed route");
    AssertEqual(1, planner.BuildCount, "a clear neighboring lane must not rebuild the full route");
    AssertContains(retained.Diagnostic, "lookahead=heading-held");
    var guidanceX = retained.Waypoint.X - upperLane.X;
    var guidanceY = retained.Waypoint.Y - upperLane.Y;
    AssertEqual(
        true,
        guidanceX * movement.DeltaX + guidanceY * movement.DeltaY > 0,
        "clear-lane guidance must never point behind the observed movement");
}

static void AssertFieldNavigationRouteTrackerKeepsObstacleRecoveryUntilClear()
{
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(CreateWideVerticalCorridorWalkmesh().Triangles.ToArray()));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "North exit",
        600,
        580,
        0,
        "exit:blocked-north");
    var position = new FieldPositionSnapshot(1, 900, 0, 600, 20, 0, 0, 0);
    var blocked = new FieldNavigationMovementObservation(
        true,
        false,
        FieldNavigationInput.Up,
        0,
        0,
        0,
        "directional input was blocked or stationary");
    var observedAt = new DateTime(2026, 7, 27, 12, 0, 0, DateTimeKind.Utc);

    AssertEqual(true, tracker.TryStart(position, target, out _), "blocked-route test should start");
    FieldNavigationRouteGuidance recovery = default;
    for (var sample = 1; sample <= 8; sample++)
    {
        AssertEqual(
            true,
            tracker.TryUpdate(
                position,
                target,
                blocked,
                observedAt.AddMilliseconds(sample * 200),
                out var guidance),
            $"blocked sample {sample} should retain guidance");
        if (sample < 8)
        {
            AssertEqual(
                false,
                guidance.Diagnostic.Contains("lookahead=obstacle-recovery", StringComparison.Ordinal),
                "a brief stationary sample must not create a needless side-step");
        }
        else
        {
            recovery = guidance;
        }
    }

    AssertContains(recovery.Diagnostic, "lookahead=obstacle-recovery");
    AssertEqual(
        true,
        Math.Abs(recovery.Waypoint.X - position.X) >= 48,
        "sustained blockage should produce a lateral recovery waypoint");

    var towardRecovery = position with
    {
        X = position.X + Math.Sign(recovery.Waypoint.X - position.X) * 20,
        Y = position.Y + 8
    };
    var movement = new FieldNavigationMovementObservation(
        true,
        true,
        recovery.Waypoint.X > position.X
            ? FieldNavigationInput.UpRight
            : FieldNavigationInput.UpLeft,
        towardRecovery.X - position.X,
        towardRecovery.Y - position.Y,
        Math.Sqrt(
            Math.Pow(towardRecovery.X - position.X, 2) +
            Math.Pow(towardRecovery.Y - position.Y, 2)),
        "moving around obstacle");
    AssertEqual(
        true,
        tracker.TryUpdate(
            towardRecovery,
            target,
            movement,
            observedAt.AddMilliseconds(1800),
            out var retained),
        "movement toward the side-step should retain the route");
    AssertEqual(
        recovery.Waypoint,
        retained.Waypoint,
        "the side-step should stay committed until Cloud clears the obstacle");
    AssertContains(retained.Diagnostic, "lookahead=obstacle-recovery");

    var cleared = towardRecovery with
    {
        X = recovery.Waypoint.X,
        Y = recovery.Waypoint.Y
    };
    var clearMovement = movement with
    {
        DeltaX = cleared.X - towardRecovery.X,
        DeltaY = cleared.Y - towardRecovery.Y,
        Distance = Math.Sqrt(
            Math.Pow(cleared.X - towardRecovery.X, 2) +
            Math.Pow(cleared.Y - towardRecovery.Y, 2))
    };
    AssertEqual(
        true,
        tracker.TryUpdate(
            cleared,
            target,
            clearMovement,
            observedAt.AddMilliseconds(1900),
            out var resumed),
        "reaching the recovery waypoint should resume the original route");
    AssertContains(resumed.Diagnostic, "lookahead=heading-held");
    AssertEqual(
        cleared.X,
        resumed.Waypoint.X,
        "resumed guidance should continue the original heading instead of extending the side-step");
    AssertEqual(true, resumed.Waypoint.Y > cleared.Y, "resumed route should continue north");
}

static void AssertFieldNavigationRouteTrackerDoesNotDiscardShortRecoveryBeforeMovement()
{
    var planner = new ShortRecoveryRoutePlanner();
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "North exit",
        0,
        200,
        0,
        "exit:short-recovery");
    var position = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);
    var blocked = new FieldNavigationMovementObservation(
        true,
        false,
        FieldNavigationInput.Up,
        0,
        0,
        0,
        "directional input was blocked or stationary");
    var observedAt = new DateTime(2026, 8, 12, 14, 0, 0, DateTimeKind.Utc);

    AssertEqual(true, tracker.TryStart(position, target, out _), "short-recovery route should start");
    FieldNavigationRouteGuidance recovery = default;
    for (var sample = 1; sample <= 8; sample++)
    {
        AssertEqual(
            true,
            tracker.TryUpdate(
                position,
                target,
                blocked,
                observedAt.AddMilliseconds(sample * 200),
                out recovery),
            $"short blocked sample {sample} should retain guidance");
    }

    AssertContains(recovery.Diagnostic, "lookahead=obstacle-recovery");
    AssertEqual(
        true,
        Math.Sqrt(
            Math.Pow(recovery.Waypoint.X - position.X, 2) +
            Math.Pow(recovery.Waypoint.Y - position.Y, 2)) < 36d,
        "the regression fixture must reproduce the live sub-36-unit recovery point");

    AssertEqual(
        true,
        tracker.TryUpdate(
            position,
            target,
            blocked,
            observedAt.AddMilliseconds(1800),
            out var retained),
        "a stationary sample must retain the short recovery waypoint");
    AssertEqual(
        recovery.Waypoint,
        retained.Waypoint,
        "a short recovery point must not be treated as reached before Cloud actually moves");
    AssertContains(retained.Diagnostic, "lookahead=obstacle-recovery");

    var cleared = position with
    {
        X = recovery.Waypoint.X - 2,
        Y = recovery.Waypoint.Y - 2
    };
    var clearingMovement = new FieldNavigationMovementObservation(
        true,
        true,
        FieldNavigationInput.UpRight,
        cleared.X - position.X,
        cleared.Y - position.Y,
        Math.Sqrt(Math.Pow(cleared.X - position.X, 2) + Math.Pow(cleared.Y - position.Y, 2)),
        "moved through short recovery point");
    AssertEqual(
        true,
        tracker.TryUpdate(
            cleared,
            target,
            clearingMovement,
            observedAt.AddMilliseconds(1900),
            out var rebuilt),
        "clearing the short recovery point should retain navigation");
    AssertEqual(false, rebuilt.Replanned, "clearing an obstacle should retain the shared route identity");
    AssertContains(rebuilt.Diagnostic, "lookahead=heading-held");
    AssertEqual(1, planner.BuildCount, "manual and automatic guidance should keep the same recovered route");
}

static void AssertFieldNavigationRouteTrackerRetainsBlockedEvidenceAcrossDirectionChanges()
{
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(CreateWideVerticalCorridorWalkmesh().Triangles.ToArray()));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "North exit",
        600,
        580,
        0,
        "exit:alternating-blocked-north");
    var position = new FieldPositionSnapshot(1, 900, 0, 600, 20, 0, 0, 0);
    var observedAt = new DateTime(2026, 7, 28, 17, 16, 42, DateTimeKind.Utc);
    var samples = new[]
    {
        (200, FieldNavigationInput.Up),
        (300, FieldNavigationInput.None),
        (400, FieldNavigationInput.UpRight),
        (500, FieldNavigationInput.Up),
        (600, FieldNavigationInput.UpLeft),
        (700, FieldNavigationInput.Left),
        (800, FieldNavigationInput.Up),
        (900, FieldNavigationInput.Down),
        (1000, FieldNavigationInput.Up),
        (1100, FieldNavigationInput.UpRight),
        (1200, FieldNavigationInput.Up)
    };

    AssertEqual(
        true,
        tracker.TryStart(position, target, out _),
        "alternating blocked-input route should start");
    FieldNavigationRouteGuidance guidance = default;
    foreach (var (milliseconds, input) in samples)
    {
        var directional = input is >= FieldNavigationInput.Up and <= FieldNavigationInput.UpLeft;
        var movement = new FieldNavigationMovementObservation(
            true,
            false,
            input,
            0,
            0,
            0,
            directional
                ? "directional input was blocked or stationary"
                : "brief neutral sample between blocked attempts");
        AssertEqual(
            true,
            tracker.TryUpdate(
                position,
                target,
                movement,
                observedAt.AddMilliseconds(milliseconds),
                out guidance),
            $"alternating blocked sample at {milliseconds}ms should retain guidance");
    }

    AssertContains(guidance.Diagnostic, "lookahead=obstacle-recovery");
    AssertEqual(
        true,
        Math.Abs(guidance.Waypoint.X - position.X) >= 48,
        "changing or briefly releasing the direction while stuck must still activate a lateral recovery");
}

static void AssertFieldNavigationRouteTrackerTreatsQuantizedWalkingAsProgress()
{
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(CreateWideVerticalCorridorWalkmesh().Triangles.ToArray()));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "North exit",
        600,
        580,
        0,
        "exit:quantized-walk");
    var position = new FieldPositionSnapshot(1, 900, 0, 600, 20, 0, 0, 0);
    var quantizedWalking = new FieldNavigationMovementObservation(
        true,
        false,
        FieldNavigationInput.Up,
        0,
        2,
        2,
        "directional input advanced less than the per-sample movement threshold");
    var observedAt = new DateTime(2026, 7, 27, 12, 0, 0, DateTimeKind.Utc);

    AssertEqual(true, tracker.TryStart(position, target, out _), "quantized-walk route should start");
    for (var sample = 1; sample <= 12; sample++)
    {
        position = position with { Y = position.Y + 2 };
        AssertEqual(
            true,
            tracker.TryUpdate(
                position,
                target,
                quantizedWalking,
                observedAt.AddMilliseconds(sample * 50),
                out var guidance),
            $"quantized walking sample {sample} should retain guidance");
        AssertEqual(
            false,
            guidance.Diagnostic.Contains("lookahead=obstacle-recovery", StringComparison.Ordinal),
            "small coordinate updates must accumulate as real walking progress instead of looking blocked");
    }
}

static void AssertFieldNavigationRouteTrackerAbandonsRecoveryWhenRouteProgressResumes()
{
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(CreateWideVerticalCorridorWalkmesh().Triangles.ToArray()));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "North exit",
        600,
        580,
        0,
        "exit:stale-recovery");
    var position = new FieldPositionSnapshot(1, 900, 0, 600, 20, 0, 0, 0);
    var blocked = new FieldNavigationMovementObservation(
        true,
        false,
        FieldNavigationInput.Up,
        0,
        0,
        0,
        "directional input was blocked or stationary");
    var observedAt = new DateTime(2026, 7, 27, 12, 0, 0, DateTimeKind.Utc);

    AssertEqual(true, tracker.TryStart(position, target, out _), "stale-recovery route should start");
    FieldNavigationRouteGuidance recovery = default;
    for (var sample = 1; sample <= 8; sample++)
    {
        AssertEqual(
            true,
            tracker.TryUpdate(
                position,
                target,
                blocked,
                observedAt.AddMilliseconds(sample * 200),
                out recovery),
            $"blocked sample {sample} should retain guidance");
    }

    AssertContains(recovery.Diagnostic, "lookahead=obstacle-recovery");
    var resumedPosition = position with { Y = position.Y + 64 };
    var resumedMovement = new FieldNavigationMovementObservation(
        true,
        true,
        FieldNavigationInput.Up,
        0,
        64,
        64,
        "normal route progress resumed");
    AssertEqual(
        true,
        tracker.TryUpdate(
            resumedPosition,
            target,
            resumedMovement,
            observedAt.AddMilliseconds(1800),
            out var resumed),
        "normal route progress should retain the route");
    AssertEqual(
        false,
        resumed.Diagnostic.Contains("lookahead=obstacle-recovery", StringComparison.Ordinal),
        "a recovery waypoint must not stay latched after Cloud resumes the original route");
    AssertEqual(true, resumed.Waypoint.Y > resumedPosition.Y, "resumed guidance should point along the route");
}

static void AssertFieldNavigationRouteTrackerKeepsRouteHeadingAcrossWideLateralDrift()
{
    var mesh = CreateWideVerticalCorridorWalkmesh();
    var planner = new FieldWalkmeshRoutePlanner(
        CreateFieldWalkmeshReader(mesh.Triangles.ToArray()));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "North exit",
        600,
        580,
        0,
        "exit:wide-north");
    var start = new FieldPositionSnapshot(1, 900, 0, 600, 20, 0, 0, 0);
    var driftedRight = start with { X = 1600, Y = 68, TriangleId = 1 };
    var lateralMovement = new FieldNavigationMovementObservation(
        true,
        true,
        FieldNavigationInput.UpRight,
        driftedRight.X - start.X,
        driftedRight.Y - start.Y,
        Math.Sqrt(
            Math.Pow(driftedRight.X - start.X, 2) +
            Math.Pow(driftedRight.Y - start.Y, 2)),
        "wide-corridor lateral drift");

    AssertEqual(true, tracker.TryStart(start, target, out _), "wide-corridor route should start");
    AssertEqual(
        true,
        tracker.TryUpdate(driftedRight, target, lateralMovement, out var movingGuidance),
        "wide-corridor lateral movement should retain guidance");
    AssertEqual(
        driftedRight.X,
        movingGuidance.Waypoint.X,
        $"open-corridor guidance must preserve the committed north heading instead of recentering laterally ({movingGuidance.Diagnostic})");
    AssertEqual(
        true,
        movingGuidance.Waypoint.Y > driftedRight.Y,
        "open-corridor guidance should continue north");
    AssertContains(movingGuidance.Diagnostic, "lookahead=heading-held");

    AssertEqual(
        true,
        tracker.TryUpdate(driftedRight, target, movement: default, out var pausedGuidance),
        "pausing after lateral drift should retain guidance");
    AssertEqual(
        movingGuidance.Waypoint.X,
        pausedGuidance.Waypoint.X,
        "an idle sample must not turn harmless lateral offset into a correction");
    AssertEqual(
        true,
        pausedGuidance.Waypoint.Y > driftedRight.Y,
        "an idle sample should retain the same general north heading");
}

static void AssertInstalledWallMarketConnectedRunNeverPointsBackToCrossedCorner()
{
    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(195));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        195,
        FieldNavigationCategory.Story,
        "Continue north toward Corneo Hall",
        -135,
        2496,
        0,
        "story:195:-1:191:Continue north toward Corneo Hall",
        CompletesOnArrival: true,
        TriggerLine: new FieldNavigationTriggerLine(-251, 2500, 0, -19, 2492, 0));
    var start = new FieldPositionSnapshot(1, 195, 0, 204, -365, -10, 174, 128);
    (int X, int Y, int Triangle)[] capturedRun =
    [
        (204, -317, 171),
        (204, -269, 171),
        (204, -253, 171),
        (204, -237, 171),
        (204, -189, 165),
        (204, -141, 165),
        (204, -93, 166),
        (204, -29, 167),
        (204, 19, 168),
        (210, 67, 191),
        (213, 114, 192),
        (231, 159, 197),
        (250, 203, 197),
        (265, 248, 198),
        (268, 296, 203),
        (268, 360, 203),
        (268, 408, 204),
        (268, 456, 204),
        (268, 504, 205),
        (268, 552, 205),
        (271, 616, 210),
        (271, 664, 17),
        (271, 712, 17),
        (271, 760, 85),
        (271, 808, 89),
        (271, 856, 89),
        (271, 872, 89),
        (271, 888, 89),
        (271, 936, 89),
        (271, 984, 89),
        (271, 1032, 89),
        (271, 1080, 89),
        (271, 1128, 89),
        (271, 1176, 55),
        (271, 1240, 55),
        (271, 1256, 55),
        (271, 1320, 54),
        (271, 1368, 54),
        (271, 1416, 48),
        (271, 1464, 47),
        (271, 1512, 47),
        (271, 1560, 47),
        (271, 1624, 47)
    ];

    AssertEqual(true, tracker.TryStart(start, target, out _), "Wall Market story route should start");
    var previous = start;
    FieldNavigationRouteGuidance atCapturedFailure = default;
    foreach (var sample in capturedRun)
    {
        var destination = previous with
        {
            X = sample.X,
            Y = sample.Y,
            TriangleId = (ushort)sample.Triangle
        };
        var segmentStart = previous;
        var sampleCount = Math.Max(
            1,
            (int)Math.Ceiling(
                Math.Max(
                    Math.Abs(destination.X - segmentStart.X),
                    Math.Abs(destination.Y - segmentStart.Y)) /
                16d));
        for (var sampleIndex = 1; sampleIndex <= sampleCount; sampleIndex++)
        {
            var position = destination with
            {
                X = (int)Math.Round(
                    segmentStart.X +
                    (destination.X - segmentStart.X) * sampleIndex / (double)sampleCount),
                Y = (int)Math.Round(
                    segmentStart.Y +
                    (destination.Y - segmentStart.Y) * sampleIndex / (double)sampleCount)
            };
            var dx = position.X - previous.X;
            var dy = position.Y - previous.Y;
            var movement = new FieldNavigationMovementObservation(
                true,
                dx != 0 || dy != 0,
                FieldNavigationInput.Up,
                dx,
                dy,
                Math.Sqrt(dx * (double)dx + dy * (double)dy),
                "captured Wall Market north run");
            AssertEqual(
                true,
                tracker.TryUpdate(position, target, movement, out var guidance),
                $"captured Wall Market position {position.X},{position.Y} should retain the route");
            if (position.Y == 1624)
            {
                atCapturedFailure = guidance;
            }

            previous = position;
        }
    }

    AssertEqual(
        true,
        atCapturedFailure.Waypoint.Y > previous.Y,
        $"a continuous north run must not point back to a crossed funnel corner ({atCapturedFailure.Diagnostic})");
}

