static void AssertInstalledPillarEntranceRecoversFromMissedRamp()
{
    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(156));
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        156,
        FieldNavigationCategory.Story,
        "Enter the Sector 7 pillar and begin climbing",
        354,
        1253,
        139,
        "story:156:exit:158",
        TriggerLine: new FieldNavigationTriggerLine(
            319,
            1265,
            130,
            388,
            1240,
            148));
    var start = new FieldPositionSnapshot(1, 156, 0, 357, 1123, -10, 268, 160);
    FieldPositionSnapshot[] observedPositions =
    [
        start with { X = 342, Y = 1116, TriangleId = 268 },
        start with { X = 306, Y = 1085, TriangleId = 268 },
        start with { X = 283, Y = 1062, TriangleId = 267 },
        start with { X = 243, Y = 1042, TriangleId = 264 },
        start with { X = 211, Y = 1042, TriangleId = 264 },
        start with { X = 177, Y = 1076, TriangleId = 272 },
        start with { X = 131, Y = 1121, TriangleId = 272 }
    ];

    AssertEqual(
        true,
        tracker.TryStart(start, target, out _),
        "the installed support-pillar entrance route should start");
    var previous = start;
    FieldNavigationRouteGuidance guidance = default;
    foreach (var observed in observedPositions)
    {
        var deltaX = observed.X - previous.X;
        var deltaY = observed.Y - previous.Y;
        var distance = Math.Sqrt(deltaX * (double)deltaX + deltaY * (double)deltaY);
        AssertEqual(
            true,
            tracker.TryUpdate(
                observed,
                target,
                new FieldNavigationMovementObservation(
                    true,
                    distance > 0d,
                    FieldNavigationInput.UpLeft,
                    deltaX,
                    deltaY,
                    distance,
                    "captured support-pillar entrance movement"),
                out guidance),
            "the captured support-pillar detour should remain routable");
        previous = observed;
    }

    var probe = tracker.CurrentProbeSnapshot;
    var stableSteps = probe is null
        ? "none"
        : string.Join(
            ";",
            probe.StableWaypoints.Select(
                step =>
                    $"{step.Waypoint.X},{step.Waypoint.Y},{step.Waypoint.Z}" +
                    $"/portal={step.RequiredPortalIndex}/mustReach={step.MustReach}"));
