        true,
        guidance.Waypoint.X is >= 174 and <= 270 &&
        guidance.Waypoint.Y is >= 1036 and <= 1140 &&
        guidance.Waypoint.Z <= 20,
        $"missing the narrow ramp must guide back to its local entrance instead of across the save point " +
        $"({guidance.Diagnostic}; stableSteps={stableSteps})");
}

static void AssertInstalledSector6DeadEndBranchRetainsReachableCorner()
