        "script-exit:191:7:192,193",
        CompletesOnArrival: false);
    var routeStart = new FieldPositionSnapshot(1, 191, 0, -413, -207, -6, 279, 120);
    var deadEndBranch = new FieldPositionSnapshot(1, 191, 0, -361, 367, -6, 291, 32);

    AssertEqual(
        true,
        tracker.TryStart(routeStart, target, out _),
        "Sector 6 route should start on the lower corridor");
