    var observedAt = new DateTime(2026, 7, 28, 17, 16, 42, DateTimeKind.Utc);
    var attemptedInputs = new[]
    {
        FieldNavigationInput.Up,
        FieldNavigationInput.None,
        FieldNavigationInput.UpRight,
        FieldNavigationInput.Up,
        FieldNavigationInput.UpLeft,
        FieldNavigationInput.Left,
        FieldNavigationInput.Up,
        FieldNavigationInput.Right,
        FieldNavigationInput.Up,
        FieldNavigationInput.Down,
        FieldNavigationInput.UpRight,
        FieldNavigationInput.Up
    };

    AssertEqual(
        true,
        tracker.TryStart(stalled, target, out _),
        $"captured playground route should start ({planner.LastDiagnostic})");
    FieldNavigationRouteGuidance guidance = default;
