        (6, -789, 113, 233),
        (-28, -789, 136, 200),
        (-73, -792, 144, 202),
        (-137, -792, 144, 204),
        (-185, -792, 144, 205),
        (-233, -792, 144, 225)
    ];
    var observedAt = new DateTime(2026, 7, 28, 17, 13, 0, DateTimeKind.Utc);

