}

static void AssertInstalledSector6PostCollapseRoutePreservesLayerTransition()
{
    var planner = new FieldWalkmeshRoutePlanner(CreateInstalledFieldWalkmeshReader(191));
    var start = new FieldPositionSnapshot(1, 191, 0, 1162, 269, 12, 209, 0);
    var target = new FieldNavigationTarget(
        191,
        FieldNavigationCategory.Exits,
        "Exit to Sector 5 Slum",
        -906,
        -775,
        0,
        "regression:sector6-post-collapse-return",
        CompletesOnArrival: false);

    AssertEqual(
        true,
        planner.TryBuildRoute(start, target, out var plan),
        $"the captured post-collapse Sector 6 route should build ({planner.LastDiagnostic})");
    var steps = plan.StableWaypointsOverride ??
        FieldWalkmeshPathfinder.BuildStableWaypoints(
            start.X,
            start.Y,
            start.Z,
            plan.Portals,
            plan.FinalApproach);
    var firstElevatedStepIndex = -1;
    for (var index = 0; index < steps.Count; index++)
    {
        if (steps[index].Waypoint.Z >= 96)
        {
            firstElevatedStepIndex = index;
            break;
        }
    }

    var stepDump = string.Join(
        ";",
        steps.Select(
            step =>
                $"{step.Waypoint.X},{step.Waypoint.Y},{step.Waypoint.Z}" +
                $"/portal={step.RequiredPortalIndex}/mustReach={step.MustReach}"));
    var portalDump = string.Join(
        ";",
        plan.Portals.Select(
            (portal, index) =>
                $"{index}:{portal.FromTriangle}>{portal.ToTriangle}" +
                $"/mid={portal.Midpoint.X},{portal.Midpoint.Y},{portal.Midpoint.Z}"));

    AssertEqual(
        true,
        firstElevatedStepIndex > 0 &&
        steps[firstElevatedStepIndex - 1].MustReach &&
        steps[firstElevatedStepIndex - 1].Waypoint.Z <= 32,
        "the post-collapse route must retain a mandatory ground-layer entry before its first elevated continuation " +
        $"(steps={stepDump}; portals={portalDump})");
}

static void AssertFieldNavigationRouteTrackerDoesNotTreatLookaheadAsRouteProgress()
{
