    var start = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    var pastFirstWaypoint = start with { X = 90, Y = 10 };

    AssertEqual(true, tracker.TryStart(start, target, out var first), "running waypoint route should start");
    AssertEqual(
        new FieldNavigationRouteWaypoint(50, 0, 0),
        first.Waypoint,
        "running waypoint route should begin at the safe bend");

    AssertEqual(true, tracker.TryUpdate(pastFirstWaypoint, target, out var advanced), "running overshoot should retain guidance");
    AssertEqual(
        false,
        advanced.Waypoint == first.Waypoint,
        "crossing within the waypoint radius between samples must advance instead of pointing backward");
    AssertEqual(1, planner.BuildCount, "running past a waypoint should advance the committed route without replanning");
}

