static void AssertFieldNavigationRouteTrackerWaitsForSustainedOffRouteDeviation()
{
    var planner = new FixedPortalRoutePlanner();
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Bent exit",
        150,
        150,
        0,
        "exit:bent");
    var start = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);
    AssertEqual(true, tracker.TryStart(start, target, out _), "off-route test should start");
    for (var sample = 1; sample <= 11; sample++)
    {
        var y = start.Y + sample * 16;
        var outsideRoute = start with { Y = y, TriangleId = 99 };
        AssertEqual(true, tracker.TryUpdate(outsideRoute, target, out var retained), "short physical deviation should retain guidance");
        AssertEqual(false, retained.Replanned, $"off-route movement at y={y} must not replan before twelve sustained samples");
        AssertEqual(1, planner.BuildCount, $"off-route movement at y={y} must retain the original route");
    }

    var threshold = start with { Y = start.Y + 12 * 16, TriangleId = 99 };
    AssertEqual(true, tracker.TryUpdate(threshold, target, out var replanned), "sustained deviation should remain routable");
    AssertEqual(true, replanned.Replanned, "twelve genuine off-route movement samples should permit one replan");
    AssertEqual(2, planner.BuildCount, "physical deviation should rebuild the route once");
}

