static void AssertFieldNavigationRouteTrackerClearLaneResetsDeviation()
{
    var planner = new ConfigurableCorridorRoutePlanner
    {
        ConfirmedMode = FieldNavigationLookaheadMode.VisibleStep
    };
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Far exit",
        100,
        0,
        0,
        "exit:clear-reset");
    var start = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);

    AssertEqual(true, tracker.TryStart(start, target, out _), "clear-lane reset route should start");
    planner.ConfirmsRoute = false;
    var firstDeviation = start with { Y = 50, TriangleId = 99 };
    AssertEqual(
        true,
        tracker.TryUpdate(
            firstDeviation,
            target,
            new FieldNavigationMovementObservation(true, true, FieldNavigationInput.Up, 0, 50, 50d, "first deviation"),
            out var first),
        "first partial deviation should retain guidance");
    AssertEqual(false, first.Replanned, "50-unit deviation remains below threshold");

    planner.ConfirmsRoute = true;
    var clearNeighbor = start with { Y = 70, TriangleId = 98 };
    AssertEqual(
        true,
        tracker.TryUpdate(
            clearNeighbor,
            target,
            new FieldNavigationMovementObservation(true, true, FieldNavigationInput.Up, 0, 20, 20d, "clear neighbor"),
            out var confirmed),
        "clear neighboring corridor should retain guidance");
    AssertEqual(false, confirmed.Replanned, "clear neighboring corridor must reset deviation");

    planner.ConfirmsRoute = false;
    for (var sample = 1; sample <= 11; sample++)
    {
        var y = clearNeighbor.Y + sample * 50;
        var secondDeviation = start with { Y = y, TriangleId = 97 };
        AssertEqual(
            true,
            tracker.TryUpdate(
                secondDeviation,
                target,
                new FieldNavigationMovementObservation(true, true, FieldNavigationInput.Up, 0, 50, 50d, "second deviation"),
                out var retained),
            "post-confirmation deviation should stay routable");
        AssertEqual(false, retained.Replanned, "fewer than twelve samples after a clear lane must retain the route");
    }

    AssertEqual(1, planner.BuildCount, "clear-lane confirmation should retain the original plan");
    var threshold = start with { Y = clearNeighbor.Y + 12 * 50, TriangleId = 96 };
    AssertEqual(
        true,
        tracker.TryUpdate(
            threshold,
            target,
            new FieldNavigationMovementObservation(true, true, FieldNavigationInput.Up, 0, 50, 50d, "threshold"),
            out var replanned),
        "new sustained deviation should remain routable");
    AssertEqual(true, replanned.Replanned, "twelve sustained samples and 192 or more new deviation units should rebuild");
    AssertEqual(2, planner.BuildCount, "sustained deviation should rebuild exactly once");
}

