static void AssertFieldNavigationRouteTrackerResetsDeviationOnRouteReentry()
{
    var planner = new FixedPortalRoutePlanner();
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Bent exit",
        150,
        150,
        0,
        "exit:bent");
    var start = new FieldPositionSnapshot(1, 900, 0, 10, 10, 0, 0, 0);

    AssertEqual(true, tracker.TryStart(start, target, out _), "route re-entry test should start");
    AssertEqual(true, tracker.TryUpdate(start with { Y = 42, TriangleId = 99 }, target, out _), "first 32 off-route units");
    AssertEqual(true, tracker.TryUpdate(start with { Y = 74, TriangleId = 99 }, target, out var beforeReentry), "first 64 off-route units");
    AssertEqual(false, beforeReentry.Replanned, "64 off-route units must remain below threshold");
    AssertEqual(true, tracker.TryUpdate(start with { X = 20, TriangleId = 0 }, target, out var reentered), "route re-entry should retain guidance");
    AssertEqual(false, reentered.Replanned, "route re-entry must reset deviation distance");
    FieldNavigationRouteGuidance afterReset = default;
    for (var sample = 1; sample <= 11; sample++)
    {
        var y = start.Y + sample * 32;
        AssertEqual(true, tracker.TryUpdate(start with { Y = y, TriangleId = 99 }, target, out afterReset), "post-reentry off-route sample");
        AssertEqual(false, afterReset.Replanned, "fewer than twelve post-reentry samples must retain the route");
    }

    AssertEqual(false, afterReset.Replanned, "pre-reentry evidence must not carry into a later deviation");
    AssertEqual(true, tracker.TryUpdate(start with { Y = start.Y + 12 * 32, TriangleId = 99 }, target, out var threshold), "second sustained deviation should stay routable");
    AssertEqual(true, threshold.Replanned, "twelve new off-route samples after re-entry should replan");
}

