            X = observed.X,
            Y = observed.Y,
            Z = observed.Z
        };
        var dx = current.X - previous.X;
        var dy = current.Y - previous.Y;
        var distance = Math.Sqrt(dx * (double)dx + dy * (double)dy);
        var movement = new FieldNavigationMovementObservation(
            true,
            true,
            FieldNavigationInput.Up,
            dx,
            dy,
            distance,
            $"captured tunnel movement dx={dx}, dy={dy}");

        AssertEqual(
            true,
            tracker.TryUpdate(current, target, movement, out var guidance),
            $"installed winding-tunnel route should update at {current.X},{current.Y}");
        AssertEqual(
            false,
            guidance.Replanned,
            $"clear tunnel movement at {current.X},{current.Y} must not rebuild the route");
        var guidanceX = guidance.Waypoint.X - current.X;
        var guidanceY = guidance.Waypoint.Y - current.Y;
        AssertEqual(
            true,
            guidanceX * dx + guidanceY * dy > 0,
            $"tunnel guidance at {current.X},{current.Y} must remain ahead of movement; " +
            $"waypoint={guidance.Waypoint.X},{guidance.Waypoint.Y}, delta={dx},{dy}, " +
            $"diagnostic={guidance.Diagnostic}");
        previous = current;
    }
}

