static void AssertFieldNavigationControlReaderReadsNativeTransform()
{
    var memory = new Dictionary<int, byte>();
    const int triggerHeader = 0x02400000;
    memory[FieldPositionReader.AddressCurrentModule] = FieldPositionReader.FieldModule;
    WriteUInt16(memory, FieldPositionReader.AddressFieldId, 120);
    WriteUInt32(memory, FieldNavigationControlReader.AddressFieldTriggersPtr, triggerHeader);
    memory[triggerHeader + FieldNavigationControlReader.ControlDirectionOffset] = 160;

    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0;
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    var reader = new FieldNavigationControlReader(ReadInt32Value, ReadByte);
    var result = reader.Read(new FieldPositionSnapshot(1, 120, 2, 0, 0, 0, 0, 0));

    AssertEqual(true, result.IsUsable, "native field control transform should not depend on model event data");
    AssertEqual(-96, result.Transform.SignedControlDirection, "control byte should use signed game arithmetic");
    AssertEqual(
        false,
        result.Diagnostic.Contains("modelOffset", StringComparison.Ordinal),
        "unknown field event byte 0x35 must not influence or describe the control transform");

    var rotatedField = new FieldNavigationControlTransform(-96);
    var upPress = rotatedField.TransformWorldVector(-100, 100);
    AssertApprox(0f, upPress.X, 0.01f, "rotated field up press should have no horizontal component");
    AssertApprox(-1f, upPress.Y, 0.01f, "rotated field should invert the native control transform back to up");
}

static void AssertFieldNavigationSpokenCueUsesOnlyMeaningfulDiagonalDirections()
{
    var noRotation = new FieldNavigationControlTransform(-128);
    AssertEqual(
        "up 4",
        FieldNavigationSpokenCueFormatter.Format(-85, 320, noRotation, distanceUnitsPerCount: 80),
        "a mostly vertical open leg should not speak a small sideways correction");
    AssertEqual(
        "right 1",
        FieldNavigationSpokenCueFormatter.Format(75, 0, noRotation, distanceUnitsPerCount: 80),
        "a cardinal leg should retain its coarse distance");
    AssertEqual(
        "up 9",
        FieldNavigationSpokenCueFormatter.Format(0, 720, noRotation, distanceUnitsPerCount: 80),
        "coarse navigation counts must not be capped at four");
    AssertEqual(
        "up 4",
        FieldNavigationSpokenCueFormatter.Format(-10, 320, noRotation, distanceUnitsPerCount: 80),
        "a negligible secondary controller axis should be omitted");
    AssertEqual(
        "right 3",
        FieldNavigationSpokenCueFormatter.Format(240, 80, noRotation, distanceUnitsPerCount: 80),
        "one-up three-right geometry should be spoken as one mostly-right leg");
    AssertEqual(
        "up-right 4",
        FieldNavigationSpokenCueFormatter.Format(240, 240, noRotation, distanceUnitsPerCount: 80),
        "a substantial equal-axis route should retain its safe diagonal instead of inventing a cardinal detour");
    AssertEqual(
        "up-left 4",
        FieldNavigationSpokenCueFormatter.Format(-240, 240, noRotation, distanceUnitsPerCount: 80),
        "substantial upper-left route geometry");
    AssertEqual(
        "down-right 4",
        FieldNavigationSpokenCueFormatter.Format(240, -240, noRotation, distanceUnitsPerCount: 80),
        "substantial lower-right route geometry");
    AssertEqual(
        "down-left 4",
        FieldNavigationSpokenCueFormatter.Format(-240, -240, noRotation, distanceUnitsPerCount: 80),
        "substantial lower-left route geometry");

    var shinraLobbyTransform = new FieldNavigationControlTransform(-64);
    AssertEqual(
        "up-right 16",
        FieldNavigationSpokenCueFormatter.Format(
            983 - 1427,
            775 - (-70),
            shinraLobbyTransform,
            distanceUnitsPerCount: 60),
        "captured field 234 lobby route must speak the diagonal that remains inside the native corridor");

    var rotatedField = new FieldNavigationControlTransform(-96);
    AssertEqual(
        "up 2",
        FieldNavigationSpokenCueFormatter.Format(-100, 100, rotatedField, distanceUnitsPerCount: 80),
        "spoken guidance should use the native field control rotation");
    AssertEqual(
        "at destination",
        FieldNavigationSpokenCueFormatter.Format(0, 0, noRotation, distanceUnitsPerCount: 80),
        "zero waypoint offset should use the FFIX destination phrase");

    var config = new AccessibilityConfig();
    AssertEqual(60, config.FieldNavigationSpeechDistanceUnitsPerCount, "measured walking-step count scale default");

    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Upper-left door",
        X: -85,
        Y: 320,
        Z: 0,
        StableId: "exit:spoken");
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        new SingleTriangleRoutePlanner());
    var position = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);
    controller.HandleAction(FieldNavigationAction.ToggleBeacon, position, noRotation);

    var cue = controller.CreateSpokenGuidance(position, noRotation, arrivalDistanceUnits: 80);
    AssertEqual("up 4", cue?.Speech, "controller should speak one normalized stable waypoint direction");

    var widerScaleController = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        new SingleTriangleRoutePlanner(),
        spokenDistanceUnitsPerCount: 160);
    widerScaleController.HandleAction(FieldNavigationAction.ToggleBeacon, position, noRotation);
    AssertEqual(
        "up 2",
        widerScaleController.CreateSpokenGuidance(position, noRotation, arrivalDistanceUnits: 80)?.Speech,
        "controller should apply the configured coarse count scale consistently");
}

