static void AssertFieldNavigationRouteProgressUsesOrderedThreeDimensionalDistance()
{
    var planner = new SingleTriangleRoutePlanner();
    var route = new FieldNavigationRouteTracker(planner);
    var progress = new FieldNavigationRouteProgressTracker();
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Upper landing",
        0,
        0,
        1000,
        "exit:vertical-progress");
    var start = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);

    AssertEqual(true, route.TryStart(start, target, out var initial), "vertical route should start");
    AssertApprox(1000f, (float)initial.RemainingDistance, 0.001f, "initial 3D route length");
    progress.Start(initial.RemainingDistance);
    AssertEqual(0, progress.Percent, "a newly activated route starts at zero percent");

    var quarterHeight = start with { Z = 250 };
    AssertEqual(
        true,
        route.TryUpdate(quarterHeight, target, default, out var quarter),
        "vertical route should update from Cloud's absolute Z position");
    AssertApprox(750f, (float)quarter.RemainingDistance, 0.001f, "ordered route distance should include Z");
    AssertEqual(25, progress.Observe(quarter.RemainingDistance), "one quarter of the 3D route");

    AssertEqual(
        20,
        progress.Observe(800d),
        "route progress should fall when Cloud backtracks along the connected route");
    AssertEqual(
        25,
        progress.Observe(750d),
        "route progress should rise again when Cloud recovers the lost distance");
    progress.BeginRemainingSegment(500d);
    AssertEqual(
        62,
        progress.Observe(250d),
        "a replan should preserve completed progress and divide only the remaining route");
    AssertEqual(
        43,
        progress.Observe(375d),
        "backtracking after a replan should lower progress on the preserved scale");
    AssertEqual(
        25,
        progress.Observe(500d),
        "returning to the replan origin should return to its preserved percentage");
    AssertEqual(
        99,
        progress.Observe(0d),
        "position alone reserves one percent until the route's arrival condition is confirmed");
    AssertEqual(100, progress.Complete(), "confirmed route completion reaches one hundred percent");
}

static void AssertFieldNavigationRouteProgressStaysOnCommittedPortalWhenNeighborTriangleIsUnresolved()
{
    var planner = new OverlappingCorridorRoutePlanner();
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Overlapping corridor exit",
        0,
        200,
        0,
        "exit:overlapping-corridor");
    var start = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);

    AssertEqual(true, tracker.TryStart(start, target, out var initial), "overlapping route should start");
    AssertApprox(2200f, (float)initial.ProgressRemainingDistance, 0.001f, "overlapping route initial progress distance");

    var neighboringTriangle = start with { X = 100, Y = 95, TriangleId = 99 };
    var movement = new FieldNavigationMovementObservation(
        true,
        true,
        FieldNavigationInput.Right,
        100,
        95,
        Math.Sqrt(100d * 100d + 95d * 95d),
        "captured neighboring-corridor movement");
    AssertEqual(
        true,
        tracker.TryUpdate(neighboringTriangle, target, movement, out var retained),
        "an unresolved neighboring triangle should retain the route");
    AssertEqual(false, retained.Replanned, "one neighboring-triangle sample must not replan");
    AssertEqual(
        true,
        retained.ProgressRemainingDistance > 2000d,
        "unresolved progress must stay on the committed first portal instead of jumping to a later overlapping segment");
    AssertEqual(
        true,
        retained.ProgressRemainingDistance < initial.ProgressRemainingDistance,
        "forward movement on the committed segment should still advance progress");
}

