static void AssertFieldNavigationControllerExposesNativeRouteProgressAndExplicitSpeech()
{
    FieldNavigationRouteStep[] stableSteps =
    [
        new(new FieldNavigationRouteWaypoint(0, 500, 0), 1),
        new(new FieldNavigationRouteWaypoint(0, 1000, 0), 2)
    ];
    var planner = new ConfigurableCorridorRoutePlanner
    {
        ConfirmsRoute = true,
        StableWaypointsOverride = stableSteps
    };
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Story,
        "North checkpoint",
        0,
        1000,
        0,
        "story:progress",
        CompletesOnArrival: true);
    var progressSink = new RecordingFieldNavigationProgressSink();
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        planner,
        spokenDistanceUnitsPerCount: 100,
        routeProgressSink: progressSink);
    var transform = new FieldNavigationControlTransform(-128);
    var start = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);
    var north = new FieldNavigationInputSnapshot(
        FieldNavigationInputReader.UpMask,
        FieldNavigationInput.Up);

    controller.HandleAction(FieldNavigationAction.NextCategory, start, transform);
    var activated = controller.HandleAction(
        FieldNavigationAction.ToggleBeacon,
        start,
        transform);
    AssertEqual(
        false,
        activated?.Speech.Contains("Route progress", StringComparison.Ordinal) ?? false,
        "activation speech should not duplicate the native progress value");
    AssertEqual(0, progressSink.Percent, "native progress sink starts at zero");

    var quarter = start with { Y = 250 };
    controller.UpdateLiveTracking(
        quarter,
        north,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5);
    AssertEqual(25, controller.CurrentRouteProgressPercent, "controller route progress after moving one quarter");
    AssertEqual(25, progressSink.Percent, "native progress sink receives one-quarter progress");
    var ordinaryGuidance = controller.CreateSpokenGuidance(
        quarter,
        transform,
        arrivalDistanceUnits: 5);
    AssertEqual(
        false,
        ordinaryGuidance
            ?.Speech.Contains("Route progress", StringComparison.Ordinal) ?? false,
        "ordinary Prism guidance must not duplicate the native progress control");

    var repeated = controller.HandleAction(
        FieldNavigationAction.RepeatTarget,
        quarter,
        transform);
    AssertContains(repeated?.Speech ?? string.Empty, "Route progress 25 percent");

    var halfway = start with { Y = 500 };
    controller.UpdateLiveTracking(
        halfway,
        north,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5);
    AssertEqual(50, controller.CurrentRouteProgressPercent, "halfway route progress");

    controller.UpdateLiveTracking(
        start with { Y = 400 },
        north,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5);
    AssertEqual(
        40,
        controller.CurrentRouteProgressPercent,
        "controller route progress should fall while Cloud backtracks");
    AssertEqual(
        40,
        progressSink.Percent,
        "native progress sink should receive the lower backtracking value");

    var arrival = controller.UpdateLiveTracking(
        start with { Y = 1000 },
        north,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5);
    AssertEqual(
        false,
        arrival?.Speech.Contains("Route progress", StringComparison.Ordinal) ?? false,
        "arrival speech should not duplicate the native one-hundred-percent event");
    AssertContains(arrival?.Speech ?? string.Empty, "Navigation off");
    AssertEqual(100, progressSink.Percent, "confirmed arrival publishes one hundred percent");
    AssertEqual(1, progressSink.CompletionCount, "confirmed arrival completes the native progress once");
}

static void AssertNativeFieldNavigationProgressBarUsesStandardAccessibleControl()
{
    using var foregroundWindow = new NativeProgressTestWindow();
    using var progressBar = new NativeFieldNavigationProgressBar(
        _ => { },
        () => foregroundWindow.Handle);
    AssertEqual(
        true,
        progressBar.WaitUntilReady(TimeSpan.FromSeconds(3)),
        "native route progress host should initialize");
    AssertEqual(
        "msctls_progress32",
        progressBar.ControlClassName,
        "route progress must use the standard Windows progress control");
    AssertEqual(
        true,
        progressBar.HasAccessibleClient,
        "standard route progress control should expose an MSAA/UIA client");

    progressBar.Activate(0);
    AssertEqual(
        true,
        progressBar.WaitForAppliedState(active: true, percent: 0, TimeSpan.FromSeconds(2)),
        "route activation should publish zero percent");
    AssertEqual(
        foregroundWindow.Handle,
        progressBar.HostParentHandle,
        "the progress bar must be a descendant of FFVII's foreground window");
    progressBar.SetValue(37);
    AssertEqual(
        true,
        progressBar.WaitForAppliedState(active: true, percent: 37, TimeSpan.FromSeconds(2)),
        "route progress should publish the native value");
    AssertEqual(
        37,
        progressBar.ReadNativePercent(),
        "PBM_GETPOS should expose the same progress value");
    progressBar.SetValue(12);
    AssertEqual(
        true,
        progressBar.WaitForAppliedState(active: true, percent: 12, TimeSpan.FromSeconds(2)),
        "the native progress control should publish a lower value while backtracking");
    AssertEqual(
        12,
        progressBar.ReadNativePercent(),
        "PBM_GETPOS should expose the lower backtracking value");
    AssertEqual(
        true,
        progressBar.ValueChangeNotificationCount > 0,
        "progress changes should raise normal accessibility value-change events");

    progressBar.Deactivate();
    AssertEqual(
        true,
        progressBar.WaitForAppliedState(active: false, percent: 12, TimeSpan.FromSeconds(2)),
        "cancelled navigation should hide the progress control");

    progressBar.Activate(37);
    progressBar.Complete();
    progressBar.Deactivate();
    AssertEqual(
        true,
        progressBar.WaitForAppliedState(active: true, percent: 100, TimeSpan.FromSeconds(2)),
        "confirmed arrival should expose one hundred percent before hiding");
    AssertEqual(
        true,
        progressBar.WaitForAppliedState(active: false, percent: 100, TimeSpan.FromSeconds(3)),
        "one hundred percent should remain available long enough for screen readers to report it");
}

