static void AssertFieldNavigationDistanceCalibrationUsesOnlyConfidentCurrentPaceSamples()
{
    var stable = new FieldFootstepDistanceProbeSummary(
        new FieldFootstepDistanceStatistics(4, 69.4, 0.8, 68.2, 70.5),
        new FieldFootstepDistanceStatistics(8, 180.2, 8.0, 168.0, 192.0),
        new FieldFootstepDistanceStatistics(12, 143.3, 55.0, 68.2, 192.0),
        SuggestedDistanceUnitsPerCount: 69);

    AssertEqual(
        69,
        FieldNavigationDistanceCalibration.ResolveForNavigation(
            244,
            fallbackUnitsPerCount: 60,
            FieldFootstepCadence.Walk,
            stable),
        "stable walking samples should calibrate spoken walking counts");
    AssertEqual(
        180,
        FieldNavigationDistanceCalibration.ResolveForNavigation(
            244,
            fallbackUnitsPerCount: 60,
            FieldFootstepCadence.Run,
            stable),
        "stable running samples should calibrate only spoken running counts");

    var undersampled = stable with
    {
        Walk = new FieldFootstepDistanceStatistics(3, 90.0, 1.0, 89.0, 91.0),
        Run = new FieldFootstepDistanceStatistics(7, 210.0, 1.0, 209.0, 211.0)
    };
    AssertEqual(
        60,
        FieldNavigationDistanceCalibration.ResolveForNavigation(
            245,
            fallbackUnitsPerCount: 60,
            FieldFootstepCadence.Walk,
            undersampled),
        "three walking samples must not replace an uncalibrated field fallback");
    AssertEqual(
        60,
        FieldNavigationDistanceCalibration.ResolveForNavigation(
            245,
            fallbackUnitsPerCount: 60,
            FieldFootstepCadence.Run,
            undersampled),
        "seven running samples must not replace an uncalibrated field fallback");

    var noisy = stable with
    {
        Walk = new FieldFootstepDistanceStatistics(12, 70.0, 20.0, 30.0, 110.0),
        Run = new FieldFootstepDistanceStatistics(16, 180.0, 50.0, 90.0, 270.0)
    };
    AssertEqual(
        60,
        FieldNavigationDistanceCalibration.ResolveForNavigation(
            245,
            fallbackUnitsPerCount: 60,
            FieldFootstepCadence.Walk,
            noisy),
        "noisy walking data must preserve the configured fallback");
    AssertEqual(
        60,
        FieldNavigationDistanceCalibration.ResolveForNavigation(
            245,
            fallbackUnitsPerCount: 60,
            FieldFootstepCadence.Run,
            noisy),
        "noisy running data must preserve the configured fallback");
}

static void AssertFieldNavigationSpeechPolicyUsesFfixCadenceAndForeground()
{
    var config = new AccessibilityConfig();
    AssertEqual(1000, config.FieldNavigationSpeechIntervalMs, "spoken navigation should default to the installed FFIX cadence");
    AssertEqual(350, config.FieldNavigationRunningSpeechIntervalMs, "running navigation should default to a faster live cadence");
    AssertEqual(
        1000,
        FieldNavigationSpeechPolicy.ResolveIntervalMs(
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: false),
        "walking prediction should use the exact clamped speech interval");
    AssertEqual(
        350,
        FieldNavigationSpeechPolicy.ResolveIntervalMs(
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: true),
        "running prediction should use the exact clamped speech interval");
    AssertEqual(
        FieldNavigationSpeechPolicy.MinimumRunningIntervalMs,
        FieldNavigationSpeechPolicy.ResolveIntervalMs(
            configuredIntervalMs: 10,
            configuredRunningIntervalMs: 10,
            isRunning: true),
        "prediction must honor the same minimum interval as speech scheduling");

    var lastSpokenAt = new DateTime(2026, 7, 14, 12, 0, 0, DateTimeKind.Utc);
    AssertEqual(
        false,
        FieldNavigationSpeechPolicy.IsDue(
            lastSpokenAt.AddMilliseconds(999),
            lastSpokenAt,
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: false,
            isSuppressed: false,
            isForeground: true,
            hasUsableControl: true,
            navigationEnabled: true),
        "spoken navigation should not repeat before one second");
    AssertEqual(
        true,
        FieldNavigationSpeechPolicy.IsDue(
            lastSpokenAt.AddMilliseconds(1000),
            lastSpokenAt,
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: false,
            isSuppressed: false,
            isForeground: true,
            hasUsableControl: true,
            navigationEnabled: true),
        "spoken navigation should update every second");
    AssertEqual(
        false,
        FieldNavigationSpeechPolicy.IsDue(
            lastSpokenAt.AddMilliseconds(349),
            lastSpokenAt,
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: true,
            isSuppressed: false,
            isForeground: true,
            hasUsableControl: true,
            navigationEnabled: true),
        "running guidance should not repeat before its faster native-input cadence");
    AssertEqual(
        true,
        FieldNavigationSpeechPolicy.IsDue(
            lastSpokenAt.AddMilliseconds(350),
            lastSpokenAt,
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: true,
            isSuppressed: false,
            isForeground: true,
            hasUsableControl: true,
            navigationEnabled: true),
        "running guidance should keep pace with faster portal traversal");
    AssertEqual(
        false,
        FieldNavigationSpeechPolicy.IsDue(
            lastSpokenAt.AddSeconds(2),
            lastSpokenAt,
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: false,
            isSuppressed: true,
            isForeground: true,
            hasUsableControl: true,
            navigationEnabled: true),
        "suppression should block automatic navigation speech");
    AssertEqual(
        false,
        FieldNavigationSpeechPolicy.IsDue(
            lastSpokenAt.AddSeconds(2),
            lastSpokenAt,
            config.FieldNavigationSpeechIntervalMs,
            config.FieldNavigationRunningSpeechIntervalMs,
            isRunning: false,
            isSuppressed: false,
            isForeground: false,
            hasUsableControl: true,
            navigationEnabled: true),
        "automatic navigation speech should require FFVII in the foreground");
}

static void AssertFieldNavigationGuidanceRepeatGateSuppressesUnchangedSpeech()
{
    var gate = new FieldNavigationGuidanceRepeatGate();
    var startedAt = new DateTime(2026, 7, 31, 12, 0, 0, DateTimeKind.Utc);

    AssertEqual(true, gate.ShouldSpeak("down 4", startedAt), "the first automatic guidance should speak");
    AssertEqual(
        false,
        gate.ShouldSpeak("down 4", startedAt.AddMilliseconds(350)),
        "running cadence must not repeat an unchanged rounded instruction");
    AssertEqual(
        false,
        gate.ShouldSpeak("down 4", startedAt.AddMilliseconds(1999)),
        "unchanged guidance should remain quiet until the reminder window");
    AssertEqual(
        true,
        gate.ShouldSpeak("down 3", startedAt.AddMilliseconds(400)),
        "a changed distance should speak immediately");
    AssertEqual(
        true,
        gate.ShouldSpeak("down 3", startedAt.AddMilliseconds(2400)),
        "an unchanged instruction should remain available as a two-second reminder");
    AssertEqual(false, gate.ShouldSpeak(string.Empty, startedAt.AddSeconds(3)), "empty guidance must not speak");

    gate.Reset();
    AssertEqual(
        true,
        gate.ShouldSpeak("down 3", startedAt.AddMilliseconds(2500)),
        "an explicit navigation-context reset should allow the current instruction immediately");
}

static void AssertFieldNavigationControllerHasNoSyntheticControlOverloads()
{
    var methods = typeof(FieldNavigationController).GetMethods(
        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
    var syntheticUpdate = methods.Any(method =>
        method.Name == nameof(FieldNavigationController.UpdateLiveTracking) &&
        method.GetParameters().Length == 2 &&
        method.GetParameters()[0].ParameterType == typeof(FieldPositionSnapshot) &&
        method.GetParameters()[1].ParameterType == typeof(int));
    var syntheticCue = methods.Any(method =>
        method.Name == nameof(FieldNavigationController.CreateBeaconCue) &&
        method.GetParameters().Length == 2 &&
        method.GetParameters()[0].ParameterType == typeof(FieldPositionSnapshot) &&
        method.GetParameters()[1].ParameterType == typeof(int));

    AssertEqual(false, syntheticUpdate, "live tracking must require an explicit native control transform");
    AssertEqual(false, syntheticCue, "beacon creation must require an explicit native control transform");
}

static void AssertFieldNavigationInputReaderDecodesNativeDirections()
{
    var memory = new Dictionary<int, uint>();
    var reader = new FieldNavigationInputReader(
        address => memory.TryGetValue(address, out var value) ? value : 0u);

    memory[FieldNavigationInputReader.AddressCurrentKeyInput] =
        FieldNavigationInputReader.UpMask | FieldNavigationInputReader.LeftMask;
    var upLeft = reader.Read();
    AssertEqual(FieldNavigationInput.UpLeft, upLeft.Direction, "native up-left input should decode");

    memory[FieldNavigationInputReader.AddressCurrentKeyInput] =
        FieldNavigationInputReader.UpMask | FieldNavigationInputReader.DownMask;
    AssertEqual(FieldNavigationInput.Conflicting, reader.Read().Direction, "opposite native inputs should be rejected");

    memory[FieldNavigationInputReader.AddressCurrentKeyInput] = 0;
    AssertEqual(FieldNavigationInput.None, reader.Read().Direction, "released native input should decode as none");

    memory[FieldNavigationInputReader.AddressCurrentKeyInput] =
        FieldNavigationInputReader.RunMask | FieldNavigationInputReader.UpMask;
    AssertEqual(true, reader.Read().IsDirectionalRun, "native run plus direction should select faster guidance");
    memory[FieldNavigationInputReader.AddressCurrentKeyInput] = FieldNavigationInputReader.RunMask;
    AssertEqual(false, reader.Read().IsDirectionalRun, "run without movement should retain walking guidance cadence");
}

static void AssertFieldNavigationMovementObserverValidatesUnblockedMovement()
{
    var observer = new FieldNavigationMovementObserver();
    var transform = new FieldNavigationControlTransform(-128);
    var up = new FieldNavigationInputSnapshot(FieldNavigationInputReader.UpMask, FieldNavigationInput.Up);
    var start = new FieldPositionSnapshot(1, 900, 0, 100, 100, 0, 1, 0);

    var initial = observer.Observe(start, up, transform, isSuppressed: false);
    AssertEqual(false, initial.IsMoving, "first movement sample should establish a baseline");

    var firstMove = observer.Observe(start with { Y = 110 }, up, transform, isSuppressed: false);
    AssertEqual(true, firstMove.IsMoving, "native movement should be observed");
    AssertEqual(10, firstMove.DeltaY, "movement observer should retain live y displacement");

    observer.Observe(start with { Y = 120 }, up, transform, isSuppressed: false);
    var recommendation = observer.ResolveStickDirection(0, 100, transform);
    AssertEqual(FieldNavigationInput.Up, recommendation.Input, "native up should guide toward matching world movement");
    AssertEqual(true, recommendation.IsObserved, "two consistent samples should validate the native instruction");

    var blockedObserver = new FieldNavigationMovementObserver();
    blockedObserver.Observe(start, up, transform, isSuppressed: false);
    blockedObserver.Observe(start, up, transform, isSuppressed: false);
    blockedObserver.Observe(start, up, transform, isSuppressed: false);
    var blockedRecommendation = blockedObserver.ResolveStickDirection(0, 100, transform);
    AssertEqual(false, blockedRecommendation.IsObserved, "stationary wall contact must not validate movement mapping");

    var suppressedObserver = new FieldNavigationMovementObserver();
    suppressedObserver.Observe(start, up, transform, isSuppressed: true);
    suppressedObserver.Observe(start with { Y = 120 }, up, transform, isSuppressed: true);
    var suppressedRecommendation = suppressedObserver.ResolveStickDirection(0, 100, transform);
    AssertEqual(false, suppressedRecommendation.IsObserved, "suppressed scripted movement must not validate mapping");
}

static void AssertFieldNavigationMovementObserverDoesNotOverrideNativeDirection()
{
    var observer = new FieldNavigationMovementObserver();
    var transform = new FieldNavigationControlTransform(-128);
    var right = new FieldNavigationInputSnapshot(FieldNavigationInputReader.RightMask, FieldNavigationInput.Right);
    var start = new FieldPositionSnapshot(1, 900, 0, 100, 100, 0, 1, 0);

    observer.Observe(start, right, transform, isSuppressed: false);
    observer.Observe(start with { X = 90 }, right, transform, isSuppressed: false);
    observer.Observe(start with { X = 80 }, right, transform, isSuppressed: false);

    var recommendation = observer.ResolveStickDirection(100, 0, transform);
    AssertEqual(
        FieldNavigationInput.Right,
        recommendation.Input,
        "movement constrained by walls or a narrow corridor must not retrain the native field controls");
    AssertEqual(false, recommendation.IsObserved, "contradictory movement may diagnose the route but must not drive it");
}

static void AssertFieldNavigationMovementObserverResetsOnStableControlChange()
{
    var observer = new FieldNavigationMovementObserver();
    var originalTransform = new FieldNavigationControlTransform(-128);
    var changedTransform = new FieldNavigationControlTransform(0);
    var none = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    var up = new FieldNavigationInputSnapshot(FieldNavigationInputReader.UpMask, FieldNavigationInput.Up);
    var start = new FieldPositionSnapshot(1, 900, 0, 100, 100, 0, 1, 0);

    observer.Observe(start, none, originalTransform, isSuppressed: false);
    observer.Observe(start, up, originalTransform, isSuppressed: false);
    observer.Observe(start with { Y = 110 }, up, originalTransform, isSuppressed: false);
    observer.Observe(start with { Y = 120 }, up, originalTransform, isSuppressed: false);
    AssertEqual(true, observer.ResolveStickDirection(0, 100, originalTransform).IsObserved, "native movement mapping should be validated");

    observer.Observe(start with { Y = 120 }, none, originalTransform, isSuppressed: false);
    observer.Observe(start with { Y = 120 }, none, changedTransform, isSuppressed: false);
    AssertEqual(
        false,
        observer.ResolveStickDirection(0, 100, changedTransform).IsObserved,
        "a stable control rotation while input is released must clear stale movement mapping");

    var heldObserver = new FieldNavigationMovementObserver();
    heldObserver.Observe(start, none, originalTransform, isSuppressed: false);
    heldObserver.Observe(start, up, originalTransform, isSuppressed: false);
    heldObserver.Observe(start with { Y = 110 }, up, originalTransform, isSuppressed: false);
    heldObserver.Observe(start with { Y = 120 }, up, originalTransform, isSuppressed: false);
    heldObserver.Observe(start with { Y = 130 }, up, changedTransform, isSuppressed: false);
    AssertEqual(
        false,
        heldObserver.ResolveStickDirection(0, 100, changedTransform).IsObserved,
        "held movement evidence must not override a changed native control direction");
}

static void AssertFieldNavigationVelocityEstimatorUsesRollingNativePositions()
{
    var estimator = new FieldNavigationVelocityEstimator();
    var startTime = new DateTime(2026, 7, 25, 12, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 1, 0);

    estimator.Observe(position, startTime, isSuppressed: false);
    estimator.Observe(
        position with { Y = 30 },
        startTime.AddMilliseconds(50),
        isSuppressed: false);
    estimator.Observe(
        position with { Y = 60 },
        startTime.AddMilliseconds(100),
        isSuppressed: false);

    AssertEqual(
        true,
        estimator.TryGetEstimate(out var estimate),
        "three coherent native positions should produce a rolling velocity");
    AssertEqual(
        0,
        (int)Math.Round(estimate.XPerSecond),
        "rolling native velocity should retain the measured x component");
    AssertEqual(
        600,
        (int)Math.Round(estimate.YPerSecond),
        "rolling native velocity should divide displacement by observed time");
    AssertEqual(
        600,
        (int)Math.Round(estimate.Speed),
        "rolling native velocity should expose planar speed");
    AssertEqual(
        100,
        (int)Math.Round(estimate.Coherence * 100d),
        "straight native movement should be fully coherent");
}

static void AssertFieldNavigationVelocityEstimatorRejectsUnsafeHistory()
{
    var startTime = new DateTime(2026, 7, 25, 12, 0, 0, DateTimeKind.Utc);
    var position = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 1, 0);

    var suppressed = new FieldNavigationVelocityEstimator();
    suppressed.Observe(position, startTime, isSuppressed: false);
    suppressed.Observe(position with { Y = 30 }, startTime.AddMilliseconds(50), isSuppressed: false);
    suppressed.Observe(position with { Y = 60 }, startTime.AddMilliseconds(100), isSuppressed: false);
    suppressed.Observe(position with { Y = 60 }, startTime.AddMilliseconds(150), isSuppressed: true);
    AssertEqual(
        false,
        suppressed.TryGetEstimate(out _),
        "suppression must clear predictive movement history");

    var delayed = new FieldNavigationVelocityEstimator();
    delayed.Observe(position, startTime, isSuppressed: false);
    delayed.Observe(position with { Y = 30 }, startTime.AddMilliseconds(50), isSuppressed: false);
    delayed.Observe(position with { Y = 60 }, startTime.AddMilliseconds(600), isSuppressed: false);
    AssertEqual(
        false,
        delayed.TryGetEstimate(out _),
        "a gap over 500 milliseconds must restart the rolling window");

    var teleported = new FieldNavigationVelocityEstimator();
    teleported.Observe(position, startTime, isSuppressed: false);
    teleported.Observe(position with { Y = 100 }, startTime.AddMilliseconds(50), isSuppressed: false);
    teleported.Observe(position with { Y = 130 }, startTime.AddMilliseconds(100), isSuppressed: false);
    AssertEqual(
        false,
        teleported.TryGetEstimate(out _),
        "implausible instantaneous movement must not become predictive velocity");

    var reversing = new FieldNavigationVelocityEstimator();
    reversing.Observe(position, startTime, isSuppressed: false);
    reversing.Observe(position with { Y = 30 }, startTime.AddMilliseconds(50), isSuppressed: false);
    reversing.Observe(position, startTime.AddMilliseconds(100), isSuppressed: false);
    AssertEqual(
        false,
        reversing.TryGetEstimate(out _),
        "reversing jitter must fail the rolling coherence threshold");
}

static void AssertFieldNavigationPredictiveTurnResolverLooksOneSpeechIntervalAhead()
{
    var position = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 1, 0);
    var currentWaypoint = new FieldNavigationRouteWaypoint(0, 120, 0);
    var nextWaypoint = new FieldNavigationRouteWaypoint(150, 120, 0);
    var velocity = new FieldNavigationVelocityEstimate(
        XPerSecond: 0d,
        YPerSecond: 600d,
        Speed: 600d,
        Coherence: 1d);

    AssertEqual(
        true,
        FieldNavigationPredictiveTurnResolver.TryResolve(
            position,
            currentWaypoint,
            nextWaypoint,
            velocity,
            predictionHorizonMs: 350,
            out var turn),
        "a runner who will reach a 90-degree corner within one speech interval should hear the turn");
    AssertEqual(
        nextWaypoint,
        turn.Waypoint,
        "predictive guidance should expose the following stable route corner");
    AssertEqual(
        210,
        (int)Math.Round(turn.ProjectedDistance),
        "predictive guidance should use measured speed over the configured interval");
}

static void AssertFieldNavigationPredictiveTurnResolverRejectsUnsafePreview()
{
    var position = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 1, 0);
    var currentWaypoint = new FieldNavigationRouteWaypoint(0, 120, 0);
    var rightTurn = new FieldNavigationRouteWaypoint(150, 120, 0);
