    AssertEqual(
        false,
        FieldNavigationPredictiveTurnResolver.TryResolve(
            position,
            currentWaypoint,
            rightTurn,
            new FieldNavigationVelocityEstimate(0d, -600d, 600d, 1d),
            predictionHorizonMs: 350,
            out _),
        "movement away from the current corner must not predict its following turn");
    AssertEqual(
        false,
        FieldNavigationPredictiveTurnResolver.TryResolve(
            position,
            new FieldNavigationRouteWaypoint(0, 300, 0),
            new FieldNavigationRouteWaypoint(150, 300, 0),
            towardCorner,
            predictionHorizonMs: 350,
            out _),
