    AssertEqual(
        false,
        FieldNavigationPredictiveTurnResolver.TryResolve(
            position,
            currentWaypoint,
            rightTurn,
            towardCorner,
            predictionHorizonMs: 0,
            out _),
        "a zero horizon must keep manual and initial speech non-predictive");
}

static void AssertFieldNavigationControllerAppendsPredictiveTurnAtExistingCadence()
{
    var planner = new FixedPortalRoutePlanner();
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Bent exit",
        150,
        150,
        0,
        "exit:bent");
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        planner);
    var transform = new FieldNavigationControlTransform(-128);
    var right = new FieldNavigationInputSnapshot(
        FieldNavigationInputReader.RightMask | FieldNavigationInputReader.RunMask,
        FieldNavigationInput.Right);
    var startTime = new DateTime(2026, 7, 25, 12, 0, 0, DateTimeKind.Utc);
    var start = new FieldPositionSnapshot(1, 900, 0, -12, 10, 0, 0, 0);

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, transform);
    controller.UpdateLiveTracking(
        start,
        right,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: startTime);
    controller.UpdateLiveTracking(
        start with { X = -2, Y = 9 },
        right,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: startTime.AddMilliseconds(50));
    var current = start with { X = 8, Y = 8 };
    controller.UpdateLiveTracking(
        current,
        right,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: startTime.AddMilliseconds(100));

    var predicted = controller.CreateSpokenGuidance(
        current,
        transform,
        arrivalDistanceUnits: 5,
        predictionHorizonMs: 350);
    if (predicted is null)
    {
        var probe = controller.CreateProbeSnapshot(current);
        throw new InvalidOperationException(
            $"Predictive integration produced no ordinary guidance. " +
            $"Beacon={probe.BeaconEnabled}, currentGuidance={controller.CurrentRouteGuidance is not null}, " +
            $"diagnostic={controller.LastNavigationDiagnostic}");
    }

    AssertContains(
        predicted.Value.Speech,
        ", then ");
    AssertEqual(
        "right 1, then up-right",
        predicted.Value.Speech,
        "a predictive turn should retain a materially diagonal next route leg");

    var precise = controller.CreateSpokenGuidance(
        current,
        transform,
        arrivalDistanceUnits: 5,
        predictionHorizonMs: 0);
    AssertEqual(
        false,
        precise?.Speech.Contains(", then ", StringComparison.Ordinal) ?? false,
        "manual or initial guidance must retain the current safe waypoint only");
}

static void AssertFieldNavigationRouteTrackerDoesNotSkipCloseObstacleCornerForPrediction()
{
    FieldNavigationRouteStep[] stableSteps =
    [
        new(new FieldNavigationRouteWaypoint(0, 100, 0), 1),
        new(new FieldNavigationRouteWaypoint(0, 200, 0), 2),
        new(new FieldNavigationRouteWaypoint(4, 203, 0), 3),
        new(new FieldNavigationRouteWaypoint(100, 203, 0), 4)
    ];
    var planner = new ConfigurableCorridorRoutePlanner
    {
        ConfirmsRoute = true,
        ObservedStableStepIndex = 1,
        ObservedWaypoint = stableSteps[1].Waypoint,
        StableWaypointsOverride = stableSteps
    };
    var tracker = new FieldNavigationRouteTracker(planner);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Upper dead-end hairpin",
        100,
        203,
        0,
        "exit:hairpin");
    var start = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);

    AssertEqual(true, tracker.TryStart(start, target, out _), "hairpin preview route should start");
    AssertEqual(
        true,
        tracker.TryUpdate(
            start with { Y = 10 },
            target,
            new FieldNavigationMovementObservation(
                true,
                true,
                FieldNavigationInput.Up,
                0,
                10,
                10d,
                "running toward live lookahead"),
            out var guidance),
        "hairpin preview route should update");
    AssertEqual(
        stableSteps[1].Waypoint,
        guidance.Waypoint,
        "live lookahead should expose the farther safe approach");
    AssertEqual(
        true,
        tracker.TryGetUpcomingStep(out var upcoming),
        "a material turn after the live lookahead should be available");
    AssertEqual(
        stableSteps[2],
        upcoming,
        "predictive speech must preserve the next stable corner even when it is close, because the corner can encode obstacle clearance");
}

static void AssertFieldNavigationControllerDoesNotPredictPastNativeAction()
{
    var planner = new FixedPortalRoutePlanner(FieldNavigationTransitionKind.Jump);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Bent exit",
        150,
        150,
        0,
        "exit:bent");
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        planner);
    var transform = new FieldNavigationControlTransform(-128);
    var right = new FieldNavigationInputSnapshot(
        FieldNavigationInputReader.RightMask | FieldNavigationInputReader.RunMask,
        FieldNavigationInput.Right);
    var startTime = new DateTime(2026, 7, 25, 12, 0, 0, DateTimeKind.Utc);
    var start = new FieldPositionSnapshot(1, 900, 0, -12, 10, 0, 0, 0);

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, transform);
    controller.UpdateLiveTracking(
        start,
        right,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: startTime);
    controller.UpdateLiveTracking(
        start with { X = -2, Y = 9 },
        right,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: startTime.AddMilliseconds(50));
    var current = start with { X = 8, Y = 8 };
    controller.UpdateLiveTracking(
