static void AssertFieldNavigationControllerRecoversFromSameFieldWrap()
{
    var now = new DateTime(2026, 7, 25, 0, 0, 0, DateTimeKind.Utc);
    var target = new FieldNavigationTarget(
        161,
        FieldNavigationCategory.Exits,
        "North through the winding tunnel",
        746,
        2237,
        5,
        "script-exit:161:2:161,162",
        CompletesOnArrival: false,
        TriggerLine: new FieldNavigationTriggerLine(805, 2862, 9, 687, 1611, 0));
    var planner = new SingleTriangleRoutePlanner();
    var controller = new FieldNavigationController(new FieldNavigationTargetSource([target]), planner);
    var transform = new FieldNavigationControlTransform(-128);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    var tunnelTop = new FieldPositionSnapshot(1, 161, 0, 663, 1920, -10, 37, 128);

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, tunnelTop, transform);
    controller.UpdateLiveTracking(
        tunnelTop,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now);
    AssertEqual(1, planner.BuildCount, "the tunnel route should initially build once");

    var transientOrigin = controller.UpdateLiveTracking(
        tunnelTop with { X = 0, Y = 0, Z = 0, TriangleId = 0 },
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(50));
    AssertNull(transientOrigin, "the transient same-field origin should stay silent");
    AssertEqual(true, controller.BeaconEnabled, "same-field wrap must retain the selected beacon");
    AssertNull(controller.CurrentRouteGuidance, "same-field wrap must discard the pre-wrap route");
    AssertEqual(1, planner.BuildCount, "the transient origin must not build a false route");
    AssertContains(controller.LastNavigationDiagnostic, "position discontinuity");

    var wrappedSpawn = controller.UpdateLiveTracking(
        tunnelTop with { X = 293, Y = -404, Z = -17, TriangleId = 226 },
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(100));
    AssertNull(wrappedSpawn, "the tunnel wrap spawn should re-prime silently");
    AssertEqual(true, controller.BeaconEnabled, "the beacon should remain selected through the tunnel wrap");
    AssertNull(controller.CurrentRouteGuidance, "the route should wait for a coherent post-wrap position");
    AssertEqual(1, planner.BuildCount, "the wrap spawn must not build from teleport motion");

    controller.UpdateLiveTracking(
        tunnelTop with { X = 325, Y = -404, Z = -16, TriangleId = 215 },
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(150));
    AssertEqual(true, controller.BeaconEnabled, "navigation should stay active after the tunnel wrap");
    AssertEqual(true, controller.CurrentRouteGuidance is not null, "coherent post-wrap movement should rebuild the route");
    AssertEqual(2, planner.BuildCount, "the tunnel route should rebuild exactly once from the stable spawn");
}

static void AssertFieldNavigationControllerRecoversCoherentlyAfterSuppression()
{
    var now = new DateTime(2026, 7, 25, 21, 38, 30, DateTimeKind.Utc);
    var target = new FieldNavigationTarget(
        129,
        FieldNavigationCategory.Exits,
        "Reactor 5 elevator",
        -730,
        310,
        1571,
        "exit:129:elevator");
    var planner = new SingleTriangleRoutePlanner();
    var controller = new FieldNavigationController(new FieldNavigationTargetSource([target]), planner);
    var transform = new FieldNavigationControlTransform(-128);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    var beforeBattle = new FieldPositionSnapshot(1, 129, 0, 806, -134, 544, 56, 64);

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, beforeBattle, transform);
    controller.UpdateLiveTracking(
        beforeBattle,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now);
    AssertEqual(1, planner.BuildCount, "the pre-battle route should build once");

    controller.UpdateLiveTracking(
        beforeBattle,
        noInput,
        transform,
        isSuppressed: true,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(50));

    var transientOrigin = beforeBattle with { X = 0, Y = 0, Z = 0, TriangleId = 56 };
    var originSpeech = controller.UpdateLiveTracking(
        transientOrigin,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(100));
    AssertNull(originSpeech, "the first post-battle position should remain silent");
    AssertEqual(true, controller.BeaconEnabled, "post-battle recovery must preserve the selected beacon");
    AssertNull(controller.CurrentRouteGuidance, "the transient origin must not become an active route");
    AssertEqual(1, planner.BuildCount, "the transient origin must not rebuild the route");

    controller.UpdateLiveTracking(
        transientOrigin,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(150));
    AssertNull(
        controller.CurrentRouteGuidance,
        "multiple coherent transient-origin frames must not prematurely resume navigation");
    AssertEqual(1, planner.BuildCount, "the transient origin must remain quarantined");

    controller.UpdateLiveTracking(
        transientOrigin,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(250));
    AssertNull(
        controller.CurrentRouteGuidance,
        "a long-lived hydration origin must remain quarantined against the pre-battle anchor");
    AssertEqual(1, planner.BuildCount, "a long-lived hydration origin must not rebuild the route");

    var restored = beforeBattle with { X = 838, Y = -134, Z = 544 };
    controller.UpdateLiveTracking(
        restored,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(300));
    AssertNull(controller.CurrentRouteGuidance, "the first restored frame should replace the incoherent origin candidate");
    AssertEqual(1, planner.BuildCount, "the first restored frame must not rebuild yet");

    controller.UpdateLiveTracking(
        restored with { X = 870 },
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(350));
    AssertNull(controller.CurrentRouteGuidance, "post-battle recovery requires a stable observation window");
    AssertEqual(1, planner.BuildCount, "the short restored window must not rebuild yet");

    controller.UpdateLiveTracking(
        restored with { X = 902 },
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(450));
    AssertEqual(true, controller.CurrentRouteGuidance is not null, "a coherent stable restored window should resume navigation");
    AssertEqual(2, planner.BuildCount, "the route should rebuild exactly once from a coherent restored position");
}

static void AssertFieldNavigationControllerIgnoresSuppressedMovement()
{
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Far exit",
        150,
        25,
        0,
        "exit:far");
