    var scriptedDestination = start with { X = 90, Y = 10 };

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, transform);
    AssertEqual(1, planner.BuildCount, "suppression refresh route should start once");

    controller.UpdateLiveTracking(
        scriptedDestination,
        noInput,
        transform,
        isSuppressed: true,
        arrivalDistanceUnits: 5,
        observedAt: now);
    AssertEqual(1, planner.BuildCount, "suppressed scripted movement must not build routes mid-scene");

    controller.UpdateLiveTracking(
        scriptedDestination,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(50));
    AssertEqual(1, planner.BuildCount, "the first live sample after suppression should only prime position recovery");
    AssertNull(controller.CurrentRouteGuidance, "position recovery should not expose a route from one post-suppression sample");

    controller.UpdateLiveTracking(
        scriptedDestination with { X = 91 },
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(100));
    AssertEqual(1, planner.BuildCount, "a short coherent window must remain quarantined");

    controller.UpdateLiveTracking(
        scriptedDestination with { X = 92 },
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 5,
        observedAt: now.AddMilliseconds(200));
    AssertEqual(2, planner.BuildCount, "a stable coherent window must rebuild from the recovered position");
    AssertEqual(true, controller.BeaconEnabled, "route refresh should preserve the selected navigation target");
}

static void AssertFieldNavigationControllerDefersCompletionWhileSuppressed()
{
    var now = new DateTime(2026, 7, 28, 1, 1, 0, DateTimeKind.Utc);
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Exits,
        "Next field",
        100,
        100,
        0,
        "exit:next");
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        new SingleTriangleRoutePlanner());
    var position = new FieldPositionSnapshot(1, 900, 0, 90, 100, 0, 0, 0);
    var arrived = position with { X = 100 };
    var transform = new FieldNavigationControlTransform(-128);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, position, transform);
    var suppressed = controller.UpdateLiveTracking(
        arrived,
        noInput,
        transform,
        isSuppressed: true,
        arrivalDistanceUnits: 80,
        observedAt: now);

    AssertNull(suppressed, "field-transition completion speech must wait through scripted suppression");
    AssertEqual(true, controller.BeaconEnabled, "suppression should retain the pending route completion");

    var resumed = controller.UpdateLiveTracking(
        arrived,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80,
        observedAt: now.AddMilliseconds(50));
    AssertNull(resumed, "the first resumed sample should only prime position recovery");
