    resumed = controller.UpdateLiveTracking(
        arrived,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80,
        observedAt: now.AddMilliseconds(100));
    AssertNull(resumed, "a short recovery window must not complete the route");

    resumed = controller.UpdateLiveTracking(
        arrived,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80,
        observedAt: now.AddMilliseconds(200));
    AssertContains(resumed?.Speech ?? string.Empty, "Next field reached");
