static void AssertFieldNavigationNonObjectTargetsCompleteAtArrival()
{
    var transform = new FieldNavigationControlTransform(-128);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    foreach (var category in new[]
             {
                 FieldNavigationCategory.Exits,
                 FieldNavigationCategory.Story,
                 FieldNavigationCategory.Npcs
             })
    {
        var target = new FieldNavigationTarget(
            900,
            category,
            $"{category} destination",
            100,
            100,
            0,
            $"{category}:destination",
            CompletesOnArrival: category == FieldNavigationCategory.Story);
        var controller = new FieldNavigationController(
            new FieldNavigationTargetSource([target]),
            new SingleTriangleRoutePlanner());
        var position = new FieldPositionSnapshot(1, 900, 0, 90, 100, 0, 0, 0);

        while (controller.CurrentCategory != category)
        {
            controller.HandleAction(FieldNavigationAction.NextCategory, position, transform);
        }

        controller.HandleAction(FieldNavigationAction.ToggleBeacon, position, transform);
        var arrival = controller.UpdateLiveTracking(
            position,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 80);

        AssertEqual(false, controller.BeaconEnabled, $"{category} navigation should stop inside arrival range");
        AssertContains(arrival?.Speech ?? string.Empty, $"{category} destination reached");
        AssertContains(arrival?.Speech ?? string.Empty, "Navigation off");
    }
}

static void AssertFieldNavigationModelStoryWaitsForNativeCompletion()
{
    IReadOnlyList<FieldNavigationTarget> liveTargets =
    [
        new FieldNavigationTarget(
            900,
            FieldNavigationCategory.Story,
            "Help Jessie free her leg",
            100,
            100,
            0,
            "story:900:4:jessie",
            CompletesOnArrival: false,
            InteractionRadius: 240)
    ];
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([], storyTargetProvider: _ => liveTargets),
        new SingleTriangleRoutePlanner());
    var position = new FieldPositionSnapshot(1, 900, 0, 90, 100, 0, 0, 0);
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    var transform = new FieldNavigationControlTransform(-128);

    controller.HandleAction(FieldNavigationAction.NextCategory, position, transform);
    controller.HandleAction(FieldNavigationAction.ToggleBeacon, position, transform);
    var proximity = controller.UpdateLiveTracking(
        position,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80);

    AssertContains(proximity?.Speech ?? string.Empty, "Help Jessie free her leg reached");
    AssertContains(proximity?.Speech ?? string.Empty, "Interact here");
    AssertContains(proximity?.Speech ?? string.Empty, "Navigation paused");
    AssertEqual(true, controller.BeaconEnabled, "model Story navigation must retain its native target until the event completes");
    AssertNull(
        controller.UpdateLiveTracking(
            position,
            noInput,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 80),
        "a paused model Story target must not repeat its arrival");
    AssertNull(
        controller.CreateSpokenGuidance(position, transform, arrivalDistanceUnits: 80),
        "a paused model Story target must not continue steering");

    liveTargets =
    [
        liveTargets[0] with { X = 500 }
    ];
    var resumed = controller.UpdateLiveTracking(
        position,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80);
    AssertContains(resumed?.Speech ?? string.Empty, "Navigation resumed");
    AssertEqual(true, controller.BeaconEnabled, "a moving Story target leaving native reach must resume guidance");

    liveTargets =
    [
        liveTargets[0] with { X = 100 }
    ];
    var pausedAgain = controller.UpdateLiveTracking(
        position,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80);
    AssertContains(pausedAgain?.Speech ?? string.Empty, "Navigation paused");

    liveTargets = [];
    var completed = controller.UpdateLiveTracking(
        position,
        noInput,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80);
    AssertContains(completed?.Speech ?? string.Empty, "completed");
    AssertContains(completed?.Speech ?? string.Empty, "Navigation off");
    AssertEqual(false, controller.BeaconEnabled, "native Story removal after interaction must end navigation");
}

