        new FieldPositionSnapshot(1, 120, 0, -1525, 4423, -282, 60, 0),
        new FieldPositionSnapshot(1, 120, 0, -1489, 4423, -282, 60, 0),
        new FieldPositionSnapshot(1, 120, 0, -1385, 4421, -282, 63, 0),
        new FieldPositionSnapshot(1, 120, 0, -1346, 4413, -282, 63, 0),
        new FieldPositionSnapshot(1, 120, 0, -1300, 4390, -282, 63, 0),
        new FieldPositionSnapshot(1, 120, 0, -1250, 4380, -282, 63, 0)
    };

    controller.HandleAction(FieldNavigationAction.ToggleBeacon, positions[0], transform);
    controller.CreateBeaconCue(positions[0], transform, arrivalDistanceUnits: 80);
    var portalIndices = new List<int>();
    foreach (var position in positions)
    {
        controller.UpdateLiveTracking(
            position,
            right,
            transform,
            isSuppressed: false,
            arrivalDistanceUnits: 80);
        portalIndices.Add(controller.CurrentRouteGuidance?.PortalIndex ?? -1);
    }

    for (var index = 1; index < portalIndices.Count; index++)
    {
        AssertEqual(
            true,
            portalIndices[index] >= portalIndices[index - 1],
            "captured reactor portal progress must never decrease");
    }

    AssertEqual(2, portalIndices[3], "entering triangle 63 should finish both captured portals");
    AssertEqual(true, portalIndices.Skip(3).All(index => index == 2), "triangle 60 portal must never be selected again");
    AssertEqual(true, controller.BeaconEnabled, "missed 80-unit approach must not disable the exit beacon");
    AssertContains(controller.LastNavigationDiagnostic, "route retained");
    AssertEqual(1, planner.BuildCount, "captured reactor movement must retain one stable route");

    var completion = controller.UpdateLiveTracking(
        positions[^1] with { FieldId = 121, TriangleId = 0 },
        right,
        transform,
        isSuppressed: false,
        arrivalDistanceUnits: 80);
    AssertEqual(false, controller.BeaconEnabled, "reactor exit should complete on the native field transition");
    AssertContains(completion?.Speech ?? string.Empty, "Reactor walkway exit reached");
}

