static void AssertFieldNavigationStoryGatewayCompletesAtMatchingFieldTransition()
{
    var gatewayLine = new FieldNavigationTriggerLine(-251, 2500, 0, -19, 2492, 0);
    var storyTarget = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Story,
        "Continue through the north gate",
        -135,
        2496,
