        TriggerLine: gatewayLine);
    IReadOnlyList<FieldNavigationTarget> exits =
    [
        new FieldNavigationTarget(
            900,
            FieldNavigationCategory.Exits,
            "Exit to the next area",
            -135,
            2496,
            0,
            "gateway:900:0:901",
            DestinationFieldIds: [901],
            TriggerLine: gatewayLine)
    ];
    var source = new FieldNavigationTargetSource(
        [storyTarget],
        exitTargetProvider: position => position.FieldId == 900 ? exits : []);
    var controller = new FieldNavigationController(source, new SingleTriangleRoutePlanner());
    var start = new FieldPositionSnapshot(1, 900, 0, 0, 0, 0, 0, 0);
