    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, noRotation);
    var completion = controller.UpdateLiveTracking(
        start with { FieldId = 901 },
        noInput,
        noRotation,
        isSuppressed: false,
        arrivalDistanceUnits: 80);

    AssertEqual(false, controller.BeaconEnabled, "matching native gateway transition should stop story navigation");
    AssertEqual(
        "Continue through the north gate reached. Navigation off.",
        completion?.Speech,
        "a story target sharing the crossed native gateway should announce arrival");

    var wrongExitController = new FieldNavigationController(source, new SingleTriangleRoutePlanner());
    wrongExitController.HandleAction(FieldNavigationAction.NextCategory, start, noRotation);
    wrongExitController.HandleAction(FieldNavigationAction.ToggleBeacon, start, noRotation);
