static void AssertFieldNavigationObjectWaitsForNativeRemoval()
{
    IReadOnlyList<FieldNavigationTarget> liveTargets =
    [
        new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Objects,
        "Potion",
        X: 1000,
        Y: 2000,
        Z: 0,
        StableId: "object:900:4")
    ];
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([], _ => liveTargets),
        new SingleTriangleRoutePlanner());
    var position = new FieldPositionSnapshot(1, 900, 0, 900, 2000, 0, 0, 0);
    var noRotation = new FieldNavigationControlTransform(-128);

    controller.HandleAction(FieldNavigationAction.NextCategory, position, noRotation);
    controller.HandleAction(FieldNavigationAction.NextCategory, position, noRotation);
    controller.HandleAction(FieldNavigationAction.NextCategory, position, noRotation);
    controller.HandleAction(FieldNavigationAction.ToggleBeacon, position, noRotation);
    AssertEqual(true, controller.BeaconEnabled, "object beacon should start outside arrival range");

    var reachedPosition = position with { X = 960 };
    var update = controller.UpdateLiveTracking(
        reachedPosition,
        new FieldNavigationInputSnapshot(0, FieldNavigationInput.None),
        noRotation,
        isSuppressed: false,
        arrivalDistanceUnits: 80);

    AssertContains(update?.Speech ?? string.Empty, "Potion reached");
    AssertContains(update?.Speech ?? string.Empty, "Interact here");
    AssertEqual(true, controller.BeaconEnabled, "object beacon should remain locked while its native target still exists");
    AssertNull(
        controller.CreateSpokenGuidance(reachedPosition, noRotation, arrivalDistanceUnits: 80),
        "object navigation should stop speaking directions inside pickup range while awaiting native removal");

    liveTargets = [];
    var removed = controller.UpdateLiveTracking(
        reachedPosition,
        new FieldNavigationInputSnapshot(0, FieldNavigationInput.None),
        noRotation,
        isSuppressed: false,
        arrivalDistanceUnits: 80);
    AssertEqual(false, controller.BeaconEnabled, "native object removal should complete navigation");
    AssertContains(removed?.Speech ?? string.Empty, "Potion");
    AssertContains(removed?.Speech ?? string.Empty, "Navigation off");
}

static void AssertFieldNavigationInteractionArrivalPausesAndResumesGuidance()
{
    var target = new FieldNavigationTarget(
        900,
        FieldNavigationCategory.Story,
        "Place the battery",
        X: 200,
        Y: 100,
        Z: 0,
        StableId: "story:900:battery",
        CompletesOnArrival: false,
        TriggerLine: new FieldNavigationTriggerLine(200, 50, 0, 200, 150, 0));
    var controller = new FieldNavigationController(
        new FieldNavigationTargetSource([target]),
        new SingleTriangleRoutePlanner());
    var noInput = new FieldNavigationInputSnapshot(0, FieldNavigationInput.None);
    var noRotation = new FieldNavigationControlTransform(-128);
    var start = new FieldPositionSnapshot(1, 900, 0, 0, 100, 0, 0, 0);

    controller.HandleAction(FieldNavigationAction.NextCategory, start, noRotation);
    controller.HandleAction(FieldNavigationAction.ToggleBeacon, start, noRotation);
    var reachedPosition = start with { X = 140 };
    var arrival = controller.UpdateLiveTracking(
        reachedPosition,
        noInput,
        noRotation,
        isSuppressed: false,
        arrivalDistanceUnits: 80);

    AssertContains(arrival?.Speech ?? string.Empty, "Place the battery reached");
    AssertContains(arrival?.Speech ?? string.Empty, "Interact here");
    AssertEqual(true, controller.BeaconEnabled, "interaction arrival must retain the native target lock");
    AssertNull(
        controller.CreateBeaconCue(reachedPosition, noRotation, arrivalDistanceUnits: 80),
        "the beacon must stop at an uncompleted interaction");
    AssertNull(
        controller.CreateSpokenGuidance(reachedPosition, noRotation, arrivalDistanceUnits: 80),
        "spoken directions must stop at an uncompleted interaction");
    AssertNull(
        controller.UpdateLiveTracking(
            reachedPosition,
            noInput,
            noRotation,
            isSuppressed: false,
            arrivalDistanceUnits: 80),
        "remaining at the interaction must not repeat the arrival message");

    var movedAway = start with { X = 60 };
    var resumed = controller.UpdateLiveTracking(
        movedAway,
        noInput,
        noRotation,
        isSuppressed: false,
        arrivalDistanceUnits: 80);

    AssertContains(resumed?.Speech ?? string.Empty, "Navigation resumed");
    AssertEqual(
        true,
        controller.CreateBeaconCue(movedAway, noRotation, arrivalDistanceUnits: 80) is not null,
        "the beacon must resume after the player walks away from an uncompleted interaction");
}

