static void AssertNavigationBeaconPlayerInitializesSteamAudioHrtf()
{
    var type = typeof(FieldNavigationBeacon).Assembly.GetType("Ff7.Accessibility.Reloaded.NavigationBeaconPlayer")
        ?? throw new InvalidOperationException("NavigationBeaconPlayer type was not found.");
    var outputDirectory = Path.GetDirectoryName(type.Assembly.Location)
        ?? throw new InvalidOperationException("Could not resolve navigation beacon player assembly path.");
    AssertEqual(true, File.Exists(Path.Combine(outputDirectory, "phonon.dll")), "Steam Audio x86 phonon.dll should be copied beside the mod assembly");

    var logs = new List<string>();
    var player = (IDisposable?)Activator.CreateInstance(type, GetNavigationBeaconSoundPath(), 100, (Action<string>)logs.Add)
        ?? throw new InvalidOperationException("Could not construct NavigationBeaconPlayer.");
    player.Dispose();

    if (!logs.Any(log => log.Contains("Steam Audio HRTF backend initialized.", StringComparison.Ordinal)))
    {
        throw new InvalidOperationException($"navigation beacon player should initialize Steam Audio HRTF. Logs: {string.Join(" | ", logs)}");
    }

    AssertEqual(false, logs.Any(log => log.Contains("fake pan fallback", StringComparison.OrdinalIgnoreCase)), "navigation beacon player should not fall back to fake pan");
}

static void AssertNavigationBeaconPlayerRendersAudibleSteamAudioSamples()
{
    var samples = RenderNavigationBeaconSamples(
        CreateNavigationBeaconCue("right", 1f, 0f, 1f, 0f, 0f),
        LoadNavigationBeaconMonoSamples());
    var peak = samples.Select(Math.Abs).DefaultIfEmpty().Max();
    var rms = Math.Sqrt(samples.Select(sample => sample * (double)sample).DefaultIfEmpty().Average());

    AssertEqual(true, peak > 0.15f, $"Steam Audio beacon render peak should be audible, peak={peak:0.000000}, rms={rms:0.000000}");
    AssertEqual(true, rms > 0.015d, $"Steam Audio beacon render RMS should be audible, peak={peak:0.000000}, rms={rms:0.000000}");
}

static void AssertNavigationBeaconPlayerRendersDirectionalChannelSeparation()
{
    var sound = LoadNavigationBeaconMonoSamples();
    var right = CalculateStereoEnergy(RenderNavigationBeaconSamples(CreateNavigationBeaconCue("right", 1f, 0f, 1f, 0f, 0f), sound));
    var left = CalculateStereoEnergy(RenderNavigationBeaconSamples(CreateNavigationBeaconCue("left", -1f, 0f, -1f, 0f, 0f), sound));

    AssertEqual(true, right.RightRms > right.LeftRms * 1.35d, $"right beacon should be clearly stronger in the right ear, left={right.LeftRms:0.000000}, right={right.RightRms:0.000000}");
    AssertEqual(true, left.LeftRms > left.RightRms * 1.35d, $"left beacon should be clearly stronger in the left ear, left={left.LeftRms:0.000000}, right={left.RightRms:0.000000}");
}

static void AssertNavigationBeaconPlayerRendersBackCueWithRearMarker()
{
    var sound = LoadNavigationBeaconMonoSamples();
    var front = RenderNavigationBeaconSamples(CreateNavigationBeaconCue("up", 0f, -1f, 0f, 0f, -1f), sound);
    var back = RenderNavigationBeaconSamples(CreateNavigationBeaconCue("down", 0f, 1f, 0f, 0f, 1f), sound);
    var backEarly = CalculateStereoWindowRms(back, 0, 4);
    var backMarker = CalculateStereoWindowRms(back, 31, 50);
    var frontMarker = CalculateStereoWindowRms(front, 31, 50);

    AssertEqual(true, backMarker > frontMarker * 1.50d, $"back/down beacon should retain a distinct delayed rear marker, front={frontMarker:0.000000}, back={backMarker:0.000000}");
    AssertEqual(true, backMarker > backEarly * 0.85d, $"back/down delayed rear marker should stay prominent, early={backEarly:0.000000}, marker={backMarker:0.000000}");
}

static void AssertNavigationBeaconRearCueIsDistinctFromFront()
{
    var sound = LoadNavigationBeaconMonoSamples();
    var front = RenderNavigationBeaconSamples(CreateNavigationBeaconCue("up", 0f, -1f, 0f, 0f, -1f), sound);
    var back = RenderNavigationBeaconSamples(CreateNavigationBeaconCue("down", 0f, 1f, 0f, 0f, 1f), sound);
    var frontRearSignatureWindow = CalculateStereoWindowRms(front, 24, 48);
    var backRearSignatureWindow = CalculateStereoWindowRms(back, 24, 48);

    AssertEqual(
        true,
        backRearSignatureWindow > frontRearSignatureWindow * 1.75d,
        $"rear cue should have an unmistakable delayed signature, front={frontRearSignatureWindow:0.000000}, back={backRearSignatureWindow:0.000000}");
}

