static void AssertNavigationHotkeysRequireFf7ForegroundWindow()
{
    nint foregroundWindow = 0x1234;
    uint foregroundProcessId = 77;
    var gate = new ForegroundProcessGate(
        () => foregroundWindow,
        _ => foregroundProcessId,
        currentProcessId: 42);

    AssertEqual(false, gate.IsCurrentProcessForeground(), "another application's window must reject FFVII navigation hotkeys");
    foregroundProcessId = 42;
    AssertEqual(true, gate.IsCurrentProcessForeground(), "FFVII's own foreground window should accept navigation hotkeys");
    foregroundWindow = 0;
    AssertEqual(false, gate.IsCurrentProcessForeground(), "missing foreground window must reject navigation hotkeys");
}

static void AssertNavigationHotkeysDoNotFireWhenRefocusedWhileHeld()
{
    var tracker = new NavigationKeyPressTracker();
    const int key = 0x49;

    AssertEqual(false, tracker.Observe(key, isDown: true, isForeground: false), "background key press must stay silent");
    AssertEqual(false, tracker.Observe(key, isDown: true, isForeground: true), "held background key must not fire when FFVII regains focus");
    AssertEqual(false, tracker.Observe(key, isDown: false, isForeground: true), "release should only rearm the key");
    AssertEqual(true, tracker.Observe(key, isDown: true, isForeground: true), "fresh foreground key press should fire once");
    AssertEqual(false, tracker.Observe(key, isDown: true, isForeground: true), "held foreground key should not repeat");
}

static void AssertRepeatLastSpeechHotkeyRepeatsOnlyDeliveredSpeech()
{
    var controller = new RepeatLastSpeechController();
    var tracker = new NavigationKeyPressTracker();
    var spoken = new List<string>();
    var isDown = false;
    var isForeground = true;

    bool Poll() => controller.Poll(
        virtualKey => tracker.Observe(virtualKey, isDown, isForeground),
        text =>
        {
            spoken.Add(text);
            return true;
        });

    isDown = true;
    AssertEqual(false, Poll(), "R should stay silent before Blind Soldier has delivered speech");
    isDown = false;
    AssertEqual(false, Poll(), "releasing R only rearms the repeat hotkey");

    controller.RememberDelivered("Cloud, front row");
    isDown = true;
    AssertEqual(true, Poll(), "R should repeat the last delivered Blind Soldier utterance");
    AssertEqual("Cloud, front row", spoken.Single(), "R should repeat the exact utterance");
    AssertEqual(false, Poll(), "holding R should not repeat continuously");

    isDown = false;
    AssertEqual(false, Poll(), "R release should remain silent");
    isDown = true;
    AssertEqual(true, Poll(), "a new R press should repeat again");
    AssertEqual(
        "Cloud, front row",
        spoken.Last(),
        "repeating speech must not replace the remembered utterance");

    isDown = false;
    AssertEqual(false, Poll(), "R release before background test");
    isForeground = false;
    isDown = true;
    AssertEqual(false, Poll(), "R pressed in another application must stay silent");
    isForeground = true;
    AssertEqual(false, Poll(), "R held while returning to FFVII must not fire late");
    AssertEqual(0x52, RepeatLastSpeechController.VirtualKeyR, "repeat speech must use the R key");
}

static unsafe void AssertNativeTextDrawQueueCopiesEventsWithoutAllocatingOnCapture()
{
    var queue = new NativeTextDrawEventQueue(capacity: 4, maxTextBytes: 8);
    queue.WarmUp();
    byte[] source = [0x21, 0x22, 0xff, 0x44];

    bool accepted;
    var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
    fixed (byte* text = source)
    {
        accepted = queue.TryCapture(NativeTextDrawSource.InGameB, 12, 34, text, 7, 0x12345678, currentModule: 1);
    }
    var allocatedAfter = GC.GetAllocatedBytesForCurrentThread();

    AssertEqual(true, accepted, "native draw capture should accept a valid event");
    AssertEqual(0L, allocatedAfter - allocatedBefore, "native callback capture must not allocate managed objects");
    source[0] = 0x55;
    AssertEqual(true, queue.TryDequeue(out var captured), "captured draw should be available to the monitor thread");
    AssertEqual(NativeTextDrawSource.InGameB, captured.Source, "captured draw source");
    AssertEqual(12, captured.X, "captured draw x");
    AssertEqual(34, captured.Y, "captured draw y");
    AssertEqual(7, captured.Color, "captured draw color");
    AssertEqual(0x12345678, captured.Context, "captured draw context");
    AssertEqual((byte)1, captured.CurrentModule, "captured draw module");
    AssertEqual(3, captured.TextBytes.Length, "capture should stop after the FFVII terminator");
    AssertEqual((byte)0x21, captured.TextBytes[0], "capture must own a copy of the native text");
    AssertEqual((byte)0xff, captured.TextBytes[2], "capture must retain the terminator for deferred decoding");
    AssertEqual(false, queue.TryDequeue(out _), "queue should be empty after the event is drained");
}

static void AssertNativeFieldHookQueueCopiesEventsWithoutAllocatingOnCapture()
{
    var queue = new NativeFieldHookEventQueue(capacity: 8);
    queue.WarmUp();
    var message = new FieldOpcodeMessageObservation(
        FieldOpcodeKind.Ask,
        FieldId: 124,
        WindowId: 3,
        DialogId: 25,
        FirstQuestionLine: 2,
        LastQuestionLine: 4);
    var context = new FieldScriptContext(FieldId: 124, EntityId: 7, ScriptId: 2, ByteIndex: 91, Opcode: 0xF1);

    var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
    var messageAccepted = queue.TryCaptureOpcodeMessage(message, result: 1);
    var cursorAccepted = queue.TryCaptureAskCursor(
        fieldId: 124,
        windowId: 3,
        dialogId: 25,
        firstQuestionLine: 2,
        lastQuestionLine: 4,
        currentQuestionLine: 3);
    var contextAccepted = queue.TryCaptureCutsceneContext(context);
    var timerAccepted = queue.TryCaptureTimerSet(context, result: 0);
    var allocatedAfter = GC.GetAllocatedBytesForCurrentThread();

    AssertEqual(true, messageAccepted, "bounded field opcode message event");
    AssertEqual(true, cursorAccepted, "bounded field ASK cursor event");
    AssertEqual(true, contextAccepted, "bounded field cutscene event");
    AssertEqual(true, timerAccepted, "bounded field timer event");
    AssertEqual(0L, allocatedAfter - allocatedBefore, "field hook capture allocation count");

    AssertEqual(true, queue.TryDequeue(out var messageEvent), "deferred field opcode message event");
    AssertEqual(NativeFieldHookEventKind.OpcodeMessage, messageEvent.Kind, "field opcode message event kind");
    AssertEqual(message, messageEvent.MessageObservation, "field opcode message observation");
    AssertEqual(1, messageEvent.Result, "field opcode message result");

    AssertEqual(true, queue.TryDequeue(out var cursorEvent), "deferred field ASK cursor event");
    AssertEqual(NativeFieldHookEventKind.AskCursor, cursorEvent.Kind, "field ASK cursor event kind");
    AssertEqual(124, cursorEvent.FieldId, "field ASK cursor field");
    AssertEqual(3, cursorEvent.WindowId, "field ASK cursor window");
    AssertEqual(25, cursorEvent.DialogId, "field ASK cursor dialog");
    AssertEqual(3, cursorEvent.CurrentQuestionLine, "field ASK current question line");

    AssertEqual(true, queue.TryDequeue(out var contextEvent), "deferred field cutscene event");
    AssertEqual(NativeFieldHookEventKind.CutsceneContext, contextEvent.Kind, "field cutscene event kind");
    AssertEqual(context, contextEvent.ScriptContext, "field cutscene context");
    AssertEqual(true, queue.TryDequeue(out var timerEvent), "deferred field timer event");
    AssertEqual(NativeFieldHookEventKind.TimerSet, timerEvent.Kind, "field timer event kind");
    AssertEqual(context, timerEvent.ScriptContext, "field timer context");
    AssertEqual(0, timerEvent.Result, "field timer result");
    AssertEqual(false, queue.TryDequeue(out _), "field hook queue should be empty after draining");
}

static void AssertNativeFieldHookQueueDropsOverflowWithoutInventingEvents()
{
    var queue = new NativeFieldHookEventQueue(capacity: 2);
    var first = new FieldOpcodeMessageObservation(FieldOpcodeKind.Message, 117, 0, 1);
    var second = new FieldOpcodeMessageObservation(FieldOpcodeKind.Message, 117, 0, 2);
    var overflow = new FieldOpcodeMessageObservation(FieldOpcodeKind.Message, 117, 0, 3);

    AssertEqual(true, queue.TryCaptureOpcodeMessage(first, result: 1), "first field hook event");
    AssertEqual(true, queue.TryCaptureOpcodeMessage(second, result: 1), "second field hook event");
    AssertEqual(false, queue.TryCaptureOpcodeMessage(overflow, result: 1), "overflow field hook event");
    AssertEqual(1L, queue.DroppedCount, "field hook overflow count");

    AssertEqual(true, queue.TryDequeue(out var firstEvent), "first queued field hook event");
    AssertEqual(first, firstEvent.MessageObservation, "first queued field hook observation");
    AssertEqual(true, queue.TryDequeue(out var secondEvent), "second queued field hook event");
    AssertEqual(second, secondEvent.MessageObservation, "second queued field hook observation");
    AssertEqual(false, queue.TryDequeue(out _), "overflow must not invent a field hook event");
}

static unsafe void AssertNativeTextDrawQueueDropsOverflowWithoutInventingEvents()
{
    var queue = new NativeTextDrawEventQueue(capacity: 2, maxTextBytes: 4);
    byte[] source = [0x21, 0xff];

    fixed (byte* text = source)
    {
        AssertEqual(true, queue.TryCapture(NativeTextDrawSource.InGameA, 1, 2, text, 3, 4, currentModule: 1), "first bounded event");
        AssertEqual(true, queue.TryCapture(NativeTextDrawSource.InGameA, 5, 6, text, 7, 8, currentModule: 1), "second bounded event");
        AssertEqual(false, queue.TryCapture(NativeTextDrawSource.InGameA, 9, 10, text, 11, 12, currentModule: 1), "full queue should drop instead of overwriting unread state");
    }

    AssertEqual(1L, queue.DroppedCount, "overflow diagnostic count");
    AssertEqual(true, queue.TryDequeue(out var first), "first queued event should remain intact");
    AssertEqual(1, first.X, "overflow must not overwrite the oldest event");
    AssertEqual(true, queue.TryDequeue(out var second), "second queued event should remain intact");
    AssertEqual(5, second.X, "overflow must not invent a replacement event");
}

static void AssertExitShortcutDiagnosticsReportsOnlyExitModuleTransitions()
{
    var tracker = new ExitShortcutDiagnosticsTracker(TimeSpan.FromMilliseconds(750));
    var now = new DateTime(2026, 7, 17, 12, 0, 0, DateTimeKind.Utc);

    tracker.ObserveInput(now, controlActive: false, qActive: false, isForeground: true);
    AssertNull(tracker.ObserveModule(1, now), "ordinary field module should not produce exit diagnostics");
    AssertNull(tracker.ObserveModule(1, now.AddMilliseconds(10)), "stable module should remain silent");
    var exit = tracker.ObserveModule(ExitShortcutDiagnosticsTracker.ExitModule, now.AddMilliseconds(20));
    AssertNotNull(exit, "module 19 transition should produce one diagnostic");
    AssertEqual(false, exit!.Value.ControlQRecent, "unrelated exit should not be attributed to Control+Q");
    AssertNull(tracker.ObserveModule(ExitShortcutDiagnosticsTracker.ExitModule, now.AddMilliseconds(30)), "stable exit module should log once");
}

static void AssertExitShortcutDiagnosticsCorrelatesRecentForegroundControlQ()
{
    var tracker = new ExitShortcutDiagnosticsTracker(TimeSpan.FromMilliseconds(750));
    var now = new DateTime(2026, 7, 17, 12, 0, 0, DateTimeKind.Utc);

    tracker.ObserveModule(1, now);
    tracker.ObserveInput(now.AddMilliseconds(100), controlActive: true, qActive: true, isForeground: true);
    var exit = tracker.ObserveModule(ExitShortcutDiagnosticsTracker.ExitModule, now.AddMilliseconds(300));

    AssertNotNull(exit, "exit transition after Control+Q should be reported");
    AssertEqual(true, exit!.Value.ControlQRecent, "recent foreground Control+Q correlation");
    AssertEqual(true, exit.Value.WasForeground, "diagnostic should retain foreground state");
    AssertEqual(true, exit.Value.ControlActive, "diagnostic should retain Control state");
    AssertEqual(true, exit.Value.QActive, "diagnostic should retain Q state");
}

static void AssertOpeningMovieProbeLifetimeStopsAfterDetectedMovieCloses()
{
    var lifetime = new OpeningMovieProbeLifetime();

    AssertEqual(true, lifetime.ShouldProbe, "opening movie probe should begin active");
    lifetime.Observe(
        FieldPositionReader.FieldModule,
        DeferredZoneSpeechTracker.OpeningFieldId,
        movieDetected: true,
        movieFileActive: true);
    AssertEqual(true, lifetime.ShouldProbe, "active opening movie should remain observable");
    lifetime.Observe(
        FieldPositionReader.FieldModule,
        DeferredZoneSpeechTracker.OpeningFieldId,
        movieDetected: true,
        movieFileActive: false);
    AssertEqual(false, lifetime.ShouldProbe, "closed detected movie should permanently stop Restart Manager polling");
}

static void AssertOpeningMovieProbeLifetimeStopsAfterDirectFieldLoad()
{
    var lifetime = new OpeningMovieProbeLifetime();

    lifetime.Observe(
        FieldPositionReader.FieldModule,
        DeferredZoneSpeechTracker.OpeningFieldId,
        movieDetected: false,
        movieFileActive: false);
    AssertEqual(true, lifetime.ShouldProbe, "opening field race should keep movie detection available");
    lifetime.Observe(
        FieldPositionReader.FieldModule,
        fieldId: 133,
        movieDetected: false,
        movieFileActive: false);
    AssertEqual(false, lifetime.ShouldProbe, "direct non-opening field load should stop startup-only polling");
}

static void AssertModule19WriterCatalogIdentifiesRuntimeWriters()
{
    AssertEqual(3, Module19WriterCatalog.RuntimeSites.Count, "runtime module 19 writer count");
    AssertEqual(0x00409F94, Module19WriterCatalog.RuntimeSites[0].Address, "Control+Q writer address");
    AssertEqual("keyboard Control+Q handler", Module19WriterCatalog.RuntimeSites[0].Cause, "Control+Q writer cause");
    AssertEqual(0x0060E58F, Module19WriterCatalog.RuntimeSites[1].Address, "quit menu writer address");
    AssertEqual("native quit menu callback", Module19WriterCatalog.RuntimeSites[1].Cause, "quit menu writer cause");
    AssertEqual(0x0063C452, Module19WriterCatalog.RuntimeSites[2].Address, "field request writer address");
    AssertEqual("field module request 0x1A", Module19WriterCatalog.RuntimeSites[2].Cause, "field request writer cause");
    AssertNull(Module19WriterCatalog.FindById(999), "unknown writer marker should not be guessed");
}

static void AssertModule19WriterProbeBuildsNativeMarkerWithoutManagedCallback()
{
    var site = Module19WriterCatalog.RuntimeSites[0];
    var assembly = Module19WriterProbe.BuildMarkerAssembly(new IntPtr(0x12345678), site);

    AssertEqual(2, assembly.Length, "writer probe assembly instruction count");
    AssertEqual("use32", assembly[0], "writer probe architecture");
    AssertEqual($"mov dword [0x12345678], {site.Id}", assembly[1], "writer probe should only store a native marker");
}

static NavigationBeaconCue CreateNavigationBeaconCue(
    string direction,
    float stickX,
    float stickY,
    float steamAudioX,
    float steamAudioY,
    float steamAudioZ,
    NavigationBeaconMovementState movementState = NavigationBeaconMovementState.OnCourse) =>
    new(
        "Test beacon",
        direction,
        stickX,
        stickY,
        steamAudioX,
        steamAudioY,
        steamAudioZ,
        movementState,
        DurationMs: 160,
        DistanceUnits: 1000d);

static string GetNavigationBeaconSoundPath()
{
    var outputDirectory = Path.GetDirectoryName(typeof(FieldNavigationBeacon).Assembly.Location)
        ?? throw new InvalidOperationException("Could not resolve navigation beacon output directory.");
    return Path.Combine(outputDirectory, "Assets", "navigation", "navigation_beacon_214_remix.wav");
}

static float[] LoadNavigationBeaconMonoSamples() =>
    NavigationBeaconSound.LoadMonoSamples(GetNavigationBeaconSoundPath(), expectedSampleRate: 44100);

static float[] RenderNavigationBeaconSamples(NavigationBeaconCue cue, float[] monoSamples)
{
    var type = typeof(FieldNavigationBeacon).Assembly.GetType("Ff7.Accessibility.Reloaded.NavigationBeaconPlayer+SteamAudioNavigationBeaconRenderer")
        ?? throw new InvalidOperationException("Steam Audio navigation beacon renderer type was not found.");
    var tryCreate = type.GetMethod(
        "TryCreate",
        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static)
        ?? throw new MissingMethodException(type.FullName, "TryCreate");
    var render = type.GetMethod(
        "Render",
        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance)
        ?? throw new MissingMethodException(type.FullName, "Render");

    var logs = new List<string>();
    var renderer = (IDisposable?)tryCreate.Invoke(null, new object[] { 44100, 1024, (Action<string>)logs.Add })
        ?? throw new InvalidOperationException($"Could not initialize Steam Audio renderer. Logs: {string.Join(" | ", logs)}");
    try
    {
        return (float[]?)render.Invoke(renderer, new object[] { cue, monoSamples, 1f })
            ?? throw new InvalidOperationException("Steam Audio renderer returned null samples.");
    }
    finally
    {
        renderer.Dispose();
    }
}

static (double LeftRms, double RightRms) CalculateStereoEnergy(IReadOnlyList<float> samples)
{
    var frameCount = samples.Count / 2;
    if (frameCount == 0)
    {
        return (0d, 0d);
    }

    var left = 0d;
    var right = 0d;
    for (var frame = 0; frame < frameCount; frame++)
    {
        var leftSample = samples[frame * 2];
        var rightSample = samples[frame * 2 + 1];
        left += leftSample * (double)leftSample;
        right += rightSample * (double)rightSample;
    }

    return (Math.Sqrt(left / frameCount), Math.Sqrt(right / frameCount));
}

static double CalculateStereoWindowRms(IReadOnlyList<float> samples, int startMs, int endMs)
{
    const int sampleRate = 44100;
    var startFrame = Math.Max(0, sampleRate * startMs / 1000);
    var endFrame = Math.Min(samples.Count / 2, sampleRate * endMs / 1000);
    if (endFrame <= startFrame)
    {
        return 0d;
    }

    var sum = 0d;
    var count = 0;
    for (var frame = startFrame; frame < endFrame; frame++)
    {
        var left = samples[frame * 2];
        var right = samples[frame * 2 + 1];
        sum += left * (double)left + right * (double)right;
        count += 2;
    }

    return Math.Sqrt(sum / count);
}

