static void AssertFlevelDataSourceReadsArchiveWithoutExtraction()
{
    var root = Path.Combine(Path.GetTempPath(), $"ff7-test-runtime-{Guid.NewGuid():N}");
    try
    {
        var fieldDirectory = Path.Combine(root, "data", "field");
        Directory.CreateDirectory(fieldDirectory);
        var mapList = BuildFakeMapList("md1stin", "md1_1");
        WriteFakeLgpWithPayloads(
            Path.Combine(fieldDirectory, "flevel.lgp"),
            ("maplist", mapList),
            ("md1stin", new byte[] { 1, 2, 3, 4 }),
            ("md1_1", new byte[] { 5, 6, 7 }));

        var source = new FlevelDataSource(root);

        AssertEqual(true, source.IsUsable, "archive-backed flevel source should be usable");
        AssertContains(source.Diagnostic, "flevel.lgp");
        AssertEqual("md1stin", source.FieldNames[0], "archive maplist field zero");
        AssertEqual("md1_1", source.FieldNames[1], "archive maplist field one");
        AssertEqual(true, source.TryReadField(1, out var fieldBytes), "archive field should be readable by field id");
        AssertEqual("050607", Convert.ToHexString(fieldBytes), "archive field payload");
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, true);
        }
    }
}

static void AssertFlevelDataSourceUsesOneValidatedSourceWithoutMixing()
{
    var root = Path.Combine(Path.GetTempPath(), $"ff7-test-extracted-runtime-{Guid.NewGuid():N}");
    try
    {
        var fieldDirectory = Path.Combine(root, "data", "field");
        var extractedDirectory = Path.Combine(fieldDirectory, "flevel");
        Directory.CreateDirectory(extractedDirectory);
        File.WriteAllBytes(Path.Combine(extractedDirectory, "maplist"), BuildFakeMapList("md1stin", "md1_1"));
        File.WriteAllBytes(Path.Combine(extractedDirectory, "md1stin"), new byte[] { 0x11, 0x12 });
        WriteFakeLgpWithPayloads(
            Path.Combine(fieldDirectory, "flevel.lgp"),
            ("maplist", BuildFakeMapList("md1stin", "md1_1")),
            ("md1stin", new byte[] { 0x21, 0x22 }),
            ("md1_1", new byte[] { 0x31, 0x32 }));

        var source = new FlevelDataSource(root);

        AssertContains(source.Diagnostic, "extracted field data");
        AssertEqual(true, source.TryReadField(0, out var extractedBytes), "selected extracted field should be readable");
        AssertEqual("1112", Convert.ToHexString(extractedBytes), "selected source must supply field bytes");
        AssertEqual(
            false,
            source.TryReadField(1, out _),
            "a selected extracted source must not fall back to a different archive for missing fields");
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, true);
        }
    }
}

