static void AssertCosmoFootstepConfigParsesSequentialEntries()
{
    var config = CosmoFootstepConfig.Parse("""
        # Footsteps
        [md1stin_159]
        sequential = [ 5000, 5001, 5002 ]

        [md1stin_7_159]
        sequential = [ 5040, 5041 ]

        [ujunon3_159]
        sequential = [ 0 ]
        """);

    AssertEqual(true, config.TryGetSequence("md1stin_159", out var fieldSequence), "field-level Cosmo footstep entry should parse");
    AssertEqual(3, fieldSequence.Count, "field-level Cosmo sequence length");
    AssertEqual(5001, fieldSequence[1], "field-level Cosmo sequence item");
    AssertEqual(true, config.TryGetSequence("md1stin_7_159", out var triangleSequence), "triangle-level Cosmo footstep entry should parse");
    AssertEqual(5040, triangleSequence[0], "triangle-level Cosmo sequence item");
    AssertEqual(true, config.TryGetSequence("ujunon3_159", out var silentSequence), "silent Cosmo footstep track should still claim the field");
    AssertEqual(0, silentSequence.Count, "silent Cosmo footstep id 0 should produce an empty sequence");
}

static void AssertCosmoFootstepSequencerUsesExplicitMappingsWithoutFallbacks()
{
    var config = CosmoFootstepConfig.Parse("""
        [md1stin_7_159]
        sequential = [ 5040, 5041 ]

        [md1stin_159]
        sequential = [ 5000, 5001 ]

        [gaiafoot_159]
        sequential = [ 5090 ]

        [ujunon3_159]
        sequential = [ 0 ]
        """);
    var fieldNames = new Dictionary<int, string> { [404] = "md1stin", [777] = "ujunon3" };
    var sequencer = new CosmoFootstepSequencer(config, fieldNames, @"C:\FF7\sfx");
    var position = new FieldPositionSnapshot(1, 404, 0, 100, 200, 300, 7, 16);

    var first = sequencer.SelectNext(position);
    AssertEqual("md1stin_7_159", first.TrackName, "triangle-specific Cosmo track should win");
    AssertEqual(5040, first.SoundId, "first triangle-specific sound id");
    AssertEqual(Path.Combine(@"C:\FF7\sfx", "5040.ogg"), first.Path, "first triangle-specific sound path");

    var second = sequencer.SelectNext(position);
    AssertEqual(5041, second.SoundId, "triangle-specific sequence should advance");

    var fieldOnly = sequencer.SelectNext(position with { TriangleId = 9 });
    AssertEqual("md1stin_159", fieldOnly.TrackName, "field-level Cosmo track should be an explicit field mapping");
    AssertEqual(5000, fieldOnly.SoundId, "first field-level sound id");
    AssertEqual(5001, sequencer.SelectNext(position with { TriangleId = 9 }).SoundId, "field-level sequence should advance");

    AssertEqual(false, sequencer.TrySelectNext(position with { FieldId = 999, TriangleId = 0 }, out _), "unknown field should not use a generic Cosmo fallback");
    AssertEqual(false, sequencer.TrySelectProbe(out _), "load-time probe should not use a generic Cosmo fallback");

    var silent = sequencer.SelectNext(position with { FieldId = 777, TriangleId = 0 });
    AssertEqual("ujunon3_159", silent.TrackName, "silent Cosmo field track should suppress generic fallback");
    AssertEqual(true, silent.IsSilent, "silent Cosmo field track should be marked as silence");
}

static void AssertFootstepProbeSchedulerPlaysOnceAfterDelay()
{
    var startedAt = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var reasons = new List<string>();
    var scheduler = new FootstepProbeScheduler(true, TimeSpan.FromSeconds(1), startedAt, reasons.Add);

    AssertEqual(false, scheduler.TryPlay(startedAt.AddMilliseconds(999)), "footstep probe should wait for configured delay");
    AssertEqual(0, reasons.Count, "footstep probe should not play early");
    AssertEqual(true, scheduler.TryPlay(startedAt.AddSeconds(1)), "footstep probe should play at configured delay");
    AssertEqual("probe", reasons.Single(), "footstep probe should use probe playback reason");
    AssertEqual(false, scheduler.TryPlay(startedAt.AddSeconds(2)), "footstep probe should play only once");
    AssertEqual(1, reasons.Count, "footstep probe should not add a second playback");
}

static void AssertFootstepProbeSchedulerRespectsDisabledConfig()
{
