    var scheduler = new FootstepProbeScheduler(false, TimeSpan.Zero, startedAt, reasons.Add);

    AssertEqual(false, scheduler.TryPlay(startedAt), "disabled footstep probe should not play");
    AssertEqual(0, reasons.Count, "disabled footstep probe should not call playback");
}

static void AssertFootstepVolumePolicyAllowsBoostedGain()
{
    AssertEqual(0f, FootstepVolumePolicy.ToGain(-10), "negative footstep volume should clamp to silence");
    AssertEqual(0.8f, FootstepVolumePolicy.ToGain(80), "normal footstep volume gain");
    AssertEqual(2.0f, FootstepVolumePolicy.ToGain(200), "boosted footstep volume gain");
    AssertEqual(400, FootstepVolumePolicy.ClampVolumePercent(900), "footstep volume should keep a practical boost ceiling");
}

static void AssertMainMenuSelectionUsesNativeIndexAndMasks()
{
    var allEnabled = 0x7ffu;
    var materia = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 2, Target: 2, MenuOpen: 1, EnabledMask: allEnabled, DisabledMask: 0, Animation: 0);
    if (!MainMenuStateReader.TryCreateSelection(materia, out var materiaSelection))
    {
        throw new InvalidOperationException("Expected main menu selection to be accepted.");
    }

    AssertEqual(2, materiaSelection.Index, "main menu selected index");
    AssertEqual("Materia", materiaSelection.SpokenText, "main menu selected label");
    AssertEqual(true, materiaSelection.IsAvailable, "main menu selected availability");

    var order = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 5, Target: 0, MenuOpen: 1, EnabledMask: allEnabled, DisabledMask: 0, Animation: 0);
    if (!MainMenuStateReader.TryCreateSelection(order, out var orderSelection))
    {
        throw new InvalidOperationException("Expected cursor-index main menu selection to be accepted.");
    }

    AssertEqual("Order", orderSelection.SpokenText, "main menu cursor-index label");
    AssertEqual(true, orderSelection.IsAvailable, "main menu cursor-index availability");

    var saveDisabled = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 9, Target: 9, MenuOpen: 1, EnabledMask: allEnabled, DisabledMask: 1u << 9, Animation: 0);
    if (!MainMenuStateReader.TryCreateSelection(saveDisabled, out var disabledSelection))
    {
        throw new InvalidOperationException("Expected disabled main menu selection to be accepted.");
    }

    AssertEqual("Save", disabledSelection.Label, "disabled main menu selected label");
    AssertEqual("Save unavailable", disabledSelection.SpokenText, "disabled visible main menu item should announce its native label and availability");
    AssertEqual(false, disabledSelection.IsAvailable, "disabled main menu selected availability");

    var hidden = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 2, Target: 2, MenuOpen: 1, EnabledMask: allEnabled & ~(1u << 2), DisabledMask: 0, Animation: 0);
    if (MainMenuStateReader.TryCreateSelection(hidden, out _))
    {
        throw new InvalidOperationException("Expected a hidden cursor value to be rejected rather than named from the static table.");
    }

    var transition = new MainMenuSnapshot(State: 5, SelectedA: 0, SelectedB: 4, CursorIndex: 0, Target: 4, MenuOpen: 1, EnabledMask: allEnabled, DisabledMask: 0, Animation: 8);
    if (!MainMenuStateReader.TryCreateSelection(transition, out var transitionSelection))
    {
        throw new InvalidOperationException("Expected transition main menu selection to be accepted.");
    }

    AssertEqual("Status", transitionSelection.SpokenText, "transition main menu selected label");

    var closed = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 0, Target: 0, MenuOpen: 0, EnabledMask: allEnabled, DisabledMask: 0, Animation: 0);
    if (MainMenuStateReader.TryCreateSelection(closed, out _))
    {
        throw new InvalidOperationException("Expected closed main menu snapshot to clear selection.");
    }
}

static void AssertCheckedMainMenuSnapshotPreservesX86SelectionSemantics()
{
    var memory = new MainMenuGuestMemory();
    memory.WriteInt32(MainMenuStateReader.AddressState, 1);
    memory.WriteInt32(MainMenuStateReader.AddressSelectedA, 0);
    memory.WriteInt32(MainMenuStateReader.AddressSelectedB, 4);
    memory.WriteInt32(MainMenuStateReader.AddressCursorIndex, 9);
    memory.WriteInt32(MainMenuStateReader.AddressTarget, 9);
    memory.WriteInt32(MainMenuStateReader.AddressOpenFlag, 1);
    memory.WriteUInt32(MainMenuStateReader.AddressEnabledMask, 0x7ffu);
    memory.WriteUInt32(MainMenuStateReader.AddressDisabledMask, 1u << 9);
    memory.WriteInt32(MainMenuStateReader.AddressAnimation, 16);

    var reader = new MainMenuStateReader(memory);
    AssertEqual(true, reader.TryReadSnapshot(out var snapshot), "x86 checked main-menu snapshot");
    AssertEqual(true, MainMenuStateReader.TryCreateSelection(snapshot, out var selection), "x86 checked main-menu selection");
    AssertEqual("Save", selection.Label, "x86 checked main-menu label");
    AssertEqual(false, selection.IsAvailable, "x86 checked main-menu disabled mask");
}

static void AssertMainMenuSpeechWaitsForSettledSelection()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var scheduler = new MainMenuSpeechScheduler(TimeSpan.FromMilliseconds(120));

    AssertNull(scheduler.Observe("Quit", now), "new menu selection should wait before speaking");
    AssertNull(scheduler.Observe("Config", now.AddMilliseconds(60)), "changed menu selection should restart wait");
    AssertNull(scheduler.Observe("Config", now.AddMilliseconds(150)), "menu selection should still be settling");
    AssertEqual("Config", scheduler.Observe("Config", now.AddMilliseconds(200)), "settled menu selection should speak");
    AssertNull(scheduler.Observe("Config", now.AddMilliseconds(400)), "settled menu selection should not repeat");

    AssertNull(scheduler.Observe("Quit", now.AddMilliseconds(500)), "changed menu selection should wait before speaking");
    AssertEqual("Quit", scheduler.Observe("Quit", now.AddMilliseconds(650)), "settled quit selection should speak");
    AssertNull(scheduler.Observe("", now.AddMilliseconds(700)), "empty menu selection should clear speech scheduler");
    AssertNull(scheduler.Observe("Quit", now.AddMilliseconds(760)), "reappeared menu selection should wait again");
    AssertEqual("Quit", scheduler.Observe("Quit", now.AddMilliseconds(900)), "reappeared settled menu selection should speak again");
}

static void AssertMainMenuSpeechCanSpeakImmediately()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var scheduler = new MainMenuSpeechScheduler(TimeSpan.Zero);

    AssertEqual("Item", scheduler.Observe("Item", now), "immediate menu speech should speak new selection");
    AssertNull(scheduler.Observe("Item", now.AddMilliseconds(10)), "immediate menu speech should not repeat unchanged selection");
    AssertEqual("Magic", scheduler.Observe("Magic", now.AddMilliseconds(20)), "immediate menu speech should speak changed selection");
    AssertNull(scheduler.Observe("", now.AddMilliseconds(30)), "empty menu selection should clear immediate scheduler");
    AssertEqual("Magic", scheduler.Observe("Magic", now.AddMilliseconds(40)), "immediate menu speech should speak reappeared selection after clear");
}

static void AssertMainMenuSpeechSkipsUnavailableSelections()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var scheduler = new MainMenuSpeechScheduler(TimeSpan.Zero);
    const uint allEnabled = 0x7ffu;

    var item = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 0, Target: 0, MenuOpen: 1, EnabledMask: allEnabled, DisabledMask: 0, Animation: 16);
    if (!MainMenuStateReader.TryCreateSelection(item, out var itemSelection))
    {
        throw new InvalidOperationException("Expected available main menu selection to be accepted.");
    }

    AssertEqual("Item", scheduler.Observe(itemSelection.SpokenText, now), "available main menu selection should speak");

    var unavailable = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 2, Target: 2, MenuOpen: 1, EnabledMask: allEnabled, DisabledMask: 1u << 2, Animation: 16);
    if (!MainMenuStateReader.TryCreateSelection(unavailable, out var unavailableSelection))
    {
        throw new InvalidOperationException("Expected visibly unavailable main menu selection to be accepted.");
    }

    AssertEqual(false, unavailableSelection.IsAvailable, "unavailable main menu selection should be marked unavailable");
    AssertEqual("Materia unavailable", scheduler.Observe(unavailableSelection.SpokenText, now.AddMilliseconds(20)), "visibly unavailable main menu selection should speak its native label and availability");

    if (!MainMenuStateReader.TryCreateSelection(item, out var repeatedItemSelection))
    {
        throw new InvalidOperationException("Expected available main menu selection to be accepted again.");
    }

    AssertEqual("Item", scheduler.Observe(repeatedItemSelection.SpokenText, now.AddMilliseconds(40)), "available selection should be repeatable after silent unavailable row");
}

static void AssertInGameMenuSpeechIgnoresTitleMenuTextWithoutCursorSignal()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var coordinator = new InGameMenuSpeechCoordinator(TimeSpan.Zero);

    coordinator.ObserveDraw(new MenuTextRenderEntry("NEW GAME", 267, 192, 7, 0x3DCCCCCD), now);
    coordinator.ObserveDraw(new MenuTextRenderEntry("Continue?", 267, 218, 0, 0x3DCCCCCD), now);
    AssertNull(coordinator.Poll(now), "title menu text draw is not enough to infer native cursor selection");

    coordinator.ObserveDraw(new MenuTextRenderEntry("NEW GAME", 267, 192, 0, 0x3DCCCCCD), now.AddMilliseconds(100));
    coordinator.ObserveDraw(new MenuTextRenderEntry("Continue?", 267, 218, 7, 0x3DCCCCCD), now.AddMilliseconds(100));
    AssertNull(coordinator.Poll(now.AddMilliseconds(100)), "changed title text color should not be treated as a cursor signal");
}

