static void AssertFf7PcSaveFileReaderReadsNativePreviewAndEmptySlots()
{
    var directory = Path.Combine(Path.GetTempPath(), $"ff7-save-reader-{Guid.NewGuid():N}");
    Directory.CreateDirectory(directory);
    try
    {
        var path = Path.Combine(directory, "save00.ff7");
        var bytes = new byte[Ff7PcSaveFileReader.HeaderSize +
            Ff7PcSaveFileReader.SlotsPerFile * Ff7PcSaveFileReader.SlotSize];
        var slot = Ff7PcSaveFileReader.HeaderSize;
        bytes[slot + 0x04] = 8;
        WriteFf7TextBytes(bytes, slot + 0x08, "Cloud", 16);
        WriteUInt16Bytes(bytes, slot + 0x18, 296);
        WriteUInt16Bytes(bytes, slot + 0x1A, 334);
        WriteUInt16Bytes(bytes, slot + 0x1C, 18);
        WriteUInt16Bytes(bytes, slot + 0x1E, 64);
        WriteUInt32Bytes(bytes, slot + 0x20, 539);
        WriteUInt32Bytes(bytes, slot + 0x24, 1572);
        WriteFf7TextBytes(bytes, slot + 0x28, "No.1 Reactor", 32);
        WriteUInt32Bytes(
            bytes,
            slot,
            CalculateReferenceFf7SaveChecksum(bytes.AsSpan(slot + sizeof(uint), Ff7PcSaveFileReader.SlotSize - sizeof(uint))));
        File.WriteAllBytes(path, bytes);

        if (!Ff7PcSaveFileReader.TryReadSlot(path, 1, out var preview))
        {
            throw new InvalidOperationException("Expected the native PC save preview to be readable.");
        }

        AssertEqual(false, preview.IsEmpty, "occupied native save slot");
        AssertEqual("Cloud", preview.LeadCharacterName, "native save lead character");
        AssertEqual(8, preview.Level, "native save level");
        AssertEqual(296, preview.CurrentHp, "native save current HP");
        AssertEqual(334, preview.MaxHp, "native save maximum HP");
        AssertEqual(18, preview.CurrentMp, "native save current MP");
        AssertEqual(64, preview.MaxMp, "native save maximum MP");
        AssertEqual(539u, preview.Gil, "native save gil");
        AssertEqual(1572u, preview.PlaySeconds, "native save play time");
        AssertEqual("No.1 Reactor", preview.Location, "native save location");

        if (!Ff7PcSaveFileReader.TryReadSlot(path, 2, out var empty))
        {
            throw new InvalidOperationException("Expected an empty native PC save slot record.");
        }

        AssertEqual(true, empty.IsEmpty, "zeroed native save slot");

        var repository = new Ff7SaveFileRepository([directory]);
        AssertEqual(true, repository.HasData(1), "save data file with occupied game");
        AssertEqual(false, repository.HasData(2), "missing save data file");
    }
    finally
    {
        Directory.Delete(directory, true);
    }
}

