static void AssertSaveMenuStateReaderReadsEmptySlotsAndConfirmation()
{
    var memory = new MainMenuGuestMemory();
    memory.WriteInt32(SaveMenuStateReader.AddressMode, SaveMenuStateReader.SaveMode);
    memory.WriteInt32(SaveMenuStateReader.AddressPage, (int)SaveMenuPage.Games);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x00, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x04, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x08, 5);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x0C, 2);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x14, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x24, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x30, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x00, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x04, 1);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x08, 1);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x0C, 3);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x14, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x24, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x30, 0);
    memory.WriteUInt16(SaveMenuStateReader.AddressOccupancyMask, 1);
    memory.WriteUInt32(SaveMenuStateReader.AddressSlotBufferPointer, 0x01000000);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x00, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x04, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x08, 1);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x0C, 2);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x14, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x24, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x30, 0);

    var reader = new SaveMenuStateReader(memory);
    AssertEqual(true, reader.TryRead(out var empty), "checked in-game save page");
    AssertEqual(SaveMenuPage.Games, empty.Page, "in-game save game-list page");
    AssertEqual(1, empty.SaveFileNumber, "in-game save file number");
    AssertEqual(2, empty.GameNumber, "in-game empty game number");
    AssertEqual(true, empty.Preview?.IsEmpty, "in-game empty slot preview");

    var nativePreview = new byte[Ff7PcSaveFileReader.RuntimePreviewSize];
    nativePreview[0x04] = 8;
    WriteFf7TextBytes(nativePreview, 0x08, "Cloud", 16);
    WriteUInt16Bytes(nativePreview, 0x18, 296);
    WriteUInt16Bytes(nativePreview, 0x1A, 334);
    WriteUInt16Bytes(nativePreview, 0x1C, 18);
    WriteUInt16Bytes(nativePreview, 0x1E, 64);
    WriteUInt32Bytes(nativePreview, 0x20, 539);
    WriteUInt32Bytes(nativePreview, 0x24, 1572);
    WriteFf7TextBytes(nativePreview, 0x28, "No.1 Reactor", 32);
    memory.WriteBytes(SaveMenuStateReader.AddressSlotPreviewCache, nativePreview);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x04, 0);
    memory.WriteUInt32(SaveMenuStateReader.AddressSlotBufferPointer, 0);
    AssertEqual(true, reader.TryRead(out var occupied), "runtime-native occupied save preview");
    AssertEqual(false, occupied.Preview?.IsEmpty, "occupied live save slot");
    AssertEqual("Cloud", occupied.Preview?.LeadCharacterName, "live save preview lead character");
    AssertEqual("No.1 Reactor", occupied.Preview?.Location, "live save preview location");

    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x04, 3);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x0C, 4);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x30, 1);
    AssertEqual(true, reader.TryRead(out var fourthVisible), "alternate four-row save layout");
    AssertEqual(4, fourthVisible.GameNumber, "fourth visible save row remains selectable");

    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x04, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x0C, 3);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x30, 0);
    memory.WriteBytes(
        SaveMenuStateReader.AddressSlotPreviewCache,
        Enumerable.Repeat((byte)0xFF, Ff7PcSaveFileReader.RuntimePreviewSize).ToArray());
    memory.WriteInt32(SaveMenuStateReader.AddressPage, (int)SaveMenuPage.Confirmation);
    memory.WriteInt32(SaveMenuStateReader.AddressConfirmationWidget + 0x04, 1);
    AssertEqual(true, reader.TryRead(out var confirmation), "checked in-game save confirmation");
    AssertEqual(SaveMenuPage.Confirmation, confirmation.Page, "in-game save confirmation page");
    AssertEqual(1, confirmation.ConfirmationCursor, "native No confirmation selection");
}

static void AssertSaveMenuStateReaderKeepsNestedPageOwnershipWhenOuterMetadataIsInactive()
{
    var memory = new MainMenuGuestMemory();
    memory.WriteInt32(SaveMenuStateReader.AddressMode, SaveMenuStateReader.SaveMode);
    memory.WriteInt32(SaveMenuStateReader.AddressPage, (int)SaveMenuPage.SaveFiles);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x00, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x04, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x08, 5);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x0C, 2);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x14, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x24, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x30, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x00, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x04, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x08, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x0C, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x14, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x24, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressGameWidget + 0x30, 0);
    memory.WriteUInt16(SaveMenuStateReader.AddressOccupancyMask, 1);

    var nativePreview = new byte[Ff7PcSaveFileReader.RuntimePreviewSize];
    nativePreview[0x04] = 8;
    WriteFf7TextBytes(nativePreview, 0x08, "Cloud", 16);
    WriteUInt16Bytes(nativePreview, 0x18, 296);
    WriteUInt16Bytes(nativePreview, 0x1A, 334);
    WriteUInt16Bytes(nativePreview, 0x1C, 18);
    WriteUInt16Bytes(nativePreview, 0x1E, 64);
    WriteUInt32Bytes(nativePreview, 0x20, 539);
    WriteUInt32Bytes(nativePreview, 0x24, 1572);
    WriteFf7TextBytes(nativePreview, 0x28, "No.1 Reactor", 32);
    memory.WriteBytes(SaveMenuStateReader.AddressSlotPreviewCache, nativePreview);

    var reader = new SaveMenuStateReader(memory);
    AssertEqual(true, reader.TryRead(out var files), "active outer save-file grid");

    var now = new DateTime(2026, 7, 22, 2, 0, 0, DateTimeKind.Utc);
    var tracker = new SaveMenuSpeechTracker(TimeSpan.Zero);
    tracker.ObserveWidget(new ActiveMenuWidgetSnapshot(
        SaveMenuStateReader.AddressSaveFileWidget,
        "Save file grid",
        MenuWidgetKind.Generic,
        0,
        0,
        5,
        2,
        0,
        0,
        0));
    tracker.Observe(files, now);
    AssertEqual("Save 1.", tracker.Poll(now), "initial same-file save speech");

    // FUN_006FEDB0 uses the fixed file selectors while its nested pages own the menu.
    // The outer widget's shape metadata is not a native dependency on these pages.
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x08, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x0C, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressPage, (int)SaveMenuPage.Checking);
    var checkingRead = reader.TryRead(out var checking);
    memory.WriteInt32(SaveMenuStateReader.AddressPage, (int)SaveMenuPage.Games);
    var gameRead = reader.TryRead(out var game);

    AssertEqual(
        "True/True",
        $"{checkingRead}/{gameRead}",
        "nested Save pages use their native direct selectors");
    AssertEqual(SaveMenuPage.Checking, checking.Page, "checked Save page remains readable");
    AssertEqual("Cloud", game.Preview?.LeadCharacterName, "selected in-game Save details");

    tracker.Observe(checking, now.AddMilliseconds(10));
    AssertEqual("Checking save data.", tracker.Poll(now.AddMilliseconds(10)), "checked Save speech");
    tracker.Observe(game, now.AddMilliseconds(20));
    AssertContains(tracker.Poll(now.AddMilliseconds(20)) ?? string.Empty, "Cloud");

    memory.WriteInt32(SaveMenuStateReader.AddressPage, (int)SaveMenuPage.SaveFiles);
    AssertEqual(true, reader.TryRead(out var filesAgain), "outer Save page uses its native direct selectors");
    tracker.Observe(filesAgain, now.AddMilliseconds(30));
    AssertEqual("Save 1.", tracker.Poll(now.AddMilliseconds(30)), "same Save file reacquired immediately");
}

static void AssertSaveMenuStateReaderReadsOuterPageDuringWidgetTransition()
{
    var memory = new MainMenuGuestMemory();
    memory.WriteInt32(SaveMenuStateReader.AddressMode, SaveMenuStateReader.SaveMode);
    memory.WriteInt32(SaveMenuStateReader.AddressPage, (int)SaveMenuPage.SaveFiles);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x00, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x04, 0);

    // The animated widget geometry is still uninitialized, but FUN_006FEDB0
    // already owns the SaveFiles page and its direct selectors are coherent.
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x08, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x0C, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x14, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x24, 0);
    memory.WriteInt32(SaveMenuStateReader.AddressSaveFileWidget + 0x30, 0);

    var reader = new SaveMenuStateReader(memory);
    AssertEqual(
        true,
        reader.TryRead(out var snapshot),
        "SaveFiles remains readable while widget geometry is transitional");
    AssertEqual(SaveMenuPage.SaveFiles, snapshot.Page, "transitional outer Save page");
    AssertEqual(1, snapshot.SaveFileNumber, "transitional outer Save selection");

    var now = new DateTime(2026, 7, 22, 3, 0, 0, DateTimeKind.Utc);
    var tracker = new SaveMenuSpeechTracker(TimeSpan.Zero);
    tracker.ObserveWidget(new ActiveMenuWidgetSnapshot(
        SaveMenuStateReader.AddressSaveFileWidget,
