    memory.WriteInt32(TitleLoadMenuDataReader.AddressSaveFileWidget + 0x0C, 2);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressSaveFileWidget + 0x14, 0);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressSaveFileWidget + 0x24, 0);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressSaveFileWidget + 0x30, 0);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressGameWidget + 0x00, 0);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressGameWidget + 0x04, 0);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressGameWidget + 0x08, 1);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressGameWidget + 0x0C, 3);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressGameWidget + 0x14, 0);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressGameWidget + 0x24, 0);
    memory.WriteInt32(TitleLoadMenuDataReader.AddressGameWidget + 0x30, 0);
    memory.WriteUInt16(SaveMenuStateReader.AddressOccupancyMask, 1);

    var nativePreview = new byte[Ff7PcSaveFileReader.RuntimePreviewSize];
    nativePreview[0x04] = 8;
    WriteFf7TextBytes(nativePreview, 0x08, "Cloud", 16);
    WriteUInt16Bytes(nativePreview, 0x18, 296);
    WriteUInt16Bytes(nativePreview, 0x1A, 334);
    WriteUInt16Bytes(nativePreview, 0x1C, 18);
    WriteUInt16Bytes(nativePreview, 0x1E, 64);
    WriteUInt32Bytes(nativePreview, 0x20, 539);
    WriteUInt32Bytes(nativePreview, 0x24, 1572);
    WriteFf7TextBytes(nativePreview, 0x28, "No.1 Reactor", 32);
    memory.WriteBytes(SaveMenuStateReader.AddressSlotPreviewCache, nativePreview);

