static void AssertSaveMenuSpeechTracksPageOwnershipAndReacquiresOuterSlot()
{
    var now = new DateTime(2026, 7, 21, 22, 0, 0, DateTimeKind.Utc);
    var tracker = new SaveMenuSpeechTracker(TimeSpan.Zero);
    var saveWidget = new ActiveMenuWidgetSnapshot(
        SaveMenuStateReader.AddressSaveFileWidget,
        "Save file grid",
        MenuWidgetKind.Generic,
        0,
        0,
        5,
        2,
        0,
        0,
        0);

    tracker.ObserveWidget(saveWidget);
    tracker.ObserveWidget(saveWidget with
    {
        Address = SaveMenuStateReader.AddressGameWidget,
        Name = "Save game slot",
        Columns = 1,
        Rows = 3
    });
    AssertEqual(true, tracker.IsActive, "nested game widget retains save ownership");
    tracker.Observe(new SaveMenuStateSnapshot(
        SaveMenuPage.SaveFiles,
        1,
        0,
        null,
        0), now);
    AssertEqual("Save 1.", tracker.Poll(now), "initial in-game save file");

    tracker.Observe(new SaveMenuStateSnapshot(
        SaveMenuPage.Games,
        1,
        2,
        Ff7SaveSlotPreview.Empty,
        0), now.AddMilliseconds(10));
    AssertEqual("Game 2. Empty.", tracker.Poll(now.AddMilliseconds(10)), "empty in-game save slot");

    tracker.Observe(new SaveMenuStateSnapshot(
        SaveMenuPage.SaveFiles,
        1,
        0,
        null,
        0), now.AddMilliseconds(15));
    AssertEqual("Save 1.", tracker.Poll(now.AddMilliseconds(15)), "backing out reacquires the same save file");

    tracker.Observe(new SaveMenuStateSnapshot(
        SaveMenuPage.Games,
        1,
        2,
        Ff7SaveSlotPreview.Empty,
        0), now.AddMilliseconds(18));
    AssertEqual("Game 2. Empty.", tracker.Poll(now.AddMilliseconds(18)), "re-entering reacquires the same game slot");

    tracker.Observe(new SaveMenuStateSnapshot(
        SaveMenuPage.Confirmation,
        1,
        2,
        Ff7SaveSlotPreview.Empty,
        0), now.AddMilliseconds(20));
    var confirmationSpeech = tracker.Peek(now.AddMilliseconds(20))
        ?? throw new InvalidOperationException("Expected retained native save confirmation speech.");
    AssertEqual("Are you sure? Yes.", confirmationSpeech.Text, "save confirmation prompt and default choice");
    AssertEqual(
        confirmationSpeech,
        tracker.Peek(now.AddMilliseconds(21)),
        "unacknowledged save confirmation must retry unchanged");
    AssertEqual(true, tracker.Acknowledge(confirmationSpeech.Id), "accepted save confirmation speech");
    AssertNull(tracker.Peek(now.AddMilliseconds(22)), "accepted save confirmation must not repeat");

    tracker.Observe(new SaveMenuStateSnapshot(
        SaveMenuPage.Confirmation,
        1,
        2,
        Ff7SaveSlotPreview.Empty,
        1), now.AddMilliseconds(30));
    AssertEqual("No.", tracker.Poll(now.AddMilliseconds(30)), "changed save confirmation choice");

    tracker.Observe(new SaveMenuStateSnapshot(
        SaveMenuPage.SaveFiles,
        1,
        0,
        null,
        0), now.AddMilliseconds(40));
    AssertEqual("Save 1.", tracker.Poll(now.AddMilliseconds(40)), "outer save selection reacquired after backing out");

    tracker.ObserveWidget(saveWidget with
    {
        Address = 0x00DC1150,
        Name = "Item/Main list",
        Kind = MenuWidgetKind.RootMainMenu,
        Columns = 1,
        Rows = 11
    });
    AssertEqual(false, tracker.IsActive, "root menu revokes in-game save ownership");
}

static void AssertSaveMenuNestedWidgetsAcquireOwnershipWithoutOuterObservation()
{
    var now = new DateTime(2026, 8, 8, 1, 19, 0, DateTimeKind.Utc);
    var tracker = new SaveMenuSpeechTracker(TimeSpan.Zero);
    var gameWidget = new ActiveMenuWidgetSnapshot(
        SaveMenuStateReader.AddressGameWidget,
        "Save game slot",
        MenuWidgetKind.Generic,
        0,
        1,
        1,
        3,
        0,
        0,
        0);

    tracker.ObserveHostState(
        SaveMenuSpeechTracker.InGameMenuModule,
        isForeground: true,
        isNameEntryActive: false,
        gameWidget);
    AssertEqual(true, tracker.IsActive, "exact nested Save game widget acquires ownership");
    tracker.Observe(
        new SaveMenuStateSnapshot(SaveMenuPage.Games, 1, 2, Ff7SaveSlotPreview.Empty, 0),
        now);
