static void AssertNameEntryNativeNameTrackerSpeaksActualSlotContents()
{
    var tracker = new NameEntryNativeNameTracker(TimeSpan.FromMilliseconds(750));
    var now = new DateTime(2026, 7, 11, 0, 0, 0, DateTimeKind.Utc);
    var buffer = new byte[]
    {
        0x23, // C
        0x4C, // l
        0x4F, // o
        0x55, // u
        0x44, // d
        0xFF,
        0xFF,
        0x00,
        0x00
    };

    AssertNull(
        tracker.Observe(active: true, focus: 0, gridColumn: 0, gridRow: 0, commandRow: 0, selectedSlot: 5, buffer: buffer, now: now),
        "initial native name snapshot should not interrupt the prompt");
    AssertNull(
        tracker.Observe(active: true, focus: 0, gridColumn: 0, gridRow: 0, commandRow: 0, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(700)),
        "top name row should wait until the prompt has had time to speak");
    AssertEqual(
        "Current name: Cloud. Character grid: capital A.",
        tracker.Observe(active: true, focus: 0, gridColumn: 0, gridRow: 0, commandRow: 0, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(750)),
        "entry speech should read the complete name without enumerating its slots");

    AssertEqual(
        "Character grid: capital B.",
        tracker.Observe(active: true, focus: 0, gridColumn: 1, gridRow: 0, commandRow: 0, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(775)),
        "native grid column movement should read the actual character grid");

    AssertEqual(
        "Character grid: capital L.",
        tracker.Observe(active: true, focus: 0, gridColumn: 1, gridRow: 1, commandRow: 0, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(790)),
        "native grid row movement should read the actual character grid");

    AssertEqual(
        "Character grid: lowercase b.",
        tracker.Observe(active: true, focus: 0, gridColumn: 1, gridRow: 3, commandRow: 0, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(792)),
        "the lowercase alphabet block must be distinguishable from the uppercase block in speech");

    AssertEqual(
        "Character grid: 9.",
        tracker.Observe(active: true, focus: 0, gridColumn: 9, gridRow: 6, commandRow: 0, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(793)),
        "the final numeric cell must read 9 rather than the adjacent Default command");

    AssertEqual(
        "Command: Default.",
        tracker.Observe(active: true, focus: 1, gridColumn: 9, gridRow: 6, commandRow: 3, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(794)),
        "Default should speak only after native focus enters the command column");

    AssertEqual(
        "Command: Select.",
        tracker.Observe(active: true, focus: 1, gridColumn: 1, gridRow: 1, commandRow: 2, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(795)),
        "native command focus should read the actual command row");

    buffer[5] = 0x43;
    AssertEqual(
        "Name slot 6: lowercase c.",
        tracker.Observe(active: true, focus: 1, gridColumn: 1, gridRow: 1, commandRow: 2, selectedSlot: 6, buffer: buffer, now: now.AddMilliseconds(800)),
        "typing should announce the actual letter written to the top-row slot");

    AssertEqual(
        "Name slot 1: capital C.",
        tracker.Observe(active: true, focus: 1, gridColumn: 1, gridRow: 1, commandRow: 2, selectedSlot: 0, buffer: buffer, now: now.AddMilliseconds(850)),
        "moving the native insertion position should read that top-row slot's actual letter");

    buffer[5] = 0xFF;
    AssertEqual(
        "Name slot 6: empty.",
        tracker.Observe(active: true, focus: 1, gridColumn: 1, gridRow: 1, commandRow: 2, selectedSlot: 5, buffer: buffer, now: now.AddMilliseconds(900)),
        "deleting should announce that the native top-row slot is empty");

    AssertNull(
        tracker.Observe(active: false, focus: 0, gridColumn: 0, gridRow: 0, commandRow: 0, selectedSlot: 0, buffer: buffer, now: now.AddMilliseconds(950)),
        "name slot tracker should reset outside the native naming screen");

    AssertEqual(10, NameEntryNativeNameTracker.RecommendedScanIntervalMs, "name entry scan interval should capture one-frame selections");
}

