static void AssertBattleHookAddressResolverUsesFfnxCallChain()
{
    var bytes = new Dictionary<int, byte>();
    var ints = new Dictionary<int, int>();
    const int updateDisplayText = 0x00510000;
    const int setBattleTextActive = 0x00610000;
    WriteRelativeCall(
        bytes,
        ints,
        BattleHookAddressResolver.AddressUpdateDisplayTextCall,
        updateDisplayText);
    WriteRelativeCall(
        bytes,
        ints,
        updateDisplayText + BattleHookAddressResolver.SetBattleTextActiveCallOffset,
        setBattleTextActive);

    var resolver = new BattleHookAddressResolver(
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0,
        address => ints.TryGetValue(address, out var value) ? value : 0);

    AssertEqual(true, resolver.TryResolveBattleTextActive(out var actual), "battle text hook call-chain resolution");
    AssertEqual(setBattleTextActive, actual, "battle text active hook address");

    bytes[BattleHookAddressResolver.AddressUpdateDisplayTextCall] = 0x90;
    AssertEqual(false, resolver.TryResolveBattleTextActive(out _), "battle text hook must reject a non-call root");
}

static void AssertBattleHookDelegatesHaveReloadedFunctionAttributes()
{
    foreach (var type in new[]
    {
        typeof(BattleMenuRenderDelegate),
        typeof(BattleUpdateDelegate),
        typeof(BattleTextActiveDelegate),
        typeof(BattleResultsUpdateDelegate),
        typeof(BattleDamageDisplayDelegate)
    })
    {
        var attribute = type.GetCustomAttributes(
            typeof(Reloaded.Hooks.Definitions.X86.FunctionAttribute),
            inherit: false);
        if (attribute.Length == 0)
        {
            throw new InvalidOperationException($"{type.Name} must be marked with Reloaded x86 FunctionAttribute.");
        }
    }
}

