static void AssertActiveMenuWidgetReaderReadsCompleteNativeSelector()
{
    var memory = new Dictionary<int, int>
    {
        [0x00DD1708] = 1,
        [0x00DD170C] = 2,
        [0x00DD1710] = 3,
        [0x00DD1714] = 7,
        [0x00DD171C] = 4,
        [0x00DD172C] = -3,
        [0x00DD1738] = 2
    };
    var reader = new ActiveMenuWidgetReader(address => memory.TryGetValue(address, out var value) ? value : 0);

    var snapshot = reader.Read(0x00DD1708);

    AssertEqual(0x00DD1708u, snapshot.Address, "active widget reader should retain the native pointer");
    AssertEqual(MenuWidgetKind.MagicList, snapshot.Kind, "active widget reader should resolve the native widget kind");
    AssertEqual(1, snapshot.First, "active widget reader should read the native column field");
    AssertEqual(2, snapshot.Cursor, "active widget reader should read the native row field");
    AssertEqual(3, snapshot.Columns, "active widget reader should read native columns");
    AssertEqual(7, snapshot.Rows, "active widget reader should read native rows");
    AssertEqual(4, snapshot.ScrollOffset, "active widget reader should read the scroll offset");
    AssertEqual(-3, snapshot.ScrollDelta, "active widget reader should read the scroll delta");
    AssertEqual(2, snapshot.ScrollState, "active widget reader should read the native scroll state");
}

