static void AssertActiveMenuWidgetBridgeCapturesFrameBeforeNativeUpdate()
{
    var memory = new Dictionary<int, int>
    {
        [0x00DD1698] = 0,
        [0x00DD169C] = 0,
        [0x00DD16A0] = 1,
        [0x00DD16A4] = 3
    };
    var reader = new ActiveMenuWidgetReader(address => memory.TryGetValue(address, out var value) ? value : 0);
    var coordinator = new ActiveMenuFrameSpeechCoordinator();
    var bridge = new ActiveMenuWidgetFrameBridge(reader, coordinator);
    coordinator.ObserveDraw(new MenuTextRenderEntry("Magic", 508, 56, 7, 0x3DCED917));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 450, 62, 0x3DCCCCCD));

    var captured = bridge.CompleteBeforeUpdate(
        0x00DD1698,
        DateTime.UtcNow,
        () => memory[0x00DD169C] = 1);

    AssertEqual(0, captured?.Cursor, "active widget bridge should capture the cursor before FFVII updates it");
    AssertEqual(1, memory[0x00DD169C], "active widget bridge should still invoke the native update");
    AssertEqual("Magic", coordinator.Poll(), "pre-update frame should retain its matching rendered category");
}

