static void AssertActiveMenuFrameScopesRepeatSuppressionByWidget()
{
    var coordinator = new ActiveMenuFrameSpeechCoordinator();
    var command = new ActiveMenuWidgetSnapshot(
        0x00DCA1D0, "Limit command", MenuWidgetKind.Generic,
        0, 0, 2, 1, 0, 0, 0);
    var level = new ActiveMenuWidgetSnapshot(
        0x00DCA198, "Limit level", MenuWidgetKind.Generic,
        0, 0, 2, 2, 0, 0, 0);

    coordinator.ObserveDraw(new MenuTextRenderEntry("Set", 337, 81, 7, 0x3DCCCCCD));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 293, 84, 0x3DCCCCCD));
    coordinator.CompleteFrame(command, DateTime.UtcNow);
    AssertEqual("Set", coordinator.Poll(), "Limit command should speak once");

    coordinator.ObserveDraw(new MenuTextRenderEntry("LEVEL 1", 56, 193, 7, 0x3E99999A));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 0, 201, 0x3DCCCCCD));
    coordinator.CompleteFrame(level, DateTime.UtcNow.AddMilliseconds(16));
    AssertEqual("LEVEL 1", coordinator.Poll(), "Limit level should speak once");

    coordinator.ObserveDraw(new MenuTextRenderEntry("Set", 337, 81, 7, 0x3DCCCCCD));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 293, 84, 0x3DCCCCCD));
    coordinator.CompleteFrame(command, DateTime.UtcNow.AddMilliseconds(32));
    AssertNull(coordinator.Poll(), "a second stable Limit widget must not reset command repeat suppression");

    coordinator.ObserveDraw(new MenuTextRenderEntry("LEVEL 1", 56, 193, 7, 0x3E99999A));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 0, 201, 0x3DCCCCCD));
    coordinator.CompleteFrame(level, DateTime.UtcNow.AddMilliseconds(48));
    AssertNull(coordinator.Poll(), "stable Limit levels must not alternate repeatedly with the command widget");
}

static void AssertActiveMenuFrameKeepsRepeatSuppressionAcrossPartialFrames()
{
    var coordinator = new ActiveMenuFrameSpeechCoordinator();
    var level = new ActiveMenuWidgetSnapshot(
        0x00DCA198, "Limit set level", MenuWidgetKind.LimitLevel,
        0, 0, 2, 2, 0, 0, 0);

