    coordinator.CompleteFrame(level, DateTime.UtcNow);
    AssertEqual("LEVEL 1", coordinator.Poll(), "Limit level should speak on its first complete frame");

    coordinator.CompleteFrame(level, DateTime.UtcNow.AddMilliseconds(16));
    AssertNull(coordinator.Poll(), "a blank partial frame should stay silent");

    coordinator.ObserveDraw(new MenuTextRenderEntry("LEVEL 1", 56, 193, 7, 0x3E99999A));
