static void AssertActiveMenuFrameKeepsLimitHistoryAcrossRootFrames()
{
    var coordinator = new ActiveMenuFrameSpeechCoordinator();
    var root = new ActiveMenuWidgetSnapshot(
        0x00DC1150, "Item/Main list", MenuWidgetKind.RootMainMenu,
        0, 6, 1, 11, 0, 0, 0);
    var command = new ActiveMenuWidgetSnapshot(
        0x00DCA1D0, "Limit command", MenuWidgetKind.LimitCommand,
        1, 0, 2, 1, 0, 0, 0);
    var level = new ActiveMenuWidgetSnapshot(
        0x00DCA208, "Limit check level", MenuWidgetKind.LimitLevel,
        0, 0, 2, 2, 0, 0, 0);
    var now = DateTime.UtcNow;

    coordinator.ObserveDraw(new MenuTextRenderEntry("Check", 417, 81, 7, 0x3DCCCCCD));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 373, 84, 0x3DCCCCCD));
    coordinator.CompleteFrame(command, now);
    AssertEqual("Check", coordinator.Poll(), "Limit command should speak before entering Check");

    coordinator.CompleteFrame(root, now.AddMilliseconds(16));
    coordinator.ObserveDraw(new MenuTextRenderEntry("LEVEL 1", 56, 193, 7, 0x3E99999A));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 0, 201, 0x3DCCCCCD));
    coordinator.CompleteFrame(level, now.AddMilliseconds(32));
    AssertEqual("LEVEL 1", coordinator.Poll(), "Limit level should speak after entering Check");

    coordinator.CompleteFrame(root, now.AddMilliseconds(48));
    coordinator.ObserveDraw(new MenuTextRenderEntry("Check", 417, 81, 7, 0x3DCCCCCD));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 373, 84, 0x3DCCCCCD));
    coordinator.CompleteFrame(command, now.AddMilliseconds(64));
    AssertNull(coordinator.Poll(), "background root frames must not make the stable Limit command repeat");

    coordinator.CompleteFrame(root, now.AddMilliseconds(80));
    coordinator.ObserveDraw(new MenuTextRenderEntry("LEVEL 1", 56, 193, 7, 0x3E99999A));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 0, 201, 0x3DCCCCCD));
    coordinator.CompleteFrame(level, now.AddMilliseconds(96));
    AssertNull(coordinator.Poll(), "background root frames must not make the stable Limit level repeat");

    coordinator.ObserveDraw(new MenuTextRenderEntry("Check", 417, 81, 7, 0x3DCCCCCD));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 373, 84, 0x3DCCCCCD));
    coordinator.CompleteFrame(command, now.AddMilliseconds(700));
    AssertEqual("Check", coordinator.Poll(), "a Limit command should speak again after its widget has been inactive");
}

static void AssertActiveMenuFrameReadsNativeLimitCommandWithoutCursorDraw()
{
    var coordinator = new ActiveMenuFrameSpeechCoordinator();
    var command = new ActiveMenuWidgetSnapshot(
        0x00DCA1D0, "Limit command", MenuWidgetKind.LimitCommand,
        0, 0, 2, 1, 0, 0, 0);
