    coordinator.ObserveDraw(new MenuTextRenderEntry("[SWITCH]\"Attacks one opponent", 42, 133, 7, 0x3DCED917));
    coordinator.ObserveDraw(new MenuTextRenderEntry("[SWITCH]\"Braver", 75, 219, 7, 0x3DCED917));
    coordinator.ObserveCursor(new MenuCursorDrawObservation("B", 5, 28, 225, 0));
    coordinator.CompleteFrame(widget, now.AddMilliseconds(48));
    AssertNull(coordinator.Poll(), "a stable learned Limit move should not repeat");
}

static void AssertActiveMenuFrameReadsLimitConfirmation()
{
    AssertEqual(
        true,
        Enum.TryParse<MenuWidgetKind>("LimitConfirmation", out var confirmationKind),
        "Limit confirmation kind should exist");

    var coordinator = new ActiveMenuFrameSpeechCoordinator();
    var now = DateTime.UtcNow;
    var noWidget = new ActiveMenuWidgetSnapshot(
        0x00DCA278,
        "Limit level confirmation",
        confirmationKind,
        0,
        1,
        1,
        2,
        0,
        0,
        0);

    AddLimitConfirmationFrame(
        coordinator,
        "To change BREAK LEVEL,",
        "it will begin from Limit Point 0.",
        "Change BREAK LEVEL?",
        "Yes",
        "No");
    coordinator.CompleteFrame(noWidget, now);
    AssertEqual(
        "To change BREAK LEVEL, it will begin from Limit Point 0. Change BREAK LEVEL? No",
        coordinator.Poll(),
        "opening Limit confirmation should read its warning, question, and native No selection");

    AddLimitConfirmationFrame(
        coordinator,
        "To change BREAK LEVEL,",
        "it will begin from Limit Point 0.",
        "Change BREAK LEVEL?",
        "Yes",
        "No");
    coordinator.CompleteFrame(noWidget with { Cursor = 0 }, now.AddMilliseconds(16));
    AssertEqual(
        "Yes",
        coordinator.Poll(),
        "moving through the Limit confirmation should read only the newly selected choice");

    AddLimitConfirmationFrame(
        coordinator,
        "Aby zmienić POZIOM LIMITU,",
        "punkty limitu zostaną wyzerowane.",
        "Zmienić POZIOM LIMITU?",
        "Tak",
        "Nie");
    coordinator.CompleteFrame(noWidget with { Cursor = 1 }, now.AddMilliseconds(32));
    AssertEqual(
        "Nie",
        coordinator.Poll(),
        "Limit confirmation choices should come from the rendered game language");

    AddLimitConfirmationFrame(
        coordinator,
        "Aby zmienić POZIOM LIMITU,",
        "punkty limitu zostaną wyzerowane.",
        "Zmienić POZIOM LIMITU?",
        "Tak",
        "Nie");
    coordinator.CompleteFrame(noWidget with { Cursor = 1 }, now.AddMilliseconds(48));
    AssertNull(coordinator.Poll(), "stable Limit confirmation selection should not repeat");

    coordinator.CompleteFrame(
        noWidget with
        {
            Address = 0x00DCA240,
            Name = "Limit move list",
            Kind = MenuWidgetKind.LimitMoveList
        },
        now.AddMilliseconds(64));
    AssertNull(coordinator.Poll(), "closing the Limit confirmation does not leave stale speech");

    AddLimitConfirmationFrame(
        coordinator,
        "Aby zmienić POZIOM LIMITU,",
        "punkty limitu zostaną wyzerowane.",
        "Zmienić POZIOM LIMITU?",
        "Tak",
        "Nie");
    coordinator.CompleteFrame(noWidget with { Cursor = 1 }, now.AddMilliseconds(80));
    AssertEqual(
        "Aby zmienić POZIOM LIMITU, punkty limitu zostaną wyzerowane. Zmienić POZIOM LIMITU? Nie",
        coordinator.Poll(),
        "reopening the Limit confirmation should read the full prompt again");
}

static void AddLimitConfirmationFrame(
    ActiveMenuFrameSpeechCoordinator coordinator,
    string warning,
    string consequence,
    string question,
    string yes,
    string no)
{
    coordinator.ObserveDraw(new MenuTextRenderEntry(warning, 177, 75, 7, 0));
    coordinator.ObserveDraw(new MenuTextRenderEntry(consequence, 177, 109, 7, 0));
    coordinator.ObserveDraw(new MenuTextRenderEntry(question, 177, 143, 7, 0));
    coordinator.ObserveDraw(new MenuTextRenderEntry(yes, 297, 178, 7, 0));
    coordinator.ObserveDraw(new MenuTextRenderEntry(no, 297, 203, 7, 0));
}

static void AssertMateriaTutorialSpeechReadsNativeInstructionsOnce()
{
    var tracker = new MateriaTutorialSpeechTracker();
    var now = new DateTime(2026, 7, 17, 17, 52, 27, DateTimeKind.Utc);
    var instruction = new MenuTextRenderEntry(
        "Sure, I'll explain how Materia works.",
        23,
        23,
        7,
        0);
    var sentinel = new MenuTextRenderEntry("Tutorial", 66, 431, 4, 0);

    tracker.Observe(instruction, currentModule: 5, now);
    AssertEqual(true, tracker.IsActive(now), "a native tutorial instruction should immediately suppress generic menu speech");
    AssertNull(tracker.Poll(now), "the first instruction should wait for the native Tutorial sentinel");

    tracker.Observe(sentinel, currentModule: 5, now.AddMilliseconds(50));
    AssertEqual(
        instruction.Text,
        tracker.Poll(now.AddMilliseconds(50)),
        "the native Tutorial sentinel should confirm and speak the pending instruction");

    tracker.Observe(instruction, currentModule: 5, now.AddMilliseconds(100));
    tracker.Observe(sentinel, currentModule: 5, now.AddMilliseconds(110));
    AssertNull(
        tracker.Poll(now.AddMilliseconds(110)),
        "a tutorial instruction redrawn every frame must speak only once");

    tracker.Observe(new MenuTextRenderEntry("Materia", 508, 13, 7, 0x3A83126F), 5, now.AddSeconds(3));
    AssertEqual(false, tracker.IsActive(now.AddSeconds(3)), "tutorial ownership should end after native evidence disappears");
}

static void AssertMateriaTutorialSpeechQueuesEveryNewInstructionLine()
{
    var tracker = new MateriaTutorialSpeechTracker();
    var now = new DateTime(2026, 7, 17, 17, 53, 0, DateTimeKind.Utc);
    tracker.Observe(new MenuTextRenderEntry("Tutorial", 66, 431, 4, 0), 5, now);
    tracker.Observe(new MenuTextRenderEntry("Directional buttons move the cursor,", 53, 73, 7, 0), 5, now.AddMilliseconds(10));
    tracker.Observe(new MenuTextRenderEntry("Select each menu by using [OK].", 53, 93, 7, 0), 5, now.AddMilliseconds(20));

    AssertEqual(
        "Directional buttons move the cursor,",
        tracker.Poll(now.AddMilliseconds(20)),
        "the first newly rendered tutorial line should retain visual order");
    AssertEqual(
        "Select each menu by using [OK].",
        tracker.Poll(now.AddMilliseconds(20)),
        "subsequent lines on the same tutorial page should be queued instead of interrupting one another");
    AssertNull(tracker.Poll(now.AddMilliseconds(20)), "a completed tutorial page should not leave duplicate speech");

    tracker.Observe(new MenuTextRenderEntry("First, access the menu.", 23, 23, 7, 0), 1, now.AddMilliseconds(30));
    AssertNull(tracker.Poll(now.AddMilliseconds(30)), "tutorial text outside FFVII's menu module must be ignored");
}

static void AssertConfigMenuValueReaderReadsNativeSettings()
{
    var bytes = new Dictionary<int, byte>
    {
        [ConfigMenuValueReader.AddressBattleSpeed] = 0,
        [ConfigMenuValueReader.AddressBattleMessageSpeed] = 128,
        [ConfigMenuValueReader.AddressFieldMessageSpeed] = 255
    };
    var settings = (ushort)((1 << 2) | (1 << 4) | (2 << 6) | (1 << 8));
    var reader = new ConfigMenuValueReader(
        address => bytes.TryGetValue(address, out var value) ? value : (byte)0,
        address => address == ConfigMenuValueReader.AddressSettingsBits ? settings : (ushort)0,
        _ => 0);

    AssertEqual("Customize", reader.ReadMainValue("Controller")?.Text, "Controller should use the selected native setting");
    AssertEqual("Memory", reader.ReadMainValue("Cursor")?.Text, "Cursor should use the selected native setting");
    AssertEqual("Wait", reader.ReadMainValue("ATB")?.Text, "ATB should use the selected native setting");
    AssertEqual("Fixed", reader.ReadMainValue("Camera angle")?.Text, "Camera should use the selected native setting");
    AssertEqual("0 percent from Fast to Slow", reader.ReadMainValue("Battle speed")?.Text, "Battle speed should report its native slider position");
    AssertEqual("50 percent from Fast to Slow", reader.ReadMainValue("Battle message")?.Text, "Battle message should report its native slider position");
    AssertEqual("100 percent from Fast to Slow", reader.ReadMainValue("Field message")?.Text, "Field message should report its native slider position");
    AssertNull(reader.ReadMainValue("Sound"), "Sound opens a native modal and should keep its rendered command on the main Config screen");
}

static void AssertConfigMenuValueReaderRejectsInvalidSettings()
{
    var settings = (ushort)((3 << 2) | (3 << 4) | (3 << 6) | (3 << 8));
    var reader = new ConfigMenuValueReader(
        _ => 0,
        address => address == ConfigMenuValueReader.AddressSettingsBits ? settings : (ushort)0,
        _ => 0);

    AssertNull(reader.ReadMainValue("Controller"), "invalid native Controller bits should remain silent");
    AssertNull(reader.ReadMainValue("Cursor"), "invalid native Cursor bits should remain silent");
    AssertNull(reader.ReadMainValue("ATB"), "invalid native ATB bits should remain silent");
    AssertNull(reader.ReadMainValue("Camera angle"), "invalid native Camera bits should remain silent");
}

static void AssertConfigMenuValueReaderReadsSoundModalValues()
{
    var values = new Dictionary<int, int>
    {
        [ConfigMenuValueReader.AddressSoundModalState] = 9,
        [ConfigMenuValueReader.AddressMusicVolume] = 73,
        [ConfigMenuValueReader.AddressSoundEffectsVolume] = 42
    };
    var reader = new ConfigMenuValueReader(
        _ => 0,
        _ => 0,
        address => values.TryGetValue(address, out var value) ? value : 0);

    AssertNull(reader.ReadSoundVolume(0), "Sound volume rows should stay silent outside the native Sound modal state");

    values[ConfigMenuValueReader.AddressSoundModalState] = ConfigMenuValueReader.SoundModalActiveState;
    AssertEqual("Music volume, 73 percent", reader.ReadSoundVolume(0)?.Text, "Sound row zero should read native MusicVolume");
    AssertEqual("Sound effects volume, 42 percent", reader.ReadSoundVolume(1)?.Text, "Sound row one should read native SFXVolume");
    AssertNull(reader.ReadSoundVolume(2), "unknown Sound modal rows should remain silent");

    values[ConfigMenuValueReader.AddressMusicVolume] = 101;
    AssertNull(reader.ReadSoundVolume(0), "out-of-range native volume values should remain silent");
}

static void AssertActiveMenuFrameReadsChangingSoundVolume()
{
    var coordinator = new ActiveMenuFrameSpeechCoordinator();
    var widget = new ActiveMenuWidgetSnapshot(
        0x00DC1088, "Config sound volume", MenuWidgetKind.ConfigSoundVolume,
        0, 0, 1, 2, 0, 0, 0,
        NativeSelection: new NativeMenuSelection("Music volume, 73 percent", null, "config-sound:0:73"));

    coordinator.CompleteFrame(widget, DateTime.UtcNow);
    AssertEqual("Music volume, 73 percent", coordinator.Poll(), "Sound modal should use its native row and value");

    coordinator.CompleteFrame(widget with
    {
        NativeSelection = new NativeMenuSelection("Music volume, 74 percent", null, "config-sound:0:74")
    }, DateTime.UtcNow.AddMilliseconds(16));
    AssertEqual("Music volume, 74 percent", coordinator.Poll(), "changing a Sound value should speak without moving the cursor");

    coordinator.CompleteFrame(widget with
    {
        NativeSelection = new NativeMenuSelection("Music volume, 74 percent", null, "config-sound:0:74")
    }, DateTime.UtcNow.AddMilliseconds(32));
    AssertNull(coordinator.Poll(), "a stable Sound value should not repeat");
}

static void AssertMagicMenuSelectionReaderReadsLiveSpellRecord()
{
    const int widgetAddress = 0x00DD1708;
    var memory = new Dictionary<int, byte>();
    memory[MagicMenuSelectionReader.AddressSelectedPartySlot] = 1;
    WriteUInt16(
        memory,
        MagicMenuSelectionReader.AddressCurrentMp + MagicMenuSelectionReader.CharacterBlockSize,
        40);
    WriteUInt32(memory, widgetAddress + 0x00, 0);
    WriteUInt32(memory, widgetAddress + 0x04, 1);
    WriteUInt32(memory, widgetAddress + 0x08, 3);
    WriteUInt32(memory, widgetAddress + 0x0C, 7);
    WriteUInt32(memory, widgetAddress + 0x14, 2);
    WriteUInt32(memory, widgetAddress + 0x24, 0);
    WriteUInt32(memory, widgetAddress + 0x30, 0);
    var record = MagicMenuSelectionReader.AddressMagicRecords +
        MagicMenuSelectionReader.CharacterBlockSize +
        (9 * MagicMenuSelectionReader.RecordSize);
    memory[record] = 30;
    memory[record + MagicMenuSelectionReader.MpCostOffset] = 7;
    var widget = new ActiveMenuWidgetSnapshot(
        widgetAddress, "Magic list", MenuWidgetKind.MagicList,
        0, 1, 3, 7, 2, 0, 0);

    MagicMenuSelectionReader CreateReader(Func<int, int, byte, byte>? transform = null)
    {
        var readCounts = new Dictionary<int, int>();
        byte ReadByteValue(int address)
        {
            var value = memory.TryGetValue(address, out var candidate) ? candidate : (byte)0;
            readCounts[address] = readCounts.GetValueOrDefault(address) + 1;
            return transform?.Invoke(address, readCounts[address], value) ?? value;
        }

        ushort ReadUInt16Value(int address) =>
            (ushort)(ReadByteValue(address) | (ReadByteValue(address + 1) << 8));
        int ReadInt32Value(int address) =>
            ReadByteValue(address) |
            (ReadByteValue(address + 1) << 8) |
            (ReadByteValue(address + 2) << 16) |
            (ReadByteValue(address + 3) << 24);
        bool IsReadable(int address, int length) =>
            address > 0 &&
            length > 0 &&
            (long)address + length <= (long)int.MaxValue + 1 &&
            Enumerable.Range(0, length).All(offset => memory.ContainsKey(address + offset));

        return new MagicMenuSelectionReader(
            ReadByteValue,
            ReadUInt16Value,
            ReadInt32Value,
            IsReadable,
            id => id is 30 or 31 ? "Native spell" : null,
            id => id == 30 ? "Ice element attack" : null);
    }

    var reader = CreateReader();

    AssertEqual(true, reader.TryRead(widget, out var spell), "live Magic reader should resolve the selected native record");
    AssertEqual(30, spell.SpellId, "live Magic reader should preserve the native spell id");
    AssertEqual(7, spell.MpCost, "live Magic reader should read the adjusted MP cost at record offset +1");
    AssertEqual("Native spell", spell.Name, "live Magic reader should resolve the native spell name");
    AssertEqual("Ice element attack", spell.Description, "live Magic reader should resolve the native spell description");

    memory[record] = 0xFF;
    AssertEqual(false, reader.TryRead(widget, out _), "an empty native Magic record should remain silent");
    memory[record] = 30;

    memory.Remove(record + MagicMenuSelectionReader.MpCostOffset);
    AssertEqual(false, CreateReader().TryRead(widget, out _), "an unreadable native Magic cost should remain silent");
    memory[record + MagicMenuSelectionReader.MpCostOffset] = 7;

    AssertEqual(
        false,
        CreateReader((address, count, value) => address == record && count > 1 ? (byte)31 : value)
            .TryRead(widget, out _),
        "a torn native Magic spell id should remain silent");
    AssertEqual(
        false,
        CreateReader((address, count, value) =>
                address == record + MagicMenuSelectionReader.MpCostOffset && count > 1 ? (byte)8 : value)
            .TryRead(widget, out _),
        "a torn native Magic cost should remain silent");
    AssertEqual(
        false,
        CreateReader((address, count, value) =>
                address == MagicMenuSelectionReader.AddressCurrentMp + MagicMenuSelectionReader.CharacterBlockSize && count > 1
                    ? (byte)(value + 1)
                    : value)
            .TryRead(widget, out _),
        "torn current MP should invalidate native Magic speech");
    AssertEqual(
        false,
        CreateReader((address, count, value) => address == widgetAddress + 0x04 && count > 1 ? (byte)2 : value)
            .TryRead(widget, out _),
        "a torn native Magic cursor should remain silent");
}

static void AssertMagicMenuSelectionReaderReadsStableEmptySlots()
{
    const int widgetAddress = 0x00DD1778;
    const int selectedIndex = 21;
    var memory = new Dictionary<int, byte>();
    memory[MagicMenuSelectionReader.AddressSelectedPartySlot] = 0;
    WriteUInt16(memory, MagicMenuSelectionReader.AddressCurrentMp, 40);
    WriteUInt32(memory, widgetAddress + 0x00, 1);
    WriteUInt32(memory, widgetAddress + 0x04, 10);
    WriteUInt32(memory, widgetAddress + 0x08, 2);
    WriteUInt32(memory, widgetAddress + 0x0C, 12);
    WriteUInt32(memory, widgetAddress + 0x14, 0);
    WriteUInt32(memory, widgetAddress + 0x24, 0);
    WriteUInt32(memory, widgetAddress + 0x30, 0);
    var recordAddress = MagicMenuSelectionReader.AddressEnemySkillRecords +
        (selectedIndex * MagicMenuSelectionReader.RecordSize);
    memory[recordAddress] = 0xFF;
    memory[recordAddress + MagicMenuSelectionReader.MpCostOffset] = 0;
    var widget = new ActiveMenuWidgetSnapshot(
        widgetAddress,
        "Enemy Skill list",
        MenuWidgetKind.EnemySkillList,
        1,
        10,
        2,
        12,
        0,
        0,
        0);
    var reader = new MagicMenuSelectionReader(
        new DictionaryLegacyAddressSpace(memory),
        id => id == 0x52 ? "Matra Magic" : null,
        id => id == 0x52 ? "Damages all enemies" : null);

    AssertEqual(
        true,
        reader.TryReadSlot(widget, out var empty),
        "a stable late Enemy Skill cell is readable even when empty");
    AssertEqual(true, empty.IsEmpty, "native 0xFF Enemy Skill record is empty");
    AssertEqual(selectedIndex, empty.Slot, "Enemy Skill empty slot keeps its two-column grid index");

    memory[recordAddress] = 10;
    memory[recordAddress + MagicMenuSelectionReader.MpCostOffset] = 8;
    AssertEqual(true, reader.TryReadSlot(widget, out var learned), "learned Enemy Skill cell is readable");
    AssertEqual(false, learned.IsEmpty, "learned Enemy Skill cell is not empty");
    AssertEqual("Matra Magic", learned.Spell.Name, "Enemy Skill local id uses the native 0x48 action base");

    memory[recordAddress] = 0xFF;
    var tearing = new MagicMenuSelectionReader(
        new TearingLegacyAddressSpace(memory, (uint)recordAddress),
        _ => null,
        _ => null);
    AssertEqual(
        false,
        tearing.TryReadSlot(widget, out _),
        "a torn Enemy Skill record must not be announced as empty");
}

