    tracker.ObserveDraw(new MenuTextRenderEntry("Fast", 264, 307, 7, 0x3DCCCCCD), now.AddMilliseconds(4));
    tracker.ObserveDraw(new MenuTextRenderEntry("Slow", 526, 307, 7, 0x3DCCCCCD), now.AddMilliseconds(4));

