static void AssertStaticMenuCursorSpeechReadsQuitChoices()
{
    var now = new DateTime(2026, 7, 10, 20, 1, 0, DateTimeKind.Utc);
    var tracker = new StaticMenuCursorSpeechTracker(TimeSpan.FromMilliseconds(30));

    AddQuitFrame(tracker, now, 364);
    AssertEqual("No", tracker.Poll(now.AddMilliseconds(40)), "Quit cursor x=364 should read the native No choice");

    AddQuitFrame(tracker, now.AddMilliseconds(100), 162);
    AssertEqual("Yes", tracker.Poll(now.AddMilliseconds(140)), "Quit cursor x=162 should read the native Yes choice");

    AddQuitFrame(tracker, now.AddMilliseconds(180), 162);
    AssertNull(tracker.Poll(now.AddMilliseconds(220)), "a stable Quit choice should not repeat");

    AddQuitFrame(tracker, now.AddMilliseconds(600), 364);
    AssertEqual("No", tracker.Poll(now.AddMilliseconds(640)), "reopening Quit should read its initial native choice again");
}

static void AddQuitFrame(StaticMenuCursorSpeechTracker tracker, DateTime now, int cursorX)
{
    tracker.ObserveDraw(new MenuTextRenderEntry("Do you want to quit", 220, 158, 7, 0x3C23D70A), now);
    tracker.ObserveCursor(new MenuCursorDrawObservation("B", 5, cursorX, 304, 0x3A83126F), now.AddMilliseconds(2));
    tracker.ObserveDraw(new MenuTextRenderEntry("Yes", 212, 296, cursorX == 162 ? 7 : 0, 0x3C23D70A), now.AddMilliseconds(4));
    tracker.ObserveDraw(new MenuTextRenderEntry("No", 414, 296, cursorX == 364 ? 7 : 0, 0x3C23D70A), now.AddMilliseconds(4));
}

static void AssertStaticMenuCursorSpeechReadsDrawOnlyQuitChoices()
{
    var now = new DateTime(2026, 8, 1, 22, 39, 10, DateTimeKind.Utc);
    var tracker = new StaticMenuCursorSpeechTracker(TimeSpan.FromMilliseconds(30));

    AddDrawOnlyQuitFrame(tracker, now, "Yes");
    AssertEqual(
        "Yes",
        tracker.Poll(now.AddMilliseconds(40)),
        "draw-only Quit should read the color-7 selected text without a cursor draw");

    AddDrawOnlyQuitFrame(tracker, now.AddMilliseconds(100), "No");
    AssertEqual(
        "No",
        tracker.Poll(now.AddMilliseconds(140)),
        "draw-only Quit should follow the native color-7 selection");

    AddDrawOnlyQuitFrame(tracker, now.AddMilliseconds(180), "No");
    AssertNull(tracker.Poll(now.AddMilliseconds(220)), "a stable draw-only Quit choice must not repeat");

    AddDrawOnlyQuitFrame(tracker, now.AddMilliseconds(600), "Yes");
    AssertEqual(
        "Yes",
        tracker.Poll(now.AddMilliseconds(640)),
        "reopening draw-only Quit should announce its initial choice again");
}

static void AssertStaticMenuCursorSpeechClearsStaleCursorWhenQuitReopensDrawOnly()
{
    var now = new DateTime(2026, 8, 1, 22, 40, 10, DateTimeKind.Utc);
    var tracker = new StaticMenuCursorSpeechTracker(TimeSpan.FromMilliseconds(30));

    AddQuitFrame(tracker, now, 364);
    AssertEqual("No", tracker.Poll(now.AddMilliseconds(40)), "the cursor-backed Quit frame should read No");

    // Reopen after the new-screen gap, but before the old cursor evidence ages
    // out. The new x64 dialog has draw-only selection evidence and must not be
    // blocked or resolved using the old dialog's cursor.
    AddDrawOnlyQuitFrame(tracker, now.AddMilliseconds(280), "Yes");
    AssertEqual(
        "Yes",
        tracker.Poll(now.AddMilliseconds(320)),
        "a reopened draw-only Quit dialog must discard the previous dialog's cursor state");
}

static void AddDrawOnlyQuitFrame(
    StaticMenuCursorSpeechTracker tracker,
    DateTime now,
    string selected)
{
    tracker.ObserveDraw(new MenuTextRenderEntry("Do you want to quit", 220, 158, 7, 0x3C23D70A), now);
    tracker.ObserveDraw(
        new MenuTextRenderEntry("Yes", 212, 296, selected == "Yes" ? 7 : 0, 0x3C23D70A),
        now.AddMilliseconds(4));
    tracker.ObserveDraw(
        new MenuTextRenderEntry("No", 414, 296, selected == "No" ? 7 : 0, 0x3C23D70A),
        now.AddMilliseconds(4));
}

static void AssertStatusMenuSpeechReadsOneNativeSummaryPerOpen()
{
    var now = new DateTime(2026, 7, 10, 20, 2, 0, DateTimeKind.Utc);
    var tracker = new StatusMenuSpeechTracker(TimeSpan.FromMilliseconds(30));
    var status = new StatusMenuSnapshot(
        PartySlot: 0,
        CharacterId: 0,
        Name: "Cloud",
        Level: 7,
        CurrentHp: 314,
        MaxHp: 314,
        CurrentMp: 54,
        MaxMp: 54,
        Strength: 17,
        Dexterity: 8,
        Vitality: 14,
        Magic: 13,
        Spirit: 12,
        Luck: 10,
        Attack: 22,
        AttackPercent: 96,
        Defense: 18,
        DefensePercent: 13,
        MagicAttack: 13,
        MagicDefense: 12,
        MagicDefensePercent: 4,
        Experience: 1250,
        ExperienceToNextLevel: 550,
        LimitLevel: 1,
        WeaponName: "Buster Sword",
        ArmorName: "Bronze Bangle",
        AccessoryName: "None");

    AddStatusFrame(tracker, now);
    AssertNull(tracker.Poll(now.AddMilliseconds(20), () => status), "Status summary should wait for its native screen to settle");
    var speech = tracker.Poll(now.AddMilliseconds(40), () => status)
        ?? throw new InvalidOperationException("Expected a native Status summary.");
    AssertContains(speech, "Cloud. Level 7. HP 314 of 314. MP 54 of 54");
    AssertContains(speech, "Strength 17. Dexterity 8. Vitality 14");
    AssertContains(speech, "Attack 22. Attack percent 96. Defense 18. Defense percent 13");
    AssertContains(speech, "Weapon Buster Sword. Armor Bronze Bangle. Accessory None");

    AddStatusFrame(tracker, now.AddMilliseconds(100));
    AssertNull(tracker.Poll(now.AddMilliseconds(140), () => status), "a visible Status summary should not repeat");

    AddStatusFrame(tracker, now.AddMilliseconds(600));
    AssertEqual(speech, tracker.Poll(now.AddMilliseconds(640), () => status), "reopening Status should read the summary again");
}

