static void AssertInGameMenuSpeechQueuesHelpTextAfterSettle()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var coordinator = new InGameMenuSpeechCoordinator(TimeSpan.FromMilliseconds(80));

    coordinator.ObserveDraw(new MenuTextRenderEntry("Change battle speed", 16, 13, 7, 0x3DCCCCCD), now);
    AssertNull(coordinator.Poll(now.AddMilliseconds(40)), "in-game help text should wait for settle");
    AssertEqual("Change battle speed", coordinator.Poll(now.AddMilliseconds(90)), "in-game help text should speak after settle");
    AssertNull(coordinator.Poll(now.AddMilliseconds(120)), "in-game help text should not repeat");

    coordinator.ObserveDraw(new MenuTextRenderEntry("Change battle message speed", 16, 13, 7, 0x3DCCCCCD), now.AddMilliseconds(200));
    coordinator.ObserveDraw(new MenuTextRenderEntry("Change field message speed", 16, 13, 7, 0x3DCCCCCD), now.AddMilliseconds(230));
    AssertNull(coordinator.Poll(now.AddMilliseconds(280)), "changed in-game help text should restart settle");
    AssertEqual("Change field message speed", coordinator.Poll(now.AddMilliseconds(320)), "in-game help text should prefer latest settled line");
}

