static void AssertMainMenuSpeechUsesNativeRootMainMenuIndexWithoutDrawnText()
{
    var now = new DateTime(2026, 7, 3, 0, 0, 0, DateTimeKind.Utc);
    var scheduler = new MainMenuSpeechScheduler(TimeSpan.Zero);
    var magic = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 1, Target: 1, MenuOpen: 1, EnabledMask: 0x7ffu, DisabledMask: 0, Animation: 16);

    if (!MainMenuStateReader.TryCreateSelection(magic, out var magicSelection))
    {
        throw new InvalidOperationException("Expected native Magic main menu selection.");
    }

    AssertEqual("Magic", scheduler.Observe(magicSelection.SpokenText, now), "root main menu should read the native menu index when drawn rows are not ready yet");

    var quit = new MainMenuSnapshot(State: 1, SelectedA: 0, SelectedB: 0, CursorIndex: 10, Target: 10, MenuOpen: 1, EnabledMask: 0x7ffu, DisabledMask: 0, Animation: 16);
    if (!MainMenuStateReader.TryCreateSelection(quit, out var quitSelection))
    {
        throw new InvalidOperationException("Expected native Quit main menu selection.");
    }

    AssertEqual("Quit", scheduler.Observe(quitSelection.SpokenText, now.AddMilliseconds(120)), "root main menu should use the native menu index instead of unrelated recent submenu text");
}

