static void WriteFf7Text(Dictionary<int, byte> memory, int address, string text, int length)
{
    for (var index = 0; index < length; index++)
    {
        memory[address + index] = 0xFF;
    }

    var limit = Math.Min(text.Length, Math.Max(0, length - 1));
    for (var index = 0; index < limit; index++)
    {
        var character = text[index];
        memory[address + index] = character == ' '
            ? (byte)0
            : (byte)(character - 0x20);
    }
}

static void WriteFf7TextBytes(byte[] memory, int address, string text, int length)
{
    Array.Fill(memory, (byte)0xFF, address, length);
    var limit = Math.Min(text.Length, Math.Max(0, length - 1));
    for (var index = 0; index < limit; index++)
    {
        memory[address + index] = text[index] == ' '
            ? (byte)0
            : (byte)(text[index] - 0x20);
    }
}

static void WriteUInt16(Dictionary<int, byte> memory, int address, ushort value)
{
    memory[address] = (byte)value;
    memory[address + 1] = (byte)(value >> 8);
}

static void WriteUInt16Bytes(byte[] memory, int address, ushort value)
{
    memory[address] = (byte)value;
    memory[address + 1] = (byte)(value >> 8);
}

static void WriteUInt32(Dictionary<int, byte> memory, int address, uint value)
{
    memory[address] = (byte)value;
    memory[address + 1] = (byte)(value >> 8);
    memory[address + 2] = (byte)(value >> 16);
    memory[address + 3] = (byte)(value >> 24);
}

static void WriteUInt32Bytes(byte[] memory, int address, uint value)
{
    memory[address] = (byte)value;
    memory[address + 1] = (byte)(value >> 8);
    memory[address + 2] = (byte)(value >> 16);
    memory[address + 3] = (byte)(value >> 24);
}

static uint CalculateReferenceFf7SaveChecksum(ReadOnlySpan<byte> payload)
{
    if (payload.Length != Ff7PcSaveFileReader.SlotSize - sizeof(uint))
    {
        throw new InvalidOperationException($"FFVII save checksum payload had {payload.Length} bytes.");
    }

    var result = 0xFFFF;
    foreach (var value in payload)
    {
        result ^= value << 8;
        for (var bit = 0; bit < 8; bit++)
        {
            result = (result & 0x8000) != 0
                ? (result << 1) ^ 0x1021
                : result << 1;
        }

        result &= 0xFFFF;
    }

    return (uint)((result ^ 0xFFFF) & 0xFFFF);
}

static Type GetOpeningMovieDescriptionType()
{
    return typeof(TitleMenuVisualDetector).Assembly.GetType("Ff7.Accessibility.Reloaded.OpeningMovieDescription")
        ?? throw new InvalidOperationException("OpeningMovieDescription type was not found.");
}

static List<(int Seconds, string Text)> ReadOpeningMovieCues()
{
    var type = GetOpeningMovieDescriptionType();
    var property = type.GetProperty("Cues")
        ?? throw new MissingMemberException(type.FullName, "Cues");
    var rawCues = (System.Collections.IEnumerable?)property.GetValue(null)
        ?? throw new InvalidOperationException("OpeningMovieDescription.Cues was null.");

    var cues = new List<(int Seconds, string Text)>();
    foreach (var rawCue in rawCues)
    {
        var cueType = rawCue.GetType();
        var seconds = (int)(cueType.GetProperty("Seconds")?.GetValue(rawCue)
            ?? throw new MissingMemberException(cueType.FullName, "Seconds"));
        var text = (string)(cueType.GetProperty("Text")?.GetValue(rawCue)
            ?? throw new MissingMemberException(cueType.FullName, "Text"));
        cues.Add((seconds, text));
    }

    return cues;
}

static void Invoke(object target, string method)
{
    var methodInfo = target.GetType().GetMethod(method)
        ?? throw new MissingMethodException(target.GetType().FullName, method);
    var parameters = methodInfo.GetParameters();
    var values = parameters.Length == 0
        ? null
        : parameters.Select(parameter => parameter.HasDefaultValue ? parameter.DefaultValue : null).ToArray();
    methodInfo.Invoke(target, values);
}

static FieldMessageReader CreateFieldMessageReader(Dictionary<int, int> memory, Dictionary<int, string> texts)
{
    return new FieldMessageReader(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => (byte)(memory.TryGetValue(address, out var value) ? value : 0xff),
        (address, _) => texts.TryGetValue(address, out var text) ? text : string.Empty);
}

