static FieldWalkmesh CreateThreeTriangleWalkmesh(bool connected)
{
    var missing = (short)-1;
    return new FieldWalkmesh(
    [
        new FieldWalkmeshTriangle(
            0,
            new FieldWalkmeshVertex(0, 0, 0),
            new FieldWalkmeshVertex(100, 0, 0),
            new FieldWalkmeshVertex(0, 100, 0),
            missing,
            connected ? (short)1 : missing,
            missing),
        new FieldWalkmeshTriangle(
            1,
            new FieldWalkmeshVertex(100, 0, 0),
            new FieldWalkmeshVertex(100, 100, 0),
            new FieldWalkmeshVertex(0, 100, 0),
            connected ? (short)2 : missing,
            missing,
            connected ? (short)0 : missing),
        new FieldWalkmeshTriangle(
            2,
            new FieldWalkmeshVertex(100, 0, 0),
            new FieldWalkmeshVertex(200, 0, 0),
            new FieldWalkmeshVertex(100, 100, 0),
            missing,
            missing,
            connected ? (short)1 : missing)
    ]);
}

static FieldWalkmesh CreateStraightSegmentTraceWalkmesh(bool connected)
{
    var missing = (short)-1;
    return new FieldWalkmesh(
    [
        new FieldWalkmeshTriangle(
            0,
            new FieldWalkmeshVertex(0, 0, 0),
            new FieldWalkmeshVertex(100, 0, 0),
            new FieldWalkmeshVertex(0, 100, 0),
            missing,
            1,
            missing),
        new FieldWalkmeshTriangle(
            1,
            new FieldWalkmeshVertex(100, 0, 0),
            new FieldWalkmeshVertex(100, 100, 0),
            new FieldWalkmeshVertex(0, 100, 0),
            connected ? (short)2 : missing,
            missing,
            0),
        new FieldWalkmeshTriangle(
            2,
            new FieldWalkmeshVertex(100, 0, 0),
            new FieldWalkmeshVertex(200, 0, 0),
            new FieldWalkmeshVertex(100, 100, 0),
            missing,
            3,
            connected ? (short)1 : missing),
        new FieldWalkmeshTriangle(
            3,
            new FieldWalkmeshVertex(200, 0, 0),
            new FieldWalkmeshVertex(200, 100, 0),
            new FieldWalkmeshVertex(100, 100, 0),
            missing,
            missing,
            2)
    ]);
}

static FieldWalkmesh CreateVerticalCorridorWalkmesh()
{
    const int cellCount = 4;
    var missing = (short)-1;
    var triangles = new List<FieldWalkmeshTriangle>(cellCount * 2);
    for (var cell = 0; cell < cellCount; cell++)
    {
        var y = cell * 100;
        var first = cell * 2;
        triangles.Add(new FieldWalkmeshTriangle(
            first,
            new FieldWalkmeshVertex(0, (short)y, 0),
            new FieldWalkmeshVertex(100, (short)y, 0),
            new FieldWalkmeshVertex(0, (short)(y + 100), 0),
            cell == 0 ? missing : (short)(first - 1),
            (short)(first + 1),
            missing));
        triangles.Add(new FieldWalkmeshTriangle(
            first + 1,
            new FieldWalkmeshVertex(100, (short)y, 0),
            new FieldWalkmeshVertex(100, (short)(y + 100), 0),
            new FieldWalkmeshVertex(0, (short)(y + 100), 0),
            missing,
            cell == cellCount - 1 ? missing : (short)(first + 2),
            (short)first));
    }

    return new FieldWalkmesh(triangles);
}

static FieldWalkmesh CreateWideVerticalCorridorWalkmesh()
{
    const int cellCount = 6;
    const short corridorWidth = 2000;
    const short cellHeight = 100;
    var missing = (short)-1;
    var triangles = new List<FieldWalkmeshTriangle>(cellCount * 2);
    for (var cell = 0; cell < cellCount; cell++)
    {
        var y = (short)(cell * cellHeight);
        var nextY = (short)(y + cellHeight);
        var first = cell * 2;
        triangles.Add(new FieldWalkmeshTriangle(
            first,
            new FieldWalkmeshVertex(0, y, 0),
            new FieldWalkmeshVertex(corridorWidth, y, 0),
            new FieldWalkmeshVertex(0, nextY, 0),
            cell == 0 ? missing : (short)(first - 1),
            (short)(first + 1),
            missing));
        triangles.Add(new FieldWalkmeshTriangle(
            first + 1,
            new FieldWalkmeshVertex(corridorWidth, y, 0),
            new FieldWalkmeshVertex(corridorWidth, nextY, 0),
            new FieldWalkmeshVertex(0, nextY, 0),
            missing,
            cell == cellCount - 1 ? missing : (short)(first + 2),
            (short)first));
    }

    return new FieldWalkmesh(triangles);
}

