static FieldWalkmeshReader CreateFieldWalkmeshReader(params FieldWalkmeshTriangle[] triangles)
{
    const int fieldDataBase = 0x02000000;
    const int walkmeshSectionOffset = 0x100;
    var memory = new Dictionary<int, int>
    {
        [FieldWalkmeshReader.AddressFieldDataPtr] = fieldDataBase
    };
    var sectionTableEntry = fieldDataBase + FieldWalkmeshReader.SectionOffsetsHeaderOffset +
        FieldWalkmeshReader.WalkmeshSectionIndex * sizeof(int);
    memory[sectionTableEntry] = walkmeshSectionOffset;
    memory[sectionTableEntry + sizeof(int)] = walkmeshSectionOffset + sizeof(int) + sizeof(int) +
        triangles.Length * (FieldWalkmeshReader.TriangleSize + FieldWalkmeshReader.AccessSize);

    var payload = fieldDataBase + walkmeshSectionOffset + sizeof(int);
    memory[payload] = triangles.Length;
    var trianglesBase = payload + sizeof(int);
    for (var index = 0; index < triangles.Length; index++)
    {
        var triangle = triangles[index];
        var triangleBase = trianglesBase + index * FieldWalkmeshReader.TriangleSize;
        WriteWalkmeshVertex(memory, triangleBase, triangle.Vertex0);
        WriteWalkmeshVertex(memory, triangleBase + FieldWalkmeshReader.VertexSize, triangle.Vertex1);
        WriteWalkmeshVertex(memory, triangleBase + FieldWalkmeshReader.VertexSize * 2, triangle.Vertex2);
    }

    var accessBase = trianglesBase + triangles.Length * FieldWalkmeshReader.TriangleSize;
    for (var index = 0; index < triangles.Length; index++)
    {
        var triangle = triangles[index];
        var entry = accessBase + index * FieldWalkmeshReader.AccessSize;
        memory[entry] = triangle.Adjacent0;
        memory[entry + sizeof(short)] = triangle.Adjacent1;
        memory[entry + sizeof(short) * 2] = triangle.Adjacent2;
    }

    return new FieldWalkmeshReader(
        address => memory.TryGetValue(address, out var value) ? value : 0,
        address => (short)(memory.TryGetValue(address, out var value) ? value : 0));
}

static FieldWalkmeshReader CreateInstalledFieldWalkmeshReader(int fieldId)
{
    const int fieldDataBase = 0x02000000;
    var gameRoot = FindGameRoot();
    var dataSource = new FlevelDataSource(gameRoot);
    if (!dataSource.TryReadField(fieldId, out var encodedFieldBytes))
    {
        throw new InvalidOperationException($"Installed field {fieldId} is unavailable from {dataSource.Diagnostic}.");
    }
    var fieldBytes = Ff7LzsDecoder.DecodeFieldFile(encodedFieldBytes);

    int ReadInt32Value(int address)
    {
        if (address == FieldWalkmeshReader.AddressFieldDataPtr)
        {
            return fieldDataBase;
        }

        var offset = address - fieldDataBase;
        return offset >= 0 && offset + sizeof(int) <= fieldBytes.Length
            ? BitConverter.ToInt32(fieldBytes, offset)
            : 0;
    }

    short ReadInt16Value(int address)
    {
        var offset = address - fieldDataBase;
        return offset >= 0 && offset + sizeof(short) <= fieldBytes.Length
            ? BitConverter.ToInt16(fieldBytes, offset)
            : (short)0;
    }

    return new FieldWalkmeshReader(ReadInt32Value, ReadInt16Value);
}

static void WriteWalkmeshVertex(Dictionary<int, int> memory, int address, FieldWalkmeshVertex vertex)
{
    memory[address] = vertex.X;
    memory[address + sizeof(short)] = vertex.Y;
    memory[address + sizeof(short) * 2] = vertex.Z;
    memory[address + sizeof(short) * 3] = 0;
}

