static BattleStateReader CreateBattleStateReader(
    Dictionary<int, byte> memory,
    Func<int, string?>? abilityName = null,
    Func<int, string?>? abilityDescription = null,
    Func<int, string?>? itemName = null,
    Func<int, string?>? itemDescription = null,
    Func<int, string?>? commandName = null,
    Func<int, string?>? limitName = null,
    Func<int, string?>? limitDescription = null,
    Func<int, int, byte, byte>? byteTransform = null)
{
    var readCounts = new Dictionary<int, int>();
    byte ReadByte(int address)
    {
        var value = memory.TryGetValue(address, out var candidate) ? candidate : (byte)0xFF;
        readCounts[address] = readCounts.GetValueOrDefault(address) + 1;
        return byteTransform?.Invoke(address, readCounts[address], value) ?? value;
    }

    ushort ReadUInt16Value(int address) => (ushort)(ReadByte(address) | (ReadByte(address + 1) << 8));
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);
    bool IsReadable(int address, int length) =>
        address > 0 &&
        length > 0 &&
        (long)address + length <= (long)int.MaxValue + 1 &&
        Enumerable.Range(0, length).All(offset => memory.ContainsKey(address + offset));

    return new BattleStateReader(
        ReadByte,
        ReadUInt16Value,
        ReadInt32Value,
        new SavemapPartyReader(ReadByte),
        IsReadable,
        abilityName,
        abilityDescription,
        itemName,
        itemDescription,
        commandName,
        limitName,
        limitDescription);
}

static BattleDamagePopupReader CreateBattleDamagePopupReader(Dictionary<int, byte> memory)
{
    byte ReadByte(int address) => memory.TryGetValue(address, out var value) ? value : (byte)0xFF;
    ushort ReadUInt16Value(int address) => (ushort)(ReadByte(address) | (ReadByte(address + 1) << 8));
    short ReadInt16Value(int address) => unchecked((short)ReadUInt16Value(address));
    int ReadInt32Value(int address) =>
        ReadByte(address) |
        (ReadByte(address + 1) << 8) |
        (ReadByte(address + 2) << 16) |
        (ReadByte(address + 3) << 24);

    return new BattleDamagePopupReader(ReadByte, ReadInt16Value, ReadUInt16Value, ReadInt32Value);
}

static BattleResultsReader CreateBattleResultsReader(
