static void WriteRelativeCall(Dictionary<int, byte> bytes, Dictionary<int, int> memory, int callAddress, int targetAddress)
{
    bytes[callAddress] = 0xE8;
    memory[callAddress + 1] = targetAddress - callAddress - 5;
}

static void WriteFakeLgp(string path, params string[] names)
{
    using var stream = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.None);
    using var writer = new BinaryWriter(stream);
    writer.Write((short)0);
    writer.Write("SQUARESOFT"u8);
    writer.Write(names.Length);

    for (var index = 0; index < names.Length; index++)
    {
        var nameBytes = new byte[20];
        var encoded = System.Text.Encoding.ASCII.GetBytes(names[index]);
        Array.Copy(encoded, nameBytes, Math.Min(encoded.Length, nameBytes.Length));
        writer.Write(nameBytes);
        writer.Write(0x1000 + index);
        writer.Write((byte)0);
        writer.Write((short)0);
    }
}

static byte[] BuildFakeMapList(params string[] names)
{
    var bytes = new byte[sizeof(ushort) + names.Length * 32];
    BitConverter.GetBytes((ushort)names.Length).CopyTo(bytes, 0);
    for (var index = 0; index < names.Length; index++)
    {
        var encoded = System.Text.Encoding.ASCII.GetBytes(names[index]);
        Array.Copy(encoded, 0, bytes, sizeof(ushort) + index * 32, Math.Min(encoded.Length, 32));
    }

    return bytes;
}

static void WriteFakeLgpWithPayloads(string path, params (string Name, byte[] Data)[] entries)
{
    const int lookupTableSize = 30 * 30 * sizeof(uint);
    var headerSize = 16 + entries.Length * 27 + lookupTableSize + sizeof(ushort);
    var dataOffset = headerSize;

    using var stream = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.None);
    using var writer = new BinaryWriter(stream);
    writer.Write((short)0);
    writer.Write("SQUARESOFT"u8);
    writer.Write(entries.Length);
    foreach (var entry in entries)
    {
        WriteFixedAscii(writer, entry.Name, 20);
        writer.Write(dataOffset);
        writer.Write((byte)0);
        writer.Write((ushort)0);
        dataOffset += 24 + entry.Data.Length;
    }

    writer.Write(new byte[lookupTableSize]);
    writer.Write((ushort)0);
    foreach (var entry in entries)
    {
        WriteFixedAscii(writer, entry.Name, 20);
        writer.Write(entry.Data.Length);
        writer.Write(entry.Data);
    }

    writer.Write("FINAL FANTASY7"u8);
}

static void WriteFixedAscii(BinaryWriter writer, string value, int length)
{
    var bytes = new byte[length];
    var encoded = System.Text.Encoding.ASCII.GetBytes(value);
    Array.Copy(encoded, bytes, Math.Min(encoded.Length, bytes.Length));
    writer.Write(bytes);
}

static byte[] ReadInstalledFieldMessageBytes(int fieldId, int messageId)
{
    var source = new FlevelDataSource(FindGameRoot());
    if (!source.TryReadField(fieldId, out var encodedFieldBytes))
    {
        throw new InvalidOperationException($"Field {fieldId} is unavailable from {source.Diagnostic}.");
    }

    var fieldBytes = Ff7LzsDecoder.DecodeFieldFile(encodedFieldBytes);
    var sectionOneOffset = BitConverter.ToInt32(fieldBytes, 6);
    var sectionOneDataOffset = sectionOneOffset + sizeof(int);
    var sectionOneLength = BitConverter.ToInt32(fieldBytes, sectionOneOffset);
    var sectionOneEnd = sectionOneDataOffset + sectionOneLength;
    var stringOffset = BitConverter.ToUInt16(fieldBytes, sectionOneDataOffset + 4);
    var dialogTableOffset = sectionOneDataOffset + stringOffset;
    var dialogCount = BitConverter.ToUInt16(fieldBytes, dialogTableOffset);
    if (messageId < 0 || messageId >= dialogCount)
    {
        throw new ArgumentOutOfRangeException(nameof(messageId));
    }

    var relativeOffset = BitConverter.ToUInt16(
        fieldBytes,
        dialogTableOffset + sizeof(ushort) + messageId * sizeof(ushort));
    var textOffset = dialogTableOffset + relativeOffset;
    var terminator = Array.IndexOf(fieldBytes, (byte)0xff, textOffset, sectionOneEnd - textOffset);
    if (terminator < 0)
    {
        throw new InvalidDataException($"Field {fieldId} message {messageId} is not terminated.");
    }

    return fieldBytes[textOffset..(terminator + 1)];
}

static void AssertLogPathUsesModDirectory()
{
    const string modDirectory = @"C:\Reloaded-II\Mods\ff7.accessibility.reloaded";
    var logPath = ModPaths.ResolveLogPath(modDirectory);
    var expected = Path.Combine(modDirectory, "ff7_accessibility_reloaded.log");
    if (!string.Equals(logPath, expected, StringComparison.OrdinalIgnoreCase))
    {
        throw new InvalidOperationException($"Expected log path {expected}, got {logPath}.");
    }
}

static void AssertEqual<T>(T expected, T actual, string label)
{
    if (!EqualityComparer<T>.Default.Equals(expected, actual))
    {
        throw new InvalidOperationException($"{label}: expected {expected}, got {actual}.");
    }
}

static void AssertApprox(float expected, float actual, float tolerance, string label)
{
    if (Math.Abs(expected - actual) > tolerance)
    {
        throw new InvalidOperationException($"{label}: expected {expected:0.00}, got {actual:0.00}.");
    }
}

static void AssertNull(object? actual, string label)
{
    if (actual is not null)
    {
        throw new InvalidOperationException($"{label}: expected <null>, got {actual}.");
    }
}

static void AssertNotNull(object? actual, string label)
{
    if (actual is null)
    {
        throw new InvalidOperationException($"{label}: expected a value, got <null>.");
    }
}

static void AssertContains(string actual, string expectedSubstring)
{
    if (!actual.Contains(expectedSubstring, StringComparison.Ordinal))
    {
        throw new InvalidOperationException($"Expected text to contain '{expectedSubstring}', got '{actual}'.");
    }
}

static string FindGameRoot()
{
    var dataRoot = Environment.GetEnvironmentVariable("FF7_ACCESSIBILITY_DATA_ROOT");
    if (!string.IsNullOrWhiteSpace(dataRoot))
    {
        if (Directory.Exists(Path.Combine(dataRoot, "data")))
        {
            return Path.GetFullPath(dataRoot);
        }

        throw new DirectoryNotFoundException(
            $"FF7_ACCESSIBILITY_DATA_ROOT does not identify an FFVII data root: {dataRoot}");
    }

    var configuredRoot = Environment.GetEnvironmentVariable("FF7_ACCESSIBILITY_RUNTIME");
    if (!string.IsNullOrWhiteSpace(configuredRoot))
    {
        if (IsGameRuntime(configuredRoot))
        {
            return Path.GetFullPath(configuredRoot);
        }

        throw new DirectoryNotFoundException(
            $"FF7_ACCESSIBILITY_RUNTIME does not identify an FFVII runtime: {configuredRoot}");
    }

    var dir = new DirectoryInfo(AppContext.BaseDirectory);
    while (dir is not null)
    {
        if (IsGameRuntime(dir.FullName))
        {
            return dir.FullName;
        }

        dir = dir.Parent;
    }

    var reloadedRoot = Environment.GetEnvironmentVariable("RELOADED_II_ROOT");
    if (string.IsNullOrWhiteSpace(reloadedRoot))
    {
        reloadedRoot = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
            "AccessXI",
            "external",
            "Reloaded-II");
    }

    var appConfigPath = Path.Combine(reloadedRoot, "Apps", "Ff7.En.Steam", "AppConfig.json");
    if (File.Exists(appConfigPath))
    {
        using var document = JsonDocument.Parse(File.ReadAllText(appConfigPath));
        if (document.RootElement.TryGetProperty("AppLocation", out var locationProperty))
        {
            var location = locationProperty.GetString();
            var runtime = string.IsNullOrWhiteSpace(location) ? null : Path.GetDirectoryName(location);
            if (!string.IsNullOrWhiteSpace(runtime) && IsGameRuntime(runtime))
            {
                return Path.GetFullPath(runtime);
            }
        }

        throw new DirectoryNotFoundException(
            $"Reloaded-II FFVII configuration does not identify a live game runtime: {appConfigPath}");
    }

    throw new DirectoryNotFoundException(
        "Could not locate an FFVII runtime from the test path, FF7_ACCESSIBILITY_RUNTIME, or Reloaded-II AppConfig.json.");
}

static bool IsGameRuntime(string path)
{
    return Directory.Exists(path) &&
           File.Exists(Path.Combine(path, "ff7_en.exe")) &&
           Directory.Exists(Path.Combine(path, "data"));
}

static string FindSourceRoot()
{
    var dir = new DirectoryInfo(AppContext.BaseDirectory);
    while (dir is not null)
    {
        if (Directory.Exists(Path.Combine(dir.FullName, "accessibility_prototype")))
        {
            return dir.FullName;
        }

        dir = dir.Parent;
    }

    throw new DirectoryNotFoundException("Could not locate the FFVII accessibility source root.");
}

static string FindRepositoryRoot()
{
    var dir = new DirectoryInfo(AppContext.BaseDirectory);
    while (dir is not null)
    {
        if (File.Exists(Path.Combine(
                dir.FullName,
                "Ff7.Accessibility.Reloaded",
                "ModConfig.json")))
        {
            return dir.FullName;
        }

        dir = dir.Parent;
    }

    throw new DirectoryNotFoundException(
        "Could not locate the Blind Soldier repository root.");
}

sealed class ShortRecoveryRoutePlanner :
    IFieldNavigationRoutePlanner,
    IFieldNavigationCorridorLookaheadPlanner
{
    private static readonly FieldNavigationRouteWaypoint Destination = new(0, 200, 0);
    private static readonly FieldNavigationRouteWaypoint Recovery = new(24, 16, 0);

    public int BuildCount { get; private set; }

    public string LastDiagnostic { get; private set; } = string.Empty;

    public bool TryResolvePlayerTriangle(FieldPositionSnapshot position, out int triangle)
    {
        triangle = 0;
        return position.FieldId == 900;
    }

    public bool TryBuildRoute(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRoutePlan plan)
    {
        BuildCount++;
        plan = new FieldNavigationRoutePlan(
            900,
            "900:exit:short-recovery",
            [0],
            Array.Empty<FieldNavigationRoutePortal>(),
            Destination,
            0,
            StableWaypointsOverride:
            [
                new FieldNavigationRouteStep(Destination, 0)
            ]);
        LastDiagnostic = "short recovery fixture";
        return position.FieldId == 900 && target.FieldId == 900;
    }

    public bool TryGetNextWaypoint(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRouteWaypoint waypoint)
    {
        waypoint = Destination;
        return position.FieldId == 900 && target.FieldId == 900;
    }

    public bool TryObserveCorridor(
        FieldPositionSnapshot position,
        FieldNavigationRoutePlan plan,
        IReadOnlyList<FieldNavigationRouteStep> stableWaypoints,
        int waypointIndex,
        FieldNavigationRouteAction? nextAction,
        FieldNavigationRouteHeading heading,
        out FieldNavigationCorridorObservation observation)
    {
        var recovering = heading.IsBlocked || heading.RecoveryWaypoint is not null;
        observation = recovering
            ? new FieldNavigationCorridorObservation(
                0,
                heading.RecoveryWaypoint ?? Recovery,
                0,
                FieldNavigationLookaheadMode.ObstacleRecovery,
                false,
                heading.RecoveryWaypoint is null
                    ? "lookahead=obstacle-recovery, short fixture"
                    : "lookahead=obstacle-recovery, active, short fixture")
            : new FieldNavigationCorridorObservation(
                0,
                Destination,
                0,
                FieldNavigationLookaheadMode.HeadingHeld,
                true,
                "lookahead=heading-held, short fixture");
        return true;
    }
}

sealed class FixedPortalRoutePlanner : IFieldNavigationRoutePlanner
{
    private readonly FieldNavigationTransitionKind? firstPortalTransitionKind;

    public FixedPortalRoutePlanner(
        FieldNavigationTransitionKind? firstPortalTransitionKind = null)
    {
        this.firstPortalTransitionKind = firstPortalTransitionKind;
    }

    public int BuildCount { get; private set; }

    public string LastDiagnostic { get; private set; } = string.Empty;

    public bool TryBuildRoute(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRoutePlan plan)
    {
        BuildCount++;
        plan = new FieldNavigationRoutePlan(
            900,
            "900:exit:bent",
            [0, 1, 2],
            [
                new FieldNavigationRoutePortal(
                    0,
                    1,
                    new FieldNavigationRouteWaypoint(50, 0, 0),
                    new FieldNavigationRouteWaypoint(50, 100, 0),
                    firstPortalTransitionKind,
                    firstPortalTransitionKind is null ? string.Empty : "native-action:0",
                    FieldNavigationInput.Up,
                    new FieldNavigationRouteWaypoint(75, 50, 0)),
                new FieldNavigationRoutePortal(
                    1,
                    2,
                    new FieldNavigationRouteWaypoint(100, 50, 0),
                    new FieldNavigationRouteWaypoint(0, 50, 0))
            ],
            new FieldNavigationRouteWaypoint(target.X, target.Y, target.Z),
            2);
        LastDiagnostic = $"fixed route build {BuildCount}";
        return position.FieldId == target.FieldId;
    }

    public bool TryGetNextWaypoint(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRouteWaypoint waypoint)
    {
        waypoint = new FieldNavigationRouteWaypoint(50, 0, 0);
        return position.FieldId == target.FieldId;
    }

    public bool TryResolvePlayerTriangle(FieldPositionSnapshot position, out int triangle)
    {
        triangle = position.TriangleId;
        return true;
    }
}

sealed class OverlappingCorridorRoutePlanner : IFieldNavigationRoutePlanner
{
    private static readonly FieldNavigationRouteStep[] StableSteps =
    [
        new(new FieldNavigationRouteWaypoint(1000, 0, 0), 1),
        new(new FieldNavigationRouteWaypoint(1000, 100, 0), 2),
        new(new FieldNavigationRouteWaypoint(0, 100, 0), 3),
        new(new FieldNavigationRouteWaypoint(0, 200, 0), 4)
    ];

    public string LastDiagnostic { get; private set; } = string.Empty;

    public bool TryBuildRoute(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRoutePlan plan)
    {
        plan = new FieldNavigationRoutePlan(
            position.FieldId,
            $"{position.FieldId}:{target.StableId}",
            [0, 1, 2, 3, 4],
            [
                new FieldNavigationRoutePortal(0, 1, new(1000, -20, 0), new(1000, 20, 0)),
                new FieldNavigationRoutePortal(1, 2, new(980, 100, 0), new(1020, 100, 0)),
                new FieldNavigationRoutePortal(2, 3, new(0, 80, 0), new(0, 120, 0)),
                new FieldNavigationRoutePortal(3, 4, new(-20, 200, 0), new(20, 200, 0))
            ],
            new FieldNavigationRouteWaypoint(target.X, target.Y, target.Z),
            4,
            StableWaypointsOverride: StableSteps);
        LastDiagnostic = "overlapping test corridor";
        return position.FieldId == target.FieldId;
    }

    public bool TryGetNextWaypoint(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRouteWaypoint waypoint)
    {
        waypoint = StableSteps[0].Waypoint;
        return position.FieldId == target.FieldId;
    }

    public bool TryResolvePlayerTriangle(FieldPositionSnapshot position, out int triangle)
    {
        triangle = position.TriangleId;
        return position.FieldId == 900;
    }
}

sealed class ParallelLaneRoutePlanner :
    IFieldNavigationRoutePlanner,
    IFieldNavigationRouteRefreshPlanner,
    IFieldNavigationCorridorLookaheadPlanner
{
    public int BuildCount { get; private set; }

    public string LastDiagnostic { get; private set; } = string.Empty;

    public bool TryBuildRoute(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRoutePlan plan)
    {
        BuildCount++;
        var isUpperLane = position.TriangleId == 2;
        plan = new FieldNavigationRoutePlan(
            position.FieldId,
            $"{position.FieldId}:{target.StableId}",
            [isUpperLane ? 2 : 0],
            Array.Empty<FieldNavigationRoutePortal>(),
            isUpperLane
                ? new FieldNavigationRouteWaypoint(100, 100, 0)
                : new FieldNavigationRouteWaypoint(50, 0, 0),
            isUpperLane ? 2 : 0);
        LastDiagnostic = isUpperLane ? "upper parallel lane" : "lower parallel lane";
        return position.FieldId == target.FieldId;
    }

    public bool TryGetNextWaypoint(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRouteWaypoint waypoint)
    {
        waypoint = position.TriangleId == 2
            ? new FieldNavigationRouteWaypoint(100, 100, 0)
            : new FieldNavigationRouteWaypoint(50, 0, 0);
        return position.FieldId == target.FieldId;
    }

    public bool TryBuildRouteFromCurrentTriangle(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        int resolvedTriangle,
        out FieldNavigationRoutePlan plan) =>
        TryBuildRoute(position, target, out plan) &&
        plan.TrianglePath.Count > 0 &&
        plan.TrianglePath[0] == resolvedTriangle;

    public bool TryResolvePlayerTriangle(FieldPositionSnapshot position, out int triangle)
    {
        triangle = position.TriangleId;
        return position.FieldId == 900;
    }

    public bool TryObserveCorridor(
        FieldPositionSnapshot position,
        FieldNavigationRoutePlan plan,
        IReadOnlyList<FieldNavigationRouteStep> stableWaypoints,
        int waypointIndex,
        FieldNavigationRouteAction? nextAction,
        FieldNavigationRouteHeading heading,
        out FieldNavigationCorridorObservation observation)
    {
        var headingLength = Math.Sqrt(
            heading.DeltaX * heading.DeltaX +
            heading.DeltaY * heading.DeltaY);
        var projectedX = headingLength <= 0.001d
            ? position.X
            : position.X + (int)Math.Round(heading.DeltaX / headingLength * 240d);
        var projectedY = headingLength <= 0.001d
            ? position.Y
            : position.Y + (int)Math.Round(heading.DeltaY / headingLength * 240d);
        observation = new FieldNavigationCorridorObservation(
            position.TriangleId,
            new FieldNavigationRouteWaypoint(
                projectedX,
                projectedY,
                position.Z),
            Math.Clamp(waypointIndex, 0, Math.Max(0, stableWaypoints.Count - 1)),
            FieldNavigationLookaheadMode.HeadingHeld,
            true,
            "lookahead=heading-held, test clear parallel lane");
        return position.FieldId == plan.FieldId && heading.IsUsable;
    }
}

sealed class ConfigurableCorridorRoutePlanner :
    IFieldNavigationRoutePlanner,
    IFieldNavigationCorridorLookaheadPlanner
{
    private readonly bool includeAction;

    public ConfigurableCorridorRoutePlanner(bool includeAction = false)
    {
        this.includeAction = includeAction;
    }

    public bool ConfirmsRoute { get; set; }

    public FieldNavigationLookaheadMode ConfirmedMode { get; set; } =
        FieldNavigationLookaheadMode.HeadingHeld;

    public bool ReturnLastStableStep { get; set; }

    public int? ObservedStableStepIndex { get; set; }

    public FieldNavigationRouteWaypoint? ObservedWaypoint { get; set; }

    public IReadOnlyList<FieldNavigationRouteStep>? StableWaypointsOverride { get; set; }

    public int BuildCount { get; private set; }

    public string LastDiagnostic { get; private set; } = string.Empty;

    public bool TryBuildRoute(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRoutePlan plan)
    {
        BuildCount++;
        var portals = includeAction
            ? new[]
            {
                new FieldNavigationRoutePortal(
                    0,
                    1,
                    new FieldNavigationRouteWaypoint(50, 50, 0),
                    new FieldNavigationRouteWaypoint(50, 50, 0),
                    FieldNavigationTransitionKind.Ladder,
                    "test-ladder",
                    FieldNavigationInput.Right,
                    new FieldNavigationRouteWaypoint(75, 50, 0),
                    RequiresAction: true)
            }
            : Array.Empty<FieldNavigationRoutePortal>();
        plan = new FieldNavigationRoutePlan(
            position.FieldId,
            $"{target.FieldId}:{target.StableId}",
            includeAction ? [0, 1] : [position.TriangleId],
            portals,
            new FieldNavigationRouteWaypoint(target.X, target.Y, target.Z),
            includeAction ? 1 : position.TriangleId,
            StableWaypointsOverride: StableWaypointsOverride);
        LastDiagnostic = $"configurable corridor build {BuildCount}";
        return position.FieldId == target.FieldId;
    }

    public bool TryGetNextWaypoint(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRouteWaypoint waypoint)
    {
        waypoint = new FieldNavigationRouteWaypoint(target.X, target.Y, target.Z);
        return position.FieldId == target.FieldId;
    }

    public bool TryResolvePlayerTriangle(FieldPositionSnapshot position, out int triangle)
    {
        triangle = position.TriangleId;
        return position.FieldId == 900;
    }

    public bool TryObserveCorridor(
        FieldPositionSnapshot position,
        FieldNavigationRoutePlan plan,
        IReadOnlyList<FieldNavigationRouteStep> stableWaypoints,
        int waypointIndex,
        FieldNavigationRouteAction? nextAction,
        FieldNavigationRouteHeading heading,
        out FieldNavigationCorridorObservation observation)
    {
        var observedIndex = ObservedStableStepIndex ?? (ReturnLastStableStep
            ? Math.Max(0, stableWaypoints.Count - 1)
            : Math.Clamp(waypointIndex, 0, Math.Max(0, stableWaypoints.Count - 1)));
        observation = new FieldNavigationCorridorObservation(
            position.TriangleId,
            ObservedWaypoint ?? plan.FinalApproach,
            observedIndex,
            ConfirmsRoute
                ? ConfirmedMode
                : FieldNavigationLookaheadMode.RequiredCorner,
            ConfirmsRoute,
            ConfirmsRoute
                ? "lookahead=heading-held, configurable clear lane"
                : "lookahead=required-corner, configurable deviation");
        return position.FieldId == plan.FieldId;
    }
}

