sealed class SelectiveRoutePlanner : IFieldNavigationRoutePlanner
{
    private readonly Func<FieldNavigationTarget, bool> isReachable;

    public SelectiveRoutePlanner(Func<FieldNavigationTarget, bool> isReachable)
    {
        this.isReachable = isReachable;
    }

    public string LastDiagnostic { get; private set; } = string.Empty;

    public bool TryBuildRoute(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRoutePlan plan)
    {
        if (position.FieldId != target.FieldId || !isReachable(target))
        {
            plan = null!;
            LastDiagnostic = $"unreachable {target.StableId}";
            return false;
        }

        plan = new FieldNavigationRoutePlan(
            position.FieldId,
            target.StableId,
            [position.TriangleId],
            [],
            new FieldNavigationRouteWaypoint(target.X, target.Y, target.Z),
            position.TriangleId);
        LastDiagnostic = $"reachable {target.StableId}";
        return true;
    }

    public bool TryGetNextWaypoint(
        FieldPositionSnapshot position,
        FieldNavigationTarget target,
        out FieldNavigationRouteWaypoint waypoint)
    {
        waypoint = new FieldNavigationRouteWaypoint(target.X, target.Y, target.Z);
        return position.FieldId == target.FieldId && isReachable(target);
    }

    public bool TryResolvePlayerTriangle(FieldPositionSnapshot position, out int triangle)
    {
        triangle = position.TriangleId;
        return true;
    }
}

