sealed record GenericRuntimeEvent(DateTime TimestampUtc, string Name) : RuntimeEvent(TimestampUtc);

sealed class FakeRuntimeBackend : IFf7RuntimeBackend
{
    private readonly RuntimeCapabilityReport report;
    private readonly RuntimeFrameObservation frame;
    private IRuntimeEventSink? eventSink;

    public FakeRuntimeBackend(RuntimeCapabilityReport report, RuntimeFrameObservation frame)
    {
        this.report = report;
        this.frame = frame;
    }

    public RuntimeIdentity Identity => report.Identity;

    public RuntimeEvent? StartEvent { get; init; }

    public IReadOnlyList<RuntimeEvent>? StartEvents { get; init; }

    public bool ThrowOnStop { get; init; }

    public bool ThrowOnStart { get; init; }

    public bool ThrowOnRead { get; set; }

    public bool Started { get; private set; }

    public bool Stopped { get; private set; }

    public bool Disposed { get; private set; }

    public int ReadCount { get; private set; }

    public RuntimeCapabilityReport ValidateCapabilities() => report;

    public void Start(IRuntimeEventSink sink)
    {
        Started = true;
        eventSink = sink;
        if (StartEvent is not null)
        {
            eventSink.Publish(StartEvent);
        }

        if (StartEvents is not null)
        {
            foreach (var runtimeEvent in StartEvents)
            {
                eventSink.Publish(runtimeEvent);
            }
        }

        if (ThrowOnStart)
        {
            throw new InvalidOperationException("test backend start failure");
        }
    }

    public RuntimeFrameObservation ReadFrame()
    {
        ReadCount++;
        if (ThrowOnRead)
        {
            throw new InvalidOperationException("test backend frame failure");
        }

        return frame;
    }

    public RuntimeEventPublishResult PublishLate(RuntimeEvent runtimeEvent) =>
        eventSink?.Publish(runtimeEvent)
        ?? new RuntimeEventPublishResult(RuntimeEventPublishStatus.RejectedNotAccepting);

    public void Stop()
    {
        Stopped = true;
        if (ThrowOnStop)
        {
            throw new InvalidOperationException("test backend stop failure");
        }
    }

    public void Dispose() => Disposed = true;
}

sealed class RecordingAccessibilityOutput : IAccessibilityOutput
{
    public List<(string Text, bool Interrupt)> Spoken { get; } = [];

    public List<AccessibilityCue> Played { get; } = [];

    public List<AccessibilityCueKind> Stopped { get; } = [];

    public int PlayCueFailuresRemaining { get; set; }

    public int StopCueFailuresRemaining { get; set; }

    public int SpeakFailuresRemaining { get; set; }

    public int SpeakAttempts { get; private set; }

    public int PlayCueAttempts { get; private set; }

    public int StopCueAttempts { get; private set; }

    public void Speak(string text, bool interrupt)
    {
        SpeakAttempts++;
        if (SpeakFailuresRemaining > 0)
        {
            SpeakFailuresRemaining--;
            throw new InvalidOperationException("test Speak output failure");
        }

        Spoken.Add((text, interrupt));
    }

    public void PlayCue(AccessibilityCue cue)
    {
        PlayCueAttempts++;
        if (PlayCueFailuresRemaining > 0)
        {
            PlayCueFailuresRemaining--;
            throw new InvalidOperationException("test PlayCue output failure");
        }

        Played.Add(cue);
    }

    public void StopCue(AccessibilityCueKind kind)
    {
        StopCueAttempts++;
        if (StopCueFailuresRemaining > 0)
        {
            StopCueFailuresRemaining--;
            throw new InvalidOperationException("test StopCue output failure");
        }

        Stopped.Add(kind);
    }
}

