sealed class NativeProgressTestWindow : IDisposable
{
    private const uint WmQuit = 0x0012;
    private readonly ManualResetEventSlim ready = new(false);
    private readonly Thread windowThread;
    private nint handle;
    private uint threadId;
    private int disposed;

    public NativeProgressTestWindow()
    {
        windowThread = new Thread(WindowThreadMain)
        {
            IsBackground = true,
            Name = "Native progress test parent"
        };
        windowThread.Start();
        if (!ready.Wait(TimeSpan.FromSeconds(3)) || Handle == 0)
        {
            throw new InvalidOperationException("Could not create the native progress test parent window.");
        }
    }

    public nint Handle => Volatile.Read(ref handle);

    public void Dispose()
    {
        if (Interlocked.Exchange(ref disposed, 1) != 0)
        {
            return;
        }

        if (Volatile.Read(ref threadId) is var id && id != 0)
        {
            PostThreadMessageW(id, WmQuit, 0, 0);
        }

        if (windowThread.IsAlive)
        {
            windowThread.Join(TimeSpan.FromSeconds(2));
        }

        ready.Dispose();
    }

    private void WindowThreadMain()
    {
        threadId = GetCurrentThreadId();
        handle = CreateWindowExW(
            0,
            "STATIC",
            "FFVII foreground test window",
            0x00CF0000,
            0,
            0,
            800,
            600,
            0,
            0,
            GetModuleHandleW(null),
            0);
        ready.Set();
        while (GetMessageW(out var message, 0, 0, 0) > 0)
        {
            TranslateMessage(ref message);
            DispatchMessageW(ref message);
        }

        if (handle != 0)
        {
            DestroyWindow(handle);
            handle = 0;
        }
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct Point
    {
        public int X;
        public int Y;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct NativeMessage
    {
        public nint Hwnd;
        public uint Message;
        public nuint WParam;
        public nint LParam;
        public uint Time;
        public Point Point;
        public uint Private;
    }

    [DllImport("kernel32.dll")]
    private static extern uint GetCurrentThreadId();

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)]
    private static extern nint GetModuleHandleW(string? moduleName);

    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern nint CreateWindowExW(
        uint extendedStyle,
        string className,
        string windowName,
        uint style,
        int x,
        int y,
        int width,
        int height,
        nint parent,
        nint menu,
        nint instance,
        nint parameter);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool DestroyWindow(nint window);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool PostThreadMessageW(
        uint threadId,
        uint message,
        nuint wParam,
        nint lParam);

    [DllImport("user32.dll")]
    private static extern int GetMessageW(
        out NativeMessage message,
        nint window,
        uint filterMinimum,
        uint filterMaximum);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool TranslateMessage(ref NativeMessage message);

    [DllImport("user32.dll")]
    private static extern nint DispatchMessageW(ref NativeMessage message);
}

sealed class MainMenuGuestMemory : Ff7.Accessibility.LegacyLayout.ILegacyAddressSpace
{
    private readonly Dictionary<uint, byte> bytes = [];

    public void WriteInt32(int address, int value) => Write(address, BitConverter.GetBytes(value));

    public void WriteUInt32(int address, uint value) => Write(address, BitConverter.GetBytes(value));

    public void WriteUInt16(int address, ushort value) => Write(address, BitConverter.GetBytes(value));

    public void WriteBytes(int address, IReadOnlyList<byte> values) => Write(address, values);

    public bool TryRead(uint virtualAddress, Span<byte> destination)
    {
        for (var index = 0; index < destination.Length; index++)
        {
            if (!bytes.TryGetValue(virtualAddress + (uint)index, out destination[index]))
            {
                destination.Clear();
                return false;
            }
        }

        return virtualAddress != 0;
    }

    private void Write(int address, IReadOnlyList<byte> values)
    {
        for (var index = 0; index < values.Count; index++)
        {
            bytes[checked((uint)address + (uint)index)] = values[index];
        }
    }
}

sealed class DictionaryLegacyAddressSpace(
    IReadOnlyDictionary<int, byte> bytes,
    Func<uint, int, bool>? isReadable = null) : Ff7.Accessibility.LegacyLayout.ILegacyAddressSpace
{
    public bool TryRead(uint virtualAddress, Span<byte> destination)
    {
        if (virtualAddress == 0 ||
            (ulong)virtualAddress + (ulong)destination.Length > (ulong)uint.MaxValue + 1 ||
            (isReadable is not null && !isReadable(virtualAddress, destination.Length)))
        {
            destination.Clear();
            return false;
        }

        for (var index = 0; index < destination.Length; index++)
        {
            var address = (ulong)virtualAddress + (uint)index;
            if (address > int.MaxValue ||
                !bytes.TryGetValue((int)address, out destination[index]))
            {
                destination.Clear();
                return false;
            }
        }

        return true;
    }
}

sealed class TearingLegacyAddressSpace(
    IReadOnlyDictionary<int, byte> bytes,
    uint tearingAddress) : Ff7.Accessibility.LegacyLayout.ILegacyAddressSpace
{
    private int targetReadCount;

    public bool TryRead(uint virtualAddress, Span<byte> destination)
    {
        for (var index = 0; index < destination.Length; index++)
        {
            var address = (ulong)virtualAddress + (uint)index;
            if (address > int.MaxValue ||
                !bytes.TryGetValue((int)address, out destination[index]))
            {
                destination.Clear();
                return false;
            }
        }

        if (virtualAddress == tearingAddress &&
            destination.Length == sizeof(ushort) &&
            Interlocked.Increment(ref targetReadCount) >= 2)
        {
            destination[0]++;
        }

        return virtualAddress != 0;
    }
}

static class BlindSoldierRuntimeLeaseTests
{
    public static void Run()
    {
        var processId = Environment.ProcessId;
        if (!BlindSoldierRuntimeLease.TryAcquire(processId, out var first) || first is null)
        {
            throw new InvalidOperationException("The first runtime lease acquisition should succeed.");
        }

        try
        {
            if (BlindSoldierRuntimeLease.TryAcquire(processId, out var duplicate) || duplicate is not null)
            {
                duplicate?.Dispose();
                throw new InvalidOperationException("A concurrent runtime lease should be rejected.");
            }
        }
        finally
        {
            first.Dispose();
        }

        if (!BlindSoldierRuntimeLease.TryAcquire(processId, out var reacquired) || reacquired is null)
        {
            throw new InvalidOperationException("A cleanly released runtime lease should be reacquirable.");
        }

        reacquired.Dispose();
    }
}
